/* ÇEVİRİ pl · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("pl","olay",{
"OLAYLAR:1299-01:0":{"b": ["Powstanie beliku osmańskiego", "9f0b7c0a"], "d": ["Rozpoczęcie przez Osmana Gazi z plemienia Kayı samodzielnej działalności w okolicach Söğüt i Domaniç uznaje się za tradycyjny początek państwa osmańskiego; niektórzy historycy za prawdziwy punkt zwrotny uważają zwycięstwo pod Bafeusem w 1302 roku. Dzięki położeniu na bizantyjskim pograniczu bejlik szybko zyskiwał siłę dzięki wyprawom gazi. W atmosferze rozpadu spuścizny seldżuckiej Osman Gazi zgromadził wokół siebie ahich, gazich i koczowniczych Turkmenów; więź z szejchem Edebalim uważa się za podstawę duchowej legitymacji bejliku. W tym samym dniu przyłączono także inne miejscowości: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Zdobycie Bursy", "98c727fa"], "d": ["Bursa, przez lata trzymana w blokadzie, poddała się Orhanowi Gazi, który kierował ostatnią fazą oblężenia; miasto uczyniono pierwszą wielką stolicą bejliku. Według przekazu wiadomość o zdobyciu doniesiono umierającemu Osmanowi Gazi; zgodnie z jego testamentem został pochowany w Bursie. Miasto szybko wyposażono w meczety, imarety i medresy, a stało się wzorem wczesnego miejskiego budownictwa osmańskiego.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Zdobycie Nikei (İznik)", "a846a811"], "d": ["Nikea (İznik), jeden z najważniejszych ośrodków Bizancjum w Anatolii, po zwycięstwie pod Pelekanonem w 1329 roku straciła nadzieję na dalszy opór i poddała się Orhanowi Gazi. Założono tu pierwszą medresę osmańską, w której zaczęli wykładać uczeni, tacy jak Dâvûd-i Kayserî; miasto stało się ośrodkiem nauki wczesnego okresu. Kościół Hagia Sophia przekształcono w meczet, dając wczesny przykład tradycji zdobywczej.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Zdobycie İzmitu", "06a35035"], "d": ["Wraz z upadkiem İzmitu (Nikomedii) pod władzę osmańską przeszła ostatnia ważna twierdza Bizancjum po azjatyckiej stronie; cały półwysep Kocaeli aż po przeciwległy brzeg Konstantynopola stał się ziemią osmańską. Bejlik opanował w ten sposób całe południowe i wschodnie wybrzeże Morza Marmara, przygotowując przejście do Rumelii.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Twierdza Çimpe — przejście do Rumelii", "c2f0a07d"], "d": ["Süleyman Pasza, syn Orhana Gazi, w 1352 roku uczynił swoją bazą twierdzę Çimpe, przekazaną w toku bizantyjskiej wojny domowej; po wielkim trzęsieniu ziemi, które w marcu 1354 roku zniszczyło Gallipoli, opuszczone twierdze szybko umocniono i przekształcono półwysep w trwały przyczółek osmański. Ten krok, wsparty osiedleniem sprowadzonej z Anatolii ludności turkmeńskiej, jest początkiem obecności Osmanów na kontynencie europejskim, która miała trwać ponad 550 lat.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Zdobycie Edirne", "2f54ebb0"], "d": ["Zajęcie Edirne (Adrianopola), kluczowego miasta Tracji, wyznaczyło główną bazę i kierunek podbojów bałkańskich; data zdobycia jest w źródłach sporna i mieści się między 1361 a 1369 rokiem. Miasto wkrótce uczyniono stolicą, ogłaszając przesunięcie środka ciężkości państwa do Rumelii; pozostało siedzibą władzy przez około 90 lat, aż do zdobycia Stambułu.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I wstąpił na tron", "f8d48a26"], "d": ["Murad I (Hüdavendigâr), który objął tron po śmierci Orhana Gazi, w czasie 27-letnich rządów przekształcił państwo z pogranicznego bejliku w szkielet imperium. System pençik położył podwaliny pod korpus janczarów, rozpowszechniono system timarów, utworzono beylerbeylik Rumelii i wzmocniono instytucję wezyratu. Podboje bałkańskie stały się za jego rządów systematyczną polityką państwa.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["I bitwa na Kosowie — męczeńska śmierć Murada I", "10b8ddc9"], "d": ["Sojusz bałkański pod wodzą kneza Lazara poniósł na Kosowym Polu decydującą klęskę; Serbia znalazła się pod zwierzchnictwem osmańskim. Murad I, obchodzący pole bitwy, został zasztyletowany przez serbskiego szlachcica Miloša Obilicia i poległ jako męczennik; jest jedynym sułtanem osmańskim, który zginął na polu bitwy. W obozie na tron wprowadzono Bayezida Błyskawicę; jego brata Yakuba Çelebiego kazano udusić, co jest jednym z pierwszych znanych przykładów praktyki bratobójstwa.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Zwycięstwo pod Nikopolis", "75716e96"], "d": ["Wielka armia krzyżowa zebrana na wezwanie króla Węgier Zygmunta, w której uczestniczyli także rycerze francuscy i burgundzcy, została dotkliwie rozbita pod Nikopolis nad Dunajem przez Bayezida Błyskawicę. Zwycięstwo przypieczętowało osmańskie panowanie nad Bułgarią; przez pokolenie nie zorganizowano w Europie wielkiej wyprawy krzyżowej.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Bitwa pod Ankarą — początek Interregnum", "b4a99d96"], "d": ["W ciężkiej klęsce poniesionej na równinie Çubuk przed armią Timura Bayezid Błyskawica dostał się do niewoli i po kilku miesiącach zmarł w jej trakcie. Timur przywrócił beliki anatolijskie; ziemie osmańskie podzielono między synów Bayezida i rozpoczęła się trwająca 11 lat walka o tron (Interregnum, Fetret Devri). Ten najcięższy kryzys państwa od jego powstania wyrył w pamięci osmańskiej wagę zcentralizowanej struktury. W tym samym dniu utracono także inne miejscowości: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, twierdza Aydos, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, wyspa İmralı, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delczew), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofia, Niš, Widyń, Tyrnowo, Warna, Şumnu, Silistra, Nikopol, Ruse, Saloniki, Serez, Kawala, Skopje, Monastyr, Ochryda, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plewen, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Konstanca, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Çelebi Mehmed na nowo zjednoczył państwo", "03413dfd"], "d": ["Mehmed I, który w ostatnim rozrachunku między braćmi pokonał Mûsę Çelebiego pod Çamurlu, zjednoczył ziemie kraju pod jednym zarządem; dlatego uważa się go za „drugiego założyciela państwa”. W czasie jego rządów naprawiono nadwątlone struktury państwa, wyważono stosunki z bejlikami anatolijskimi i prowadzono w Rumelii ostrożną politykę pokoju.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Powstanie szejcha Bedreddina", "e0a072ca"], "d": ["Ruch religijno-społeczny rozwijający się wokół szejcha Bedreddina, wielkiego prawnika i mistyka, który w okresie Interregnum pełnił urząd kazaskera, wybuchł równocześnie z powstaniami Börklüce Mustafy w Karaburun i Torlaka Kemala w Manisie. Powstania krwawo stłumiono; Bedreddin został schwytany w Deliormanie i stracony w Serez. Wydarzenie to jako najwcześniejsze wielkie powstanie społeczno-mesjańskie w dziejach osmańskich pozostawiło głęboki ślad w literaturze i historiografii.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Zwycięstwo pod Warną", "f739eedc"], "d": ["Węgiersko-polska armia krzyżowa, która złamawszy układ w Segedynie ruszyła na południe, została zniszczona pod Warną przez Murada II, który po abdykacji powrócił na czoło wojska; młody król Władysław III poległ na polu bitwy. Zwycięstwo odebrało ostatnią wielką szansę zewnętrznej interwencji mającej na celu likwidację obecności osmańskiej na Bałkanach i zabezpieczyło drogę do zdobycia Stambułu.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["II bitwa na Kosowie", "ebe0b662"], "d": ["Armia Jánosa Hunyadiego, pragnąca pomścić Warnę, została w trwającej trzy dni zaciętej bitwie ostatecznie pokonana przez Murada II. Była to ostatnia wielka bitwa polna, jaką krzyżowcy stoczyli przeciw Osmanom na Bałkanach; dzięki zwycięstwu panowanie osmańskie na południe od Dunaju ugruntowało się w sposób nieodwracalny.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Zdobycie Konstantynopola", "583d5e3e"], "d": ["Po pięćdziesięciu czterech dniach oblężenia (6 kwietnia–29 maja 1453) armia osmańska rankiem 29 maja przekroczyła mury i wkroczyła do miasta; ostatni cesarz Konstantyn XI zginął w walkach i 1100-letnie Cesarstwo Wschodniorzymskie przeszło do historii. Młody sułtan przyjął tytuł „Zdobywcy” (Fâtih), uczynił miasto stolicą i przekształcił Hagia Sophia w meczet; miasto w krótkim czasie odrodziło się dzięki osadnictwu i odbudowie. Według TDV Silivri i Vize zostały ostatecznie zdobyte dopiero w 1453 roku; według hasła TDV o Limnos wyspa weszła pod zarząd osmański bezpośrednio po zdobyciu i została pozostawiona rodowi Gattilusio na warunkach daniny. W atlasie Silivri, Vize i Limnos są zapisane od tego dnia jako przechodzące z Bizancjum do Osmanów (Limnos jako płacące daninę). Odlewanie olbrzymich dział, przeciąganie okrętów drogą lądową i układ oblężniczy przed murami uważa się za szczyt ówczesnej sztuki inżynierii wojskowej. Zdobycie uchodzi w historiografii europejskiej za jedną z symbolicznych dat końca średniowiecza.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Zdobycie Trapezuntu", "15f52403"], "d": ["Po trudnej wyprawie czarnomorskiej, którą Fatih prowadził jednocześnie wojskiem i flotą, Cesarstwo Trapezuntu poddało się; wraz z likwidacją tej ostatniej bizantyjskiej pozostałości w Anatolii całe południowe wybrzeże Morza Czarnego znalazło się pod panowaniem osmańskim. Położenie kresu dynastii Komnenów umocniło pretensje Fatiha do miana „władcy dwóch mórz i dwóch lądów”. W tym samym dniu przyłączono także inne miejscowości: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Ostateczne zdobycie Silifke — złamanie ostatniego oporu Karamanidów", "d988bee4"], "d": ["Twierdza Silifke poddała się w 1472 roku Gedikowi Ahmedowi Paszy, lecz w tym samym roku Karamanoğlu Kasım Bej odbił ją z pomocą floty krzyżowców ze Morza Śródziemnego. Po zwycięstwie pod Otlukbeli Fatih powierzył synowi i Gedikowi Ahmedowi Paszy ostateczne opanowanie regionu; przy pomocy dawnych artylerzystów osmańskich podpalono skład prochu i twierdzę szybko zdobyto. W ten sposób złamano ostatni opór Karamanidów w górach Taşeli-İçel; likwidacja beliku miała zostać zakończona w 1474 roku.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Bitwa pod Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, władca Akkoyunlu, który stał się wielką potęgą na Wschodzie i zawarł sojusz z Wenecją, poniósł pod Otlukbeli ciężką klęskę w starciu z uzbrojoną w broń palną armią Fatiha. Zwycięstwo przypieczętowało osmańską przewagę w Anatolii; było też wczesnym dowodem wyższości armii centralnej używającej dział i muszkietów nad armią klasyczną. Według hasła TDV o Gümüşhane miasto od 1467 roku znajdowało się pod panowaniem Akkoyunlu; panowanie to zakończyło się klęską pod Otlukbeli, a Gümüşhane przeszło ostatecznie pod władzę osmańską.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Przejście Krymu pod protektorat osmański", "44e3f7c8"], "d": ["Flota pod dowództwem Gediga Ahmeda Paszy zdobyła południowe miasta wybrzeża Krymu, na czele z genueńską Kafą; wybrzeża te uczyniono bezpośrednio sandżakiem osmańskim. Chanat Krymski natomiast pod rządami Mengliego Gireja stał się uprzywilejowanym państwem zależnym, uznającym zwierzchnictwo osmańskie, i przez trzy stulecia był kamieniem węgielnym polityki północnej; Morze Czarne przekształciło się faktycznie w osmańskie morze wewnętrzne. W tym samym dniu przyłączono także inne miejscowości: Bakczysaraj, Kercz, Azow.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Śmierć Fatiha — sprawa księcia Cema", "190ecf01"], "d": ["Po nagłej śmierci Fatiha w drodze na wyprawę tron objął Bayezid II; jego brat książę Cem, rościwszy sobie prawa do sułtanatu, kazał w Bursie czytać w swoim imieniu chutbę i bić monetę. Pokonany, schronił się najpierw u Mameluków, potem u rycerzy rodyjskich; w rękach rycerzy i papiestwa stał się kartą przetargową dyplomacji europejskiej i zmarł w 1495 roku w Neapolu. Wydarzenie to przez piętnaście lat zmuszało osmańską politykę zagraniczną do ostrożności.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Zwycięstwo pod Çaldıranem", "fea64ebb"], "d": ["Sułtan Selim Straszny, pragnąc u korzeni rozwiązać zagrożenie stworzone w Anatolii przez propagandę safawidzką, rozgromił na równinie Çaldıran armię szacha İsmaila dzięki przewadze w armatach i muszkietach. Wkroczono do Tabrizu; Wschodnia i Południowo-Wschodnia Anatolia oraz linia Mosul–Diyarbakır weszły pod zarząd osmański. Związanie kurdyjskich bejów z Osmanami dzięki staraniom İdrîsa-i Bitlisîego ustanowiło ramy wschodniej granicy, które miały przetrwać stulecia.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Zwycięstwo pod Mardż Dabik", "07d254d3"], "d": ["Armia mameluków została rozbita w ciągu kilku godzin pod Mardż Dabik na północ od Aleppo; stary sułtan Kansu Gavri zginął podczas bitwy. Zwycięstwo, które otworzyło szeroko bramy Aleppo i Damaszku, przyniosło Osmanom Syrię, Liban i Palestynę i utorowało drogę wyprawie egipskiej, która miała położyć kres państwu mameluków.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniya — zdobycie Egiptu i kalifat", "caf378d6"], "d": ["Armia osmańska, szybko przekroczywszy pustynię Synaj, przełamała linię obrony Tomanbaya pod Ridaniją i wkroczyła do Kairu; Tomanbay, który nadal stawiał opór, został schwytany i stracony, a państwo mameluków przeszło do historii. Egipt, Hidżaz i święte miasta weszły pod zarząd osmański; kalifa abbasydzkiego i święte relikwie zabrano do Stambułu. Wraz z przejściem kalifatu na dynastię osmańską sułtani przyjęli pretensje do przywództwa nad światem islamu; kontrola nad Szlakiem Korzennym przyniosła też imperium wielkie dochody. W tym samym dniu przyłączono także inne miejscowości: Akka, Maan, Sajda, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Sulejman Prawodawca wstąpił na tron", "f6512269"], "d": ["Sulejman I, który po śmierci Selima Strasznego objął tron jako jedyny syn, w trwającym 46 lat panowaniu osiągnął polityczny, wojskowy, prawny i kulturalny szczyt imperium. Kanunname systematyzujące prawo zwyczajowe przyniosły mu tytuł „Prawodawcy” (Kanunî); na Zachodzie zwano go „Wspaniałym” (Magnificent). Symbolami tego okresu są dzieła architekta Sinana, złoty wiek literatury dywanowej i przewaga floty na Morzu Śródziemnym.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Zdobycie Belgradu", "59ef5cec"], "d": ["Belgrad, którego Fatih nie zdołał zdobyć w 1456 roku i który uchodził za „klucz do Europy Środkowej”, padł w pierwszej wyprawie Sulejmana po oblężeniu u zbiegu Dunaju i Sawy. Załamała się południowa linia obrony Węgier; to zdobycie otworzyło bramę akcji w Europie Środkowej, która po pięciu latach sięgnęła Mohacza, a po dwudziestu — aneksji Budy.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Zdobycie Rodos", "807bbb1e"], "d": ["Rodos, baza joannitów zagrażających szlakom morskim wschodniej części Morza Śródziemnego i trasie pielgrzymów, poddało się po wielomiesięcznym krwawym oblężeniu na mocy układu; rycerzom pozwolono swobodnie opuścić wyspę (później osiedlili się na Malcie). Zapewniono bezpieczeństwo wybrzeży Anatolii, a morska trasa Stambuł–Egipt znalazła się pod nieprzerwaną kontrolą osmańską.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Bitwa pod Mohaczem", "f3418b0d"], "d": ["Armia węgierska została zniszczona w ciągu około dwóch godzin dzięki ogniowi dział i przewadze manewrowej na równinie Mohacz; król Ludwik II zginął w bagnie podczas ucieczki. Mohacz, jedna z najszybciej wygranych wielkich bitew w dziejach osmańskich, faktycznie zakończył istnienie niezależnego królestwa węgierskiego i otworzył w Europie Środkowej epokę rywalizacji osmańsko-habsburskiej.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["I oblężenie Wiednia", "dc49ea4f"], "d": ["W wyprawie zorganizowanej przeciw sięgnięciu Habsburgów po tron węgierski armia osmańska oblegała Wiedeń; z powodu pozostawienia ciężkich dział w drodze, wcześnie nadchodzącej zimy i trudności z zaopatrzeniem oblężenie zniesiono po trzech tygodniach. Choć miasta nie zdobyto, wpływy osmańskie na Węgrzech utrzymano; okolice Wiednia wyznaczyły granicę logistycznych możliwości imperium w Europie Środkowej.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Zdobycie Bagdadu — wyprawa Irakejn", "897092c3"], "d": ["W wyprawie na „dwa Iraki” (Irak Arabski i Irak Perski) wkroczono najpierw do Tabrizu, a następnie bez walki do Bagdadu; zajęcie dawnej stolicy Abbasydów przyniosło władcy osmańskiemu wielki prestiż w świecie islamu. Odnowiono mauzoleum imama Abû Hanîfy; wraz z przyłączeniem Bagdadu i Basry ziemie osmańskie sięgnęły Zatoki Perskiej. W tym samym dniu przyłączono także inne miejscowości: Kirkuk, Karbala.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Zwycięstwo morskie pod Prewezą", "30dc0f97"], "d": ["Flota krzyżowców zorganizowana z inicjatywy papieża, mimo przewagi liczebnej, została rozproszona pod Prewezą dzięki taktyce Barbarossy, który po mistrzowsku wykorzystał wiatr i wybrzeże; Andrea Doria opuścił pole bitwy. Zwycięstwo ustanowiło trwającą około 33 lat niekwestionowaną przewagę morską Osmanów na Morzu Śródziemnym; jest symboliczną datą Dnia Floty w tureckiej tradycji morskiej. W tym samym dniu przyłączono także inne miejscowości: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Aneksja Budy — Węgry prowincją osmańską", "db53b244"], "d": ["Sulejman, który wyruszył na wyprawę wobec oblężenia Budy przez Habsburgów, po wyzwoleniu miasta objął Środkowe Węgry bezpośrednim zarządem osmańskim i utworzył beylerbeylik Budy; Siedmiogród zaś uczyniono autonomicznym księstwem zależnym od Osmanów. Ten podzielony na trzy części ład węgierski trwał około 150 lat i stworzył trwały szkielet administracji osmańskiej w Europie Środkowej.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Pokój w Amasyi", "a5afe0d1"], "d": ["Pierwszy oficjalny traktat pokojowy, który zakończył trwające latami wojny osmańsko-safawidzkie. Bagdad i Irak pozostały przy Osmanach, granica we Wschodniej Anatolii została po raz pierwszy wzajemnie uznana; Safawidzi zobowiązali się zaprzestać propagandy szyickiej na ziemiach osmańskich, a Osmanowie — zapewnić bezpieczeństwo przejazdu pielgrzymów irańskich. Traktat stał się pierwszym przykładem prawnych ram stosunków między obu państwami.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — śmierć Sulejmana Prawodawcy", "e2917ed2"], "d": ["72-letni Sulejman zmarł w swoim namiocie na kilka godzin przed upadkiem twierdzy Szigetvár, oblężonej podczas trzynastej wyprawy; Sokollu Mehmed Pasza przez tygodnie ukrywał jego śmierć, by armia się nie rozproszyła. Twierdzę zdobyto, lecz państwo straciło swego najdłużej panującego i najwspanialszego sułtana; na tron wstąpił jego syn Selim II, a w zarządzaniu państwem zaczęło rosnąć znaczenie wielkich wezyrów.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Zdobycie Cypru", "e364a2b3"], "d": ["W 1570 roku wylądowano na Cyprze pod władzą wenecką; Nikozja szybko padła, a Famagusta poddała się dopiero w sierpniu 1571 roku po jedenastomiesięcznym oblężeniu. Wyspę, kluczową dla bezpieczeństwa handlowych i pielgrzymich szlaków wschodniej części Morza Śródziemnego, zorganizowano jako beylerbeylik i osiedlono tam ludność z Anatolii; zdobycie było też powodem zawiązania wielkiego sojuszu krzyżowców, który doprowadził do Lepanto.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Klęska pod Lepanto (İnebahtı)", "6a1d44a9"], "d": ["Flota krzyżowców, zjednoczona w następstwie zdobycia Cypru, dopadła flotę osmańską w zatoce Lepanto i zniszczyła jej większą część; kapudan pasza Müezzinzâde Ali Pasza poległ jako męczennik, uratowała się jedynie flota Uluça Alego. Po katastrofie wielki wezyr Sokollu Mehmed Pasza mianował Uluça Alego Paszę kapudanem paszą, powierzając mu zebranie rozproszonej floty, i rozpoczął budowę nowej floty we wszystkich stoczniach od Stambułu po Alanyę; mimo to absolutna przewaga na Morzu Śródziemnym została psychologicznie nadwerężona.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Bitwa pod Mezőkeresztes (Haçova)", "da308ec5"], "d": ["W największej bitwie polnej Długiej Wojny (1593–1606) armia, na której czele osobiście stał Mehmed III, w chwili gdy zaczęła się rozpadać, zebrała się dzięki namowom Hoca Sâdeddina Efendiego i rozbiła armię habsburską. Uważa się ją za ostatnią wielką klasyczną bitwę polną wygraną przez Osmanów; to, że nie zmieniła ogólnego przebiegu wojny, uznano jednak także za oznakę wyczerpania systemu wojskowego.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Pokój w Zsitvatorok", "39c01142"], "d": ["Traktat, który zakończył trzynastoletnią wyczerpującą wojnę, po raz pierwszy uznał władcę Habsburgów za równego sułtanowi z tytułem „cesarza rzymskiego” i zniósł coroczną daninę. Strata terytorialna była znikoma; ta zmiana języka dyplomatycznego odczytywana jest jednak jako symbol końca osmańskich pretensji do absolutnej wyższości wobec Europy.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Traktat w Kasr-ı Şirin", "c1acf3af"], "d": ["Traktat podpisany po odebraniu Bagdadu przez Murada IV (1638) zakończył ponadstuletnie wojny osmańsko-safawidzkie. Bagdad i Irak pozostały ostatecznie przy Osmanach, Erywań oddano Safawidom; wytyczona linia z drobnymi zmianami stała się podstawą dzisiejszej granicy turecko-irańskiej i uchodzi za jedną z najtrwalszych granic świata. Traktat pozostawił Osmanom Bedrę, Cessân, Mendelî, Derteng i Dernę; twierdza graniczna Zencir miała zostać zburzona, wsie na jej zachód miały przypaść Osmanom, a na wschód — Iranowi. Okolice twierdzy Zalim w pobliżu Şehrizoru oraz Kızılca Kale pozostały przy Osmanach, Awroman i Mihriban przy Iranie; twierdze Kotur, Mâkû i Mağazberd miały zostać zburzone przez obie strony.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Zakończenie zdobywania Krety", "e0d85604"], "d": ["Oblężenie Kandii, ostatni akt wojny kreteńskiej rozpoczętej w 1645 roku, zakończyło się trzyletnią zdecydowaną kampanią Fâzıla Ahmeda Paszy; wenecki dowódca Morosini oddał miasto na mocy układu. Trwająca około ćwierć wieku walka weszła do historii jako najdłuższe oblężenie w dziejach osmańskich; ostatnia wielka łacińska twierdza wschodniej części Morza Śródziemnego weszła pod zarząd osmański. Trzy małe skaliste twierdze na północnym wybrzeżu wyspy — Suda, Spinalonga i Grambousa — pozostały jeszcze przy Wenecji; ponieważ leżą na odrębnych wysepkach, nie można ich na mapie pokazać oddzielnie od reszty Krety.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Traktat w Buczaczu — najdalsze granice", "b17b6e5a"], "d": ["Na mocy traktatu w Buczaczu, podpisanego po zdobyciu Kamieńca w wyprawie polskiej, Podole przyłączono do Osmanów, a część Ukrainy objęto protektoratem. Imperium osiągnęło w ten sposób swoje największe granice w Europie; punkt ten uważa się za szczyt epoki ekspansji, a zarazem jej ostatnie ogniwo.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Klęska pod Wiedniem (II oblężenie)", "7d889252"], "d": ["Trwające dwa miesiące oblężenie Wiednia pod wodzą Merzifonlu Kara Mustafy Paszy zakończyło się klęską wskutek nagłego uderzenia króla Polski Jana Sobieskiego ze wzgórz Kahlenbergu; armia wycofała się, porzucając ciężary, a Merzifonlu został stracony w Belgradzie. W następstwie zwycięstwa powstała Święta Liga, a wojna trwała 16 lat; klęskę tę wskazuje się jako początek wielkiego upadku w dziejach osmańskich.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Zdobycie twierdzy Grambousa — jednej ze skalistych twierdz Krety pozostających przy Wenecji", "3ddf9eeb"], "d": ["Choć po kapitulacji Kandii w 1669 roku zdobycie Krety uważano w dużej mierze za zakończone, skalista wyspa-twierdza Grambousa na północno-zachodnim krańcu wyspy pozostała w rękach Wenecji jeszcze dwadzieścia trzy lata. Jej zajęcie w 1692 roku usunęło jedną z trzech weneckich pozostałości na Krecie; Suda i Spinalonga miały czekać do wyprawy na Morea w 1715 roku.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Pokój w Karłowicach — pierwsza wielka utrata ziem", "8f7e2546"], "d": ["Na mocy traktatu w Karłowicach, kończącego szesnastoletnie wojny Świętej Ligi, Węgry i Siedmiogród oddano Austrii, Podole Polsce, a Morea i wybrzeża Dalmacji Wenecji. Po raz pierwszy w dziejach osmańskich terytorium tej skali traciło się przy stole negocjacyjnym i na stałe; traktat uważa się za dokument otwierający nową epokę, w której imperium przeszło w Europie do obrony, i jest także punktem zwrotnym w historii dyplomacji osmańskiej. Miejscowości, które w atlasie zmieniły właściciela tego samego dnia: Kostajnica i Jasenovac (od Osmanów do Habsburgów; tekst traktatu pozostawia Castanoviz w rękach cesarza, dzień wydania Jasenovaca nie występuje w źródle, wpisano dzień traktatu) oraz Preweza (od Wenecji do Osmanów; TDV karlofca: zgodnie z postanowieniem podpisanym 24 Receb 1110 / 26 stycznia 1699 zwrócono zajęte przez Wenecję miejsca na północ od zatoki Lepanto). Atlas zapisuje ponadto Kostajnicę (Kostajnica) i Jasenovac po stronie habsburskiej, Umań i Winnicę na Ukrainie Prawobrzeżnej od Osmanów do Polski (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: panowanie tureckie 1672–99) oraz Nadin w Dalmacji na rzecz Wenecji (dzień wydania właściwy dla miejscowości nie występuje w źródle, wpisano dzień traktatu; krańce okresu Nadinu nie zostały zweryfikowane źródłowo — przybliżenie z deklaracją). Vonitsa na północ od zatoki Lepanto również zostaje zwrócona przez Wenecję Osmanom (TDV karlofca); Vrana (Urana) w Dalmacji należy do miejsc pozostających przy Wenecji (kraniec okresu niezweryfikowany — z deklaracją).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Zwycięstwo nad Prutem", "2583572f"], "d": ["W wojnie wywołanej sprawą króla Szwecji, który po klęsce pod Połtawą schronił się u Osmanów, armia cara Piotra I została otoczona nad Prutem i zmuszona do kapitulacji. Na mocy podpisanego traktatu Azow odzyskano; to, że armii nie zniszczono, a cara wypuszczono, weszło do historii jako decyzja dyskutowana do dziś.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Zdobycie twierdz Suda i Spinalonga — wymazanie ostatniego weneckiego śladu na Krecie", "7261f7ba"], "d": ["Dwadzieścia trzy lata po upadku Grambousy w 1692 roku, w ramach pobocznej gałęzi wyprawy na Morea, zdobyto także Sudę i Spinalongę, ostatnie dwa weneckie punkty oparcia na Krecie. W ten sposób zdobywanie Krety, rozpoczęte w 1645 roku, zostało po czterdziestu sześciu latach dokończone co do ostatniego centymetra wyspy.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Powstanie Patrony Halila", "100941a4"], "d": ["Niepowodzenie na froncie perskim, podatki i gniew wywołany przepychem dworskiego otoczenia przerodziły się w wielkie powstanie pod wodzą łaziebnego Patrony Halila. Wielki wezyr İbrahim Pasza został zabity, Ahmed III zdetronizowany, a Epoka Tulipanów dobiegła końca; to, że powstańcy przez miesiące władali miastem, dobitnie ukazało kruchość władzy centralnej.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Pokój belgradzki — odzyskanie Belgradu, Smedereva i północnej Serbii", "ba7f8e46"], "d": ["Na zakończenie wojny prowadzonej na dwóch frontach przeciw Austrii i Rosji (1736–1739) odzyskano Belgrad i Serbię Północną; Rosja zgodziła się rozbroić Azow i nie utrzymywać floty na Morzu Czarnym. Traktat, uważany za ostatni wielki sukces dyplomacji i armii osmańskiej XVIII wieku, zapewnił imperium ćwierćwieczny okres pokoju. Inne miejscowości wracające tego samego dnia z Austrii do Osmanów w atlasie: Hisarcık (Grocka) (łańcuch ośrodka-brata Belgradu; TDV belgrad), Krajowa (Craiova), Râmnicu Vâlcea (Rimnik) i Turnu Severin (powrót Małej Wołoszczyzny do Osmanów, w zależności wasalnej od Wołoszczyzny). Bosanski Brod i Bosanska Dubica w pasie Sawy wracają w atlasie do Osmanów 28 września 1739 roku (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 września 1739). Tîrgu Jiu w Małej Wołoszczyźnie wraca do Osmanów tego samego dnia.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Pożar floty pod Çeşme", "840b30bd"], "d": ["Flota rosyjska, która z pomocą Anglików wypłynęła na Morze Śródziemne, napadła okrętami ogniowymi na flotę osmańską schronioną w porcie Çeşme i niemal całkowicie ją spaliła. Rosja po raz pierwszy ukazała się na Morzu Śródziemnym jako wielka potęga morska; katastrofa była jednym z ciosów, które przesądziły o losach wojny prowadzącej do Küczük Kajnardży w 1774 roku, i uwidoczniła potrzebę gruntownej reformy floty.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Traktat w Küczük Kajnardży", "2776dcdb"], "d": ["Küczük Kajnardża, kończąca wojnę 1768–1774 i uważana za jeden z najcięższych traktatów w dziejach osmańskich, dała Chanatowi Krymskiemu „niepodległość” — faktycznie stworzono w ten sposób rosyjską strefę wpływów. Rosja osiadła na wybrzeżu Morza Czarnego, zyskała dla statków handlowych prawo przepływu przez cieśniny i stałe poselstwo w Stambule; niejasna klauzula protektoratu nad prawosławnymi poddanymi uchyliła drzwi do uzasadniania interwencji w następnym stuleciu. Po raz pierwszy ziemia zamieszkana przez ludność muzułmańską wychodziła spod władzy osmańskiej.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Aneksja Krymu przez Rosję", "bdf6faa8"], "d": ["„Niepodległy” Krym, stworzony przez Küczük Kajnardżę, został anektowany przez Rosję na mocy manifestu Katarzyny II, pod pretekstem zamętu za panowania ostatniego chana Şahina Gireja. Trzystuletnie osmańsko-krymskie partnerstwo dobiegło końca; utrata północnych stepów odebrała Stambułowi głębię obronną i zapoczątkowała pierwszą wielką falę migracji dziesiątków tysięcy Tatarów krymskich na ziemie osmańskie. Tego dnia półwysep krymski (Ałuszta, Kafa, Sudak, Jałta, Bałakława, İnkirman, Mangup, Arabat) przyłączono do Rosji; Taman i Kubań przeszły do Rosji w tej samej aneksji (TDV Kırım: 8 kwietnia 1783 juliański = 19 kwietnia gregoriański).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III i Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, który wstąpił na tron w środku wojny, dostrzegłszy, że porażki mają charakter strukturalny, rozpoczął kompleksowy program reform pod nazwą „Nizâm-ı Cedîd” (Nowy Ład): nowa armia szkolona na europejską modłę, odrębny skarb ją finansujący (Îrâd-ı Cedîd), wzmocnienie szkół inżynierskich i pierwsze stałe poselstwa w stolicach europejskich. Program uchodzi za początek nowożytnej tureckiej tradycji reform; miał jednak zostać obalony w 1807 roku wskutek oporu korpusów i ajanów.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Likwidacja joannitów na Malcie — przystanek floty francuskiej w drodze", "d62f901d"], "d": ["Flota francuska płynąca do Egiptu zawinęła do leżącej na jej drodze Malty; rycerze św. Jana (maltańscy) oddali wyspę bez większego oporu. Tym samym dobiegła końca ostatnia twierdza zakonu rycerskiego, który po wygnaniu z Rodos w 1522 roku osiadł tutaj. Malta miała po dwóch latach przejść w ręce Anglii, a Napoleon skierował się z wyspy bezpośrednio do Aleksandrii.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Inwazja Napoleona na Egipt", "93fede5f"], "d": ["Armia generała Bonapartego wylądowała w Aleksandrii i zajęła Egipt; wyprawa, mająca na celu drogę Anglii do Indii, była pierwszym bezpośrednim atakiem europejskiej potęgi na centralne ziemie osmańskie. Atak Nelsona pod Abukirem i obrona Akki przez Cezzâra Ahmeda Paszę złamały pochód francuski; okupacja zakończyła się w 1801 roku, lecz w pozostawionej przez nią próżni rozpoczęły się wzrost znaczenia Mehmeda Alego Paszy z Kawali i era „kwestii wschodniej”.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i İttifak", "cce49ef5"], "d": ["Dokument podpisany między pałacem a potężnymi rodami ajanów w prowincji pod przewodnictwem Alemdara Mustafy Paszy, ajana Ruse, który wprowadził na tron Mahmuda II; ajanowie zobowiązali się do wierności sułtanowi i wsparcia wojskowego, a państwo uznało ich istnienie i prawa. Ponieważ było to pierwsze w dziejach osmańskich ograniczenie władzy sułtana dokumentem, niektórzy historycy uznają go za dalekie źródło tradycji konstytucyjnej; faktycznie w ciągu kilku miesięcy stracił skuteczność.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Wybuch powstania greckiego", "a7293715"], "d": ["Powstanie przygotowane przez organizację Filiki Eteria wybuchło najpierw w Wołoszczyźnie, a następnie z główną siłą na Peloponezie (Morea); państwo, zajęte sprawą Alego Paszy z Tepedelen, spóźniło się z pierwszą interwencją. Dzięki silnej sympatii dla Greków w europejskiej opinii publicznej (filhellenizm) powstanie szybko stało się sprawą międzynarodową; tak zapalił się lont pierwszego udanego ruchu niepodległościowego epoki nacjonalizmu na ziemiach osmańskich. W tym samym dniu utracono także inne miejscowości: Ateny, Balyabadra (Patras), İstefe (Teby), Livadya, Eleusis (Attyka), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Pierwsze zbrojne powstanie na Peloponezie", "77e6250f"], "d": ["Po przekroczeniu Prutu powstanie przeniosło się na Peloponez: zbrojne wystąpienie rozpoczęte w Kalawrycie (21 marca juliańskiego) podjęły ruchy w Patras, Kalamacie i Mani; Morea wkrótce przekształciła się w powstanie powszechne, a administracja osmańska utraciła większą część półwyspu. W tym samym dniu utracono także inne miejscowości: Ateny, Balyabadra (Patras), İstefe (Teby), Livadya, Eleusis (Attyka), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — likwidacja korpusu janczarów", "08c9372a"], "d": ["Janczarzy, którzy zbuntowali się przeciw ćwiczeniom nowo utworzonego korpusu Eşkinci, zostali zniszczeni w koszarach na Etmeydanı ogniem dział lojalnych oddziałów przygotowanych wcześniej przez Mahmuda II; korpus rozwiązano wraz z wszystkimi oddziałami i związanymi z nim tekke bektaszytów. Operacja, która weszła do historii pod nazwą oznaczającą „pomyślne wydarzenie”, likwidując czterowiekową instytucję, utorowała drogę armii Asâkir-i Mansûre-i Muhammediyye i wszystkim późniejszym reformom centralizacyjnym.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Bitwa pod Nawarynem", "ee579e7f"], "d": ["Flota osmańsko-egipska, tłumiąca powstanie greckie, została spalona pod Nawarynem przez połączoną flotę angielsko-francusko-rosyjską, która weszła do portu bez wypowiedzenia wojny; utracono prawie sześćdziesiąt okrętów i tysiące marynarzy. Starcie, w dyplomacji europejskiej zbywane jako „nieszczęśliwy wypadek”, faktycznie zagwarantowało niepodległość Grecji i otworzyło drogę wojnie osmańsko-rosyjskiej 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Edykt Tanzimatu", "5042ce7b"], "d": ["Hatt-ı Hümâyun odczytany w Gülhane objął gwarancją państwa bezpieczeństwo życia, mienia i honoru wszystkich poddanych bez różnicy wyznania; ogłoszono zasady sprawiedliwości w podatkach, porządku w służbie wojskowej i niewymierzania kar bez procesu. Edykt, dzieło Mustafy Reşida Paszy, uchodzi za pierwszy wielki dokument o charakterze konstytucyjnym w osmańskiej modernizacji, a „Epoka Tanzimatu” (1839–1876) dała nazwę epoce reform; w tych ramach przeprowadzono gruntowną przebudowę administracji, prawa, oświaty i finansów.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Początek wojny krymskiej", "3b9ca3c8"], "d": ["Kryzys wywołany sprawą miejsc świętych i rosyjskimi pretensjami do protektoratu nad prawosławnymi poddanymi przerodził się w otwarty konflikt po wypowiedzeniu wojny przez Osmanów; po ataku na Synopę Anglia i Francja (później Piemont) przystąpiły do wojny po stronie osmańskiej. Wojna, w której armie sprzymierzonych wylądowały na Krymie i zdobyły Sewastopol, została wygrana traktatem paryskim z 1856 roku; jednak pierwsza pożyczka zagraniczna zaciągnięta w latach wojny (1854) wciągnęła imperium w spiralę zależności finansowej trwającej pół wieku.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Edykt Islahat (Reformy)", "78ff234d"], "d": ["Edykt ogłoszony przed rokowaniami pokojowymi w Paryżu, rozszerzając zasady Tanzimatu, przyznał poddanym niemuzułmańskim szerokie prawa równości, w tym dostęp do służby państwowej, służby wojskowej i otwierania szkół; przeorganizowano też organizacje wspólnot. Na mocy podpisanego następnie traktatu paryskiego państwo osmańskie zostało oficjalnie przyjęte do rodziny europejskiego prawa międzynarodowego, a jego integralność terytorialna objęta wspólną gwarancją wielkich mocarstw — gwarancja ta miała w praktyce stać się nową bramą interwencji.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — I Monarchia Konstytucyjna", "0fe052c1"], "d": ["W dniu otwarcia międzynarodowej konferencji zebranej w Stambule dla omówienia kryzysu bałkańskiego ogłoszono salwami armatnimi pierwszą konstytucję osmańską; na mocy Kanûn-ı Esâsî, dzieła ruchu „Nowych Osmanów” pod przewodnictwem Midhata Paszy, utworzono parlament dwuizbowy. Meclis-i Meb'ûsan został otwarty w marcu 1877 roku; jednak Abdülhamid II, powołując się na wojnę 93, w lutym 1878 roku zawiesił parlament na czas nieokreślony, a konstytucja pozostała zawieszona przez trzydzieści lat.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Wojna 93 (wojna osmańsko-rosyjska 1877–78)", "5bd96af7"], "d": ["W wojnie nazywanej „Wojną 93” z powodu zbieżności z rokiem 1293 według kalendarza rumi armie rosyjskie uderzyły na dwóch frontach; choć obrona Plewny przez Gazi Osmana Paszę i bitwy kaukaskie Ahmeda Muhtara Paszy obrosły legendą, front się załamał i Rosjanie dotarli aż do Yeşilköy (San Stefano). Wojna wywołała wielkie fale muzułmańskich migracji z Bałkanów i Kaukazu do Stambułu, których skutki sięgają dziś; struktura demograficzna i finansowa imperium nigdy już nie wróciła do dawnego stanu.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Traktat berliński", "47f76a49"], "d": ["Kongres Berliński, rewidując w imię równowagi wielkich mocarstw „Wielką Bułgarię” stworzoną w San Stefano, pozostawił mimo to ciężki obraz: Serbia, Czarnogóra i Rumunia stały się niepodległe; utworzono autonomiczne Księstwo Bułgarii; Bośnię i Hercegowinę oddano pod okupację austriacką, Cypr pod zarząd angielski, a Kars, Ardahan i Batum Rosji. Pięćsetletni ład osmański w Rumelii w znacznej mierze się rozpadł; „kwestia wschodnia” stała się stałym punktem europejskiej dyplomacji. W tym samym dniu utracono także inne miejscowości: Płowdiw, Widyń, Tyrnowo, Warna, Şumnu, Silistra, Ruse, Bukareszt, Jassy, Konstanca. Rumunia w zamian za oddanie Besarabii Rosji otrzymała Tulczę (Tulcea) i Dobrudżę: Tulcea, Babadag, Măcin, Isaccea, Hârșova i Mangalia w Północnej Dobrudży przeszły do Rumunii.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Okupacja Tunezji i Düyûn-ı Umûmiyye", "c7e25598"], "d": ["Francja, pod pretekstem incydentów na granicy algierskiej, zajęła Tunezję i objęła ją protektoratem na mocy traktatu z Bardo; obecność osmańska w Afryce Północnej ograniczyła się do Trypolisu. Dekretem Muharrema wydanym w tym samym roku utworzono Administrację Długu Publicznego (Düyûn-ı Umûmiyye), w której reprezentowani byli wierzyciele, w celu zarządzania zbankrutowanym długiem zagranicznym: podstawowe dochody, takie jak sól, tytoń i jedwab, przekazano bezpośrednio tej zagranicznej administracji, co poważnie ograniczyło suwerenność finansową. W tym samym dniu utracono także inne miejscowości: Kairouan, Gabès, Sfaks, Dżerba (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Brytyjska okupacja Egiptu", "f1269768"], "d": ["Ruch Urâbîego Paszy, który wzbierał przeciw bankructwu finansowemu i obcej kontroli w Egipcie, został zgnieciony po bombardowaniu Aleksandrii zwycięstwem wojska angielskiego wylądowanego pod Tel el-Kebir, a Kair zajęto. Choć Egipt formalnie pozostał związany z Osmanami, faktycznie przeszedł pod zarząd brytyjski; kontrola nad Kanałem Sueskim znalazła się w centrum brytyjskiej strategii imperialnej.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Proklamowanie II Monarchii Konstytucyjnej", "95ee2fd2"], "d": ["Wobec ruchu, który narósł po wyjściu w góry w Macedonii oficerów związanych z Komitetem Jedności i Postępu, Abdülhamid II przywrócił moc Kanûn-ı Esâsî; „ogłoszenie wolności” powitano z entuzjazmem i przeprowadzono wybory. Stabilności jednak nie osiągnięto: po stłumieniu wydarzenia 31 marca (kwiecień 1909) Abdülhamid został zdetronizowany; niepodległość Bułgarii, aneksja Bośni i skierowanie się Krety ku Grecji nastąpiły w tych burzliwych miesiącach.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Wojna o Trypolitanię", "ed441994"], "d": ["Włochy, poszukujące kolonii, wypowiedziały wojnę Trypolitanii, ostatniej ziemi osmańskiej w Afryce Północnej, i zajęły wybrzeża; ponieważ państwo bez floty nie mogło wysłać regularnej armii, młodzi oficerowie, tacy jak Mustafa Kemal i Enver Bej, potajemnie przeszli do regionu i zorganizowali skuteczny opór z plemionami Senûsî. Na mocy traktatu z Ouchy (18 października 1912), podpisanego po wybuchu wojny bałkańskiej, Libię oddano Włochom; Włochy zajęły też Rodos i Dodekanez.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Traktat londyński — utrata Rumelii", "f3f976df"], "d": ["Na mocy traktatu londyńskiego kończącego I wojnę bałkańską utracono wszystkie ziemie na zachód od linii Midye–Enez oraz wyspy Morza Egejskiego; Albania stała się niepodległa. Z Rumelii, od ponad pięciu wieków demograficznego, gospodarczego i kulturalnego środka ciężkości imperium, miała pozostać jedynie Tracja Wschodnia (Edirne odzyskano w II wojnie bałkańskiej); strata gruntownie zaostrzyła politykę wojenną i osadniczą rządu młodoturków. Utracono następujące miejscowości leżące na zachód od linii Midye–Enez: Skopje, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Monastyr, Ochryda, Debar (Dibra), Prizren, Prisztina, Peć (Pejë), Yenipazar (Novi Pazar), Kosowo Pole (Kosovo Polje); Serez, Drama, Kawala, Petriç, Nevrokop, Xanthi (İskeçe), Gümülcine, Dedeağaç, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); na Krecie Chania, Kandia, Kreta (Resmo), Sitia i Sfakia (İsfakiye).", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Przystąpienie do I wojny światowej", "05a0252e"], "d": ["Wpuszczenie przez cieśninę pancerników Goeben i Breslau, uciekających przed Anglią i przedstawionych jako zakupione, krok po kroku przeciągnęło państwo na stronę Niemiec; wojna faktycznie rozpoczęła się, gdy flota pod dowództwem admirała Souchona ostrzelała rosyjskie porty (29 października), a wzajemne wypowiedzenia nastąpiły na początku listopada. Mimo ogłoszenia Cihâd-ı Ekber oczekiwany skutek nie nastąpił; imperium przez cztery lata toczyło wojnę o przetrwanie na pięciu odrębnych frontach, od Kaukazu po Palestynę.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Zwycięstwo pod Çanakkale", "95d888e8"], "d": ["Armada sprzymierzonych, mająca na celu zdobycie Stambułu i dotarcie do Rosji, została 18 marca odparta z cieśniny ogniem pól minowych i fortów; linia położona przez stawiacz min Nusret przesądziła o losach bitwy. Rozpoczęta w kwietniu lądowa operacja na Gallipoli została zatrzymana pod Anafartalar i Conkbayırı; sprzymierzeni całkowicie ewakuowali półwysep w styczniu 1916 roku. Na tym froncie zasłynęło nazwisko podpułkownika Mustafy Kemala; zwycięstwo okupione około ćwierćmilionem poległych i zaginionych uważa się za miejsce narodzin kadr i ducha Walki Narodowej.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Powstanie szeryfa Husajna", "75f7c58c"], "d": ["Szeryf Mekki Husajn, po tajnej korespondencji z Anglikami, wzniósł powstanie w zamian za obietnicę niepodległego królestwa arabskiego; kolej hidżaska stała się celem napadów. Choć legendarna obrona Medyny przez Fahreddina Paszę, trwająca aż do czasu po rozejmie, pozostała symbolem oporu, powstanie połączone z brytyjskim natarciem na froncie palestyńskim przyspieszyło rozpad władzy osmańskiej w prowincjach arabskich. W tym samym dniu utracono także inne miejscowości: Ta'if.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Rozejm w Mudros", "9e87c767"], "d": ["Państwo osmańskie, którego fronty zostały od siebie odcięte wskutek załamania się Bułgarii, wycofało się z wojny na mocy rozejmu podpisanego na pancerniku Agamemnon. Otwarcie cieśnin oraz artykuł 7, pozwalający na okupację miejsc, których bezpieczeństwo było zagrożone, szybko uczyniono prawną przykrywką faktycznego rozbioru: zajęto Mosul, İskenderun, następnie Izmir i Stambuł. Rozejm uważa się za dokument faktycznego końca imperium. W tym samym dniu utracono także inne miejscowości: Hama, Damaszek, Hims.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal w Samsun — Walka Narodowa", "09a8f784"], "d": ["W atmosferze oburzenia wywołanego okupacją Izmiru Mustafa Kemal Pasza, który jako inspektor 9. Armii wylądował w Samsun, zwrócił swoje oficjalne zadanie ku organizowaniu oporu w Anatolii. Okólnik z Amasyi oraz kongresy w Erzurum i Sivas są jego dalszym ciągiem; zasada „niepodległość narodu uratuje znów determinacja i decyzja narodu” stała się jądrem politycznego programu Walki Narodowej.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Otwarcie Wielkiego Zgromadzenia Narodowego Turcji i Sèvres", "2008feec"], "d": ["W następstwie oficjalnej okupacji Stambułu i rozwiązania Meclis-i Meb'ûsan 23 kwietnia 1920 roku w Ankarze otwarto Wielkie Zgromadzenie Narodowe; zgromadzenie, które skupiło w sobie nadzwyczajne uprawnienia, stało się zalążkiem nowego państwa opartego na woli narodu. Traktat z Sèvres podpisany w sierpniu przez rząd stambulski rozbierał Anatolię; Zgromadzenie ogłosiło sygnatariuszy zdrajcami ojczyzny, a Sèvres nigdy nie weszło w życie.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Bitwa nad Sakarią", "f2f970a6"], "d": ["Greckie natarcie, które zbliżyło się do Ankary na 50 kilometrów, zostało załamane w trwającej 22 dni i 22 noce bitwie, prowadzonej według rozkazu Mustafy Kemala Paszy, który objął uprawnienia naczelnego wodza: „Nie ma linii obrony, jest powierzchnia obrony”. Armia grecka po raz pierwszy przeszła do obrony strategicznej; zwycięstwo przyniosło Mustafie Kemalowi tytuł gazi i stopień marszałka (müşir) i otworzyło drogę do porozumienia z Francją w Ankarze oraz do uznania międzynarodowego.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Wielka Ofensywa i wyzwolenie Izmiru", "172a50c4"], "d": ["Natarcie rozpoczęte rankiem 26 sierpnia z Kocatepe doprowadziło 30 sierpnia pod Dumlupınar, w Bitwie Naczelnego Wodza, do zniszczenia głównych sił greckich; w pościgu prowadzonym pod rozkazem „Armie, waszym pierwszym celem jest Morze Śródziemne, naprzód!” Izmir wyzwolono 9 września. Na mocy rozejmu w Mudanyi (11 października) Trację Wschodnią odzyskano bez walki; zwycięstwo wojskowe przesądziło o sile przetargowej nowego państwa przy stole w Lozannie.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Zniesienie sułtanatu", "9f36a9f6"], "d": ["Wobec zaproszenia także rządu stambulskiego na rokowania w Lozannie Wielkie Zgromadzenie Narodowe 1 listopada 1922 roku rozdzieliło sułtanat i kalifat i zniosło sułtanat; 623-letnie rządy dynastii osmańskiej zakończyły się prawnie. Mehmed VI Vahideddin opuścił kraj 17 listopada na pokładzie brytyjskiego pancernika; na urząd kalifa uchwałą Zgromadzenia wprowadzono Abdülmecida Efendiego, a ten urząd miał zostać zniesiony 3 marca 1924 roku.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Traktat lozański", "38c27f7d"], "d": ["Na mocy traktatu pokojowego z Lozanny, podpisanego po ośmiu miesiącach trudnych negocjacji, uznano na arenie międzynarodowej granice, pełną niepodległość i suwerenność nowego państwa tureckiego; zniesiono kapitulacje, rozpoczęto likwidację Düyûn-ı Umûmiyye i uregulowano wymianę ludności. Lozanna, która faktycznie unieważniła Sèvres, uchodzi za dyplomatyczne zwycięstwo Walki Narodowej i założycielski dokument zewnętrzny Republiki.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Proklamowanie Republiki", "d5bfcdfb"], "d": ["Republikę ogłoszono, gdy Wielkie Zgromadzenie Narodowe w drodze zmiany konstytucji przyjęło postanowienie, że „formą rządu Państwa Tureckiego jest republika”; Mustafa Kemal Pasza został wybrany pierwszym prezydentem. Tak zamknęła się 624-letnia przygoda osmańska, rozpoczęta w 1299 roku jako pogranicznego bejliku, a nowe państwo, w którym suwerenność należy bez zastrzeżeń do narodu, powstało na spuściźnie imperium.", "f5cabb8c"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Włączenie pustynnego ośrodka Senusijji, Dżaghbub, do osmańskiego ładu — ferman Abdülmecida o zwolnieniu", "039fce6d"], "d": ["Muhammad b. Ali as-Sanusi, który przez wiele lat przebywał w Mekce, po powrocie do Trypolitanii osiadł w oazie Dżaghbub na granicy egipskiej i kazał zbudować na dominującej skale wielką zawiję; miejsce złożone z kilku baraków wkrótce przekształciło się w miasto. W 1856 na mocy fermanu sułtana Abdülmecida mienie należące do członków tarikatu zwolniono z podatku, a muridom przyznano prawo zbierania zakatu. Ten ferman uczynił oazę leżącą na szlaku karawan łączącym Afrykę Zachodnią i Sudan z Kairem częścią osmańskiego ładu finansowego i administracyjnego i umocnił Dżaghbub jako ośrodek handlu. Przywiązanie ludności regionu do kalifa potwierdza także relacja z podróży pułkownika Sâdıka al-Mu'ayyada, który w 1884 i 1893 zwiedził to miejsce.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Początek kopania Kanału Sueskiego i założenie Port Saidu", "cef0be8d"], "d": ["Prace kopania projektu Lessepsa, który Bâbıâli zatwierdziło 5 stycznia 1856, rozpoczęły się 25 kwietnia 1859; kanał miał zostać ukończony po dziesięciu latach, 16 listopada 1869. Wioska barakowa złożona z pięciu domów dla robotników, założona na kordonie brzegowym między jeziorem Manzala a morzem, na śródziemnomorskim krańcu kopania, stała się jądrem Port Saidu. Miastu nadano tę nazwę, oznaczającą „port Saida”, w 1860 urzędnicy spółki kanałowej ku czci ówczesnego namiestnika Egiptu Saida Paszy. W ten sposób na osmańskiej mapie narodził się nowy port na pasie wybrzeża, na którym wcześniej nie było żadnej miejscowości.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Wizyta sułtana Abdülaziza w Egipcie i założenie İsmâiliya na przesmyku sueskim", "bcfacf38"], "d": ["Sułtan Abdülaziz udał się z zachęty wielkiego wezyra Yûsufa Kâmila Paszy 3 kwietnia 1863 do Egiptu i został przyjęty wielkimi owacjami; celem było wzmocnienie więzi z centrum prowincji, która od powstania Mehmeda Alego Paszy z Kawali zaczęła faktycznie przybierać postać odrębnego państwa. W tym samym roku na przesmyku, na wzgórzach Tilâl al-Dżisr nad brzegiem Jeziora Krokodyli, założono centrum zarządu spółki kanałowej: najpierw osiedlono wsie Karyat at-Timsah dla inżynierów, a następnie Karyat al-Arab dla robotników. Gdy chediw İsmâil Pasza żywo interesował się kanałem słodkowodnym i kazał zbudować sobie na tym wzgórzu pawilon, osada zaczęła być nazywana od jego imienia İsmâiliya. Założenie miasta datuje się na rok 1863; dokładny dzień nie jest znany.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Namiestnictwo Midhata Paszy w Bagdadzie i osiedlenie plemion — założenie Ramâdi i Nâsıriye", "0fa98f06"], "d": ["Midhat Pasza, odsunięty od Stambułu i odwołany ze stanowiska przewodniczącego Şûrâ-yı Devlet, zarządzał w latach 1869–1872 wilajetem Bagdadu, obejmującym także Mosul i Basrę, z szerokimi uprawnieniami, mając też w ręku dowództwo VI Armii. Stosując tu Kanunname Gruntowe i nowe prawo wilajetowe, rozdzielał ziemie za pomocą tapu i wiązał koczownicze plemiona z osiadłym ładem i autorytetem państwa. Plonem tej polityki osiedleńczej było założenie w 1869 nad Eufratem Ramâdi dla plemienia Dulaym, a na południu, rękami mutasarrifa Muntafiqów Nâsıra Paszy as-Sa'dûna, Nâsıriye; oba miasta powstały w punktach, w których do tej pory nie było osady, i po raz pierwszy weszły na mapę w tej dacie.", "7babb36f"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["Po klęsce pod Ankarą wojewoda Wołoszczyzny Mircea ponownie zajął Dobrudżę — Silistra, Konstanca, Babadag, İshakçı", "5eaefc68"], "d": ["Klęska Bajezida Błyskawicy z Timurem pod Ankarą zachwiała zwierzchnictwem osmańskim nad Dunajem. Wojewoda Wołoszczyzny Mircea, wykorzystując tę lukę, ponownie wszedł do Dobrudży; Silistra, okolice Konstancy i Babadagu oraz İshakçı nad Dunajem przez lata Interregnum pozostawały w jego rękach. Mircea poparł Musę Çelebiego przeciwko Çelebiemu Mehmedowi. Silistrę utrzymał do śmierci w 1418 roku.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["Przejście Babadagu i okolic do Osmanów — pobicie Mirceę i jego syna Mihaila", "bfda2c60"], "d": ["Çelebi Mehmed, po pobiciu wojewody Wołoszczyzny Mircei i jego syna Mihaila, objął zwierzchnictwem osmańskim Babadag i okolice w Dobrudży Północnej. Babadag był miasteczkiem noszącym imię Saltuka Baby, założonym w XIII wieku przez osadnictwo turkmeńskie. Pobliskie Silistra, Konstanca i inne twierdze dobrudżańskie pozostały zaś do 1419 roku na Wołoszczyźnie; zatem Babadag przez trzy lata widnieje jako wyspa (eksklawa) oderwana od ziem osmańskich.", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["Odzyskanie Silistry i Dobrudży — po śmierci Mircei", "73eb6ae9"], "d": ["Zamieszanie na Wołoszczyźnie po śmierci wojewody Mircei w 1418 roku dało Çelebiemu Sułtanowi Mehmedowi okazję do odzyskania Silistry i Dobrudży. Wiosną 1419 roku Silistra, Konstanca i większa część Dobrudży ponownie weszły pod rządy osmańskie; twierdze Enisala (Yenisale) i İshakçı zostały naprawione i uczynione twierdzami granicznymi (serhat); Dobrudża pozostała odtąd w rękach osmańskich do 1878 roku.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["Zamknięcie dolnego Dunaju — włączenie Giurgiu, Turnu i Orsowy", "331a0b68"], "d": ["Po zakończeniu Interregnum zabiegi Çelebiego Mehmeda o uporządkowanie linii Dunaju przyniosły owoc w 1420 roku. Twierdza Giurgiu, zbudowana przez wojewodę Wołoszczyzny Mirceę Starego na jego własnej ziemi z kosztami pokrytymi ze sprzedaży soli, w tym roku wpadła w ręce osmańskie (Dobrudża została odzyskana rok wcześniej, wiosną 1419 roku — TDV silistre), a Turnu (Kule/Holovnik) na prawym brzegu Dunaju oraz Orsowa — zwana później Fethülislâm — zostały włączone. Obie strony rzeki znalazły się w ten sposób jednocześnie pod kontrolą. Znaczenie Giurgiu wynika z jego geografii: jest to osmańska twierdza założona na lewym, czyli wołoskim brzegu Dunaju, i wraz z leżącym na przeciwnym brzegu Rusczukiem trzyma oba końce tej samej przeprawy. Dokumenty osmańskie jawnie zapisują tę dwoistość — o Rusczuku mówi się „Yergöğü bu brzeg”, a o Giurgiu „Yergöğü tamten brzeg”. Twierdza miała zostać w 1427 roku odzyskana przez Wołochów, w 1449 roku ponownie wejść pod kontrolę osmańską, a kaza Giurgiu, podporządkowana sandżakowi Nikopola, miała stać się wyspą rządzoną bezpośrednio wewnątrz wojewodztwa. Odpowiedź na pytanie, dlaczego na mapie dunajski brzeg Wołoszczyzny jest ciemny, zaczyna się tutaj.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["Region Toplicy (Kuršumlija, Prokuplje) wszedł pod zwierzchnictwo osmańskie", "e22e690d"], "d": ["Prawdopodobnie w czasie zaręczyn Murada II z Marą Branković region Dubočicy i Toplicy (okolice Leskovca, Kuršumliji i Prokuplja) przeszedł pod zwierzchnictwo osmańskie; rejestr tahrir z lat 1445-1447 pokazuje, że region został nadany osmańskim sipahim jako timary. Na mapie Kuršumlija i Prokuplje od tego roku są pod rządami osmańskimi.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["Przyłączenie równiny Saraj — powstanie osmańskiego przyczółka wewnątrz Bośni", "be5c0f00"], "d": ["Po tym, jak królowie Bośni w latach 1428-1429 zostali zobowiązani do haraczu, Osmanowie zaczęli trwale osiedlać się w głąb królestwa. W latach 1428-1435 zajęto miasteczko Hodidjed; w 852 (1448) wilajet Hodidjed wraz z równiną Saraj wszedł całkowicie pod rządy osmańskie. Był to przyczółek utworzony pośrodku królestwa piętnaście lat przed podbojem Bośni, rządzony przez beja Üsküpu Isę Beja noszącego tytuł wojewody — ponieważ wokół wciąż byli bejowie bośniaccy podlegli Osmanom, region znajdował się pod podwójną kontrolą. Samo miasto również narodziło się w tym okresie: przed 1462 rokiem İshak Bej lub jego syn Isa Bej założył pierwszą muzułmańską dzielnicę, w 862 (1458) zbudowano w imieniu Zdobywcy Meczet Hünkâr, a po zagospodarowaniu pól wsi Brodec powstało miasteczko Saraj. Zdobycie w 1463 roku zlikwidowało Królestwo Bośni; równina Saraj była już wtedy od piętnastu lat ziemią osmańską.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["Włączenie Podgoricy do ziem osmańskich — objęcie kontroli nad równiną Zety", "46e401c5"], "d": ["Miasteczko położone dwadzieścia kilometrów na północ od Jeziora Szkoderskiego, na równinie, gdzie łączą się wody Moracy i Ribnicy, w źródłach po raz pierwszy wspomniane jest w 1216 roku jako Ribnica, a w 1326 jako Podgorica. W 1457 roku zostało włączone do ziem osmańskich i kontrola nad równiną Zety wyszła w ten sposób z rąk dynastii Balšićów i Crnojevićów. Mehmed Zdobywca kazał w latach 1474-1478 zbudować twierdzę i meczet na stromych skałach u zbiegu dwóch rzek; po zdobyciu Szkodry w 1479 roku region został włączony do nowo utworzonego sandżaku szkoderskiego. Podgorica, w rejestrze z 1485 roku czterdziestodomowe miasteczko chrześcijańskie, w latach 1529-30 liczyła 800 osób oraz trzydziestodwuosobowy garnizon pod dowództwem dizdara w twierdzy, a w 1582 roku 322 domy. Evliya Çelebi w 1662 roku naliczył w Twierdzy Zdobywcy trzysta domów, magazyny, arsenały i siedmiuset strażników. Zapisy te pokazują też różnicę między równiną a górą Zety: równina jest osmańską kazą spisywaną, opodatkowaną i obsadzoną garnizonem — a jednak w XVIII wieku miasto będzie musiało zostać ufortyfikowane sześcioma bastionami i murami o trzech bramach, by zapobiegać napadom plemion z gór Czarnogóry. Podgorica wpadła w ręce Czarnogóry pod koniec wojny 1876-1878 i na mocy Traktatu Berlińskiego tam pozostała.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["Zajęcie Foči — otwarcie pierwszego wejścia do Księstwa Hercegowiny", "f098a9e6"], "d": ["Po likwidacji Królestwa Bośni w 1463 roku przyszła kolej na ziemie Stjepana Vukčicia-Kosacy, który oddzielił się od królestwa i założył własne księstwo. Foča, położona w dolinie Driny, na skrzyżowaniu szlaku handlowego łączącego Stambuł z Dubrownikiem, weszła w 1465 roku pod rządy osmańskie. Znaczenie miasta od razu zostało dostrzeżone: w 1470 roku uczyniono ją ośrodkiem nowo utworzonego sandżaku hercegowińskiego — czyli administracyjny rdzeń Hercegowiny powstał w Foči, zanim samo księstwo upadło. Włączenie całego księstwa miało potrwać do 1483 roku. Foča rozwinęła się odtąd jako ośrodek handlu i administracji dzięki korzystnemu klimatowi i położeniu na skrzyżowaniu dróg. Na mapie ta data jest dniem, w którym po podboju Bośni zaczęła się druga fala ku południu.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["Ostateczne włączenie Livna i zachodniej Bośni — ustanowienie granicy z Wenecją", "c14d4283"], "d": ["Twierdza na płaskowyżu panującym nad równiną Livno w latach 1448-1454 była w rękach Stjepana Vukčicia-Kosacy, założyciela Księstwa Hercegowiny. W wyprawie bośniackiej 1463 roku została na krótko zajęta przez siły osmańskie, lecz w tym samym roku odzyskana; w 1466 roku panem miasta jest Ivaniš Vlatković. Według TDV ostateczne zwierzchnictwo osmańskie nastąpiło z największym prawdopodobieństwem w latach 1468-1469, a rejestr z 1485 roku odnotowuje już Livno jako ziemię osmańską. Oznacza to zamknięcie zachodniego krańca podboju Bośni: Livno stało się niebezpiecznym miasteczkiem granicznym, sąsiadującym przez równinę z ziemiami weneckimi oddalonymi zaledwie o trzydzieści sześć kilometrów, i zachowało to położenie do zdobycia przez wojewodę Bośni Gazi Hüsrev Beja twierdz weneckich w latach 1521-1522.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["Utrata Böğürdelen na rzecz Węgrów — pierwsza wyrwa na linii Sawy", "129fe8f2"], "d": ["W miejscu zajętym za Mehmeda Zdobywcy i dawniej zwanym Zaslon w 1471 roku zbudowano drewniano-ziemny gródek. Ponieważ leżał w punkcie zagrażającym Belgradowi i stąd łatwo można było dokonywać napadów na południowe regiony Węgier i Austrii, twierdza od tej funkcji wzięła nazwę — Böğürdelen oznacza „bastion bijący z boku”. Król Węgier Maciej Korwin oblegał twierdzę pod koniec 1475 roku i zdobył ją w lutym 1476. Węgierski poemat Szabács viadala, opisujący oblężenie, należy do najdłuższych zachowanych tekstów XV-wiecznej węgierskiej poezji historycznej. Węgrzy utworzyli w regionie banat i przebudowawszy twierdzę w kamieniu, uczynili ją ogniwem łańcucha grodów granicznych. Osmanowie próbowali ją odzyskać w 1492 roku i im się nie udało; twierdza pozostała czterdzieści pięć lat w rękach węgierskich.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["Podbój Wysp Jońskich — koniec księstwa Tocco: Santa Maura, Kefalonia, Zakintos, Itaka", "07b27251"], "d": ["Traktat stambulski z Wenecją, podpisany w styczniu tego samego roku, pozostawił Osmanom Szkodrę i wybrzeże albańskie; Wyspy Jońskie nie podlegały jednak Wenecji, lecz rodzinie Tocco, która władała hrabstwem Kefalonii i Zakintos, i zostały zajęte odrębną operacją. Według hasła TDV o Ayamavrze ostatni książę Leonardo Tocco najpierw zachował lojalność, żeniąc się z Milicą Branković, krewną Zdobywcy, lecz po jej śmierci w 1464 roku ożenił się w 1477 roku z Francescą Marzano z dynastii neapolitańskiej i tym rozgniewał padyszacha. Dwa lata później flota pod dowództwem beja Awlony Gedika Ahmeda Paszy zajęła Santa Maurę wraz z leżącą na południu Kefalonią; Leonardo i Francesca uciekli do Włoch. Hasło o Gedik Ahmedzie Paszy odnotowuje, że w tej samej operacji zajęto także Zakintos (Zante); Itaka, należąca do hrabstwa Kefalonii, również wtedy weszła pod rządy osmańskie. W ten sposób szlak morski od ujścia Adriatyku do Morei znalazł się w całości pod kontrolą. Spośród wysp Zakintos miał zostać oddany Wenecji po trzech latach, Kefalonia i Itaka miały zostać utracone w 1500 roku, a tylko Santa Maura pozostała w rękach osmańskich przez dwa wieki.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["Podporządkowanie Zety Crnojevićów i uczynienie Cetinji ośrodkiem", "59d20267"], "d": ["Gdy Szkodra w 1479 roku pozostała w rękach osmańskich, górzysta Zeta na jej zapleczu znalazła się w granicach imperium. Rodzina Crnojevićów, władająca tym regionem, uznała po śmierci Zdobywcy zwierzchnictwo Bajezida II, który wstąpił na tron, zobowiązała się do daniny i zachowała swobodę w sprawach wewnętrznych; Ivan Crnojević przeniósł swój ośrodek z równiny do Cetinji u stóp góry Lovćen i założył miasto. Dwa lata później klasztor, który tam wzniósł, stał się religijnym ośrodkiem regionu. W ten sposób Czarnogóra pojawia się na mapie nie jako bezpośrednia ziemia osmańska, lecz jako jasno zaznaczony region zależny. Hasło TDV o Czarnogórze wspomina dynastię i biskupstwo w Cetinji i pisze, że w 1514 roku zwierzchnictwo zostało przekształcone w odrębny sandżak rękami Iskendera Beja (z rodu Crnojevićów, wychowanego na dworze osmańskim); roku 1482 TDV nie podaje — jest to data z historiografii czarnogórskiej. Z powodu surowości geografii rządy tu nigdy nie działały tak ściśle jak na równinach.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["Zdobycie twierdzy Kilia — zamek u ujścia Dunaju", "ef4eca73"], "d": ["Mołdawia była od września 1455 roku zależnym wojewodztwem płacącym dwa tysiące złotych rocznego haraczu, ale dwa jej porty otwarte na Morze Czarne wciąż były w rękach wojewody i przechodził przez nie handel z Dunaju. Bajezid II pierwszą wielką wyprawę swego panowania skierował na te dwa porty. Dowódca twierdzy Kilia, ostrzeliwanej z dział dniem i nocą przez dziesięć dni, został zmuszony do poddania się. Twierdzę włączono bezpośrednio do rządów osmańskich i uczyniono sandżakiem; w drugiej połowie XVI wieku z powodu zagrożenia kozackiego uczyniono ją kazą i podporządkowano sandżakowi Akkerman w beylerbeylijku Rumelii. Od tej chwili Mołdawia na mapie ma dwa stopnie: wewnątrz wojewodztwo w jasnym odcieniu jako ziemia zależna, a na wybrzeżu dwa porty w ciemnym odcieniu jako bezpośredni sandżak osmański. Hasło TDV o Mołdawii nazywa te dwa „kluczami i bramami Mołdawii” i pisze, że region został ostatecznie związany z Osmanami za Bajezida II.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["Zdobycie Akkermanu — ujście Dniestru i zamknięcie czarnomorskiej bramy Mołdawii", "7cb20feb"], "d": ["Dwadzieścia dni po poddaniu Kilii armia stanęła przed Akkermanem u ujścia Dniestru, a twierdzę zdobyto 4 sierpnia. Miasto było najruchliwszym portem Mołdawii; za Zdobywcy, gdy wojewoda Piotr III uznał w 1455 roku zwierzchnictwo osmańskie, kupcom z Akkermanu przyznano zezwolenie na handel, teraz port stał się bezpośrednio własnością państwa. Akkerman, po zdobyciu przekształcony w sandżak podległy beylerbeylikowi Rumelii, w 1593 roku został włączony do nowo utworzonego ejaletu Özü. W ten sposób zewnętrzna skorupa Mołdawii, otoczona od północy przez Chocim, a od południa przez Kilię i Akkerman, zaczęła wchodzić pod bezpośrednią kontrolę osmańską; wojewodztwo zachowało swobodę w sprawach wewnętrznych, ale straciło dostęp do morza. Na mapie nie ma pośrodku pustego obszaru — ciemne sandżaki portowe i jasne ziemie wojewodztwa stykają się; stepy Budziaku między nimi aż do 1538 roku wciąż są częścią wojewodztwa.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["Poddanie Lepanto — wejście do Zatoki Korynckiej zabrane Wenecji", "2cfe0777"], "d": ["Lepanto od 1407 roku było w rękach Wenecji i trzymało wejście do Zatoki Korynckiej; całe wybrzeże wewnątrz zatoki było w zasięgu tej twierdzy. W wyprawie 1499 roku twierdzę oblężono od strony lądu, a flota osmańska walcząca z flotą wenecką u wybrzeży Lepanto wspierała siły oblężnicze od strony morza. Wenecjanie w twierdzy poddali miasto Osmanom 26 sierpnia. Miasto pozostało odtąd w rękach osmańskich sto osiemdziesiąt osiem lat, w 1687 roku po utracie Morei ponownie przeszło do Wenecji, w 1715 roku zostało odzyskane. Bitwa morska tego samego lata i to poddanie są dwoma odrębnymi wydarzeniami: starcie floty miało miejsce na zachodnim krańcu Morei, na wodach Sapienza-Zonchio; Lepanto zaś padło wskutek oblężenia lądowego u wejścia do Zatoki Korynckiej.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["Włączenie banatu Srebrenik — pierwsze załamanie linii węgierskiej w północnej Bośni", "6d98c725"], "d": ["Po zniszczeniu Królestwa Bośni w 1463 roku Maciej Korwin przeszedł do przeciwnatarcia i utworzył na północy królestwa dwa banaty zatrzymujące osmańskie natarcie: na zachodzie Jajce, na północnym wschodzie Srebrenik. Były one wysuniętą linią obrony Węgier w Bośni i zamykały korytarz między Sawą a Bośnią. Banat Srebrenik zdobyto w 1512 roku; w ten sposób wschodnie skrzydło linii załamało się i sandżak İzvornik mógł rozszerzyć się ku północy. Jajce na zachodnim skrzydle miało się bronić jeszcze szesnaście lat i zostać zdobyte dopiero po Mohaczu, w 1528 roku.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Zdobycie Böğürdelen — pierwsza twierdza zdobyta przez Sulejmana Wspaniałego i miejsce decyzji o Belgradzie", "85177a90"], "d": ["W pierwszej wyprawie węgierskiej Sulejmana Prawodawcy siły beylerbeya Rumelii Ahmeda Paszy, wysłane do regionu, po zaciętym oblężeniu zdobyły twierdzę 7 lipca 1521 roku. Böğürdelen jest pierwszą twierdzą zdobytą za panowania Sulejmana. Padyszach po zdobyciu sam wszedł do twierdzy i rozkazał odbudowę miasta; zapadły tu także decyzje dotyczące zdobycia Belgradu — to znaczy plan Belgradu, który padnie 29 sierpnia 1521 roku, powstał w Böğürdelen. Twierdza pozostała odtąd w rękach osmańskich blisko dwa wieki; podlegała najpierw Rumelii, od 1580 roku ejaletowi Bośni, następnie na krótko Semendirze i wreszcie sandżakowi İzvornik. Na mapie ta data jest dniem, w którym linia Sawy zamyka się na korzyść Osmanów.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Zaczyna się powstanie trzech wojewodztw — Siedmiogród przechodzi do Świętej Ligi, aresztowani zostają beje prosmańscy", "68a33800"], "d": ["W drugim roku Długiej Wojny pas wasalny Osmanów w Europie Środkowej rozpadł się nagle. Do Świętej Ligi, zawiązanej pod patronatem papieża Klemensa VIII, przeszły pod koniec lata Mołdawia i Siedmiogród: wojewoda Mołdawii Aron Vodă 16 sierpnia 1594 roku sformalizował dokumentem przystąpienie do strony chrześcijańskiej, a książę Siedmiogrodu Zsigmond Báthory 28 sierpnia 1594 roku złamał wewnętrzną opozycję, likwidując prosmańskich bejów sprzeciwiających się wojnie. Wojewoda Wołoszczyzny Michał Waleczny przyłączył się do ligi jesienią tego samego roku. W ten sposób trzy zależne księstwa Osmanów na północ od Dunaju — trzy wojewodztwa płacące haracz od stu pięćdziesięciu lat, których wojewodów zatwierdzano w Stambule — przeszły jesienią jednocześnie na stronę przeciwną. Decyzję sformalizowano układem podpisanym 28 stycznia 1595 roku w Pradze. Był to najcięższy wstrząs dla pośredniego systemu rządów Osmanów na północy Bałkanów; powstanie zostanie stłumione, ale lojalność trzech księstw nigdy już nie będzie tak pewna jak w latach 1526-1593.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["Powstanie w Bukareszcie i atak na twierdze naddunajskie", "18971100"], "d": ["Decyzja Świętej Ligi została miesiąc później wykonana krwawo: Michał Waleczny w Bukareszcie wyciął w pień osmańską załogę oraz lewantyńskich wierzycieli w mieście. Powstanie rozszerzyło się tej samej zimy na linię Dunaju; siły wołoskie zaatakowały Giurgiu, Braiłę, Hârșovę i Silistrę, a po stronie mołdawskiej Aron Vodă dokonał takiego samego napadu na osmańskich strażników w Benderze. Wybór uderzonych miejsc nie jest przypadkowy: wszystkie one były nie ziemiami wojewodztwa, lecz twierdzami i kazami podległymi bezpośrednio rządom osmańskim nad Dunajem — kaza Giurgiu podlegała sandżakbejowi Nikopola, Braiła od 1538 roku bezpośrednio państwu, Bender również od 1538 roku sandżakowi Budziak. Zatem bunt uderzył nie w wasalne wnętrze, lecz w bezpośrednią osmańską skorupę je otaczającą. Bez przebicia tej skorupy trójkąta Siedmiogród-Wołoszczyzna-Mołdawia nie można było połączyć z frontem habsburskim.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["Bitwa pod Călugăreni — wyprawa wołoska Koca Sinana Paszy", "201210a1"], "d": ["Wobec utraty wszystkich trzech wojewodztw naraz wielki wezyr Koca Sinan Pasza przekroczył Dunaj z wielką armią i ruszył, by ponownie podporządkować Wołoszczyznę. Michał Waleczny, wiedząc, że nie zdoła stawić czoła w otwartej bitwie, czekał na armię w Călugăreni, na bagnistym brodzie rzeki Neajlov, i zaatakował siły ściśnięte na wąskim terenie. Po napadzie, nie mogąc się oprzeć liczebnie przeważającej armii osmańskiej, wycofał się na północ w góry; Sinan Pasza zajął Bukareszt i Târgoviște i próbował objąć Wołoszczyznę bezpośrednimi rządami. Călugăreni nie było więc dla Osmanów klęską, lecz napadem opóźniającym dokończenie wyprawy; jednak to, że Michał zdołał ocalić swą armię, umożliwiło mu kilka tygodni później przejście do przeciwnatarcia z pomocą nadchodzącą z Siedmiogrodu.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["Odwrót z Wołoszczyzny i napad pod Giurgiu — bezskuteczność wyprawy represyjnej", "118806e1"], "d": ["Wobec przeciwnatarcia Michała Walecznego, połączonego z siłami księcia Siedmiogrodu, Sinan Pasza opróżnił Târgoviște i Bukareszt i wycofał się za Dunaj. Najkosztowniejszy moment odwrotu miał miejsce przy przeprawie: w październiku 1595 roku akindżowie ścigający wracającą z Wołoszczyzny armię zostali zaatakowani przez Michała pod Giurgiu. Wyprawa zakończyła się więc bez osiągnięcia celu objęcia Wołoszczyzny bezpośrednimi rządami, a wojewodztwo pozostało faktycznie utracone. Władza osmańska w tym trójkącie mogła być naprawiana dopiero w ciągu lat i kawałek po kawałku; powrót Siedmiogrodu do posłuszeństwa miał poczekać do powstania Bocskaia w 1604 roku, a całkowite zamknięcie frontu do traktatu z Zsitvatorok w 1606 roku.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["Oderwanie Chocimia od Mołdawii — bezpośredni sandżak osmański pośrodku wojewodztwa", "947517cb"], "d": ["Przejście wojewody Mołdawii Dimitrie Cantemira na stronę Rosji podczas wyprawy nad Prut pokazało, że północnej granicy wojewodztwa nie można już zostawić wojewodzie. Wobec tego Chocim po 1711 roku został odebrany Mołdawii i objęty bezpośrednimi rządami osmańskimi; nadano mu najpierw status nahiji, potem sandżaku. Po tymczasowej okupacji rosyjskiej w 1713 roku twierdzę odbudowano i rozbudowano pod nadzorem osmańsko-francuskiej komisji technicznej wysłanej ze Stambułu i stała się najpotężniejszą osmańską fortecą na północ od Dunaju. Na mapie to, że od tej daty Chocim wychodzi z odcienia zależnego wojewodztwa i wraca do koloru bezpośrednio osmańskiego oraz że pośrodku zależnej Mołdawii stoi jak sama wyspa, jest właśnie odpowiednikiem tego podziału administracyjnego — nie jest to błąd rysunku. Ta sama struktura istniała już w Budziaku od 1538 roku, a w Kilii i Akkermanie od 1484 roku: wojewodztwo swobodne w sprawach wewnętrznych, twierdze graniczne należące do państwa.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Druga okupacja austriacka Böğürdelen — otwarcie frontu nad Sawą", "063b3ad0"], "d": ["Po wejściu Austrii do wojny po stronie Rosji 9 lutego 1788 roku linia Sawy znowu stała się frontem, a Böğürdelen 24 kwietnia 1788 roku przeszło pod zwierzchnictwo austriackie. Twierdza wcześniej została 17 sierpnia 1717 roku bez walki ustąpiona Austrii i utrzymana do Traktatu Belgradzkiego (1739); w tym czasie liczba jej mieszkańców spadła tak, że w mieście zostały trzydzieści cztery domy chrześcijańskie, a muzułmanów nie było wcale. W okresie osmańskim 1739-1788 ludność ponownie wzrosła do 1500-2000. Druga okupacja miała się zakończyć Traktatem w Świsztowie (4 sierpnia 1791), a twierdza miała zostać zwrócona Osmanom.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Poddanie Böğürdelen Karađorđe — pierwsza twierdza w Pierwszym Powstaniu Serbskim", "5c913eb4"], "d": ["Podczas pierwszej rewolucji serbskiej, która rozpoczęła się w 1804 roku jako reakcja na ucisk dahijów i janczarów w Belgradzie, a później nabrała charakteru narodowego, twierdza Böğürdelen została 26 stycznia 1806 roku poddana Karađorđe. Ta twierdza nad Sawą jest pierwszą wielką osmańską fortyfikacją zdobytą przez powstańców i zapowiada upadek Belgradu. Gdy w 1813 roku powstanie stłumiono i Belgrad odzyskano, twierdza wróciła pod rządy osmańskie; jednak na mocy fermanu z 1830 roku z warunkiem garnizonu Böğürdelen wraz z Belgradem, Semendirą i Fethülislâm zostało określone jako jedna z czterech twierdz w autonomicznej Serbii, w których pozostawało wojsko osmańskie, i w tym statusie pozostało do wycofania garnizonu w 1867 roku.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["Lamia pozostała w granicach Grecji — linia Arta-Wolos", "930f63b8"], "d": ["Północna granica niepodległego państwa greckiego została w 1832 roku wytyczona na linii od Zatoki Arta do Zatoki Wolos. Lamia, ośrodek kazy podległej w okresie osmańskim (1424-1832) sandżakowi Eğriboz, pozostała na południe od tej linii i przeszła do Grecji; reszta Tesalii (Larisa, Tyrnavos) pozostała do 1881 roku w rękach osmańskich.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["Wypowiedzenie wojny przez Rosję — początek Wojny Dziewięćdziesiątej Trzeciej", "ac548ab8"], "d": ["Stłumienie powstania bułgarskiego w 1876 roku wywołało wielkie oburzenie w opinii publicznej Europy, a Rosja wykorzystała to do końca, by odizolować Wysoką Portę. Gdy Państwo Osmańskie odrzuciło propozycję konferencji stambulskiej (w Tersane) podziału Bułgarii na dwie autonomiczne prowincje, a następnie Protokół Londyński z 31 marca 1877 roku, Rosja 24 kwietnia 1877 roku wypowiedziała wojnę, a jej armia weszła na ziemie Księstwa Rumunii, które przeciągnęła na swoją stronę (mapa pokazuje Wołoszczyznę-Mołdawię od tej chwili aż do zawieszenia broni w Edirne jako zakreskowaną nakładkę rosyjskiego natarcia). Ponieważ przypadała na rok 1293 kalendarza rumi, wojna nazywana jest Wojną Dziewięćdziesiątej Trzeciej. Działania toczyły się na dwóch frontach, naddunajskim i wschodnioanatolijskim: nad Dunajem 180 000-osobowa armia osmańska uznała lewy brzeg rzeki za pierwszą linię obrony, a góry Bałkan za drugą; na wschodzie 55 000 żołnierzy Ahmeda Muhtara Paszy rozlokowało się między Ardahanem a Doğubayazıtem. Wojna ta na mapie jest wydarzeniem, które zapoczątkowało rozpad osmańskiej Rumelii — dzisiejsze granice Bułgarii, Serbii, Czarnogóry i Rumunii są wszystkie wytworem tych piętnastu miesięcy.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["Ogłoszenie niepodległości przez Rumunię — koniec zależności Wołoszczyzny-Mołdawii", "bdd164b3"], "d": ["Dwa tygodnie po ogłoszeniu Wojny Dziewięćdziesiątej Trzeciej Księstwo Rumunii ogłosiło niepodległość i weszło do wojny po stronie Rosji; jego udział w oblężeniu Plewny okazał się rozstrzygający dla osmańskiej klęski. Zależność Wołoszczyzny i Mołdawii trwająca ponad czterysta lat faktycznie dobiegła w ten sposób końca; niepodległość uzyskała uznanie międzynarodowe na Kongresie Berlińskim (1878). Mapa od tej daty pokazuje Rumunię nie jako zależną, lecz jako niepodległe państwo we własnym kolorze. Wraz z ogłoszeniem niepodległości cała Wołoszczyzna i Mołdawia (Jassy, Gałacz, Braiła, Giurgiu, Calafat, Botoszany i in.) stały się niepodległą Rumunią.", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["Przekroczenie Dunaju przez armię rosyjską — upadek Svisztowa i Tyrnowa", "811367b1"], "d": ["Rosjanie, którzy wraz z początkiem wojny weszli na ziemie Rumunii i przeciągnęli to księstwo na swoją stronę, posuwali się dwiema kolumnami, jedna w kierunku Dobrudży, druga Bukaresztu. Dunaj przekroczono między Rusczukiem a Nikopolem i 27 czerwca zajęto Svisztow, a 1 lipca dawną stolicę Bułgarii, Tyrnowo. Ponieważ mimo rozkazu ewakuacji nie przywiązano do niej uwagi, Nikopol również po pewnym oporze się poddał. Przełamanie pierwszej linii obrony w ciągu tygodnia wywołało w Stambule wielką panikę; rozeszły się nawet wieści o przeniesieniu centrum sułtanatu do Bursy, a kierowanie wojną przekazano radzie wojskowej utworzonej w stolicy.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["Ewakuacja przełęczy Szipka — przełamanie linii bałkańskiej", "1f45e50a"], "d": ["Siły osmańskie na Szipce, najbardziej strategicznej z przełęczy przez góry Bałkan, zaciekle opierały się rosyjskim atakom; lecz uznawszy, że zostaną pokonane, 19 lipca potajemnie opuściły przełęcz. Tak otwarła się i druga linia obrony, a generał Gurko 22 lipca zajął Starą Zagorę. Choć Sulejman Pasza, który nadciągnął od strony Czarnogóry, pokonał Gurkę i odzyskał zajęte miejsca na południe od Bałkanu, mimo trwających miesiącami od 21 sierpnia ataków nie zdołał odzyskać Szipki. Na mapie oznacza to, że nie dało się już odbudować spójności obrony między północą a południem gór Bałkan: walka na froncie naddunajskim od tej pory będzie się wiązać w Plewnie.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Łowcza zajęta przez armię rosyjską", "70e54611"], "d": ["W Wojnie Dziewięćdziesiątej Trzeciej Łowcza została zajęta przez Rosjan 5 czerwca 1877 roku, siły osmańskie pod dowództwem Rifata Paszy 15 czerwca odrzuciły Rosjan; miasto zostało 23 sierpnia opuszczone przez Osmanów i ponownie weszło pod okupację rosyjską. Mapa pokazuje Łowczę od tego dnia do Traktatu Berlińskiego jako pod okupacją rosyjską (zakreskowaną); prawnie nadal pozostaje ziemią osmańską.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["Upadek Karsu — rozpad frontu wschodniego i bastiony Azizije", "53fc3bf5"], "d": ["Rosjanie, którzy na wschodzie Anatolii posuwali się trzema kolumnami ku Karsowi, Doğubayazıtowi i Ardahanowi, 30 kwietnia zajęli Doğubayazıt, weszli do Ardahanu, lecz podczas marszu na Erzurum 15 lipca zostali pobici i wyrzuceni za granicę. Sukces ten, który przyniósł Ahmedowi Muhtarowi Paszy tytuł „Gazi”, odwrócił się w sierpniu wraz z ponownym przejściem generała Lazariewa do natarcia, a 18 listopada padł Kars. Siły osmańskie, które wycofały się do Erzurum dla dogodniejszej obrony, stawiły wielki opór na bastionach Azizije, zachęcane przez Nene Hatun do udziału ludności. Kars, Ardahan i Batum zostaną osiem miesięcy później w Berlinie oddane Rosji w zamian za część odszkodowania wojennego.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["Początek I Wojny Bałkańskiej — wypowiedzenie wojny przez Czarnogórę", "c0c2697e"], "d": ["Państwa bałkańskie, po tym jak Komitet Jedności i Postępu ustawą z 3 lipca 1911 roku rozwiązał sprawę kościołów, usunęły największą przeszkodę między sobą i z podszeptu Rosji w ciągu 1912 roku podpisywały między sobą układy sojusznicze (13 marca Serbia-Bułgaria, 29 maja Bułgaria-Grecja, w sierpniu Czarnogóra-Bułgaria, 6 października Czarnogóra-Serbia). Wysoka Porta tego nie zauważyła; co więcej, ufając gwarancjom Rosji, rozwiązała 120 batalionów wyszkolonych w Rumelii. Cztery państwa 3 października wystosowały wspólną notę żądającą autonomii dla Macedonii, Albanii i Krety; nie otrzymawszy odpowiedzi, rozpoczęły działania 8 października 1912 roku wypowiedzeniem wojny przez Czarnogórę. 13 października wręczono paszporty ambasadorom Serbii i Bułgarii, następnego dnia te dwa państwa, a potem Grecja wypowiedziały wojnę. W czasie wojny rozbieżności polityczne w armii odegrały dużą rolę w klęsce.", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["Rozbicie oddziału Kırcaali w Rodopach, upadek Kırcaali", "8cf59b7f"], "d": ["Po bułgarskim wypowiedzeniu wojny siły bułgarskie schodzące z Rodopów pobiły Oddział Kırcaali Mehmeda Yavera Paszy i weszły do Kırcaali. Rozbity oddział wycofał się w kierunku Gümülcine; wschodnia część Rodopów została utracona w pierwszym tygodniu wojny.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["Rozbicie Armii Wschodniej i odwrót na linię Çatalca — utrata Kumanowa i Salonik", "cf95591a"], "d": ["Osmańska Armia Wschodnia 23 października 1912 roku, pobita przez trzykrotnie liczniejszą armię bułgarską, wycofała się aż na linię Çatalca, trzydzieści kilometrów na zachód od Stambułu; stolica w pierwszym miesiącu wojny znalazła się pod bezpośrednim zagrożeniem. W tych samych dniach Armia Zachodnia 23-24 października została pobita pod Kumanowem przez Serbów, a Tahsin Pasza ze swoją 35 000-osobową armią poddał się w Salonikach Grekom. Wobec tych klęsk 29 października gabinet Gazi Ahmeda Muhtara Paszy podał się do dymisji; Abdülhamid II, który żył na wygnaniu w Salonikach, został 1 listopada przewieziony do Stambułu. Linia Çatalca utrzymała się do końca wojny — pięćsetletnia osmańska geografia Rumelii skurczyła się w ciągu kilku tygodni do tego wąskiego pasa.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["Książę Aleksandar wkroczył do ośrodka sandżaku Novi Pazar", "326d0616"], "d": ["Siły serbskie w pierwszym tygodniu wojny zajęły Novi Pazar i połączyły się z nadciągającymi od zachodu siłami czarnogórskimi. Sandżak Novi Pazar, od stu lat dzielący Serbię i Czarnogórę, stał się w ten sposób mostem między dwoma sojusznikami.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["Utrata Kırklareli po bitwie pod Kırkkilise", "eda4c759"], "d": ["Po klęsce Armii Wschodniej w bitwie pod Kırkkilise w Tracji Wschodniej miasto bronione przez Kölemena Abdullaha Paszę zostało pozostawione siłom bułgarskim. Miasto zostało uwolnione od trwającej dziewięć miesięcy okupacji dopiero w II Wojnie Bałkańskiej, 21 lipca 1913 roku.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Üsküp, ośrodek wilajetu Kosowa, pozostawiony bez oporu", "455d9b71"], "d": ["Po klęsce pod Kumanowem (23-24 października) Üsküp, ośrodek wilajetu Kosowa, został bez obrony. Ponieważ mieszkańcy nie chcieli walk wokół miasta, siły serbskie pod dowództwem księcia Aleksandara, zaproszone za pośrednictwem konsulów, wkroczyły do miasta bez oporu wieczorem 26 października.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["Köprülü (Veles) utracone nad Wardarem", "73d20b7d"], "d": ["Dwa dni po upadku Üsküpu armia serbska schodząca na południe wzdłuż Wardaru zajęła Köprülü. Brama doliny Wardaru otwierająca drogę do Salonik przeszła w ten sposób w ręce Serbów.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["Dorzecze Bregalnicy: generał Stefanović wkroczył do İştip", "70a84256"], "d": ["Oddziały serbskie pod dowództwem generała Stefanovicia zajęły İştip bez napotkania oporu; do miasta weszły najpierw nieregularne bandy. Po Kumanowie dorzecze Bregalnicy we wschodniej Macedonii przeszło pod kontrolę serbską.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["Po przełęczy Sarantaporo Karaferye przeszło pod zwierzchnictwo greckie", "02a68e02"], "d": ["Armia grecka posuwająca się z Tesalii na północ, po sforsowaniu przełęczy Sarantaporo (Kırkgeçit), opanowała Karaferye. Część muzułmańskiej ludności miasta opuściła wtedy region.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["Utrata Vodina na linii kolejowej Saloniki-Monastir", "fc15b917"], "d": ["Vodina na linii kolejowej Saloniki-Monastir wpadła w ręce armii greckiej. Wskutek przymusowego wyjazdu ludności słowiańskiej i tureckiej liczba mieszkańców miasta w krótkim czasie poważnie spadła.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["Bitwa pod Yenice — przejście Yenice-i Vardar w ręce Greków", "8f6cb76e"], "d": ["8. Korpus Mieszany Hasana Tahsina Paszy został pobity przez armię grecką pod Yenice na zachód od Salonik i wycofał się w rejon Salonik. Podczas bitwy większa część miasteczka spłonęła; Saloniki zostały otwarte dla armii greckiej.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Prizren poddał się na południowym zachodzie Kosowa", "bae6b1b9"], "d": ["Prizren na południowym zachodzie Kosowa poddał się siłom serbskim. Postępowanie oddziałów wkraczających do miasta wobec ludności muzułmańskiej zostało odnotowane jako jedna z najcięższych kart wojny w Kosowie.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["Pułkownik Mitov ogłosił stan wojenny w Ustrumcy", "bcad75cc"], "d": ["Bułgarski pułkownik Mitov wkroczył do Ustrumcy i ogłosił stan wojenny; następnego dnia, wyjeżdżając, pozostawił miasteczko bułgarskiemu kajmakamowi i serbskiemu dowódcy. Ustrumca w czasie wojny przechodziła z rąk do rąk między sojusznikami, a w 1913 roku została przyłączona do Bułgarii.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Hasan Tahsin Pasza oddał Saloniki Grekom", "1738933c"], "d": ["Hasan Tahsin Pasza, który po klęsce pod Yenice wycofał się do Salonik, oddał miasto Grekom, gdy armia bułgarska zbliżała się od północy; armia grecka wkroczyła do miasta 8 listopada w południe. Saloniki, największe miasto portowe osmańskiej Rumelii i kolebka Komitetu Jedności i Postępu, zostały w ten sposób utracone.", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Gümülcine, ośrodek Tracji Zachodniej, otwarte dla Bułgarów", "96eec25f"], "d": ["Wskutek odwrotu oddziału Yavera Paszy, wycofującego się z Kırcaali ku Fere, Gümülcine poddało się siłom bułgarskim. Ośrodek Tracji Zachodniej należał do pierwszych ziem, które na końcu wojny miały zostać oddane Bułgarii.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["Serbowie, którzy dotarli do Elbasanu, tego samego dnia weszli do Debaru", "16720246"], "d": ["Siły serbskie posuwające się z Monastiru na zachód tego samego dnia, w którym dotarły do Elbasanu, weszły także do Debaru i zeszły ku Adriatykowi. W tym samym dniu w Awlonie ogłaszano niepodległość Albanii.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Timur po raz drugi zajął Bagdad — zniszczono dzielnice abbasydzkie miasta", "04b68a24"], "d": ["Timur zdobył Bagdad dwa razy w odstępie ośmiu lat. Przy pierwszej okupacji w 1393 roku miasto nie ucierpiało zbytnio; druga, w 1401 roku, uważana jest za drugi ciężki cios zadany życiu kulturalnemu Bagdadu — ludność wycięto w pień, większość dzielnic i budowli z czasów abbasydzkich zniszczono. Władca dżalairydzki Ahmed w 1405 roku wrócił do miasta i próbował naprawić zburzone mury i bazary, lecz nie starczyło mu czasu; Bagdad w 1410 roku wpadł w ręce Turkmenów Karakoyunlu. Te dwie okupacje są jednym z najkonkretniejszych kroków pokazujących, jak blisko granic osmańskich i mameluckich Timur zbliżył się na drodze do Bitwy pod Ankarą.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Cüneyd Bej wrócił na czoło Aydın-ili — Aydınoğulları znów niezależni", "63281658"], "d": ["Çelebi Mehmed w latach 1414-15 zajął Izmir i wysławszy Cüneyda Beja na sandżakbeja Nikopola, objął Aydın-ili rządami osmańskimi. Cüneyd po śmierci Çelebiego Mehmeda znów pojawił się na scenie u boku Mustafy Çelebiego, wysuniętego przez Bizancjum jako pretendenta do tronu, i był nawet jego wezyrem. Murad II oderwał go od tego sojuszu obietnicą zwrotu dawnego beylika; Cüneyd wrócił do Izmiru, zajął Ayasuluk i zabiwszy Aydınoğlu Mustafę Beja, stanął na czele beylika. Tak Aydın-ili narodziło się z kryzysu Fałszywego Mustafy jako wyłączone spod rządów osmańskich.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Egzekucja Cüneyda Beja i jego rodziny — koniec beylika Aydınoğulları", "efa684ba"], "d": ["Gdy Cüneyd Bej, który ponownie zapanował nad Aydın-ili, podburzał beyów Anatolii i szukał kontaktu z Wenecją, Murad II wysłał przeciw niemu beylerbeya Anatolii Hamzę Beja. Jego syn Kurd Hasan został pobity pod Akhisarem i wzięty do niewoli, Cüneyd wycofał się do İpsili naprzeciw wyspy Samos, a gdy oczekiwana pomoc od Karamanoğlu nie nadeszła i Genueńczycy działający wspólnie z Osmanami zablokowali go od strony morza, musiał się poddać; został zgładzony wraz z całym rodem. Ziemie Aydınoğulları weszły w ten sposób całkowicie pod rządy osmańskie.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Erzurum i dorzecze Wan przeszły do Safawidów — załamanie północnego skrzydła Aqquyunlu", "b418875f"], "d": ["Szach Isma'il, który pobił Alwenda Beja pod Szarur i latem 1501 roku wszedł do Tebrizu, w następnym roku posuwając się na północny zachód objął swoim zwierzchnictwem pas od Erzurum po dorzecze jeziora Wan. Państwo Aqquyunlu po śmierci Uzuna Hasana było już podzielone walkami o tron: Alwend Bej trzymał Azerbejdżan i Diyarbakır, jego stryjeczny brat Murad Irak Perski i Fars. Ten podział ułatwił natarcie Safawidów; region zmienił ręce w ciągu roku w dziesięciu odnotowanych przypadkach. Erzurum pozostało potem szesnaście lat w rękach Safawidów i weszło pod zwierzchnictwo osmańskie dopiero po Çaldıranie, w 1518-19. W tym roku (1502) Aşkale i Pasinler (Hasankale) wraz z regionem Erzurum przeszły od Aqquyunlu do Safawidów (dzień niepotwierdzony).", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["Klęska Murada Beja pod Hamadanem: Irak Perski i Fars przeszły do Safawidów", "8de07a31"], "d": ["Sułtan Murad, drugi pretendent do tronu Aqquyunlu, poniósł ciężką klęskę w bitwie z szachem Isma'ilem w pobliżu Hamadanu i uciekł do Bagdadu. Tą jedną bitwą regiony Irak Perski, Fars i Kerman weszły pod rządy Safawidów; na mapie regiony te zmieniają ręce w tym samym czasie. Jest to największy pojedynczy krok w rozkładzie państwa Aqquyunlu — utrata Tebrizu pozbawiła dynastię stolicy, klęska pod Hamadanem pozbawiła ją ziemi.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["Szach Isma'il wkroczył do Jazdu: padła ostatnia twierdza resztek Aqquyunlu w środkowym Iranie", "6f9835df"], "d": ["Chociaż po klęsce pod Hamadanem w 1503 roku Irak Perski i Fars przeszły do Safawidów, Jazd pozostawał odrębnie w rękach Bayındırlı Murada Beja z dynastii Aqquyunlu. Miasto padło po miesięcznym oblężeniu i zamknęła się ostatnia wyspa Aqquyunlu w środkowym Iranie. Zapis TDV: „Szach Isma'il wszedł do miasta 28 Dżumada II 910 (6 grudnia 1504) po miesięcznym oblężeniu.”", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["Wyprawa szacha Isma'ila na Diyarbakır: padły ostatnie ośrodki Aqquyunlu", "b6d8504e"], "d": ["Szach Isma'il, który opanował Azerbejdżan i płaskowyż irański, w 1507 roku zwrócił się na zachód, ku regionowi Diyarbakır, gdzie narodziła się dynastia Aqquyunlu. Linia od Amidu po Mardin, od Urfy po Harput weszła w dwóch uderzeniach pod rządy Safawidów, a Aqquyunlu faktycznie znikli. Ta wyprawa po raz pierwszy oparła też granicę safawidzką o granice osmańską i mameluków; w ten sposób powstało geograficzne podłoże napięcia prowadzącego do Çaldıranu.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["Przejście Bagdadu do Safawidów — Irak Arabski zmienił ręce", "39730186"], "d": ["Szach Isma'il w 1508 roku wszedł do Iraku Arabskiego w ślad za sułtanem Muradem z Aqquyunlu, który po klęsce pod Hamadanem schronił się w Bagdadzie, i zajął Bagdad. Przejście mauzoleów w Karbali i Nadżafie pod rządy Safawidów miało dla roszczeń wyznaniowych ruchu takie samo znaczenie jak zajęcie Tebrizu. Na mapie Irak Arabski zmienia ręce tego samego dnia; jest to ostatni i najszerszy geograficznie krok rozkładu. Bagdad pozostał w rękach Safawidów do Wyprawy Irakejn Sulejmana Prawodawcy w 1534 roku.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["Bitwa pod Merwem: Uzbecy ciężko pobici, zajęto Merw i Herat", "f8e45aaf"], "d": ["Szach Isma'il, który na zachodzie dopełnił dziedzictwo Aqquyunlu, wyruszył na wschód, do Chorasanu, i pod Merwem zadał Uzbekom ciężką klęskę; Szajbani Chan poległ na polu bitwy. Merw i Herat weszły pod zwierzchnictwo Safawidów, a państwo Safawidów osiągnęło granice od Eufratu po Dżejhun. Tak proces, który rozpoczął się latem 1501 roku wejściem do Tebrizu, dobiegł końca w dziewięć lat: dziedzictwo Aqquyunlu przeszło w całości pod rządy Safawidów, a Państwo Osmańskie zaczęło sąsiadować na wschodzie z drugim państwem swej wielkości.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["Ostateczne wejście Zebidu pod zwierzchnictwo osmańskie", "ddd971c7"], "d": ["Flota, która 5 listopada 1538 roku zniosła oblężenie Diu, w drodze powrotnej zawinęła do wybrzeża Jemenu i Zebid został definitywnie włączony do rządów osmańskich; Hadım Sulejman Pasza opuścił miasto 10 marca 1539 roku, a 1 kwietnia dotarł do Dżuddy. Miasto od 1517 roku było rządzone w imieniu Osmanów przez dawnych bejów mameluckich; tą datą przeszło pod rządy bezpośrednie.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["Unia Iberyjska: korona portugalska przeszła na króla Hiszpanii", "1cc6dfdc"], "d": ["Spór o sukcesję, który otworzył się wraz z bezpotomną śmiercią kardynała-króla Henryka, zakończył się na korzyść Hiszpanii w bitwie pod Alcântarą (25 sierpnia 1580), a zebrane w Tomar portugalskie Kortezy uznały 16 kwietnia 1581 roku Filipa II za króla Portugalii. Zgodnie z warunkami z Tomar Portugalia miała zachować własne instytucje, pieniądz i język, do zarządu miano mianować wyłącznie Portugalczyków, a w Madrycie miała istnieć osobna rada portugalska — czyli połączenie było unią personalną, nie aneksją.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["Restauração: Portugalia odzyskała niepodległość", "64ec0738"], "d": ["W czasie, gdy powstanie w Katalonii zajmowało Hiszpanię, grupa szlachty w Lizbonie napadła na pałac, obaliła rządy hiszpańskie i ogłosiła księcia Braganzy królem jako Jana IV. Sześćdziesięcioletnia Unia Iberyjska dobiegła tym samym końca; jednak Ceuta wybrała pozostanie przy Hiszpanii, co zostało uznane traktatem lizbońskim w 1668 roku. To okno, w którym Portugalia została wciągnięta w wojny habsburskie, jest także ramą jej strat w Azji: Ormuz utracono w 1622, Malakkę w 1641, Colombo w 1656, a Tanger i Bombaj oddano Anglii jako cenę niepodległości. Źródło: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Tanger oddany Anglii", "1f7cad6d"], "d": ["Drugi artykuł umowy małżeńskiej (23 czerwca 1661), zawartej dla zapewnienia angielskiego poparcia w portugalskiej wojnie o niepodległość, oddawał Tanger Anglii jako posag Katarzyny Braganza. Flota hrabiego Sandwich zakotwiczyła 29 stycznia 1662 roku, a następnego dnia podczas ceremonii hrabiego Peterborough dokonano oficjalnego przekazania. Anglicy mieli opuścić miasto w 1684 roku.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["Zabójstwo Nadir Szacha — rozpad zwierzchnictwa Afszarydów", "19c218c0"], "d": ["Nadir Szach, który zakończył panowanie Safawidów i w 1736 roku ogłosił się władcą we własnym imieniu, dotarł wyprawą indyjską aż do Delhi i stoczył z Osmanami trzy wojny, godząc się z nimi układem z Kerden w 1746 roku, został zabity w swym namiocie przez własnych gwardzistów. Potem Iranem nie dało się rządzić jedną ręką: pozostałość Afszarydów w Chorasanie, Zendowie na południu i Kadżarowie wznoszący się na północy dzielili kraj przez czterdzieści dziewięć lat. Wschodnia granica osmańska dzięki tej rozdrobnionej sytuacji długo pozostawała spokojna. Nadir Szach został zabity 20 czerwca 1747 roku; według TDV Chanat Erywański powstał w tym samym roku (1747), dzień niepotwierdzony.", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["Zapanowanie dynastii Kadżarów nad Iranem", "744b48c5"], "d": ["Agha Muhammad Chan, wódz plemienia Kadżarów, obalił zwierzchnictwo Zendów i złamawszy ostatni opór Afszarydów w Chorasanie ponownie zjednoczył Iran w jednych rękach, czyniąc Teheran stolicą. Czterdziestodziewięcioletni okres rozbicia dobiegł tym samym końca; odtąd wschodnim sąsiadem Osmanów miał być do 1923 roku Iran Kadżarów. Według TDV Meszhed w 1796 roku został powitany przed Aghą Muhammad Szachem przez władcę Afszarydów Szahrucha i wszedł pod zwierzchnictwo Kadżarów (dzień nie występuje w źródle).", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Ferdynand zdobył Budę — Szapolyai usunięty ze stolicy", "99f77c29"], "d": ["Po Mohaczu na tronie węgierskim pojawiło się dwóch królów: część szlachty wybrała Jánosa Szapolyaia, część Habsburga Ferdynanda. Ferdynand w 1527 roku zajął Budę i usunął Szapolyaia ze stolicy; Szapolyai poprosił o pomoc sułtana Sulejmana. Dlatego pierwszym celem wyprawy wiedeńskiej 1529 roku była Buda.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Wyprawa Barbarossy na wyspy Morza Egejskiego — Księstwo Naksos weszło pod kontrolę osmańską", "722b2fea"], "d": ["Księstwo Naksos, od 1207 roku rządzone przez łacińskich książąt pod opieką Wenecji, weszło pod kontrolę osmańską dzięki wyprawie na wyspy Barbarossy Hayreddina Paszy. Statusu wyspy nie naruszono; księstwo trwało jako zależne od Osmanów, a układem osmańsko-weneckim z 1540 roku prawo zwierzchnictwa zostało formalnie oddane Osmanom.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["Flota krzyżowców zajęła Dżerbę — utracona baza Turguta Paszy", "f41b3f2a"], "d": ["Flota krzyżowców złożona z okrętów Hiszpanii, Papiestwa, Malty, Genui i Florencji obrała za cel Dżerbę, której Turgut Reis używał od 1551 roku jako bazy wypadów. Z powodu sztormów i epidemii dotarła pod wyspę dopiero na początku 1560 roku; 12 marca 1560 zajęła wyspę i zbudowała twierdzę. Piyale Pasza, który otrzymał wiadomość, 28 marca wyruszył ze Stambułu ze 120-galerową flotą. Okupacja nie trwała długo: flota osmańska w maju pobiła sojuszników pod Dżerbą, a twierdzę odzyskano pod koniec lipca. Ta wyprawa jest początkiem drugiej wielkiej operacji morskiej, która po Prevezie umocniła osmańską przewagę na Morzu Śródziemnym.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Upadek twierdzy Dżerba — przejście wyspy pod rządy osmańskie", "f1efc0df"], "d": ["Po morskim zwycięstwie Piyale Paszy z 14 maja 1560 roku siły krzyżowców zamknęły się w twierdzy zbudowanej na wyspie; siły Turguta Paszy, beylerbeya Trypolisu, oblegały ją od strony lądu. Dwumiesięczne oblężenie zakończyło się upadkiem twierdzy 30 lipca 1560 roku, a wyspę włączono do beylerbeylikatu Trypolisu. Między zwycięstwem morskim a zdobyciem twierdzy jest siedemdziesiąt siedem dni; wyspa faktycznie zmieniła ręce nie 14 maja, lecz 30 lipca.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["Koniec rosyjsko-pruskiego dwuwładztwa w Gdańsku — wolne miasto Napoleona wróciło do Prus", "1ccda4d2"], "d": ["Gdańsk, oddzielony od Prus pokojem w Tylży (9 lipca 1807) i uczyniony wolnym miastem pod opieką francuską, został opuszczony przez siły Napoleona po oblężeniu 1813 roku. Między 2 stycznia a 4 lutego 1814 roku w mieście trwało dwuwładztwo rosyjsko-pruskie; gdy car Aleksander zrezygnował z planu przejęcia Gdańska i ujścia Wisły, miasto przeszło pod rządy pruskie.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["W Wiedniu Kraków ogłoszony wolnym, niezależnym i neutralnym miastem", "19eea839"], "d": ["Na Kongresie Wiedeńskim Rosja, Austria i Prusy uczyniły z Krakowa wraz z okolicą wolne państwo pod ochroną trzech mocarstw; Akt Końcowy Kongresu Wiedeńskiego potwierdził ten ład.", "21a6fe2b"]},
"OLAYLAR_EK12:1846-11-11:0":{"b": ["Wolne Miasto Kraków zniesione, włączone do Austrii", "15548a14"], "d": ["Rosja, Austria i Prusy, wykorzystując jako pretekst powstanie krakowskie z lutego 1846 roku, postanowiły na konferencji w Wiedniu znieść wolne miasto i włączyć je do ziem austriackich; sprzeciwy Anglii i Francji nie przyniosły skutku.", "bf12c063"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Bornu weszło pod zwierzchnictwo Rabiha b. Zubajra", "8be4ca96"], "d": ["Sudański wódz wojenny Rabih b. Zubajr, który wstrząsnął Bagirmi i Wadai, zajął Bornu; do 1896 roku objął cały kraj i uczynił Dikoa swoim ośrodkiem.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["Rabih b. Zubajr pobity przez Francuzów i zabity — rozpad jego władzy w Bornu", "fb5a3ace"], "d": ["Rabih, pobity przez francuską armię kolonialną, został zabity; jego syn chciał utrzymać władzę, lecz nie zdołał się utrzymać, a Bornu zostało w 1902 roku podzielone między Francję, Anglię i Niemcy.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["Ogłoszono Rząd Tymczasowy Tracji Zachodniej z ośrodkiem w Gümülcine", "974b2e28"], "d": ["Gdy Traktat Bukareszteński (10 sierpnia 1913) oddał Trację Zachodnią Bułgarii, ludność turecka regionu ogłosiła rząd tymczasowy z ośrodkiem w Gümülcine; po zajęciu Dedeağaç rząd ogłosił niepodległość pod nazwą „Rząd Niezależny Tracji Zachodniej”. Wskutek interwencji wielkich mocarstw rząd osmański go nie poparł; Traktat Stambulski z 29 września 1913 oddał Trację Zachodnią Bułgarom, a rząd przetrwał do 25 października 1913 zaledwie pięćdziesiąt siedem dni.", "86d3bfee"]},
"OLAYLAR_EK12:1920-11-15:0":{"b": ["Utworzono Wolne Miasto Gdańsk pod ochroną Ligi Narodów", "bd148fe8"], "d": ["Gdańsk, oddzielony od Niemiec Traktatem Wersalskim, od 10 stycznia 1920 roku pozostawał pod tymczasowym zarządem sprzymierzonych wielkich mocarstw; 15 listopada 1920 roku utworzono go jako wolne miasto pod ochroną Ligi Narodów, w unii celnej z Polską.", "c74affc1"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["Śmierć Orhana Gaziego — koniec czterdziestu lat przejścia od beylika do państwa", "62c59cfd"], "d": ["Orhan Gazi, który po śmierci Osmana Gaziego w 1324 roku stanął na czele beylika, w trzydziestoośmioletnich rządach przekształcił Osmanów z granicznego beylika w państwo osadzone po obu stronach Marmary: zdobyto Bursę (1326), Iznik (1331) i Izmit (1337), przyłączono beylik Karesi, wybito pierwszą akçe (1327), w Iznik założono pierwszą medresę (1331), a przejście do Rumelii stało się trwałe przez Çimpe (1352) i Gelibolu (1354). Starszego syna Sulejmana Paszę, prowadzącego podboje w Rumelii, stracił w 1357 roku w wypadku na polowaniu; sam zmarł w marcu 1362 roku w Bursie, a po nim władzę objął syn Murad I.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["Przejście wysp Bahrajnu w ręce Dżabrydów", "6a242b16"], "d": ["Hasło TDV o Bahrajnie notuje, że wyspa „pozostawała kolejno pod rządami Ujunidów, Salgurydów, Tabidów, Dżabrydów, a za Dżabrydów większość przeszła od szyitów do sunnitów”; żadnej z tych dat nie podaje. W literaturze ogólnej dynastia Dżabrydów powstała na początku XV wieku przez obalenie ostatniego władcy Dżarwanidów w Katifie, a w okresie największego rozkwitu (Adżwad b. Zamil, zm. 1496) kontrolowała całe arabskie wybrzeże Zatoki Perskiej, Lahsę, Katif i wyspy Bahrajnu. Po Adżwadzie wyspy Awal przeszły na Mukrina b. Zamila — to właśnie ten władca miał w 1521 roku zostać pobity przez Portugalczyków.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["Zajęcie Arzili przez Portugalię — drugi przyczółek na wybrzeżu Maroka", "83444a11"], "d": ["Alfons V wylądował osobiście na wybrzeżu Maroka z 30 000 żołnierzy i 400-okrętową flotą i 24 sierpnia 1471 roku zajął Arzilę pod rządami Wattasydów. Upadek miasta złamał opór Tangeru; Tanger poddał się cztery dni później, 28 sierpnia, bez walki. Portugalia założyła w ten sposób po Ceucie (1415) i Alcácer Ceguer (1458) trzecią i czwartą placówkę na atlantyckim wybrzeżu Maroka; król po tej wyprawie kazał dodać do tytułu zwrot „pan Afryki”.", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["Wejście Safi w portugalską strefę wpływów", "765e703e"], "d": ["Safi, najruchliwszy port zbożowy i rybacki wybrzeża atlantyckiego, weszło w 1488 roku w portugalską strefę wpływów; miasto przez pewien czas było rządzone rękami miejscowych władców pod opieką Portugalii, a w 1508 roku zostało bezpośrednio zajęte. Ponieważ źródła inaczej ważą te dwa etapy, data początkowa waha się między 1488 a 1508; oba są końcami tego samego procesu. Safi pozostało pięćdziesiąt trzy lata w rękach Portugalczyków i zostało opuszczone w 1541 roku po upadku Agadiru.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["Założenie Santa Cruz do Cabo de Gué — portugalska twierdza w Agadirze", "cc22c433"], "d": ["Twierdza Santa Cruz do Cabo de Gué, założona z prywatnej inicjatywy na wybrzeżu Sus, w miejscu, do którego Portugalia dotąd nie dotarła, została zbudowana w 1505 roku i w 1513 przekazana koronie portugalskiej. Twierdza, kontrolując handel cukrem i złotem w dolinie Sus, zamykała południowo-zachodnie wyjście z Marrakeszu; dlatego stała się pierwszym wielkim celem ruchu Sa'dydów. Oblężenie z 1533 roku odparto, to z 1541 roku zakończyło się sukcesem i zapoczątkowało upadek Portugalii w Maroku.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["Zajęcie Azemmouru — kontrola ujścia Umm er-Rabi'", "232acd4b"], "d": ["Armia portugalska pod dowództwem księcia Braganzy Jaimego 3 września 1513 roku weszła do Azemmouru u ujścia rzeki Umm er-Rabi' bez napotkania oporu. Zajęcie miasta dało kontrolę zarówno nad ujściem rzeki, jak i nad szlakiem zbożowym otwierającym się w głąb lądu, a następnego roku utorowało drogę do założenia 12 km na południowy zachód twierdzy Mazagan. Azemmour pozostał dwadzieścia osiem lat w rękach portugalskich.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["Założenie twierdzy Mazagan — najdłużej utrzymana portugalska placówka w Maroku", "786cdb40"], "d": ["W następnym roku po zajęciu Azemmouru, latem 1514 roku, na wybrzeżu zbudowano gródek Mazagan. Po powszechnym załamaniu z 1541 roku Portugalia opuszczała wszystkie placówki w Maroku, lecz Mazagan nie opuściła; przeciwnie, kazała przebudować twierdzę z bastionami w stylu włoskim i miasto utrzymano dwieście pięćdziesiąt pięć lat. Wielkie oblężenie z 1562 roku również odparto. Mazagan, jako ostatnia portugalska placówka w Maroku, miał zostać opuszczony w 1769 roku.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["Poddanie twierdzy Mardin — koniec oporu Safawidów na południe od Diyarbakıru", "e6226de5"], "d": ["Gdy Bıyıklı Mehmed Pasza, który po Çaldıranie ruszył na region Diyarbakır, oblegał Mardin, siły safawidzkie w październiku 1515 roku wycofały się do twierdzy; miasto wpadło w ręce osmańskie, choć twierdza się broniła. Przeciwnatarcie safawidzkiego gubernatora Kara Chana ze wsparciem zakończyło się w maju 1516 roku bitwą pod Koçhisar (Kızıltepe) — w trwającej cały dzień bitwie na stepie Dede Garkın Kara Chanowi ścięto głowę, a jego armia się rozproszyła. Twierdza zaś, według TDV, poddała się „dopiero po dziewięciu miesiącach”.", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["Zajęcie Bahrajnu przez Portugalię — koniec zwierzchnictwa Dżabrydów", "315a435a"], "d": ["Gdy władca Dżabrydów Mukrin b. Zamil odmówił płacenia podatku Ormuzowi, flota portugalska i siły zależnego od Portugalii Królestwa Ormuzu wylądowały na wyspie; Mukrin został pobity w bitwie, a Bahrajn w 1521 roku wszedł pod rządy portugalskie. Wyspa była potem przez osiemdziesiąt lat rządzona przez Ormuz, głównie rękami sunnickich gubernatorów irańskich. Perły Bahrajnu i jego strategiczne położenie uczynią wyspę bezpośrednim celem osmańsko-portugalskiego współzawodnictwa w Zatoce.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["Upadek Agadiru — Sa'dydzi zaczynają wypierać Portugalię z Maroka", "bb1568f6"], "d": ["Sułtan Sa'dydów Muhammad asz-Szajch oblegał twierdzę Santa Cruz od 16 lutego 1541 roku i zdobył ją 12 marca; do niewoli wpadło około sześciuset Portugalczyków, wraz z gubernatorem Guterre de Monroy.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["Opuszczenie Safi i Azemmouru — Portugalia wycofuje się z wybrzeża atlantyckiego", "4cb6099a"], "d": ["Wobec upadku Agadiru 12 marca 1541 roku i niezawarcia oczekiwanego sojuszu z sułtanem Maroka Jan III rozkazał opuścić dwie wielkie placówki na wybrzeżu atlantyckim; ewakuację Safi i Azemmouru zakończono jesienią 1541 roku, we wrześniu-październiku. W ten sposób w jednym roku utracono trzy placówki i półwieczna ekspansja Portugalii na wybrzeżu Maroka się odwróciła; pozostały Ceuta, Tanger, Arzila, Alcácer Ceguer i nowo ufortyfikowany Mazagan.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["Opuszczenie Arzili — Portugalia zawęża północne wybrzeże", "b5d18373"], "d": ["Wskutek połączenia kryzysu finansowego i nacisku Sa'dydów Jan III opuścił Arzilę, utrzymywaną od 1471 roku. Obecność Portugalii w Maroku skurczyła się w ten sposób do Ceuty, Tangeru i Mazaganu. Arzila miała zostać na krótko ponownie zajęta w 1577 roku i ostatecznie porzucona w 1589.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["Wyprawa osmańska na Bahrajn — ostatnie wielkie uderzenie przeciw Portugalii w Zatoce", "14501df3"], "d": ["Państwo Osmańskie, które po przyłączeniu Basry w 1546 roku i utworzeniu ejaletu Lahsa zadomowiło się na arabskim wybrzeżu Zatoki, wyruszyło na Bahrajn pod dowództwem beylerbeya Lahsy Mustafy Paszy, mierząc w handel perłami na wyspie i portugalską linię Ormuzu. Wynik wyprawy rozchodzi się w źródłach: TDV İslâm Ansiklopedisi pisze, że Osmanowie „w 1559 roku zajęli Bahrajn i założyli tam bazę”, a wyspy „później ponownie przeszły pod rządy Portugalczyków”; literatura zachodnia zapisuje zaś, że oblężenie się nie powiodło, że portugalskie posiłki z Ormuzu przybyłe morzem odparły siły osmańskie i że po zarazie, która złamała obie strony, Osmanowie poprosili o warunki poddania. Obie relacje rozchodzą się w samym wyniku; wspólne jest to, że Bahrajn w rękach osmańskich nie pozostał trwale.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["Zajęcie Tunisu przez Uluç Alego Paszę — koniec ładu hafsydzko-hiszpańskiego", "d4498698"], "d": ["Gdy Karol V w 1535 roku zajął Tunis, nie rządził miastem sam, lecz przywrócił na tron sułtana Hafsydów Mulaja Hasana; według TDV miasto Tunis pozostawało „do drugiej interwencji Osmanów w 1569 roku pod opieką Hiszpanów i rządami Mulaja Ahmeda III”. Uluç Ali, mianowany 27 czerwca 1568 roku beylerbeyem Algieru, ruszył lądem na Tunis, pobił pod Bedżą sułtana Hafsydów i wszedł do miasta; Mulaj Ahmed schronił się w hiszpańskim presidio La Goulette. Zatoka została w ten sposób podzielona na dwie części — miasto osmańskie, twierdza portowa hiszpańska — i podział ten trwał cztery lata.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["Odzyskanie Tunisu przez Don Juana de Austria — jedyny lądowy odpowiednik Lepanto", "a6f044ee"], "d": ["Chociaż po Lepanto (1571) Święta Liga się rozpadła, Hiszpania sama podjęła się Afryki Północnej: według TDV „10 października 1573 roku Hiszpanie podjęli nową operację, by opanować Tunis. Zajęli Tunis i zostawili tam 8000 żołnierzy.” Ta operacja pod dowództwem Don Juana de Austria jest jedynym miejscem, w którym zwycięstwo pod Lepanto znalazło odpowiednik na lądzie; nie była jednak trwała i miasto odzyskano po jedenastu miesiącach. To, co okupacja obaliła, było ustanowioną administracją osmańską: 2 Zu al-Hidżdża 980 (5 kwietnia 1573) dowódcą Tunisu był Kılıç Ali Pasza, kajmakamem Ramazan Pasza, beylerbeyem Haydar Pasza.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["Zajęcie Bahrajnu przez Safawidów od Portugalczyków", "c37d982c"], "d": ["Siły wysłane przez szacha Abbasa I połączyły się z buntownikami na wyspie i wyparły garnizon portugalski z twierdzy; według TDV wyspy zostały „w 1602 roku odebrane Portugalczykom przez siły podległe Iranowi”. Bahrajn wyszedł w ten sposób spod osiemdziesięcioletnich rządów portugalskich i wszedł pod zwierzchnictwo Safawidów, pozostając sto piętnaście lat zależny od Iranu. Jest to pierwsze ogniwo rozkładu Portugalii w Zatoce; dwadzieścia lat później sam Ormuz miał upaść wskutek wspólnej akcji angielsko-irańskiej.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["Inwazja Omańczyków na Bahrajn — koniec zwierzchnictwa Safawidów", "c9be5820"], "d": ["W czasie rozkładu państwa Safawidów w ostatnich latach flota Omanu pod rządami dynastii Ja'rubidów najechała wyspę i zwierzchnictwo Safawidów dobiegło końca. Następne trzydzieści pięć lat to najbardziej zamętny okres w Zatoce: wyspa kilkakrotnie zmieniała ręce między Omanem, Iranem i lokalnymi siłami arabskimi.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["Przejście Bahrajnu pod rządy Al Mazkur z Buszehru", "610e2f9d"], "d": ["Rodzina Al Mazkur, pochodząca z Omanu, osiadła w Buszehrze i zaliczana do Huwala, w 1753 roku wyruszywszy ze swych baz w Buszehrze objęła Bahrajn swoimi rządami. Rodzina przewodziła społecznościom arabskim na zatokowym wybrzeżu Iranu i rządziła wyspą w imieniu Iranu; jej ostatni przedstawiciel Nasr Al Mazkur został mianowany gubernatorem Bahrajnu przez administrację Zendów. Są to ostatnie rządy na wyspie przed Al Chalifa.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["Opuszczenie Mazaganu — upadła ostatnia portugalska placówka w Maroku", "f9e9749d"], "d": ["Wobec oblężenia rozpoczętego na początku 1769 roku przez sułtana Alawitów Muhammada III b. Abdallaha 592-osobowy garnizon nie wytrwał; flota ewakuacyjna, która wyruszyła z Lizbony 1 lutego, 11 marca 1769 roku zabrała na okręty ostatnich żołnierzy, a miasto opuścił jako ostatni gubernator Dinis Gregório. Tak obecność Portugalii w Maroku, która zaczęła się zdobyciem Ceuty w 1415 roku, zakończyła się po trzech i pół wieku. Mazagan był jedyną placówką na wybrzeżu atlantyckim utrzymaną po powszechnym załamaniu 1541 roku i z dwustoma pięćdziesięcioma pięcioma latami jest miejscem, które Portugalia w Maroku trzymała najdłużej.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["Podbój Bahrajnu przez Al Chalifa — założenie dynastii panującej do dziś", "8773b011"], "d": ["Nasr Al Mazkur, gubernator Bahrajnu z ramienia Zendów, oblegał Zubarę na półwyspie Katar; siły Utubów pod dowództwem Ahmada b. Muhammada b. Chalify przełamały oblężenie i przechodząc do przeciwnatarcia zajęły w tym samym roku Bahrajn. Zapis TDV jest krótki: „Bahrajn w 1783 roku wszedł pod zwierzchnictwo Al Chalifa z plemienia Utubów.” Ahmad b. Muhammad po tym zwycięstwie zyskał przydomek „al-Fatih” (Zdobywca), a założona przez niego dynastia rządzi na wyspie do dziś.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["Układ Bahrajnu z Anglią — wejście w system protektoratu w Zatoce", "576796b2"], "d": ["Według zapisu TDV „21 maja 1861 roku Ali, brat szejka Muhammada, reprezentujący Bahrajn, i Anglia podpisali umowę zakazującą w regionie handlu niewolnikami i piractwa”; w dokumentach angielskich ten sam układ (Perpetual Truce of Friendship and Peace) nosi datę 31 maja 1861. Układ jest pierwszym ogniwem systemu protektoratu wiążącego stosunki zewnętrzne Bahrajnu z Anglią, a wyspa pozostała poza tym systemem także po ponownym osiedleniu się Osmanów w Lahsie i Katifie w 1871 roku.", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["Ahî Evran — założycielski pir organizacji ahîlik", "3392e100"], "d": ["Ahî Evran uchodzi za jednego z założycieli organizacji ahîlik w Anatolii i za pira garbarzy (skórników). Jego zawiya w Kırşehirze trwała w okresie osmańskim aż do początku XX wieku jako duchowy ośrodek organizacji rzemieślniczej/cechowej; państwo oficjalnie potwierdzało to stanowisko w latach 1780, 1782, 1822-23 i 1842.", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["Szejk Edebâli — więź założycielska między ahîlik a dynastią osmańską", "c1186059"], "d": ["Edebâli, który założył zawiję w Bilecik i był też szejkiem organizacji ahî, według przekazu wyjaśnił słynny sen Osmana Gaziego; potem Osman Gazi ożenił się z córką Edebâlego, Mâlhun Hatun. Edebâli uchodzi także za pierwszego osmańskiego kadiego i muftiego.", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["Orhan Gazi przeznacza po zdobyciu Bursy teren na gry w cirit", "da1becbd"], "d": ["Według hasła Cirit w TDV Orhan Gazi po zdobyciu Bursy ufundował jako wakf teren w okolicy na wyścigi konne i gry w cirit — jest to jeden z pierwszych odnotowanych przykładów zinstytucjonalizowania gry w cirit u Osmanów.", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["Przekazywany początek zapasów Kırkpınar", "2d93fa65"], "d": ["Według przekazu tradycja zapasów Kırkpınar rozpoczęła się od zawodów zapaśniczych między czterdziestoma gazim, którzy przeszli do Rumelii wraz ze zdobywcą Rumelii Sulejmanem Paszą. Hasła Güreş i Kırkpınar w TDV przytaczają ten przekaz, lecz nie podają dokładnej daty założenia.", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["Założenie Korpusu Janczarów", "f4206dce"], "d": ["System, który pod kierunkiem Çandarlı Kara Halila i Molla Rüstema rozpoczął się od szkolenia nie-muzułmańskich młodzieńców pobieranych z jeńców wojennych na mocy prawa pençik, nabrał za Murada I charakteru instytucjonalnego poprzez Ocak Nowicjuszy (Acemi Ocağı) założony w Gelibolu.", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["Rozpoczęcie budowy Starego Meczetu w Edirne (Wielki Meczet)", "da7a22ac"], "d": ["Budowę Eskicami, znanego wśród ludu także jako Ulucami (Camii-i Atik), rozpoczął Emir Süleyman Çelebi w latach 1402-1403.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["Rozpoczęcie budowy Kompleksu Zielonego Meczetu w Bursie", "280b8a21"], "d": ["Mehmed I, który po Interregnum na nowo zjednoczył tron, rozpoczął budowę kompleksu w 1414 roku i umieścił go w centralnym punkcie Bursy, tak by odróżniał się od kompleksów dziadka i ojca. Jego głównym architektem jest Hacı İvaz Pasza.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["Ukończenie Kompleksu Zielonego Meczetu w Bursie", "bc82821f"], "d": ["Kompleks Zielonego Meczetu, znany z programu kafli i zdobień, do którego przyczynili się także mistrzowie z Tebrizu, został ukończony w grudniu 1419 roku. Kompleks składa się z meczetu, mauzoleum (Zielone Mauzoleum), medresy, imaretu i łaźni; jest jednym z najbogatszych przykładów wczesnej architektury osmańskiej.", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["Faktyczne rozpoczęcie stosowania systemu devşirme", "fa835172"], "d": ["Devşirme, nieznany wcześniejszym państwom islamskim, rozpoczął się najpierw jako wykorzystywanie nie-muzułmańskich młodzieńców będących jeńcami wojennymi na mocy prawa pençik. Według TDV „wiadomo, że stosowano go za Çelebiego Mehmeda, lecz zakodyfikowano dopiero za jego syna Murada II.”", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["Ustanowienie urzędu şeyhülislama — mufti Bursy Molla Fenârî", "2a8ee2b9"], "d": ["Mianowanie uczonego Molla Fenârîego, od wielu lat kadiego Bursy, w 1425 roku muftim Bursy uchodzi według TDV za „początek muftiego i şeyhülislamatu u Osmanów”. TDV zaznacza jednak, że nie jest to tożsame z w pełni zinstytucjonalizowanym urzędem şeyhülislama reprezentującym w XVI wieku całą organizację ilmiye.", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["Zinstytucjonalizowanie systemu timar", "dc267780"], "d": ["Pierwsze udokumentowane wzmianki o timarze sięgają czasów Orhana Beja; systematyczna kodyfikacja nastąpiła za Murada II. Sporządzone w tym okresie rejestry zbiorcze timarów (icmal) pokazują, że ukształtowały się wszystkie podstawowe zasady systemu; dokumenty z około 1432 roku dowodzą, że prawa były w pełni w mocy.", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["Ukończenie Meczetu Üç Şerefeli i jego kompleksu", "cde6993e"], "d": ["Meczet Üç Şerefeli, zbudowany przez Murada II w ciągu dziesięciu lat (1437-1447) przez mistrzów Muslihuddina i Şehabeddina, uważany jest za pierwszy przykład meczetów o planie centralnym w architekturze osmańskiej i jeden z punktów zwrotnych architektury przejściowej przed epoką klasyczną.", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["Zinstytucjonalizowanie Divan-ı Hümayun prawem Zdobywcy", "e8443e77"], "d": ["Divan zaczął nabierać charakteru „Dîvân-ı Hümâyun” za Murada II w Edirne przez ujęcie w regularne reguły. Właściwa przemiana przyszła z prawem Mehmeda Zdobywcy: największą nowością było całkowite zniesienie przewodniczenia padyszacha divanowi i przekazanie go wielkiemu wezyrowi.", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["Przeznaczenie przez Mehmeda Zdobywcę Okmeydanı dla łuczników", "342a9fd5"], "d": ["Mehmed Zdobywca, który podczas zdobycia Stambułu rozłożył obóz na wzgórzach Kasımpaşa, używał tego miejsca zarazem jako placu ćwiczeń dla łuczników; po zdobyciu miasta przeznaczył teren trwale dla łuczników. To przeznaczenie jest początkiem tego, że Okmeydanı stał się ośrodkiem wielowiekowej osmańskiej tradycji łucznictwa.", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["Bursa osiąga szczyt w handlu jedwabiem perskim", "f1324cdf"], "d": ["Karawany z Tebrizu przywoziły do Bursy jedwab z Gilanu, Asztarabadu i Sari, gdzie kupowali go w rywalizacji kupcy genueńscy, weneccy, florenccy i żydowscy. W 1479 roku wartość jedwabiu sprowadzanego z Iranu osiągnęła 150 000 weneckich dukatów; w 1502 roku w mieście pracowało ponad 1000 krosien.", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["Bayezid II przyznaje wielką nagrodę zapaśnikom z Kırkpınar", "d745b882"], "d": ["Według hasła Güreş w TDV Bayezid II w 1504 roku dał zapaśnikom nagrody w wysokości 3000 i 1500 kuruszy; jest to jeden z wczesnych odnotowanych przykładów patronatu osmańskiego dworu nad zapasami.", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["Ukończenie Meczetu Bayezida i jego kompleksu", "eb9ab65b"], "d": ["Budowa Meczetu Bayezida i kompleksu wzniesionego dla Bayezida II rozpoczęła się według dokumentu archiwalnego w 906 (1500) i została ukończona 14 Dżumada I 911 (13 października 1505). Jego architekt jest sporny: na podstawie zapisu Ayvansarâyîego długo uważano go za dzieło Mimara Hayreddina, potem przypisywano Mimarowi Kemaleddinowi, według niektórych pracowali razem; ten sam dokument wskazuje zaś, że mistrzem był Yakub Szah b. Sułtan Szah. Meczet jest jednym z ważnych zabytków przejścia od architektury osmańskiej przedklasycznej do klasycznej.", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["Przeniesienie Tersâne-i Âmire do Stambułu (Kasımpaşa/Złoty Róg)", "f36e3675"], "d": ["Za Selima Groźnego nowa stocznia, której budowę rozpoczęto w zatoce na zachód od murów Galaty, została w 1515 roku ukończona jako 160-stanowiskowa; w ten sposób działalność stoczniowa z ośrodkiem w Gelibolu przeniosła się do Stambułu. Instytucja otrzymała potem za Barbarossy Hayreddina Paszy oficjalną nazwę „Tersâne-i Âmire”.", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["Śmierć szejka Hamdullaha i dziedzictwo szkoły kaligrafii", "f5ed4d09"], "d": ["Szejk Hamdullah z Amasyi, jako nauczyciel kaligrafii Bayezida II, doprowadził szkołę aklâm-ı sitte (sześciu rodzajów pisma) do dojrzałości i został twórcą osmańskiego stylu kaligraficznego, który miał zapanować w całym świecie islamu. Gdy zmarł w 1520 roku, zostawił po sobie szerokie grono uczniów.", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["Ukończenie przez Pirî Reisa pierwszej wersji Kitâb-ı Bahriye", "fd6cc1ff"], "d": ["Pirî Reis ukończył w 1521 roku pierwszą (prozatorską) wersję Kitâb-ı Bahriye, zbierającą wiadomości o wybrzeżach Morza Śródziemnego, portach i żegludze. Ta pierwsza wersja nie została jeszcze przedstawiona padyszachowi i miała charakter szkicu, który w następnych latach zostanie rozbudowany.", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["Rozbudowanie przez Pirî Reisa Kitâb-ı Bahriye i przedstawienie jej Sulejmanowi Prawodawcy", "d4abf0b7"], "d": ["Pirî Reis rozbudował Kitâb-ı Bahriye, częściowo w formie wierszowanej, i w 1526 roku przedstawił ją Sulejmanowi Prawodawcy. W tej postaci dzieło rozpowszechniło się jako najobszerniejszy przewodnik żeglarski osmańskiego żeglarstwa.", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["Matrakçı Nasuh maluje w Beyân-ı Menâzil trasę wyprawy Irakejn", "aa012278"], "d": ["Matrakçı Nasuh, który uczestniczył w pierwszej wyprawie perskiej (Irakejn) Sulejmana Prawodawcy w 1534 roku, namalował techniką miniatury-mapy każdy postój na trasie armii ze Stambułu do Tebrizu, a stamtąd do Bagdadu. Praca ta została zebrana w dziele Beyân-ı Menâzil-i Sefer-i Irâkeyn i jest najoryginalniejszym przykładem gatunku menzilname w Imperium Osmańskim.", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["Fuzûlî składa Sulejmanowi kasydę po zdobyciu Bagdadu", "1ef0653f"], "d": ["Po zdobyciu Bagdadu przez Sulejmana Prawodawcę w 1534 roku Fuzûlî złożył osmańskiemu sułtanowi pięć kasyd, w tym słynną kasydę zaczynającą się od wersu „Geldi burc-ı evliyâya pâdişâh-ı nâmdâr”; tak wyszedłszy spod opieki Safawidów, szukał patronatu osmańskich dostojników.", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["Fuzûlî kończy mesnewi Leylâ vü Mecnûn", "e3ef4085"], "d": ["Leylâ vü Mecnûn, uważany za jedno z najpiękniejszych mesnewi klasycznej literatury tureckiej, został przez Fuzûlîego napisany i ukończony w 1535 roku na prośbę stambulskich poetów, którzy uczestniczyli w wyprawie bagdadzkiej Sulejmana.", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["Mianowanie Mimara Sinana nadwornym głównym architektem", "7a753f0e"], "d": ["Według hasła Sinan w TDV İslâm Ansiklopedisi, po śmierci nadwornego głównego architekta Acem Alisiego w 1537 roku Sinan, który zwrócił uwagę mostem zbudowanym na rzece Prut podczas wyprawy mołdawskiej, został mianowany na to stanowisko dzięki uznaniu wielkiego wezyra Lütfi Paszy. Tak rozpoczął się trwający ponad pięćdziesiąt lat okres Sinana jako głównego architekta.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["Rozpoczęcie budowy Meczetu i Kompleksu Şehzade", "1a70ddfd"], "d": ["Sulejman Prawodawca nakazał budowę kompleksu ku czci syna Şehzade Mehmeda, którego stracił w 1543 roku w epidemii dżumy; budowa rozpoczęła się w czerwcu 1543 roku, najpierw ukończono mauzoleum, a potem przystąpiono do budowy meczetu. Ten gmach jest według słów samego Mimara Sinana „dziełem czeladnika”.", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["Ukończenie Kompleksu Üsküdar İskele (Mihrimah Sułtan)", "3769007f"], "d": ["Budowa kompleksu na placu przystani w Üsküdarze rozpoczęła się w pierwszych latach lat czterdziestych XVI wieku i została ukończona w 1547 roku. Jest chronologicznie pierwszym z dwóch wielkich meczetów, które Mihrimah Sułtan kazała zbudować Mimarowi Sinanowi; drugi (Edirnekapı) miał zostać ukończony około dwadzieścia lat później.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["Otwarcie konsulatu Wenecji w Aleppo", "3aad8b9e"], "d": ["W XVI wieku środek ciężkości handlu Europejczyków przesunął się z Damaszku do Aleppo. Konkretnym wskaźnikiem tej zmiany było otwarcie przez Wenecję konsulatu w Aleppo w 1548 roku; za nią poszły Francja w 1557 i Anglia w 1586. Miasto stało się głównym rynkiem wymiany europejskich tkanin wełnianych i srebra z indyjskimi korzeniami, a pod koniec stulecia z jedwabiem perskim.", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["Otwarcie Meczetu Şehzade do kultu", "2bb3f4b2"], "d": ["Po budowie trwającej około pięciu lat Meczet Şehzade został w sierpniu 1548 roku otwarty do kultu. Ze swym planem z podwójnym minaretem i centralną kopułą uchodzi za zwiastun późniejszych wielkich dzieł Mimara Sinana; kompleks składa się z meczetu, mauzoleum, medresy, imaretu, tabhane i karawanseraju.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["Rozpoczęcie budowy linii doprowadzającej wody Kırkçeşme", "14124b59"], "d": ["Mimar Sinan z rozkazu Sulejmana zbadał sprawę doprowadzenia wody z lasów belgradzkich do Stambułu i zawiadomił, że jest to możliwe; budowa wielkiego systemu wodnego rozpoczęła się w 1554 roku i została ukończona przed 1563. TDV opisuje ten obiekt jako „najważniejsze pod względem inżynieryjnym i największe pod względem rozmiarów dzieło” Sinana.", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["Otwarcie pierwszych kawiarni w Stambule", "85c12f9f"], "d": ["Wejście kawy do osmańskiego życia miejskiego rozpoczęło się od kawiarni otwartych w Tahtakale przez kupca z Aleppo Hakema i niejakiego Szamlego Szemsa. W krótkim czasie powstała nowa przestrzeń publiczna, w której spotykali się ludzie ze wszystkich warstw społeczeństwa; w ostatnim okresie Sulejmana w Stambule było pięćdziesiąt kawiarni.", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["Zbadanie przez Ebüssuûda Efendiego sprawy gedik (monopolu rzemieślniczego) pod względem prawnym", "5d4e2930"], "d": ["Sprawa „gedik”, czyli prawa monopolu i przywileju przyznanego określonej liczbie osób w rzemiośle, wróciła na porządek dzienny za Sulejmana; Şeyhülislâm Ebüssuûd Efendi w latach 1555-56 zbadał rzecz dogłębnie i przedstawił padyszachowi zgodność praktyki z prawem.", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["Ukończenie w Stambule przez Seydi Alego Reisa Mir'ât al-Memâlik", "ee8640e1"], "d": ["Seydi Ali Reis ukończył w styczniu 1557 roku w Stambule dzieło podróżnicze Mir'ât al-Memâlik, które pisał w drodze powrotnej, zaczynając od Bagdadu. Dzieło jest relacją z pierwszej ręki o powrocie osmańskiego żeglarza do ojczyzny drogą lądową z Oceanu Indyjskiego przez Azję Środkową.", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["Zbudowanie Kompleksu (Meczetu) Rüstema Paszy", "02e30725"], "d": ["Kompleks zbudowany przez Mimara Sinana dla zięcia i wielkiego wezyra Sulejmana, Rüstema Paszy, wzniesiono w latach 1555-1561. Budowla jest znana z oryginalnej architektury postawionej na podniesionej platformie ze sklepikami o łukowych arkadach pod spodem oraz z bogatych kafli z Iznik.", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["Ukończenie Mostu w Mostarze", "e7f434af"], "d": ["Słynny Most w Mostarze na rzece Neretwie został zbudowany około 1566-67 roku przez Mimara Hayreddina; wzmianka o moście w oficjalnym dokumencie z 1568 roku potwierdza, że był ukończony. Budowla jest jednym z najbardziej znanych przykładów klasycznej architektury mostowej osmańskiej z jednym spiczastym łukiem.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["Ukończenie Meczetu Edirnekapı (Mihrimah Sułtan)", "f2d21a82"], "d": ["Budowę meczetu rozpoczętą po potwierdzeniu w 1563 roku zezwolenia na budowę dla córki Sulejmana Mihrimah Sułtan ukończono w 1566 roku; akt fundacyjny kompleksu sporządzono w 1570-71. Budowla jest jednym z największych dzieł Mimara Sinana położonych najbliżej murów Stambułu.", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["Bâkî pisze elegię na śmierć Sulejmana Prawodawcy", "7aa6665f"], "d": ["Gdy nadeszła wiadomość o śmierci Sulejmana Prawodawcy pod Szigetvárem, Bâkî, ówczesny „sułtan poetów”, napisał jedną z najsłynniejszych elegii literatury osmańskiej.", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["Bâkî składa Selimowi II cülûsiye", "6027f034"], "d": ["Zaraz po wstąpieniu Selima II na tron Bâkî złożył nowemu padyszachowi „cülûsiye” (wiersz na wstąpienie na tron) — według TDV zaraz po elegii napisanej na śmierć Sulejmana.", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["Ukończenie Mostu Büyükçekmece", "5f49b3c5"], "d": ["Most rozpoczęty z rozkazu Sulejmana Prawodawcy został po śmierci padyszacha podczas wyprawy na Szigetvár ukończony przez jego syna Selima II w latach 1567-68. Mimar Sinan sam naprawił też odcinki mostu zbudowanego w miejscu, gdzie jezioro Büyükçekmece łączy się z morzem, uszkodzone przez powódź.", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["Rozpoczęcie budowy Meczetu Selimiye (Edirne)", "07e18c9e"], "d": ["Budowa Selimiye, które Mimar Sinan nazywał „dziełem mistrzowskim”, rozpoczęła się w 1568 roku ku czci Selima II i trwając sześć lat została ukończona w 1574 (jej ukończenie jest już zapisane w kronologii). Zachodnie sklepy arastu i szkoła dla dzieci zostały natomiast ukończone przez Dawuda Agę po śmierci Selima II, za Murada III.", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["Śmierć Kınalızâde Alego Çelebiego — autora Ahlâk-ı Alâî, klasycznego tekstu osmańskiej filozofii moralności", "dd921873"], "d": ["Kınalızâde Ali Çelebi, autor Ahlâk-ı Alâî, najbardziej znanego klasycznego tekstu osmańskiej filozofii moralności, zmarł 22 stycznia 1572 roku jako kazasker Anatolii. Jego dzieło ma ponad siedemdziesiąt egzemplarzy w bibliotekach Stambułu.", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["Zbudowanie Kompleksu Piyale Paszy", "75411278"], "d": ["Kapudan paşa Piyale Pasza, jeden z zięciów Selima II, kupił w 1573 roku grunt pod kompleks i kazał go zbudować Mimarowi Sinanowi. Kompleks zaprojektowano jako rozległy zespół składający się z meczetu, medresy, tekke, mauzoleum, cmentarza, szkoły dla dzieci, fontanny, bazaru i łaźni.", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["Ukończenie Mostu na Drinie (Sokollu Mehmed Paszy)", "1d668c73"], "d": ["Most zbudowany przez Mimara Sinana pod patronatem wielkiego wezyra Sokollu Mehmeda Paszy został według daty na inskrypcji ukończony w latach 1577-78; niektórzy badacze twierdzą, że budowa rozpoczęła się w 1571-72. Most jest symbolem przywiązania Sokollu do Višegradu, gdzie się urodził.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["Zbudowanie Meczetu Azapkapı (Sokollu Mehmed Paszy)", "f7b57feb"], "d": ["Meczet położony przy filarze Mostu Unkapanı od strony Şişhane został zbudowany przez Mimara Sinana dla wielkiego wezyra Sokollu Mehmeda Paszy. Budowla jest jednym z dwóch meczetów Sinana wzniesionych dla Sokollu (drugim jest meczet w Kadırga).", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["Murad III wydaje ferman o napisaniu Hünernâme", "b125710d"], "d": ["Murad III fermanem z 2 stycznia 1578 roku nakazał Seyyidowi Lokmanowi napisanie Hünernâme, opisującego życie padyszachów od Osmana Gaziego do jego własnych czasów; miniatury do dzieła przygotował Nakkaş Osman wraz z zespołem.", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["Ukończenie Meczetu Zal Mahmuda Paszy", "732f75bc"], "d": ["W budowie kompleksu rozpoczętej po małżeństwie Zala Mahmuda Paszy z Szah Sułtan w 1574 roku meczet ukończono w 1580; medresy trwały do 1582, a fontanna do 1590. Kompleks zwraca uwagę oryginalnym planem z dwoma symetrycznymi minaretami na zboczach Eyüp.", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["Ukończenie drugiego tomu Hünernâme", "70a1e741"], "d": ["Drugi tom Hünernâme ukończono w styczniu 1588 roku; z 65 miniaturami stał się jednym z najcenniejszych dokumentalnie dzieł osmańskiej historiografii. Oba tomy zostały ilustrowane w pracowni Nakkaşa Osmana.", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["Dawud Aga zostaje nadwornym głównym architektem", "8cdc7f53"], "d": ["Od krótkiej przerwy po śmierci Mimara Sinana w 1588 roku Dawud Aga zaczął być od 1592 roku wymieniany w oficjalnych dokumentach jako nadworny główny architekt. Dawud Aga, który podjął się niektórych uzupełniających elementów Kompleksu Selimiye i pierwszej budowy Yeni Cami, jest jednym z najważniejszych architektów swej epoki.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["Założenie fundamentów Yeni Cami (Eminönü)", "d3cddc01"], "d": ["Fundamenty meczetu, pod patronatem Safiye Sułtan, matki Mehmeda III, położono na wzmocnionym palami gruncie z kamiennych bloków. Dwa odrębne hasła TDV podają dla tego wydarzenia różne daty (hasło Yenicami Külliyesi 9 kwietnia 1598, hasło Dâvud Ağa 23 sierpnia 1597); tu przyjęto datę z osobnego hasła o samym budynku.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["Śmierć Dawuda Agi na dżumę i pozostawienie budowy Yeni Cami niedokończonej", "81f2cd04"], "d": ["Na miejsce Dawuda Agi, który zmarł w wrześniu 1598 roku w epidemii dżumy, gdy Yeni Cami wzniósł się zaledwie na łokieć od ziemi, mianowano głównym architektem Dalgıça Ahmeda Çavuşa. TDV zaznacza, że w alternatywnej relacji opartej na poemacie chronogramowym data śmierci pojawia się także jako 1599-1600 i że dokładnej daty nie ustalono.", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["Intensywny eksport sofu z Ankary do Europy", "3f37018d"], "d": ["Sof i şâlî tkane w Ankarze eksportowano nie tylko na rynki wewnętrzne, jak Stambuł, Bursa, Damaszek i Aleppo, lecz także do Wenecji, Polski, Anglii i Francji. W przykładzie podanym przez TDV w 1599 roku osiemnastu kupców kupiło 162 ładunki sofu o wartości 5 700 000 akçe i wysłało je do Aleppo i Wenecji.", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["Wstrzymanie budowy Yeni Cami po śmierci Mehmeda III", "5acef053"], "d": ["Po śmierci syna fundatorki Safiye Sułtan, Mehmeda III, w 1603 roku Safiye Sułtan została wysłana do Starego Pałacu, a budowa Yeni Cami została przerwana; budynek w tym stanie czekał około sześćdziesięciu lat na ukończenie.", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["Kâtib Çelebi rozpoczyna w Aleppo badania do Keşf az-Zunûn", "094e6870"], "d": ["Kâtib Çelebi rozpoczął w 1633 roku w Aleppo zbieranie materiału do Keşf az-Zunûn, które miało zostać jego bibliograficznym arcydziełem. W trakcie tej pracy, która miała trwać dwadzieścia lat, przeszukiwał po kolei biblioteki i księgarnie miast, w których bywał.", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["Egzekucja Nef'îego za jego satyry", "5e459c60"], "d": ["Poeta dywanowy Nef'î, znany ze swoich satyr, został w 1635 roku z rozkazu Murada IV stracony za zbiór satyr Sihâm-ı Kazâ. Wielki wezyr Bayram Pasza go wydał; Nef'î został uduszony w pałacowej drewutni, a jego ciało wrzucono do morza.", "e3b52153"]},
"OLAYLAR_EK14:1640-01-01:0":{"b": ["Pierwsza podróż Evliyi Çelebiego — początek Seyahatnâme", "ca3ce3f9"], "d": ["Evliya Çelebi odbył w 1640 roku pierwszą podróż poza Stambuł, do Bursy, rozpoczynając czterdziestoletnie życie podróżnika, które stało się podstawą jego dziesięciotomowego Seyahatnâme. Dzieło, gdy autor zmarł około 1684 roku, urywa się niedokończone nagle w dziesiątym tomie.", "1db7969c"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["Sporządzenie obszernego rejestru narh", "6c1e231b"], "d": ["Chociaż stosowanie narh (pułapu cen) sięga u Osmanów bardzo dawna, najobszerniejszy zachowany rejestr narh pochodzi z 1640 roku; rejestr ten, obejmujący żywność, odzież, usługi, standardy i warunki higieny, „funkcjonował jak pełny kodeks regulacji rynku”, jak to ujmuje TDV.", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["Kâtib Çelebi po raz pierwszy zaczyna pisać Cihannümâ", "554c6734"], "d": ["Kâtib Çelebi, aby wypełnić lukę w osmańskiej wiedzy geograficznej wobec zachodnich odkryć geograficznych, rozpoczął w 1648 roku pierwszą redakcję Cihannümâ. Ta pierwsza wersja pozostała niedokończona, ponieważ o niektórych krajach europejskich nie znaleziono dostatecznych źródeł.", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["Dojrzewanie systemu iltizam przez przejście w monopol stanu wojskowego", "2c587934"], "d": ["Iltizam (wydzierżawianie poboru podatków osobom prywatnym za opłatą) stosowano od drugiej połowy XV wieku, lecz od początku XVI wieku szybko się rozpowszechniał. Według TDV proces przejścia całego sektora w monopol członków stanu wojskowego zakończył się w 1650 roku; iltizam stał się w ten sposób główną metodą finansową zastępującą system timar.", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["Kâtib Çelebi przystępuje do ponownego pisania Cihannümâ", "e9c68110"], "d": ["Kâtib Çelebi, który porzucił pierwszą redakcję, przystąpił pod koniec 1654 roku do napisania Cihannümâ od nowa. Ta druga wersja również nie została ukończona; dzieło doszło do Wanu, gdy śmierć autora w 1657 roku przerwała pracę, i w tej postaci wydrukował je dopiero w 1732 roku İbrahim Müteferrika.", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["Ukończenie Yeni Cami i otwarcie go do kultu", "d6d86c82"], "d": ["Budowę Yeni Cami, niedokończonego przez ponad sześćdziesiąt lat, ukończono pod kierunkiem głównego architekta Meremetçi Mustafy Agi, powołanego w 1661 roku przez Hatice Turhan Valide Sułtan, i otwarto do kultu piątkową modlitwą odprawioną 30 października 1665 roku.", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["Mehmed IV organizuje przez wiele dni gry w cirit podczas wesela obrzezania w Edirne", "3638a5b6"], "d": ["Mehmed IV zorganizował na weselu obrzezania swych książąt w Edirne w 1675 roku trwające wiele dni zawody w cirit; jest to jeden z najokazalszych przykładów poparcia osmańskiego dworu dla sportu cirit, szczególnie wspomniany w haśle Cirit w TDV.", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["Hâfız Osman rozwija własny styl kaligraficzny", "93081cb3"], "d": ["Hâfız Osman, wywodzący się z linii szejka Hamdullaha, wypracował w 1679 roku w aklâm-ı sitte własny, nazwany później „szkołą Hâfıza Osmana” styl. Styl ten przetrwał do dziś w dwóch odrębnych gałęziach.", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["Mianowanie Hâfıza Osmana nauczycielem kaligrafii Mustafy II", "d976cda4"], "d": ["Hâfız Osman, uważany za najwybitniejszego kaligrafa swojej epoki, został w 1695 roku mianowany nauczycielem kaligrafii świeżo wstępującego na tron Mustafy II. W ciągu życia wykształcił około pięćdziesięciu kaligrafów i przepisał 25 egzemplarzy Koranu.", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["Śmierć Itrîego", "62750526"], "d": ["Buhûrîzâde Mustafa Itrî Efendi, jeden z największych kompozytorów muzyki tureckiej, zmarł według źródeł bliskich epoce w 1711 roku. Dziełami takimi jak tekbir segâh i na't rast pozostawił arcydzieła muzyki meczetowej i tekke.", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["Nedîm wysuwa się jako prekursor poezji Epoki Tulipanów", "d3c40dbb"], "d": ["W Epoce Tulipanów w latach 1718-1730 Nedîm rozwinął nowy styl poezji wyróżniający się doskonałością wyrazu, dążeniem do prostoty i dowcipną manierą. Styl ten, rozwijający się wokół Nevşehirlego Damata İbrahima Paszy, uchodzi za największego przedstawiciela nurtu zlokalizowania w poezji dywanowej.", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Levnî ilustruje Surnâme-i Vehbî", "8c127866"], "d": ["Nadworny malarz Levnî zilustrował 137 miniaturami Surnâme-i Vehbî, opisujący wesele obrzezania książąt Ahmeda III w 1720 roku. W odróżnieniu od wcześniejszych przykładów nie zamknął uroczystości tylko w Atmeydanı, lecz przedstawił je w różnych zakątkach miasta, czym zapoczątkował nowe podejście w osmańskiej sztuce miniatury.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["Formalne ugruntowanie systemu gedik jako ładu rzemieślniczego opartego na monopolu", "cd0f79a7"], "d": ["Według TDV systematyczna przemiana, w której prawo gedik nabrało znaczenia „monopolu, przywileju i swego rodzaju patentu”, jest śledzona od 1727 roku; ten ład, przyznający prawo pracy określonej liczbie osób w rzemiośle, utrwalił się pod nazwą „prawa gedik” głównie w sklepach będących własnością wakfów.", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Zniszczenie Sâdâbâd podczas buntu Patrony Halila", "8a30f9a0"], "d": ["W czasie buntu Patrony Halila, który wybuchł 25 września 1730 roku, zniszczono setki pawilonów i budowli w Sâdâbâd; ten kompleks, symbol Epoki Tulipanów, nigdy już nie odzyskał dawnej świetności.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Śmierć Nedîma podczas buntu Patrony Halila", "06bf909e"], "d": ["Nedîm, który w chwili wybuchu buntu Patrony Halila był müderrisem w medresie Sekban Alego Paszy, zmarł w dniach następujących po buncie. Dzień śmierci nie jest znany; ponieważ jednak kassam hüccet dotyczący jego spuścizny został sporządzony 15 Rabi' II 1143 (28 października 1730), zmarł przed tą datą. O przyczynie śmierci krążą różne relacje: część źródeł pisze, że zmarł na chorobę strachu (illet-i vehîme) albo na chorobę z drżeniem wywołaną alkoholem i opium, Müstakimzâde zaś, że podczas rewolty ze strachu wszedł na dach swego domu i spadłszy stamtąd, zginął. Wraz z jego śmiercią kulturalny blask Epoki Tulipanów faktycznie dobiegł końca.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Śmierć Levnîego", "dd48b56e"], "d": ["Levnî, uważany za ostatniego wielkiego przedstawiciela osmańskiej sztuki miniatury, zmarł w 1732 roku. Większość jego dzieł znajduje się dziś w Muzeum Pałacu Topkapı.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["Założenie fundamentów Meczetu Nuruosmaniye i jego kompleksu", "397ec798"], "d": ["Fundamenty Kompleksu Nuruosmaniye położył Mahmud I 19 stycznia 1749 roku. Budowla ta uchodzi za pierwsze wielkie zastosowanie europejskiego stylu barokowego w architekturze osmańskiej i wyraźnie odchodzi od klasycznego schematu kompleksu.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["Otwarcie Meczetu Nuruosmaniye i jego kompleksu", "15d83731"], "d": ["Otwarcie kompleksu, rozpoczętego przez Mahmuda I, który nie doczekał jego ukończenia, nastąpiło 5 grudnia 1755 roku za panowania jego brata Osmana III. Meczet otrzymał nazwę w odniesieniu do Osmana III, który dokonał otwarcia, w znaczeniu „Światło Osmana”.", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Otwarcie Mühendishâne-i Bahrî-i Hümâyun", "a2fab1cd"], "d": ["Pierwsza nowoczesna osmańska szkoła inżynierii morskiej, Mühendishâne-i Bahrî-i Hümâyun, została według francuskich dokumentów archiwalnych otwarta 29 kwietnia 1775 roku za panowania Abdülhamida I, za wielkiego wezyratu Derviş Mehmeda Paszy.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["Ustanowienie systemu esham", "eabd8ece"], "d": ["W obliczu ciężaru odszkodowania w wysokości 7,5 miliona kuruszy narzuconego Traktatem w Küçük Kaynarca w 1775 roku wprowadzono system esham. W tej metodzie, pomyślanej tak, by przekroczyć granice malikâne, dochód z mukâtaa dzielono na udziały, a w odróżnieniu od malikâne udziałowcami mogły być także kobiety, nie-muzułmanie i zwykli ludzie.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Narodziny Hammâmîzâde İsmaila Dedego Efendiego", "c033f039"], "d": ["Hammâmîzâde İsmail Dede Efendi, jeden z najpłodniejszych kompozytorów muzyki tureckiej, urodził się 9 stycznia 1778 roku w dzielnicy Şehzadebaşı w Stambule. W ciągu życia skomponował ponad 500 utworów; do dziś zachowało się około 294 z nich.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Rozpoczęcie budowy Mühendishâne-i Berrî-i Hümâyun", "4f5d521a"], "d": ["Budowę Mühendishâne-i Berrî-i Hümâyun, jednej z najważniejszych instytucji reform Nizâm-ı Cedîd Selima III, rozpoczęto 14 lipca 1793 roku. Budynek ukończono we wrześniu 1795 roku i otwarto do nauczania; instytucja była drugą osmańską szkołą inżynierii wojskowej, wzorowaną na akademiach wojskowych w Europie.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["Selim III zaczyna znosić monopol niektórych cechów rzemieślniczych", "008f4a7d"], "d": ["Według hasła Esnaf w TDV w osmańskim ładzie cechowym, od początku splecionym z organizacją ahî, funkcjonariusze tacy jak „ahî baba” i „szejk” przewodzili cechom do początku XIX wieku; gdy w XVIII wieku cechy monopolem podniosły ceny ponad narh i wywołało to nacisk ekonomiczny, Selim III zaczął od 1794 roku znosić monopol cechów podstawowych artykułów spożywczych.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Przyjęcie Dedego Efendiego na dwór jako musâhib-i şehriyârî", "0cb99ac3"], "d": ["Dede Efendi, który za Selima III zwrócił uwagę padyszacha kompozycją bûselik, został w 1812 roku przyjęty przez Mahmuda II do grona „musâhib-i şehriyârî” (towarzyszy osobistych narad padyszacha), a wkrótce awansował na müezzinbaşı.", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["Przeprowadzenie pierwszego regularnego spisu ludności u Osmanów", "4f004c6c"], "d": ["Mahmud II kazał po raz pierwszy przeprowadzić regularny spis pod koniec 1830 roku w celu ustalenia ludności podlegającej poborowi; zapisywano tylko ludność męską i ustalono w Anatolii i Rumelii około 7,5 miliona osób. W niektórych regionach, jak Erzurum i Wan, spis udało się zakończyć dopiero w 1836 roku.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Założenie Feshâne-i Âmire", "971ab85a"], "d": ["Dla zaspokojenia potrzeb armii Asâkir-i Mansûre-i Muhammediyye, utworzonej po zniesieniu Korpusu Janczarów w 1826 roku, w 1833 roku z kapitałem 1,5 miliona kuruszy rozpoczęto produkcję fezów na placu Cündî Meydanı w Kadırga. W 1839 roku zakłady przeniesiono do Pałacu Hatice Sułtan w Eyüp; Feshâne stała się podstawą osmańskiego przemysłu tekstylnego.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["Nadanie szkole medycznej nazwy Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne", "187d60f3"], "d": ["Szkoła medyczna, przeniesiona do budynku Szkoły Agów Enderunu w Galatasaray, otrzymała 14 maja 1839 roku, podczas wizyty Mahmuda II, nazwę „Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne”; instytucja została w ten sposób oficjalnie zapisana z tożsamością szkoły wojskowo-administracyjnej.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Śmierć Dedego Efendiego w Minie podczas hadżdżu", "c3e613a2"], "d": ["Hammâmîzâde İsmail Dede Efendi, który zachorował na cholerę w Minie, dokąd udał się, by wypełnić obowiązek hadżdżu, zmarł 29 listopada 1846 roku. Wraz ze śmiercią artysty, który w latach 1824-1839 skomponował siedem odrębnych ajinów mewlewijskich, zamknął się pewien okres klasycznej muzyki osmańskiej.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["Przyjęcie Kodeksu Handlowego z 1850 roku", "8ac085fd"], "d": ["W ramach reform prawnych epoki Tanzimatu od państw zachodnich przejęto nowe ustawy drogą tłumaczenia i zapożyczeń: kodeks karny wszedł w życie w 1840 roku, kodeks handlowy w 1850, kodeks ziemski w 1857. Kodeks Handlowy był pierwszą nowoczesną kodyfikacją osmańskiego prawa handlowego.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["Początek wielkiej fali migracji Tatarów krymskich i ludów kaukaskich na ziemie osmańskie", "8832c06d"], "d": ["Po dostaniu się szejka Szamila do niewoli rosyjskiej w 1859 roku wielu czerkieskich i nogajskich muhadżirów z Kaukazu, wraz z Tatarami krymskimi, zaczęło migrować na ziemie osmańskie. Ta fala migracji trwała z różnym natężeniem aż do czasów po wojnie osmańsko-rosyjskiej 1877-78.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["Utworzenie Komisji Muhâcirîn", "9717e77e"], "d": ["Aby zarządzać rosnącą falą migracji z Kaukazu, rząd osmański utworzył 16 stycznia 1860 roku Komisję Muhâcirîn. Komisja koordynowała prace osadnicze w Anatolii, na Bałkanach i w Syrii i działała do 1875 roku.", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Przekształcenie Bank-ı Osmanî w Bank-ı Osmanî-i Şâhâne (Bank Osmański)", "c3530456"], "d": ["W 1856 roku po wojnie krymskiej założono Bank-ı Osmanî z siedzibą w Londynie i kapitałem angielskim, by zarządzać spłatami długu zewnętrznego. W 1863 roku wspólnej grupie francusko-angielskiej udzielono zezwolenia na założenie nowego banku pod nazwą Bank-ı Osmanî-i Şâhâne (Bank Osmański); instytucja otrzymała później także uprawnienie do emisji banknotów.", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Założenie Cem'iyyet-i Tedrîsiyye-i İslâmiyye", "77ad553a"], "d": ["W celu podjęcia się edukacji ubogich muzułmańskich uczniów rzemieślniczych założono 30 marca 1864 roku Cem'iyyet-i Tedrîsiyye-i İslâmiyye; ta cywilna inicjatywa stowarzyszeniowa jest pionierskim przykładem przemiany tradycji instytucji dobroczynnych w projekt nowoczesnej szkoły. Stowarzyszenie miało dziewięć lat później otworzyć Darüşşafakę.", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["Uregulowanie systemu muhtarów i rad starszych przez Nizamnâme Wilajetów z 1864 roku", "1a2e8cf2"], "d": ["Nizamnâme Wilajetów z 1864 roku na nowo uregulowało zarząd wsi; przyjęto, że we wsiach zamieszkałych wspólnie przez muzułmanów i nie-muzułmanów każda wspólnota wybiera własnego muhtara i radę starszych. Rada starszych zyskała w ten sposób po raz pierwszy oficjalne miejsce w zarządzie wsi/dzielnicy.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["Szczytowy punkt Wielkiego Wygnania Czerkiesów", "b2ab1874"], "d": ["W wyniku rosyjskiej okupacji Kaukazu w latach 1858-1878, najintensywniejszej w latach 1861-1864, 1,2-1,5 miliona Czerkiesów zostało przymusowo przesiedlonych na ziemie osmańskie. Według TDV wielu badaczy określa to wydarzenie jako „pierwszy ruch czystek etnicznych w historii nowożytnej”.", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["Ogłoszenie Nizamnâme Maârif-i Umûmiyye z 1869 roku", "787f6022"], "d": ["Nizamnâme Maârif-i Umûmiyye, ogłoszone 1 września 1869 roku, było pierwszym obszernym tekstem regulującym powszechną edukację w prowincjach i w centrum. Nizamnâme powołało Meclis-i Kebîr-i Maârif; wraz z tą regulacją rozpoczęło się wyprowadzanie szkół sıbyan z roli etapu wyłącznie religijnej edukacji i przebudowa ich ku nauce czytania i pisania.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["Rozpoczęcie nauczania w szkole Darüşşafaka", "525c457c"], "d": ["Darüşşafaka, założona przez Cem'iyyet-i Tedrîsiyye-i İslâmiyye, faktycznie rozpoczęła nauczanie 28 czerwca 1873 roku, kształcąc bezpłatnie w internacie osierocone i ubogie dzieci muzułmańskie; maksymalny wiek przyjęcia ustalono na dziesięć lat.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["Trzęsienie ziemi w Stambule w 1894 roku", "7ae7f648"], "d": ["Trzęsienie ziemi, które nastąpiło 10 lipca 1894 roku u wybrzeży Zatoki Izmit, mocno uderzyło w Stambuł; uszkodzono wiele meczetów i zabytkowych budowli, w tym mury Stambułu. Hasło o trzęsieniach ziemi w TDV zalicza to trzęsienie, wraz z trzęsieniami z 1509, 1719 i 1766 roku, do tych, które spowodowały duże straty w ludziach i mieniu w regionie Marmara.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["Otwarcie Dârülaceze", "a30baf31"], "d": ["Dârülaceze, przygotowany na rozkazy wydawane przez Abdülhamida II od 1890 roku, został otwarty 2 lutego 1896 roku przez wielkiego wezyra Halila Rifata Paszę. Instytucja, w której mieszkały dzieci bez opiekunów, starcy i potrzebujący, była największym kompleksem pomocy społecznej swej epoki, z 200-łóżkowym szpitalem, warsztatami i osobnymi domami modlitwy, jak meczet, kościół i synagoga.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Ponowne założenie Dârülfünûn-ı Şâhâne jako trwałej instytucji", "7d6d8fc4"], "d": ["Darülfünun po dwóch wcześniejszych nieudanych próbach (1863 i 1870) został 31 sierpnia 1900 roku ponownie założony jako trwała instytucja pod nazwą Dârülfünûn-ı Şâhâne; TDV określa tę datę jako bezpośredni fundament dzisiejszego tureckiego systemu uniwersyteckiego.", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["Sarbadarowie zajęli Sabzewar — pierwsze państwo po Ilchanach w Chorasanie", "af997fec"], "d": ["Gdy wraz ze śmiercią Abu Sa'ida (30 listopada 1335) załamała się centralna władza Ilchanów, nagromadzony w Chorasanie sprzeciw wobec poborców podatków wybuchł w Baszticie: Abd ar-Razzaq 13 marca 1337 roku podniósł powstanie, a 9 września 1337 (12 Safar 738) zajął Sabzewar. Nazwa „Sarbadar” — „z głową na szubienicy” — to ich własne słowa, wyrażające gotowość na powieszenie w razie klęski.", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["Sajjidowie Mar'aszi zajęli Amol — władza sajjidów w Mazandaranie", "c0e03266"], "d": ["Sajjid Kiwam ad-Din Mar'aszi, idąc drogą otwartą przez Sarbadarów w Chorasanie, w roku 760 (1359) zajął Amol i założył państwo sajjidów na południowym brzegu Morza Kaspijskiego. Dynastia rozszerzyła się na Sari, Barfurusz i okolice; zachwiana w wyprawach Timura, została rozwiązana za safawidzkiego szacha Abbasa I.", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["Dynastia Karkija założona w Gilanie — ostatni niezależni władcy wybrzeża Kaspijskiego", "6e5f9db7"], "d": ["Ali Kija wraz z rodziną wrócił do Gilanu i w roku 773 (1371-72) założył władzę Karkija z ośrodkiem w Lahidżanie; dynastia trzymała południowo-zachodni brzeg Morza Kaspijskiego przez ponad dwa stulecia, aż do przyłączenia regionu przez safawidzkiego szacha Abbasa I w 1592 roku.", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["Przejście władzy Daju w Darfurze na Tunjurów", "6eb22a2a"], "d": ["Według hasła Dârfûr w TDV İslâm Ansiklopedisi pierwszymi, którzy osiedlili się w regionie i założyli pierwsze państwo, było plemię Daju; Daju, panujący tu w XIII i XIV wieku, utracili zwierzchnictwo handlowe na rzecz Tunjurów, a w XV wieku sytuacja, szczególnie w regionie środkowym, całkowicie obróciła się na korzyść Tunjurów.", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["Odzyskanie przez Hiszpanię skały Bâdis (Peñón de Vélez)", "0dc52728"], "d": ["Hasło Sa'dydzi w TDV odnotowuje, że zajęcie Bâdis przez Hiszpanów było ciężkim ciosem dla żeglugi Maghrebu (1564). Ta skalna placówka na północnym wybrzeżu Maroka stanowiła oparcie dla piractwa na zachodnim Morzu Śródziemnym i dla osmańsko-hiszpańskiej rywalizacji.", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["Oddanie Hiszpanii al-Araisz (Larache)", "7b8f6e27"], "d": ["W latach wojny domowej, w której rozpadła się dynastia Sa'dydów, port al-Araisz nad Atlantykiem został oddany Hiszpanii. Hasło Sa'dydzi w TDV odnotowuje, że w tym okresie kraj podzielił się na emiraty Marrakeszu (południe) i Fezu (północ), a strony walki o tron szukały pomocy z zewnątrz. Port miał pozostać blisko osiemdziesiąt lat w rękach hiszpańskich, a w 1689 roku odzyska go Mulaj Isma'il.", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["Przejście Mamûry (Mehdiya) w ręce Hiszpanów", "c8fd494e"], "d": ["Port Mamûra (Ma'mûra / Mehdiya) u ujścia rzeki Sebu został w 1614 roku zajęty przez Hiszpanów i ufortyfikowany pod nazwą San Miguel de Ultramar. Hasło Mulaj Isma'il w TDV odnotowuje, że port został odzyskany od Hiszpanów w roku 1092 (1681) nagłym napadem — czyli hiszpańskie panowanie trwało sześćdziesiąt siedem lat.", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["Koniec dynastii Sa'dydów — początek epoki Alawitów (Filalidów) w Maroku", "b1afa579"], "d": ["TDV İslâm Ansiklopedisi definiuje hasło Sa'dydzi jako „dynastię islamską panującą w Maroku (1511-1659)”. Dynastia, która w 1549 roku zakończyła zwierzchnictwo Wattasydów i zjednoczyła całe Maroko, w 1578 roku w bitwie nad Wadi al-Machazin zniszczyła armię portugalską i w żadnym okresie nie podlegała Osmanom, upadła w 1659 roku po długich walkach o tron. Jej miejsce zajęli alawiccy (filalijscy) szarifowie z Tafilaltu; Mulaj Raszid w 1666 roku wszedł do Fezu i umocnił nową dynastię, a jego brat Mulaj Isma'il oczyścił europejskie placówki na wybrzeżu atlantyckim.", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["Zajęcie przez Hiszpanię wysp al-Husajma (Alhucemas)", "954ca998"], "d": ["Wyspy al-Husajma na wybrzeżu śródziemnomorskim zostały w 1673 roku zajęte przez flotę hiszpańską. Wraz z Bâdis i Ceutą należą do placówek, które Hiszpania utrzymywała na północnym wybrzeżu Maroka i które pozostają w jej rękach do dziś. W tym samym roku starszy brat Mulaja Isma'ila, Mulaj Raszid, wszedł do Marrakeszu i przyjął przysięgę ludności, a zwierzchnictwo Filalidów umocniło się na południu — ta strata na wybrzeżu pokazuje, że wewnętrzne zjednoczenie nie miało jeszcze odpowiednika na froncie zewnętrznym.", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["Odzyskanie przez Mulaja Isma'ila al-Araisz od Hiszpanów", "a54bc6ee"], "d": ["Hasło Mulaj Isma'il w TDV jest jasne: „W 1100 (1689) odzyskawszy Araisz od Hiszpanów, zdobyli 200 dział, a dwa lata później odzyskali także Asilę.” Jest to jedno z ogniw łańcucha oczyszczania wybrzeża przez sułtana Filalidów — Tanger odzyskano od Anglików w 1678, Mamûrę w 1681, al-Araisz w 1689, Asilę w 1691. Port opuszczony osiemdziesiąt lat wcześniej w wojnie domowej Sa'dydów wrócił w ten sposób do Maroka.", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["Założenie Sułtanatu Darfuru — dynastia Keyra i Sulejman Solong", "0fc1c112"], "d": ["Według TDV założenie Sułtanatu Darfuru przypada na czas po zamieszaniu następującym po najeździe Bumû al-Kasîra na region pod koniec XVII wieku. Fur, pod przewodnictwem dynastii Kîrâ (Keyra) z Sulejmanem Solongiem na czele, odebrali władzę Daju i Tunjurom i ustanowili trwały zarząd. Sulejman Solong panował w latach 1695-1715. Sułtani Darfuru w następnych wiekach korespondowali z Wysoką Portą; Abdülmecid i Abdülaziz potwierdzili ich panowanie.", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["Ogłoszenie we Francji Pierwszej Republiki — koniec monarchii", "d53d49b0"], "d": ["Na pierwszym posiedzeniu Konwentu Narodowego zniesiono monarchię, a następnego dnia ogłoszono Pierwszą Republikę; od tego dnia liczono pierwszy rok nowego kalendarza. Dla Osmanów rozmówca się nie zmienił, lecz zmienił się jego rodzaj: w latach Nizâm-ı Cedîd Selima III Francja nie była już dynastią, lecz reżimem, a w 1798 roku do Egiptu miała wylądować armia tego reżimu.", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["Upadek Wielkiej Kabylii — niewola Lalli Fatmy N'Sumer", "0f61ff08"], "d": ["Hasło Algieria w TDV odnotowuje, że zajęcie górzystego regionu Kabylii (Biladu'l-kabâil) w wyprawach 1853, 1854 i 1857 w dużej mierze dopełniło francuskiego ruchu zajmowania Algierii. Wyprawa 1857 roku przełamała linię Tizi Wezzu i Akbu; symbol oporu, Lalla Fatma N'Sumer, została wzięta do niewoli. Ostatnie wielkie ognisko oporu, które pozostało po poddaniu się emira Abd al-Kadira w 1847 roku, zgasło w ten sposób.", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["Zajęcie Ajn Salih (Tidikelt) przez Francuzów", "1e28d1d0"], "d": ["Ajn Salih, ośrodek grupy oaz Tidikelt pośrodku Sahary, został zajęty przez siły francuskie 29 grudnia 1899 roku. Jest to pierwszy wielki krok francuskiej ekspansji schodzącej z wybrzeża Algierii na południe, który przeniósł się na pustynię; w ciągu dwóch lat tą samą drogą podążą Tuat i Gurara.", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["Przyłączenie oaz Tuat · Gurara · Tidikelt do Francji", "d412838b"], "d": ["Pas oaz Tuat, Gurara i Tidikelt na południowym zachodzie Algierii został 21 lutego 1901 roku formalnie przyłączony do Francji. Ten węzeł szlaków karawan, do którego nominalnie rościł sobie prawa sułtan Maroka — wraz z Adrar, Timimun, Reggan i Beni Abbes — został w ten sposób włączony do Algierii; stąd zaczyna się spór graniczny między Marokiem a francuską Algierią.", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["Założenie francuskiego posterunku w Bechar (Colomb-Béchar)", "4d44d252"], "d": ["Oaza Bechar przy granicy marokańskiej została zajęta przez siły francuskie 11 listopada 1903 roku i przekształcona w wysunięty posterunek pod nazwą Colomb-Béchar. Ten krok, dokonany dwa lata po aneksji pasa Tuat, należy do ostatnich ogniw francuskiego marszu z Algierii ku Maroku; otwiera drogę do ustanowienia protektoratu nad Marokiem w 1912 roku.", "bd1a7ae2"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["Założenie beylików Karesi i Hamidoğulları", "3905da93"], "d": ["Według hasła Karesioğulları w TDV Karesi Bej, w rozpadającej się wraz ze śmiercią ojca Kalema Beja seldżuckiej organizacji marchii, ogłosił niepodległość i od 696 (1296-97) uczynił Balıkesir swoim ośrodkiem, a wkrótce zabrał Bizancjum całą Mizję, w tym Erdek, Bigę, Edremit i Pergamon. W tym samym roku (1297) Hamid Bej, czyniąc Uluborlu ośrodkiem rządu, założył beylik Hamidoğulları; Isparta, Burdur, Eğirdir i Yalvaç zostały z rozpadającej się seldżuckiej marchii włączone w pierwsze granice beylika. Oba beyliki są wytworem tego samego załamania w zachodniej Anatolii — rozpadu seldżuckiej władzy centralnej.", "7d297343"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["Założenie beylika Aydınoğulları — zajęcie Izmiru, Ayasuluk, Tire", "69a021ae"], "d": ["Według hasła Aydınoğulları w TDV Mübarizüddin Gazi Mehmed Bej, odebrawszy ten region marchii-bejowi Germiyanoğulları Sasa Bejowi, w 1308 roku zapanował nad Aydın-ili; zdobył muzułmańską część Izmiru wraz z Ayasuluk (Selçuk), Tire i Bodemyą. Z Ayasuluk uczynił bazę floty, a zdobyte ziemie podzielił między pięciu synów — beylik w następnych dziesięcioleciach, zwłaszcza za jego syna Umura Beja, miał się stać siłą rozstrzygającą w żegludze egejskiej.", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["Faktyczny koniec Państwa Seldżuków Anatolii — bezpośrednie rządy Ilchanów", "00f85ecb"], "d": ["Według hasła Mesud II w TDV Gijaseddin Mesud II, zmarły po długiej chorobie w 708 (1308) w Kayseri, jest według powszechnie przyjętego poglądu ostatnim władcą Państwa Seldżuków Anatolii — kandydaci wyniesieni na tron po jego śmierci nie doczekali się uznania ani wewnętrznych urzędów, ani Ilchanów. Region już za panowania Mesuda był faktycznie zarządzany przez urzędników ilchańskich; wraz z jego śmiercią te bezpośrednie rządy straciły w ośrodkach takich jak Konya, Niğde i Aksaray także formalną osłonę.", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["Rozszerzenie beylika Candaroğulları na Kastamonu-Çankırı-Bartın-Safranbolu", "64e39ad0"], "d": ["Według hasła Candaroğulları w TDV beylik został założony na początku XIV wieku w okolicach Kastamonu-Synopy przez Şemseddina Yamana Candara, któremu ilchański władca Gejchatu nadał jako iktâ Eflani i okolice; z powodu niedostatku źródeł dokładna data założenia nie jest znana. Następca Candara, Sulejman Bej, jest wspominany jako władca zajmujący miejsce beylika Çobanoğulları — czyli okolice Kastamonu i Çankırı przeszły od Çobanoğulları, a linia Bartın-Safranbolu-Eflani od bezpośredniego zarządu ilchańskiego do Candaroğulları.", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["Zdobycie Rodos i Dodekanezu przez joannitów (Szpitalników)", "67885b4b"], "d": ["Hasło Rodos w TDV odnotowuje, że wyspa przeszła w 1309 roku w ręce joannitów (Szpitalników/İsbitâriyye); standardowa historia Szpitalników (zob. J. Riley-Smith, The Knights Hospitaller) rozwija, że oblężenie zaczęło się latem 1306 roku, a miasto Rodos, długo opierające się z bizantyjskimi posiłkami, padło dopiero 15 sierpnia 1310 roku przed siłami Wielkiego Mistrza Foulques de Villaret. Wyspa miała odtąd być ośrodkiem rycerzy do osmańskiego zdobycia w 1522 roku, a otaczający Dodekanez przeszedł w tym samym procesie od Bizancjum pod władzę Szpitalników.", "c1422e2c"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["Zajęcie Kos (İstanköy) przez joannitów", "445666f7"], "d": ["Według hasła İstanköy w TDV joannici, po osiedleniu się na Rodos, zajęli także Kos (1315) i zbudowali nowe twierdze. Wyspa weszła w ten sposób pod rządy rycerzy, trwające do 1523 roku; w jakich rządach znajdował się Kos po upadku miasta Rodos w 1310 roku, TDV nie rozwija.", "145d1bad"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["Założenie beylika Eretny — środkowa Anatolia po Ilchanach", "a67bacd9"], "d": ["Według hasła Eretnaoğulları w TDV Alaeddin Eretna, urzędnik ilchański pochodzenia ujgurskiego, po śmierci ilchańskiego władcy Abu Sa'ida Bahadur Chana w 1335 roku przekształcił ilchańskie namiestnictwo w Anatolii w faktycznie niezależny zarząd; najpierw występował jako namiestnik sułtana mameluków, w 1340 roku usunął z chutby imię mameluków, a około 1341 roku ogłosił pełną niepodległość. Beylik, którego ośrodkiem był najpierw Sivas, potem Kayseri, do jego śmierci (1352) ustanowił rozległe zwierzchnictwo w środkowej Anatolii, obejmujące Amasyę, Tokat, Çorum, Niğde, Aksaray i Erzincan, i został w 1381 roku zakończony przez Kadiego Burhaneddina.", "04978a80"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["Założenie Państwa Dżalairydów — Azerbejdżan po Ilchanach", "a13ada90"], "d": ["Według hasła Celayirliler w TDV Hasan-i Büzürg, wnuk ilchańskiego emira Nojana, wykorzystując walki o tron, które wybuchły wraz ze śmiercią ilchańskiego władcy Abu Sa'ida Bahadur Chana, założył w 1340 roku niezależne państwo z ośrodkiem w Tebrizie. Dżalairydzi stali się w ten sposób pierwszą wielką dynastią wypełniającą próżnię po Ilchanach w Azerbejdżanie i okolicach; za jego następcy Uwajsa (1356-1374) ich ziemie rozszerzą się aż do Mosulu i Diyarbakıru.", "224cbb81"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["Przejście Bagdadu w ręce Qaraquyunlu — klęska sułtana Dżalairydów Ahmada", "a42ebe92"], "d": ["Według hasła Karakoyunlular w TDV Kara Jusuf 28 Rabi' II 813 (30 sierpnia 1410) zadał pod Tebrizem ciężką klęskę sułtanowi Dżalairydów Ahmadowi; po śmierci sułtana Ahmada w 814 (1411) ogłosił sułtanem w Tebrizie jego syna Pir Budaka, a w tym samym roku starszy syn Szah Mehmed zdobył Bagdad. Bagdad, od blisko stulecia stolica Dżalairydów, wraz z otaczającą linią Basra-Mosul-Kirkuk przeszedł w ten sposób pod zwierzchnictwo Qaraquyunlu.", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["Erzincan i Kemah przeszły do Aqquyunlu — Karayülük Osman Bej", "122460d4"], "d": ["Po śmierci Kara Jusufa, na życzenie mieszkańców Erzincanu, wnuk Mutahhartena Jar Ali został namiestnikiem miasta. Za jego czasów bej Aqquyunlu Karayülük Osman zajął Erzincan i włączył do ziem Aqquyunlu. Od tej daty Erzincan był miejscem, które zmieniało ręce to między Aqquyunlu a Qaraquyunlu, to między książętami Aqquyunlu.", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["Założenie Chanatu Kazańskiego — odejście Ulugh Muhammada Chana z Złotej Ordy", "335a7408"], "d": ["Według hasła Kazan Hanlığı w TDV Ulugh Muhammad Chan, który utracił tron w stolicy Złotej Ordy Saraju, wycofał się najpierw z rodziną i około 3000 żołnierzy do Biełowa, w latach 1437-1438 walczył z ruskim kniaziem Wasylem II, a następnie osiadł w mieście Kazaniu; przy poparciu miejscowej ludności położył tu fundamenty nowego chanatu. TDV zaznacza, że proces zakładania zakończył się w latach 1437-1445, a chanat od 1445 roku zyskał pełny status niezależności — mapa przyjmuje za początek tego procesu rok 1438, w którym Ulugh Muhammad osiadł w Kazaniu.", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["Założenie Chanatu Krymskiego — uniezależnienie się Hadżdżi Gireja od Złotej Ordy", "5728223e"], "d": ["Według hasła Kırım w TDV Chanat Krymski powstał w drugiej połowie XIV wieku jako wytwór rozpadu Złotej Ordy wskutek walk o tron; najstarsza moneta wybita przez faktycznego założyciela chanatu, Hadżdżi Gireja, nosi datę 845 (1441-42), co uważa się za oficjalną datę założenia chanatu. W tym samym roku Hadżdżi Giraj umocnił swoją pozycję na Krymie, nawiązując przyjaźń z Moskwą, a miejscowe rody bejowskie, na czele z plemieniem Szirin, stanęły po jego stronie.", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["Dżihan Szah zajął Erzincan — zwierzchnictwo Qaraquyunlu", "0c928cc4"], "d": ["Władca Qaraquyunlu Dżihan Szah w 854 (1450) wysłał do Erzincanu armię i odebrał miasto Aqquyunlu. Ta utrata doprowadziła do poróżnienia beja Aqquyunlu Dżihangira Mirzy z jego bratem Hasan Bejem (Uzun Hasan).", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["Zajęcie przez Qaraquyunlu Dżihana Szacha timurydzkiego Iranu (Rej, Isfahan, Fars, Kerman)", "c6fbb3f5"], "d": ["Według hasła Karakoyunlular w TDV władca Qaraquyunlu Dżihan Szah, wykorzystując walki o tron między książętami Timurydów, w latach 856-857 (1452-1453) objął swoimi rządami prowincje Rej, Isfahan, Fars i Kerman; jest to punkt kulminacyjny procesu ekspansji, który rozpoczął się po śmierci Szahrucha Mirzy w 1447 roku i otworzył się aneksją Sultanijji-Kazwinu. Ziemie Timurydów w południowo-środkowym Iranie przeszły w ten sposób do Qaraquyunlu; władza Dżihana Szacha miała w 1466 roku osiągnąć rozmiary obejmujące Azerbejdżan, Arran, Irak Perski, Irak Arabski, Fars, Kerman i Anatolię Wschodnią.", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["Odzyskanie Bordeaux przez Anglię — ostatnia wyprawa Johna Talbota do Gaskonii", "01b2b7be"], "d": ["Bordeaux, utracone na rzecz Francuzów w 1451 roku, poddało się armii angielskiej pod przewodnictwem sędziwego dowódcy Johna Talbota w nocy z 22 na 23 października 1452 roku, gdy mieszkańcy powstali przeciw francuskiemu garnizonowi i otworzyli bramy; było to ostatnie i krótkotrwałe zwycięstwo Anglii w Gaskonii w Wojnie Stuletniej. Bordeaux miało rok później, po bitwie pod Castillon, trwale wrócić do Francji.", "f6945d27"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["Uzun Hasan odzyskał Erzincan — znów Aqquyunlu", "550d010a"], "d": ["Uzun Hasan, pobiwszy Qaraquyunlu, ponownie objął Erzincan zwierzchnictwem Aqquyunlu. Miasto pozostało w granicach Aqquyunlu także po bitwie pod Otlukbeli w 1473 roku.", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["Drugi Pokój Toruński — Gdańsk i Prusy Zachodnie przyłączone do Polski", "e2152dae"], "d": ["Drugi Pokój Toruński, kończący Wojnę Trzynastoletnią, która rozpoczęła się powstaniem Związku Pruskiego przeciw rządom Krzyżaków (Zakonu Niemieckiego) w 1454 roku, podpisano 19 października 1466 roku; Krzyżacy oddali Królestwu Polskiemu Pomorze Wschodnie z Gdańskiem, ujście Wisły z Elblągiem i ziemię chełmińską — ziemie te przyjęły nazwę „Prus Królewskich”. Prusy Wschodnie miały pozostać przy Krzyżakach do 1525 roku.", "831685a9"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["Królowa Katarzyna Cornaro oddała Cypr Wenecji — koniec państwa krzyżowców", "e24d3f3a"], "d": ["Katarzyna Cornaro z Wenecji, która po śmierci męża, króla Jakuba II, w 1473 roku rządziła Cyprem jako regentka królowej, nie mając dziedzica, pod naciskiem rządu weneckiego abdykowała 26 lutego 1489 roku i przekazała prawa władcze na wyspie doży i Republice Weneckiej; w zamian zachowała tytuł królowej i otrzymała hrabstwo Asolo na Terraferma. Tym przekazaniem dobiegły końca panowanie dynastii Lusignanów trwające od 1192 roku i ostatnie państwo krzyżowców; wyspa pozostała pod rządami Wenecji do osmańskiego podboju w latach 1570-71.", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["Upadek Granady — koniec ostatniego państwa muzułmańskiego na Półwyspie Iberyjskim", "46e5201b"], "d": ["Ostatni władca Emiratu Nasrydów Granady, osłabionego dziesięcioletnim stopniowym oblężeniem i podziałami wewnętrznymi, Abu Abdullah (Boabdil), zgodnie z hojnymi warunkami poddania (Kapitulacje Granady) podpisanymi w listopadzie 1491 roku, przekazał 2 stycznia 1492 roku klucze miasta Królom Katolickim Ferdynandowi i Izabeli; po wyjeździe Boabdila z Alhambry dobiegło końca ostatnie państwo muzułmańskie na Półwyspie Iberyjskim i Rekonkwista została dopełniona. W tym samym roku miały nastąpić wygnanie Żydów (marzec) i podróż Krzysztofa Kolumba (sierpień).", "5dc28ef8"]},
"OLAYLAR_EK16:1503-04-02:0":{"b": ["Rozejm moskiewsko-litewski — region czernihowsko-siewierski przeszedł do Moskwy", "8e4c56f9"], "d": ["Wojna moskiewsko-litewska z lat 1500-1503 zakończyła się sześcioletnim rozejmem dzięki pośrednictwu króla Węgier i Czech Władysława II; Wielkie Księstwo Litewskie musiało oddać Wielkiemu Księstwu Moskiewskiemu rozległy obszar stanowiący około jednej trzeciej Wielkiego Księstwa, w tym region czernihowsko-siewierski (okolice Czernihowa, Nowogrodu Siewierskiego, Starodubu, Briańska) oraz niektóre ziemie w okolicach Smoleńska i Połocka. Było to jedno z największych pojedynczych zdobyczy Moskwy w procesie „zbierania” ziem ruskich.", "4cb77b9b"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["Zdobycie przez Szajbani Chana Heratu i Chorasanu od Timurydów", "a81d8575"], "d": ["Według hasła Şeybânî Han w TDV uzbecki władca Szajbani Chan, po zajęciu w latach 1503-1505 Andiżanu, Fergany, Hisaru, Kunduzu i Balchu, w 913 (1507) zdobył także timurydzką stolicę Herat; hasło Khorasan w Encyclopaedia Iranica podaje dokładną datę tego podboju — miasto padło 8 Muharrama 913 (20 maja 1507), tydzień później, 15 Muharrama (27 maja), chutbę odczytano w imieniu Szajbani Chana i podbój został sformalizowany. Cały Chorasan, w tym Meszhed, przeszedł w tym samym roku od Timurydów do Szajbanidów; oznaczało to, że dynastia Timurydów po Transoksanii straciła także ostatnią wielką twierdzę w Iranie.", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["Upadek Oranu na rzecz Hiszpanii — wyprawa kardynała Cisnerosa do Afryki Północnej", "86ed8ac1"], "d": ["Wahran (Oran), kontrolujący szlak morski zachodniego Morza Śródziemnego i będący portem Tlemcenu, rozrósł się w 1492 roku dzięki schronieniu muzułmanów i Żydów andaluzyjskich uciekających z Granady. Królestwo Kastylii, które na początku XVI wieku zajmowało kolejno miasta portowe wybrzeża Maghrebu, zajęło Wahran 17 maja 1509 roku; większość mieszkańców wymordowano, resztę wzięto do niewoli, a w mieście nie zostało ludności muzułmańskiej ani żydowskiej. Hiszpanie rozbudowali mury i twierdze; Wahran pozostał w rękach hiszpańskich do 1708 roku.", "be7b3b1b"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["Włączenie Niderlandów do korony hiszpańskiej — śmierć Ferdynanda, wstąpienie Karola V na tron", "fbe0dbd2"], "d": ["Po śmierci króla Aragonii Ferdynanda II 23 stycznia 1516 roku jego wnuk Karol V, który od 1506 roku jako książę Burgundii już rządził Niderlandami (dzisiejsza Belgia-Holandia-Luksemburg i część północnej Francji), został dziedzicem tronów Kastylii i Aragonii i 14 marca 1516 roku ogłoszono go w Brukseli królem Hiszpanii. W ten sposób ziemie te zaczęto uważać drogą unii personalnej za podległe nie niemiecko-austriackiej linii dynastii Habsburgów, lecz bezpośrednio koronie hiszpańskiej — w 1519 roku wraz z wyborem Karola V na cesarza Świętego Cesarstwa Rzymskiego te dwie tożsamości (króla Hiszpanii i cesarza niemiecko-rzymskiego) zjednoczą się w jednej osobie, a podległość regionu Hiszpanii miała trwać do 1556 roku, gdy Karol V abdykował i przekazał dziedzictwo synowi Filipowi II.", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["Sułtanat Demak obala Majapahit i zapanowuje nad wybrzeżem Jawy", "7da602b5"], "d": ["Według hasła Demak w TDV Sułtanat Demak, pierwsze niezależne państwo muzułmańskie na Jawie, został założony w ostatniej ćwierci XV wieku przez Radena Patah; według źródeł jawajskich chylące się ku upadkowi hindusko-buddyjskie Królestwo Majapahit zniknęło wskutek ataków Demaku. W 1527 roku Demak zdobył Tuban, który źródła chińskie od XI wieku wspominają jako ważny port władców Majapahit — jest to rok, w którym także ostatnie resztki Majapahit zostały podporządkowane Demakowi, i punkt zwrotny procesu islamizacji większej części Jawy.", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["Zredukowanie Norwegii do prowincji podległej koronie duńskiej", "8e2f274e"], "d": ["Król Danii Chrystian III w akcie koronacyjnym z 1536 roku (håndfæstning) ogłosił, że Norwegia nie będzie już uważana za odrębne królestwo, lecz będzie zarządzana jako prowincja Danii, a norweska Rada Państwa (riksråd) została zniesiona; decyzja ta stała się faktem w 1537 roku wraz ze stosowaniem w Norwegii duńskiego ustroju kościelnego i złamano opór szkocko-norweskiego biskupa Olava Engelbriktssona. Choć Norwegia w praktyce zachowała jeszcze przez pewien czas własne prawa i instytucje, jej status polityczny był już nie niezależnego królestwa, lecz prowincji podległej koronie duńskiej — stan ten miał trwać do 1814 roku.", "a8c9dee7"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["Traktat wileński — rozpad Konfederacji Inflant, Kurlandia i Inflanty przyłączone do Polski-Litwy (poza miastem Ryga)", "d1ceaad5"], "d": ["Ostatni wielki mistrz Konfederacji Inflanckiej Gotthard Kettler, której rozpad nastąpił pod naciskiem rosyjskim w czasie wojny inflanckiej, wszedł traktatem podpisanym 28 listopada 1561 roku w Wilnie (Pacta Subiectionis) pod opiekę wielkiego księcia litewskiego i króla Polski Zygmunta II Augusta; większa część Inflant, z wyjątkiem miasta Ryga, została przyłączona do Polski-Litwy, a Kettler został pierwszym księciem Księstwa Kurlandii. Był to ostatni akt Zakonu Kawalerów Mieczowych na drodze od średniowiecza do czasów nowożytnych.", "bcd4efe9"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["Akt Abjuracji (Plakkaat van Verlatinghe) — Holandia ogłosiła niepodległość od Hiszpanii", "a632aaee"], "d": ["W czasie trwania Wojny Osiemdziesięcioletniej Stany Generalne (Staten-Generaal) prowincji holenderskich należących do Unii Utrechckiej Aktem Abjuracji przyjętym 26 lipca 1581 roku ogłosiły króla Hiszpanii Filipa II „tyranem” i odrzuciły wierność wobec niego; dokument ten uchodzi za deklarację założycielską faktycznie niepodległych Zjednoczonych Prowincji (Republiki Holenderskiej). Ostateczne uznanie przez Hiszpanię miało poczekać do Westfalii w 1648 roku, lecz faktyczne zerwanie nastąpiło tego dnia.", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["Upadek Smoleńska na rzecz Polski-Litwy — koniec 20-miesięcznego oblężenia", "4e9678e3"], "d": ["W Czasie Wielkiej Smuty armia króla Polski Zygmunta III 13 czerwca 1611 roku wysadziwszy minę, uczyniła wyłom w murach Smoleńska, oblężonego od września 1609 roku, i zajęła miasto; 20-miesięczny opór dobiegł końca. Smoleńsk pozostał do 1654 roku w Polsce-Litwie, a ten upadek przygotował grunt pod rozejm w Dywilinie (1618), który podpisano siedem lat później.", "25d6488d"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["Traktat w Stołbowie — Rosja utraciła wybrzeże bałtyckie (Ingrię) na rzecz Szwecji", "175dc175"], "d": ["Traktat w Stołbowie, kończący wojnę ingryjską, podpisano 27 lutego 1617 roku we wsi Stołbowo na południe od Jeziora Ładoga; Rosja odzyskała Nowogród i inne ziemie na północy, Szwecja zaś zatrzymała Karelię i Ingrię (między Estonią a Finlandią, w tym twierdze Iwangorod, Jama, Koporje, Orzeszek), a bezpośredni dostęp Rosji do Bałtyku został odcięty. To odcięcie miało trwać do założenia w tym samym regionie Petersburga przez Piotra Wielkiego w 1703 roku.", "7e70e3e6"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["Rozejm w Dywilinie — Smoleńsk, Czernihów i Nowogród Siewierski oddane Polsce", "6880d2c1"], "d": ["Rozejm w Dywilinie, kończący wojnę polsko-rosyjską 1609-1618, podpisano 11 grudnia 1618 roku i zapewnił on 14,5-letnie zawieszenie broni; Rosja musiała oddać Rzeczypospolitej Obojga Narodów Smoleńsk (z wyjątkiem Wiaźmy) oraz 29 miast w regionach czernihowskim i nowogrodzko-siewierskim — była to najcięższa utrata terytorialna Czasu Smuty. Region miał pozostać w Polsce do rozejmu w Andruszowie w 1667 roku.", "5c52de5a"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["Rada Perejasławska — Kozacy zaporoscy złożyli przysięgę wierności carowi rosyjskiemu", "bcd8f8ef"], "d": ["Hetman Kozaków zaporoskich Bohdan Chmielnicki, który od 1648 roku powstawał przeciw Polsce-Litwie, złożył przysięgę wierności carowi Aleksemu I Michajłowiczowi na Radzie Perejasławskiej z 18 stycznia 1654 (juliańskiego 8 stycznia), w której uczestniczyło poselstwo z Moskwy pod przewodnictwem Wasilija Buturlina; uchodzi to za początek wejścia Hetmanatu Kozackiego Ukrainy pod protektorat Rosji i przesunęło faktyczną kontrolę nad regionem czernihowsko-siewierskim z Polski na Rosję — oficjalna granica miała zostać wytyczona rozejmem w Andruszowie w 1667 roku.", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["Odzyskanie Smoleńska przez Rosję", "bf0eca92"], "d": ["W czasie wojny polsko-rosyjskiej rozpoczętej w 1654 roku armia rosyjska odzyskała Smoleńsk, oblegany od lipca, 3 października 1654 roku, gdy garnizon polski się poddał; miasto utracone na rzecz Polski w 1611 roku wróciło do Rosji po 43 latach. Był to jeden z najważniejszych kroków procesu odwracania przez Rosję strat z Czasu Smuty i został utrwalony rozejmem w Andruszowie w 1667 roku.", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["Rozejm w Andruszowie — Kijów i Ukraina Lewobrzeżna przeszły do Rosji", "799be067"], "d": ["Rozejm w Andruszowie, kończący wojnę polsko-rosyjską 1654-1667, zapewnił 13,5-letnie zawieszenie broni; Rosja zyskała Smoleńsk, region czernihowsko-siewierski i Ukrainę na lewym brzegu Dniepru oraz — początkowo na dwa lata, faktycznie na stałe — miasto Kijów. Ten układ położył prawną podstawę pod podział ziem ukraińskich wzdłuż Dniepru między Polskę i Rosję (i pozostanie Kijowa w Rosji).", "94445e3a"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["Założenie Petersburga — okno Rosji otwarte na Zachód", "ba196be0"], "d": ["Na Wyspie Zajęczej w delcie Newy, świeżo odzyskanej od Szwecji w czasie Wielkiej Wojny Północnej, Piotr Wielki 16/27 maja 1703 roku położył fundamenty Twierdzy Pietropawłowskiej (Twierdzy Piotra i Pawła); dzień ten uważa się za datę założenia miasta Petersburga. Piotr zaprojektował bagnistą deltę jako „okno” otwarte na Zachód, a miasto w 1712 roku stało się nową stolicą Rosji — region miał zostać formalnie przyłączony do Rosji traktatem w Nystad w 1721 roku.", "24c24aaf"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["Traktat w Rastatt — koniec Wojny o Sukcesję Hiszpańską, Niderlandy Hiszpańskie i Mediolan przeszły do Austrii", "3c0e086f"], "d": ["Traktat w Rastatt, kończący wojnę o sukcesję hiszpańską między Francją a Austrią, podpisano 7 marca 1714 roku (Utrecht uregulował w 1713 roku stosunki Anglii z Francją); na mocy traktatu Habsburgowie austriaccy przejęli Niderlandy Hiszpańskie (dzisiejsza Belgia) oraz Neapol, Mediolan i Sardynię we Włoszech. Była to największa ekspansja terytorialna w historii Austrii, która do ciężaru dynastii Habsburgów w Europie Środkowej dodała nowy front w Europie Zachodniej i Południowej.", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["Traktat w Nystad — koniec Wielkiej Wojny Północnej, wybrzeża Bałtyku przeszły do Rosji", "068ffd06"], "d": ["Traktat w Nystad, kończący trwającą 21 lat Wielką Wojnę Północną, podpisano 10 września 1721 roku (juliańskiego 30 sierpnia) w Finlandii; Szwecja oddała Rosji Estonię, Inflanty (w tym Rygę), Ingrię i część południowo-wschodniej Finlandii (Karelię), w zamian odzyskała resztę Finlandii i wypłacono odszkodowanie. Traktat uchodzi za koniec statusu wielkiego mocarstwa Szwecji i formalne potwierdzenie wzrostu Rosji jako imperium europejskiego — Piotr I po tym zwycięstwie przyjął tytuł „Imperatora”.", "f0c4fc4a"]},
"OLAYLAR_EK16:1772-08-05:0":{"b": ["Pierwszy rozbiór Polski — utrata ziem na rzecz Rosji i Austrii", "2c56a0d8"], "d": ["Układem podpisanym 5 sierpnia 1772 roku między Rosją, Prusami i Austrią podzielono około jednej trzeciej ziem Rzeczypospolitej Obojga Narodów: Rosja zajęła dzisiejszą Białoruś i część Łotwy (w tym Dyneburg, Połock, Witebsk), Austria zaś zaanektowała Galicję (Lwów i zachodnie Podole, w tym Jazłowiec); Prusy objęły nadmorski region Prus Królewskich. Sejm polski zatwierdził układ dopiero 30 września 1773 roku, pod naciskiem. Był to pierwszy z trzech rozbiorów, które miały trwać do 1795 roku.", "6f2b4118"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["Drugi rozbiór Polski — utrata ziem na rzecz Rosji i Prus", "31750484"], "d": ["Ponieważ reformy konstytucyjne 1791 roku zaniepokoiły Rosję i Prusy, oba państwa podzieliły Polskę ponownie układem podpisanym 23 stycznia 1793 roku w Petersburgu: Rosja zajęła większą część Litwy-Białorusi i zachodnią Ukrainę (w tym Kamieniec, Bar, Mińsk), Prusy zaś zaanektowały Wielkopolskę z Gdańskiem i Poznaniem — łącznie 307 000 km². Polski Sejm pod naciskiem musiał zatwierdzić układ w tym samym roku; był to krótkotrwały rozbiór, który o dwa lata odroczył całkowitą aneksję Polski. W tym dniu (23 stycznia 1793) w Drugim Rozbiorze Polski Ukraina Prawobrzeżna, w tym Berdyczów, Fastów, Żytomierz, Kaniów, Konstantynów, Humań i Czerkasy, przeszła do Rosji.", "656e71c2"]},
"OLAYLAR_EK16:1795-10-24:0":{"b": ["Trzeci rozbiór Polski — całkowite zniknięcie państwa", "e3c02d6b"], "d": ["Rosja, Prusy i Austria konwencją trójstronną podpisaną 24 października 1795 roku w Petersburgu podzieliły całkowicie pozostałe ziemie Rzeczypospolitej Obojga Narodów: Rosja zajęła Litwę (w tym Wilno, Kowno) i resztę Białorusi, Prusy Polskę środkową z Warszawą, Austria zaś południowy region z Krakowem. Trzy państwa zagwarantowały też wojskowo nawzajem swoje nowe ziemie i podjęły środki na wypadek odbudowy Polski. Było to całkowite zniknięcie państwa polsko-litewskiego jako niepodległego kraju; miało nie zostać odbudowane do XX wieku.", "a66df675"]},
"OLAYLAR_EK16:1797-05-12:0":{"b": ["Koniec Republiki Weneckiej — Wielka Rada rozwiązała się", "5efed589"], "d": ["Gdy armia wyprawy włoskiej Napoleona zajęła terytorium weneckie i postawiła republice ultimatum, Wielka Rada (Maggior Consiglio) 12 maja 1797 roku zgodziła się na samorozwiązanie głosami 512 do 20; ostatni doża Ludovico Manin złożył urząd i arystokratyczny zarząd Republiki Weneckiej, istniejącej nieprzerwanie ponad 1100 lat, dobiegł końca. Jej ziemie przekazano najpierw tymczasowemu rządowi demokratycznemu, a następnie w październiku 1797 roku układem z Campo Formio formalnie Austrii.", "8852717b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["Koniec Republiki Genui — Napoleon utworzył Republikę Liguryjską", "3d3e59ee"], "d": ["W miejsce Republiki Genui, którą pod naciskiem Napoleona prowadzącego wyprawę włoską przekazano na początku czerwca 1797 roku tymczasowemu zarządowi, 14 czerwca 1797 roku ogłoszono „Republikę Liguryjską” z konstytucją na wzór francuski; wielowiekowe państwo genueńskie faktycznie przekształciło się w jedno z państw satelickich Francji. Republika miała zostać w 1805 roku bezpośrednio przyłączona do Francji, a Kongresem Wiedeńskim w 1815 roku oddana Królestwu Sardynii-Piemontu.", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["Traktat z Campo Formio — podział Wenecji między Austrię i Francję", "9f29678c"], "d": ["Traktat z Campo Formio, podpisany 17 października 1797 roku między Napoleonem Bonaparte a przedstawicielem Austrii hrabią Cobenzlem, formalnie zlikwidował tysiącletnią Republikę Wenecką i podzielił jej ziemie: obszar na wschód od rzeki Adygi, Istria i wybrzeże Dalmacji (w tym Split, Zadar, Szybenik, Kotor) przypadły Austrii, a Wyspy Jońskie (Korfu, Kefalonia, Zakintos, Lefkada, Prevezę oraz weneckie bazy na wybrzeżu albańsko-morejskim, w tym Pargę) Francji. Austria oddała też Francji swoje ziemie w Niderlandach (dzisiejsza Belgia).", "296ee82f"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["Poddanie Malty Anglii — koniec dwuletniego oblężenia francuskiego", "fedc2867"], "d": ["Malta, zajęta przez Napoleona w 1798 roku w drodze na wyprawę egipską, wkrótce wskutek powstania ludności wyspy znalazła się w morskiej blokadzie floty angielskiej; po dwuletnim oblężeniu i głodzie francuski dowódca generał Vaubois poddał się 5 września 1800 roku angielskiemu generałowi Pigotowi. Malta przeszła w ten sposób spod Republiki Francuskiej pod protektorat angielski i miała zostać formalnie włączona do korony angielskiej traktatem paryskim w 1814 roku — stała się najważniejszą angielską bazą morską na Morzu Śródziemnym.", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["Pokój w Amiens — Minorka zwrócona Hiszpanii", "f341e4b8"], "d": ["Pokój w Amiens (25 marca 1802), podpisany między Francją, Hiszpanią, Holandią i Anglią, tymczasowo zakończył wojnę drugiej koalicji; Anglia zwróciła niemal wszystkie ziemie zdobyte w czasie wojny (z wyjątkiem Cejlonu i Trynidadu) — jedną z nich była Minorka, odebrana Hiszpanii w 1798 roku. Pokój trwał tylko rok, w maju 1803 roku wojna wybuchła ponownie, lecz Minorka po tym układzie nigdy już nie wpadła w ręce angielskie.", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["Traktat z Fredrikshamn (Hamina) — oddanie Finlandii przez Szwecję Rosji", "c0d407bc"], "d": ["Traktat z Fredrikshamn (dzisiejsza Hamina), kończący wojnę rosyjsko-szwedzką 1808-1809, podpisano 17 września 1809 roku; Szwecja oddała Rosji całą Finlandię, wraz z Wyspami Alandzkimi. Finlandia uzyskała status Wielkiego Księstwa z szeroką autonomią w ramach Imperium Rosyjskiego i zachowała wyznanie luterańskie oraz prawo szwedzkie. Oznaczało to faktyczny koniec statusu wielkiego mocarstwa Szwecji nad Bałtykiem. Na mocy tego traktatu sześć prowincji Finlandii i Västerbotten aż do rzeki Torne (Kokkola, Joensuu, Savonlinna, Tornio, Rovaniemi, Inari i in.) przeszło do Wielkiego Księstwa Finlandii podległego Rosji.", "fb46c9a1"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["Aneksja Królestwa Imeretii — król Salomon II zdjęty z tronu", "5ad36bff"], "d": ["Gdy ostatni król zachodniogruzińskiego Królestwa Imeretii Salomon II, zmuszony w 1804 roku konwencją z Elaznauri do przyjęcia wasalstwa rosyjskiego, nadal opierał się rosnącemu naciskowi rosyjskiemu, wojska rosyjskie 20 lutego 1810 roku zajęły stolicę Kutaisi, zdjęły Salomona z tronu i zmusiły miejscową szlachtę do złożenia przysięgi wierności carowi Aleksandrowi I; Królestwo Imeretii faktycznie dobiegło tym samym końca i zostało włączone pod bezpośredni zarząd rosyjski. Salomon uciekł na ziemie osmańskie i zmarł na wygnaniu (1815).", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["Traktat z Kilonii — oddanie Norwegii przez Danię Szwecji", "59ab1601"], "d": ["Szwecja, która po klęsce Napoleona pod Lipskiem zaatakowała Danię od południa, przejęła na mocy traktatu z Kilonii z 14 stycznia 1814 roku Norwegię (z wyjątkiem Islandii, Wysp Owczych i Grenlandii) — unia duńsko-norweska trwająca od 1380 roku formalnie dobiegła końca. W zamian Szwecja oddała Danii swoje ziemie na Pomorzu; Dania przekazała też Anglii Helgoland. Norwegia oparła się traktatowi z bronią w ręku i ogłosiła własną konstytucję, a Szwecja musiała ją uznać — wynikiem była unia personalna (real union) trwająca do 1905 roku. Szwecja nie zdołała faktycznie przejąć Norwegii: traktatu w Norwegii nie przyjęto, a zarząd pozostał w rękach Christiana Fredrika; armia szwedzka weszła do Norwegii dopiero 26 lipca 1814 roku.", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["Akt Końcowy Kongresu Wiedeńskiego — mapa Europy po Napoleonie wytyczona na nowo", "fca1c676"], "d": ["Akt Końcowy Kongresu Wiedeńskiego, podpisany między wielkimi mocarstwami (Austria, Rosja, Prusy, Anglia, Francja), które zakończyły wojny napoleońskie, przyjęto 9 czerwca 1815 roku (dziewięć dni przed Waterloo) i wytyczył on na nowo mapę kontynentu: dawne Niderlandy Hiszpańskie/Austriackie i Zjednoczone Prowincje połączono pod „Zjednoczonym Królestwem Niderlandów”, Republikę Genui przyłączono do Królestwa Sardynii-Piemontu, większą część Księstwa Warszawskiego przyłączono do Rosji pod nazwą „Polski Kongresowej”, a Pomorze Szwedzkie (Stralsund) przeszło do Prus. Ten jeden dzień uchodzi za formalny początek powojennej równowagi europejskiej (Concert of Europe). Na mocy tego aktu Łódź, Częstochowa, Kielce, Radom, Lublin, Chełm i Zamość (Księstwo Warszawskie) przeszły do Królestwa Polskiego podległego Rosji, Poznań (Wielkie Księstwo Poznańskie) do Prus, Maastricht i Roermond do Królestwa Niderlandów.", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["Generalny Traktat Morski — Kawasim i inne szejkaty Zatoki związane układem z Anglią", "fc499e19"], "d": ["Anglia, po zbombardowaniu Ras al-Chajma w 1819 roku i rozproszeniu „piracką” flotę Kawasimów, narzuciła Generalny Traktat Morski, rozpoczęty 8 stycznia 1820 roku i podpisywany po kolei z szejkatami regionu, zakończony do marca; traktat zakazywał piractwa i niewolnictwa i nakazywał statkom noszenie czerwono-białej flagi podobnej do brytyjskiej. Na mocy tego układu „Wybrzeże Piratów” z czasem przekształciło się w „Wybrzeże Rozejmu” (Trucial Coast); był to początek relacji trwającej do 1971 roku, z brytyjską hegemonią pogłębioną stałym rozejmem morskim z 1853 roku i wyłącznymi układami z 1892 roku.", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["Koniec oblężenia Gaety — upadek Królestwa Obojga Sycylii", "121ae580"], "d": ["Po załamaniu, które rozpoczęło się lądowaniem Garibaldiego na Sycylii w maju 1860 roku, burboński król Franciszek II, który uciekł z Neapolu, był od 3 listopada 1860 roku oblegany w swej ostatniej twierdzy Gaeta; po wycofaniu floty francuskiej z regionu w styczniu 1861 roku włoska blokada morska zacisnęła się, a 13 lutego 1861 roku Gaeta się poddała. Franciszek II zrzekł się tronu i udał się na wygnanie; ostatni punkt oporu Królestwa Obojga Sycylii, Civitella del Tronto, miał upaść dopiero 20 marca 1861 roku. Wraz z upadkiem królestwa ziemie na Sycylii (Palermo, Mesyna, Syrakuzy, Trapani, Misilmeri) i w Kampanii (w tym Nola) nie były już pod rządami Burbonów.", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["Ogłoszenie Królestwa Włoch — zjednoczenie Sardynii, Toskanii i południowych Włoch", "12e52f70"], "d": ["Na pierwszym posiedzeniu włoskiego parlamentu w Turynie 17 marca 1861 roku formalnie ogłoszono Królestwo Włoch, a król Sardynii-Piemontu Wiktor Emanuel II został pierwszym królem zjednoczonych Włoch. Nowe królestwo łączyło z Królestwem Sardynii ziemie Toskanii, Emilii-Romanii, Neapolu i Sycylii (Obojga Sycylii), przyłączone w poprzednim roku w plebiscytach; Rzym (Państwo Kościelne) i Wenecja (Austria) pozostawały jeszcze na zewnątrz — miały dołączyć odpowiednio w 1870 i 1866 roku.", "d044a9c0"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["Ustanowienie przez Brytanię protektoratu na północnym wybrzeżu Somalii — początek Somalilandu", "f301ea94"], "d": ["Według hasła Somali w TDV Zejla, Berbera i Tadżura zostały w 1884 roku skolonizowane przez Anglików pod nazwą Somaliland; według standardowego źródła akademickiego proces ten rozpoczął się w Berberze układem podpisanym z plemieniem Habar Awal, przypadającym na 21 Ramadana 1301 (14 lipca 1884), i rozszerzył się w latach 1884-1886 przez podpisanie podobnych układów z plemionami Gadabursi, Habar Tolcaala, Habar Gerhajis, Isa i Warsangeli; Anglia obiecała w zamian ochronę wojskową. Ten łańcuch układów przygotował grunt pod ogłoszenie w 1887 roku formalnego Protektoratu Somalilandu Brytyjskiego.", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["Bitwa pod Mulajdą — koniec Drugiego Państwa Saudyjskiego, Nadżd przeszedł do Raszidydów", "1cd3b213"], "d": ["W końcu zerwanych przez spór o zakat i aresztowanie posła Raszidydów stosunków armia emira Dżabal Szammar Muhammada ibn Raszida zadała 21 stycznia 1891 roku w Mulajdzie w regionie Kasim ciężką klęskę siłom saudyjskim pod przewodnictwem Abd ar-Rahmana ibn Fajsala i ich sojusznikom; był to faktyczny koniec Drugiego Państwa Saudyjskiego, rodzina Al Saud udała się na wygnanie do Kuwejtu, a cały Nadżd wszedł pod zwierzchnictwo Raszidydów; wchodziły w to także południowe okolice Dilam (Charadż), Hawta (Hawtat Bani Tamim) i Lajla (Aflaj). Zwierzchnictwo miało trwać do odzyskania Rijadu przez młodego Abd al-Aziza ibn Sauda w 1902 roku (Napad na Rijad, 16 stycznia 1902).", "b77d8161"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["Przejście Somalii Włoskiej pod bezpośredni zarząd państwa — likwidacja Kompanii Benadir", "8c7d085b"], "d": ["Według hasła Somali w TDV Włochy ustanowiły swe zwierzchnictwo na południowym wybrzeżu Somalii (Benadir) w latach 1889-1891 układami z Sułtanatem Zanzibaru i Anglią, a zarząd pozostawiły początkowo uprzywilejowanej spółce handlowej (Benadir Company); według standardowego źródła akademickiego przywilej tej spółki wygasł 24 stycznia 1905 roku, a państwo włoskie, wykupując bezpośrednią suwerenność nad wybrzeżem Benadir (w tym Mogadiszu, Merka, Baraawe), ustanowiło oficjalny zarząd kolonialny. Faktyczne rozszerzenie kolonii w głąb lądu (Bardera, Baydhabo) miało zostać dopełnione dekretem założycielskim z 1908 roku i w następnych latach.", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["Rozwiązanie unii norwesko-szwedzkiej — jednostronne ogłoszenie niepodległości przez Storting", "aaba2935"], "d": ["Gdy król Oskar II zawetował żądanie rządu norweskiego utworzenia osobnych konsulatów i oświadczył, że nie zdoła utworzyć nowego rządu, norweski Storting (parlament) 7 czerwca 1905 roku jednogłośnie postanowił, że król faktycznie nie pełni już funkcji króla Norwegii i że unia trwająca od traktatu z Kilonii z 1814 roku została rozwiązana. W referendum z 13 sierpnia 1905 roku niemal wszyscy wyborcy (371 000 głosów przeciw 184) zatwierdzili rozwiązanie; Szwecja po rokowaniach w Karlstad formalnie uznała niepodległość 26 października 1905 roku.", "94eda38c"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Bicie pierwszego osmańskiego akçe", "38d2d638"], "d": ["Pierwszy srebrny akçe wybity w imieniu Orhana Gazi jest monetarnym ogłoszeniem niezależnej suwerenności bejliku; akçe pozostał podstawową jednostką pieniężną przez pięć wieków.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Utworzenie beylerbeyliku Rumelii", "ffa16089"], "d": ["Zdobycze po europejskiej stronie zebrano pod jednym wojskowo-administracyjnym dachem; ład beylerbeylików stał się kręgosłupem prowincjonalnej organizacji imperium.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Małżeństwo Bayezida Błyskawicy z Despiną Hatun", "4b10dc6c"], "d": ["Wasalność nawiązana po Kosowie z serbskim despotatem została przypieczętowana małżeństwem Olivery, córki Lazara, z Bayezidem — typowy przykład wczesnej dyplomacji małżeńskiej.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Utworzenie beylerbeyliku Anatolii", "5ef8d3a7"], "d": ["Dla zarządzania anektowanymi ziemiami bejlików zorganizowano beylerbeylik Anatolii; dwuskrzydłowy ład administracyjny Rumelia–Anatolia został dopełniony.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Ukończenie Wielkiego Meczetu w Bursie", "27bcc4a5"], "d": ["Wielki meczet o dwudziestu kopułach, wzniesiony z łupów z Nikopolis, jest monumentalnym przykładem wczesnej architektury osmańskiej i otwartym muzeum kaligrafii.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Odwołanie i stracenie Çandarlı Halila Paszy", "5e19438f"], "d": ["Po zdobyciu miasta stracono wielkiego wezyra z zasłużonej rodziny Çandarlı, który trzymał się z dala od oblężenia; po raz pierwszy wielki wezyr został zabity z rozkazu sułtana i otwierała się epoka wezyrów pochodzących z devşirme.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Objęcie Mołdawii daniną", "25bd3693"], "d": ["Wojewódzwo Mołdawii zgodziło się płacić daninę; wraz z Wołoszczyzną i Siedmiogrodem trójdzielny pas wasalny na północ od Dunaju stał się północnym buforem imperium. W tym samym dniu przyłączono także inne miejscowości: Jassy.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Danina Dubrownika (Raguzy)", "d127c78a"], "d": ["Kupiecka republika Raguza w zamian za daninę zagwarantowała sobie autonomię i przywileje handlowe; wzbogaciła się jako okno Osmanów na Adriatyku. Wyspa Mljet, ziemia republiki, dzieliła ten status.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Wyprawa na Wołoszczyznę: Wojewoda Palownik", "fd4530bb"], "d": ["Wyprawą przeciw Vladowi Palownikowi, który odmówił daniny i zabił posłów, Wołoszczyznę ponownie obrócono w wasalność; nocny napad i sceny grozy z palami obrosły w Europie legendą. W tym samym dniu przyłączono także inne miejscowości: Bukareszt.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Otwarcie kompleksu Fatiha", "a150ea55"], "d": ["Kompleks z ośmioma medresami (Sahn-ı Semân) był pierwszym wielkim krokiem programu przekształcenia Stambułu w ośrodek nauki świata islamu.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu w Stambule", "8508229d"], "d": ["Ali Kuşçu, ostatni wielki przedstawiciel obserwatorium w Samarkandzie, został na zaproszenie Fatiha profesorem medresy Hagia Sophia; założył w Stambule tradycję matematyczno-astronomiczną.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunname Fatiha", "b08944c9"], "d": ["Pierwsze obszerne kanunname prawa zwyczajowego, zbierające organizację państwa, protokół i kary; jest dyskutowane z powodu słynnego artykułu zezwalającego na bratobójstwo „dla porządku świata”.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Wybicie pierwszego osmańskiego złota (sultanî)", "2fd5c0dd"], "d": ["Wybito pierwszą osmańską monetę złotą równą dukatowi weneckiemu; finanse imperium weszły do międzynarodowego porządku pieniężnego.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Przeniesienie do Pałacu Topkapı", "b9cd6a5e"], "d": ["Wraz z ukończeniem Nowego Pałacu (Topkapı) przeniesiono tam centrum zarządu państwa; pałac przez cztery stulecia pozostał mózgiem imperium.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Republika Florencka przekształcona w księstwo — Alessandro de' Medici", "c08764e1"], "d": ["Pod naciskiem papieża Klemensa VII florencka komisja rządząca (Balìa) przyjęła nową konstytucję; zniesiono pięciowiekowy ustrój republikański, a Alessandro de' Medici został ogłoszony księciem dziedzicznym i faktycznie objął władzę 1 maja. Florencja przekształciła się w ten sposób z niepodległej republiki miejskiej w dziedziczne księstwo dynastii Medyceuszy.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Małżeństwo Sulejmana z Hürrem Sułtan", "abc05f26"], "d": ["Zawarcie przez Sulejmana oficjalnego małżeństwa z Hürrem radykalnie zmieniło tradycję pałacową; narodziła się instytucja „Haseki Sułtan” i otwarto bramę epoce kobiet w polityce dynastii.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Pierwsze obszerne kapitulacje dla Francji", "e2264e48"], "d": ["W ramach sojuszu z Francją przeciw uściskowi Habsburgów podpisano między Jeanem de la Forest a Makbulem İbrâhimem Paszą przywileje handlowe; kapitulacje, które w owym dniu były narzędziem dyplomatycznym, miały z biegiem stuleci stać się bramą zależności finansowej.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Wyprawa na Ocean Indyjski: oblężenie Diu", "fcd1217a"], "d": ["Flota wypływająca z Suezu przeszła Morze Czerwone i oblegała Diu w Gudżaracie; choć twierdzy nie zdobyto, potęga osmańska po raz pierwszy sięgnęła Oceanu Indyjskiego, a portugalski monopol został wstrząśnięty.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Podróż Seydi Alego Reisa do Indii", "e5da3b2c"], "d": ["Seydi Ali Reis, któremu polecono sprowadzić do Egiptu flotę z Basry, został rozbity przez sztormy do Indii; Mir'âtü'l-memâlik, w którym opisał przygodę powrotu, należy do pierwszych osmańskich relacji z podróży.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Stracenie Pîrî Reisa", "63026444"], "d": ["Wielki żeglarz i kartograf, który po wyprawie do Ormuzu zostawił flotę w Basrze i wrócił, został stracony w wieku 84 lat — jedna z najbardziej spornych decyzji w naszej historii nauki.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Otwarcie kompleksu Süleymaniye", "1c6458b2"], "d": ["Kompleks nazwany przez architekta Sinana „dziełem czeladnika”; wraz z medresami, szpitalem (dârüşşifâ) i biblioteką stał się największym kompleksem edukacyjno-dobroczynnym okresu klasycznego.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Oblężenie Malty", "f57f6a85"], "d": ["Maltę, klucz Morza Śródziemnego, oblegano cztery miesiące; Turgut Reis poległ jako męczennik, oblężenie zniesiono. Był to pierwszy wielki krok wstecz osmańskiej żeglugi za czasów Sulejmana.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Ukończenie meczetu Selimiye", "3b0484e1"], "d": ["Selimiye, nazwane przez Sinana „dziełem mistrza”, w którym jedna kopuła dominuje nad przestrzenią, uważa się za szczyt osmańskiej architektury klasycznej (Światowe Dziedzictwo UNESCO).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Założenie Obserwatorium Stambulskiego", "169bdf5d"], "d": ["Obserwatorium Takiyyüddina, jedno z najlepiej wyposażonych ówczesnych obserwatoriów, zostało zburzone w 1580 wskutek sporów po komecie z 1577; instytucjonalna astronomia opóźniła się o trzy stulecia.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Zwycięstwo pod Çıldır — początek wojny wschodniej", "13125a54"], "d": ["Wraz z klęską armii safawidzkiej pod Çıldır otwarto bramy Kaukazu; zdobyto Tbilisi, a Gruzja weszła pod panowanie osmańskie.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Bitwa Pochodni — Szyrwan ostatecznie osmański", "3bbc23bc"], "d": ["W bitwie nazwanej tak, ponieważ trwała także nocą w świetle pochodni, Safawidów ostatecznie pokonano; panowanie osmańskie w Szyrwanie i Baku zostało umocnione.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Wielka dewaluacja — kryzys akçe", "9205c3d4"], "d": ["Pod naciskiem długich wojen i amerykańskiego srebra zawartość srebra w akçe obniżono o połowę; rewolucja cen podsycała rozpad ładu sipahich i zamęt celâlich.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Zdobycie Tabrizu", "6506bdb9"], "d": ["Serdar Özdemiroğlu Osman Pasza wkroczył do Tabrizu; dawną stolicę Safawidów objęto zarządem osmańskim. Osman Pasza zmarł po kilku tygodniach w obozie.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Traktat Ferhada Paszy — najdalsze granice na wschodzie", "c429972f"], "d": ["Na mocy traktatu zawartego po przybyciu do Stambułu posła szacha Abbasa, Haydara Mirzy (18 stycznia 1590), pod warunkiem, że zdobyte miejsca pozostaną przy Osmanach, a kończącego 12-letnią wojnę, Tabriz, Karabach, Szyrwan, Gruzja i Luristan pozostały osmańskie; imperium osiągnęło na wschodzie najdalsze granice w swojej historii.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Początek wojny osmańsko-safawidzkiej (1603–1612) — kontrofensywa szacha Abbasa, utrata Tabrizu", "abf27dd8"], "d": ["Szach Abbas, który przeorganizował swoją armię, przeszedł do ataku, wykorzystując zamęt celâlich; Tabriz padł, a zdobycze na Kaukazie utracono w ciągu kilku lat. Miejscowości utracone w tej samej wyprawie i następnie: Nachiczewan, Choj, Merend, Selmas; również beje Karacadağ (Ahar) i Mukrî zwrócili się ku stronie safawidzkiej.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Narodziny Evliyi Çelebiego", "2b6051ff"], "d": ["Evliya Çelebi, który podróże trwające ponad pięćdziesiąt lat zebrał w dziesięciotomowym Seyahatnâme, pozostawił niezrównaną panoramę osmańskiego świata XVII wieku.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Traktat Nasuha Paszy", "bb69e388"], "d": ["Traktat kończący wojnę trwającą od 1603 zrzekł się zdobyczy z 1590 i przywrócił granicę amasyjską z 1555; na froncie wschodnim przywrócono równowagę.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Otwarcie meczetu Sułtanahmet", "e39dfd43"], "d": ["„Błękitny Meczet” z sześcioma minaretami i błękitnymi kafelkami z İzniku jest ostatnim wielkim kompleksem sułtańskim okresu klasycznego.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Zabicie sułtana Ibrahima", "bc4eb452"], "d": ["Z powodu rozrzutności i kryzysu rządów sojusz korpusów i ulemów zdetronizował Ibrahima; po dziesięciu dniach kazano go udusić na mocy fatwy. Na tron wstąpił siedmioletni Mehmed IV; władza faktycznie przeszła w ręce wielkiej matki sułtańskiej Kösem Sułtan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Śmierć Kâtiba Çelebiego", "e167e89d"], "d": ["Szczytowa postać osmańskiej historii nauki, znany z bibliografii Keşfü'z-zunûn i geografii Cihannümâ oraz z pionierskiego podejścia korzystającego ze źródeł europejskich.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Wydarzenie edyrneńskie — detronizacja Mustafy II", "0291c1cd"], "d": ["Gniew wywołany przebywaniem sułtana w Edirne i wpływami Feyzullaha Efendiego przerodził się w wielkie powstanie armii i rzemieślników; szejhülislam został zlinczowany, sułtana zdetronizowano, a pałac wrócił do Stambułu.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Ambasador w Paryżu: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["Wielka ambasada wysłana do Francji była pierwszą systematyczną obserwacją Zachodu na miejscu; jego Sefâretnâme zainspirowało odnowę Epoki Tulipanów.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Założenie pierwszej drukarni osmańskiej", "4943f7e5"], "d": ["Udzielono zezwolenia na druk książek tureckich; pierwsze dzieło, Słownik Vankulu, wydrukowano w 1729. Drukarnia jest najtrwalszym dziedzictwem odnowy Epoki Tulipanów.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Uczynienie kapitulacji trwałymi", "d044a79e"], "d": ["Przywileje nadane Francji przestały ograniczać się do osoby sułtana i związano je z trwałym traktatem; reżim kapitulacyjny, którego nie można było jednostronnie wypowiedzieć, mógł zostać zniesiony dopiero w Lozannie.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Założenie Mühendishâne-i Bahrî-i Hümâyun", "9bf3f439"], "d": ["Szkoła inżynierska założona po katastrofie pod Çeşme w celu kształcenia nowoczesnych oficerów marynarki jest pierwszą trwałą instytucją zachodniego kształcenia technicznego; lądowa szkoła inżynierska nastąpiła w 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Pierwsze stałe poselstwo w Londynie", "6b5630eb"], "d": ["W ramach programu Nizâm-ı Cedîd otwarto stałe poselstwa w stolicach europejskich; dyplomacja osmańska przeszła na zasadę wzajemności.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Śmierć Alemdara Mustafy Paszy", "4426534e"], "d": ["W powstaniu janczarów rozpoczętym nocą 15 listopada 1808 reformatorski wielki wezyr, oblężony w Bâbıâli, gdy nie nadeszła oczekiwana pomoc, następnego dnia wysadził arsenał i zginął wraz z setkami napastników; z nim pogrzebano ład Sened-i İttifak i pierwszą próbę reform.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Pierwszy dziennik urzędowy: Takvîm-i Vekāyi", "c637f623"], "d": ["Zaczęto wydawać urzędowy dziennik państwa; jest to początek tradycji nowoczesnej opinii publicznej i urzędowych komunikatów.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Traktat handlowy z Balta Limanı", "e790b383"], "d": ["Anglii przyznano najbardziej uprzywilejowaną pozycję nawet w handlu wewnętrznym, zniesiono system yed-i vahit (monopol); gdy rodzima produkcja pozostała bez ochrony, traktat stał się dokumentem pełnego otwarcia rynku osmańskiego na wolny handel.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Koniec Emiratu Libanu — odsunięcie Beşîra Şihâba III", "f85ae454"], "d": ["Emir Beşîr II (III), który nie potrafił kontrolować rywalizacji chrześcijańsko-druzyjskiej i wewnętrznych równowag w regionie Szuf, został w styczniu 1842 odsunięty od władzy; lokalny ład emiratu trwający od 1516 (rękami Ma'noğulları, a następnie Şihâboğulları) dobiegł końca, a region przeszedł pod bezpośredni zarząd osmański, następnie do systemu podwójnego kaymakamatu.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: ład Mecidiye", "c77be809"], "d": ["Reformą pieniężną wycofano monety o zepsutym kruszcu; ustanowiono stabilny bimetaliczny ład oparty na złotym lirze (Mecidiye).", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Koniec lokalnego panowania rodu Harfûş w Baalbek", "8438f4ae"], "d": ["Wpływy rodu Harfûş, który od 1521 (po powstaniu Canbirdiego Gazâlîego) rządził w Baalbek jako mała lokalna dynastia, skończyły się wraz z nowym ładem administracyjnym Bâbıâli; miasto stało się zwykłym ośrodkiem kazy podległym wilajetowi Damaszku.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Założenie Şirket-i Hayriyye", "462830e7"], "d": ["Spółka założona do obsługi parowców na Bosforze uchodzi za pierwszą osmańską spółkę akcyjną; przystanie parowców naznaczyły życie miasta.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Pierwsza umowa o dług zagraniczny", "9017c579"], "d": ["Na sfinansowanie wojny krymskiej zaciągnięto pierwszą pożyczkę zagraniczną na rynku londyńskim; punkt, do którego doszło po 15 zadłużeniach w 21 lat, to moratorium z 1875 i Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Linia telegraficzna w Stambule", "d320f39f"], "d": ["Pierwsza linia telegraficzna założona z potrzeb wojny krymskiej została oddana do użytku; w ciągu kilku dziesięcioleci imperium zyskało jedną z najrozleglejszych sieci telegraficznych świata.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Kanunname Gruntowe (Arazi)", "6bae243a"], "d": ["Kanunname, modernizujące prawo gruntowe, związało faktyczne dysponowanie gruntami państwowymi (mîrî) z tapu; jest jednym z podstawowych dokumentów porządku własności na dzisiejszym Bliskim Wschodzie.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Pierwsze wykłady w Dârülfünun", "08f74066"], "d": ["Dârülfünun, mające prowadzić kształcenie na poziomie uniwersyteckim, rozpoczęło działalność wykładami otwartymi; instytucja, trwająca z przerwami, została otwarta na stałe w 1900 roku i stała się zalążkiem Uniwersytetu Stambulskiego.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Regulamin Wilajetów", "ad20853b"], "d": ["W miejsce ładu ejaletów ustanowiono organizację wilajetów na wzór francuski; wzorując się na praktyce Midhata Paszy w Wilajecie Dunajskim, rozszerzono ją na cały kraj.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Podróż Abdülaziza do Europy", "9ff0fa1e"], "d": ["Pierwsza w historii podróż sułtana osmańskiego do Europy w celach pokojowych; wystawa w Paryżu i wizyty w Londynie pełniły funkcję zarówno dyplomacji, jak i wystawy modernizacji.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Otwarcie Mekteb-i Sultânî w Galatasaray", "f9688524"], "d": ["Liceum prowadzące nauczanie w języku francuskim stało się, dzięki strukturze uczniów niezależnej od religii i narodowości, symbolem ideału równości w edukacji Tanzimatu.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Wejście w życie pierwszej księgi Mecelle", "6475461c"], "d": ["Mecelle, zbierające w nowoczesnej technice legislacyjnej dział zobowiązań i rzeczy prawa islamskiego, uchodzi za pierwszy islamski kodeks cywilny; komisja pod przewodnictwem Cevdeta Paszy ukończyła 16 ksiąg w 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Detronizacja Abdülaziza", "eb7397ea"], "d": ["Konstytucjonalistyczni mężowie stanu i dowództwo wojskowe zdetronizowali Abdülaziza cichym zamachem; jego podejrzana śmierć po pięciu dniach i następujące po niej wydarzenia w Çırağan zrodziły rozrachunki trwające lata.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Napad na Çırağan (sprawa Alego Suâviego)", "d2a9ac87"], "d": ["Dziennikarz Ali Suâvi napadł na Çırağan, by ponownie wprowadzić na tron Murada V; napad krwawo stłumiono, a reżim Abdülhamida trwale zacieśnił krąg bezpieczeństwa.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Utworzenie Administracji Reji (monopol tytoniowy)", "bad9b030"], "d": ["Dochody z tytoniu przekazano zagranicznej spółce Reji działającej w ramach Düyûn-ı Umûmiyye; starcia „przemytu Reji” między chłopami a strażnikami trwały przez dziesięciolecia. W tym samym dniu utracono także inne miejscowości: Zeila.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Wizyta cesarza Wilhelma II w Stambule i Jerozolimie", "2988cd06"], "d": ["Druga wizyta cesarza niemieckiego umocniła zbliżenie osmańsko-niemieckie; otwarto drogę koncesji na kolej bagdadzką, a w Damaszku wygłoszono przemówienie o „przyjacielu trzystu milionów muzułmanów”.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Kolej Hidżaska w Medynie", "95009b9c"], "d": ["Linia o długości 1464 km, zbudowana wyłącznie z datków muzułmańskich i dzięki rodzimej inżynierii, dotarła do Medyny; podróż pielgrzymia skróciła się z tygodni do dni. Jest największym dziełem infrastrukturalnym epoki Abdülhamida II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Wydarzenie 31 marca", "1d7c2bb2"], "d": ["Wielkie powstanie przeciw monarchii konstytucyjnej opanowało Stambuł; Armia Akcji przybyła z Salonik i stłumiła bunt, a Abdülhamid II został zdetronizowany.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Początek oblężenia Edirne", "234d9b28"], "d": ["Trwająca pięć miesięcy obrona Şükrü Paszy stała się eposem oporu w bałkańskiej katastrofie; miasto padło z głodu, a w lipcu 1913 zostało odzyskane.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Napad na Bâb-ı Âli", "b304d02d"], "d": ["Rząd przygotowujący się do oddania Edirne został obalony zbrojnym napadem unionistów; minister wojny Nâzım Pasza został zabity. Rozpoczął się okres pełnej władzy Komitetu Jedności i Postępu.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Zniesienie mutasarrifatu Góry Libanu", "b5639051"], "d": ["Autonomiczny ład mutasarrifatu, ustanowiony przez Reglement Organique z 1861 i oparty na odnowionym w 1864 protokole międzynarodowym, został w czasie I wojny światowej jednostronnie wypowiedziany przez państwo osmańskie; Ministerstwo Spraw Wewnętrznych zaczęło mianować w regionie bezpośrednio muzułmańskich mutasarrifów. Okres autonomii, w którym w latach 1861–1915 urzędowało ośmiu mutasarrifów, w ten sposób się zamknął.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Podział kraju między książąt", "82f26bfb"], "d": ["Po klęsce pod Ankarą Süleyman Çelebi przeszedł do Rumelii i ogłosił w Edirne sułtanat; İsa Çelebi utrzymał Bursę, a Çelebi Mehmed region Amasya–Tokat–Sivas. Na mapie te trzy działy pokazano odrębnymi kolorami.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Układ w Gallipoli: wybrzeże Morza Czarnego aż po Mesembrię oddane Bizancjum", "a4164eca"], "d": ["Emir Süleyman, pragnący utrzymać się w Rumelii po klęsce pod Ankarą, podpisał w Gallipoli układ z cesarzem bizantyjskim Manuelem. Oddał Bizancjum Kartal, Pendik i Gebze oraz niektóre wyspy, w Rumelii Saloniki i Tesalię, a nad Morzem Czarnym pas wybrzeża sięgający Mesembrii; zniesiono także podatek płacony przez Bizancjum Osmanom. Ahtapolu, İğneada i Rezve na wybrzeżu Strandży pozostały w ten sposób przez dwadzieścia jeden lat pod zarządem bizantyjskim; Murad II większość tych miejsc odzyskał pokojem w 1424.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Śmierć Bayezida Błyskawicy w niewoli", "7e968d83"], "d": ["Sułtan, który znajdował się w niewoli u Timura, zmarł w Akşehir; jego ciało przewieziono do Bursy i pochowano. Jego śmierć uczyniła walkę o tron między książętami nieodwracalną.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Układ w Gallipoli — ustępstwa na rzecz Bizancjum", "dfacbd00"], "d": ["Süleyman Çelebi, pragnący zapewnić sobie pozycję w Rumelii, porozumiał się z państwami bizantyjskim i łacińskimi i zwrócił Saloniki, wybrzeża Marmary i niektóre wyspy; zgodził się nawet płacić daninę.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Starcie pod Ulubat — klęska İsy Çelebiego", "500c5d24"], "d": ["İsa Çelebi, który trzymał Bursę, został pokonany pod Ulubat przez brata Mehmeda; kilka prób odbudowy sił również nie przyniosło skutku.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Zniknięcie İsy Çelebiego", "0effa11e"], "d": ["İsa Çelebi, który kilkakrotnie wracał do Anatolii z poparciem Süleymana Çelebiego, po ostatniej klęsce zniknął; jego dział przeszedł na Çelebiego Mehmeda, a na mapie obszar Mehmeda rozszerzył się ku zachodowi.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi przeszedł do Wołoszczyzny", "8441267a"], "d": ["Çelebi Mehmed, który wobec Süleymana Çelebiego stracił Bursę i Ankarę i wycofał się do Tokat–Amasya, zachęcił brata Musę do udania się do Rumelii. Musa, przyjąwszy zaproszenie wojewody wołoskiego Mirczy, dotarł drogą morską na Wołoszczyznę; stąd miał rozpocząć walkę, która postawi Süleymana między dwoma frontami.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed ponownie zajął Bursę i Ankarę — dział anatolijski wyszedł z rąk Süleymana Çelebiego", "bfb69f12"], "d": ["Wobec sukcesów Mûsy Çelebiego w Rumelii (Yambol, 13 lutego 1410) przebywający w Anatolii emir Süleyman Çelebi przeszedł do Rumelii. Po opuszczeniu przez Süleymana Anatolii Mehmed Çelebi ponownie zajął region Bursy wraz z Ankarą i na znak objęcia tronu kazał wybić monetę z datą 813. Na mapie anatolijska strona Marmary przechodzi z działu emira Süleymana do koloru Çelebiego Mehmeda.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Bitwa pod Kosmidion", "0efc2caa"], "d": ["W bitwie pod murami Stambułu, stoczonej z poparciem Bizancjum, Süleyman Çelebi pokonał brata Musę; jednak jego poparcie w Rumelii zaczęło szybko topnieć.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Oblężenie Stambułu przez Musę Çelebiego", "4932f586"], "d": ["Musa Çelebi, pragnąc ukarać Bizancjum, które poparło Süleymana, oblegał Stambuł; oblężenie to popchnęło Bizancjum do sojuszu z Çelebim Mehmedem.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Śmierć emira Süleymana — Musa panuje w Rumelii", "325c1549"], "d": ["Süleyman Çelebi, schwytany podczas ucieczki z Edirne, został zabity; cała Rumelia przeszła w ręce Musy Çelebiego. Na mapie Rumelia zmienia kolor z niebieskiego na fioletowy.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Bitwa pod Çamurlu — odtworzenie jedności", "0b23173e"], "d": ["Çelebi Mehmed, który uzyskał poparcie Bizancjum, serbskiego despotatu i bejów Rumelii, ostatecznie pokonał brata Musę pod Çamurlu; Musa został zabity podczas ucieczki. Rumelia w rękach Musy przeszła wraz z Edirne do Mehmeda, a Mehmed Çelebi ogłosił się w Edirne jedynym władcą państwa osmańskiego. Jedenastoletnie Interregnum dobiegło końca, a działy książąt na mapie zlały się w jedno ciało.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Decyzja o wyprawie na Wiedeń — pokój z Vasvár nie został odnowiony, cel zmieniono z Györ na Wiedeń", "1bf278f2"], "d": ["Cesarz Leopold I chciał odnowienia traktatu z Vasvár, którego termin jeszcze nie upłynął, a Mehmed IV również zdawał się sprzyjać pokojowi. Wielki wezyr Merzifonlu Kara Mustafa Pasza, powołując się na skargi Imre Thökölyego, ogłoszonego królem Węgier Środkowych, nie dopuścił do odnowienia pokoju; uruchomił kaznodziejów, na czele z Vânî Mehmedem Efendim, i przekonał sułtana do wojny. Na naradzie postanowiono, że sułtan zostanie w Belgradzie, a serdar-ı ekrem ruszy, by zdobyć Győr; jednak na naradzie w Székesfehérvár, mimo sprzeciwu chana krymskiego Murada Gireja i namiestnika Budy Uzuna İbrâhima Paszy, cel zmieniono na oblężenie Wiednia.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Początek II oblężenia Wiednia — armia pod Wiedniem", "bb542e49"], "d": ["Armia osmańska pod dowództwem wielkiego wezyra Kara Mustafy Paszy stanęła 14 lipca 1683 pod Wiedniem. Cesarz Leopold I, zostawiwszy obronę miasta Starhembergowi, wycofał się w głąb Austrii. To drugie oblężenie, przygotowywane w odróżnieniu od pierwszego z Wiedniem jako bezpośrednim celem, miało trwać do 12 września.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Klęska pod Párkány i utrata Ostrzyhomia", "a7366740"], "d": ["Armia wycofująca się spod Wiednia została po raz drugi rozbita pod Párkány; następnie padł Ostrzyhom, jedna z kluczowych twierdz Węgier. Odwrót zaczął przeradzać się w załamanie.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Stracenie Merzifonlu Kara Mustafy Paszy", "ce8b10ac"], "d": ["Wielki wezyr uznany za odpowiedzialnego za klęskę pod Wiedniem został uduszony w Belgradzie; jednak jego stracenie nie poprawiło frontu ani nie przywróciło nadwątlonego prestiżu państwa.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Zawiązanie Świętej Ligi", "060280d0"], "d": ["Z inicjatywy papiestwa zawarto Świętą Ligę przeciw Osmanom między Austrią, Polską i Wenecją; w 1686 dołączyła Rosja. Imperium weszło w ten sposób w wielofrontową wojnę trwającą szesnaście lat.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Pierwsza obrona Budy", "ccc43630"], "d": ["Pierwsze oblężenie Budy przez armię Świętej Ligi odparto dzięki upartej, czteromiesięcznej obronie twierdzy; jednak twierdze na Węgrzech nadal padały jedna po drugiej.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Utrata Uyvaru", "689ab78c"], "d": ["Twierdza Uyvar, która pozostawała w rękach osmańskich przez dwadzieścia dwa lata i stała się w Europie przysłowiem, padła; obecność osmańska w Górnych Węgrzech się rozpadła.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Aresztowanie Thökölyego w Várad — rozpad Królestwa Węgier Środkowych, poddanie twierdz Górnych Węgier", "1741aaaf"], "d": ["Po klęsce pod Wiedniem Osmanowie zaczęli widzieć w Thökölym także jednego ze sprawców wojny i porażki. 15 października 1685 z rozkazu serdara Meleka İbrâhima Paszy beylerbej Váradu Ahmed Pasza kazał pojmać przybyłego z pomocą Thökölyego; miano nadzieję, że wydając go Habsburgom uzyska się lepsze warunki pokoju. Gdy wieść o aresztowaniu się rozeszła, wszystkie twierdze i miasta Królestwa Węgier Środkowych, z wyjątkiem Mukaczewa bronionego przez jego żonę Ilonę Zrínyi, poddały się Habsburgom; większość kuruców przeszła do armii habsburskiej. Gdy Thököly został uwolniony w Belgradzie 2 stycznia 1686, królestwa już nie było.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Utrata Budy — 145-letniej stolicy węgierskiej", "70800e2b"], "d": ["Po siedemdziesięciu ośmiu dniach oblężenia Buda padła; ostatni beylerbej Abdurrahman Abdi Pasza poległ jako męczennik na murach. Utrata miasta pozostającego od 1541 pod zarządem osmańskim jest uważana za symbol utraty Węgier. W tym samym dniu utracono także inne miejscowości: Peszt.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Druga klęska pod Mohaczem (Nagyharsány) — utrata Siedmiogrodu i Mohacza", "a7922681"], "d": ["Na równinie, gdzie w 1526 odniesiono wielkie zwycięstwo, tym razem poniesiono ciężką klęskę; armia się rozproszyła, zbuntowani żołnierze zmusili do odwołania wielkiego wezyra. Klęska pociągnęła za sobą także utratę Siedmiogrodu.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Utrata Aten i wybuch Partenonu", "b6691730"], "d": ["Granat wystrzelony przez artylerię wenecką wysadził w powietrze Partenon, który Osmanowie wykorzystywali jako skład amunicji; dwutysiącletnia świątynia obróciła się w ruinę. Miasto przeszło w ręce Wenecji (zostanie odzyskane w 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Detronizacja Mehmeda IV i wstąpienie na tron Sulejmana II", "9f53037c"], "d": ["Wobec katastrof na froncie i buntu armii Mehmed IV został zdetronizowany po 39 latach panowania; na jego miejsce wprowadzono brata Sulejmana II, od czterdziestu lat trzymanego w klatce.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Pierwsza utrata Belgradu — oblężenie Świętej Ligi", "c6b9b19a"], "d": ["Belgrad, pozostający w rękach osmańskich od 1521, poddał się armii Świętej Ligi; bramy Serbii otwarto dla wroga, a niebezpieczeństwo dotarło do linii Niš–Sofia. W tym samym dniu atlas zapisuje przejście od Osmanów do Habsburgów innej miejscowości: Hisarcık (Grocka) — podąża za łańcuchem ośrodka-brata Belgradu (TDV belgrad; przybliżenie z deklaracją).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden przekroczył Morawę pod Požarevac — Požarevac wpadł w ręce Austrii", "bcf3fc59"], "d": ["Margrabia Ludwik Badeński w sierpniu 1689 przekroczył Morawę pod Požarevacem i ruszył w kierunku Niszu; miasto pozostawało w rękach austriackich do lata 1690 (TDV suleyman-ii mówi, że Požarevac został odzyskany w 1690). Odczyt dnia i Rödera nie został w tej sesji ponownie zweryfikowany.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Utrata Niszu — natarcie Habsburgów (korony Królestwa Węgier), najbardziej krytyczny rok", "c5e27b3f"], "d": ["Natarcie Habsburgów (korony Królestwa Węgier) odebrało Osmanom także Niš; napady sięgały aż po Skopje i Prisztinę. Widyń padł natomiast później, w październiku 1689 (osobny wpis). W najciemniejszym roku wojny państwo czuło zagrożenie nawet dla stolicy.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova i Fethülislâm objęte garnizonem austriackim", "ee8dd875"], "d": ["Po bezwojennym zajęciu Widynia (październik 1689, TDV vidin) Baden 25 października 1689 naprawił Orsovę i Fethülislâm i obsadził je garnizonem; Orsova pozostała przy Austrii do jesieni 1690. Dzień opiera się na Bánlakym/Röderze, w tej sesji nie został ponownie zweryfikowany.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš ponownie osmański", "0c4f44eb"], "d": ["Fâzıl Mustafa Pasza wyruszył na wyprawę w lipcu 1690; po zajęciu Şehirköy, Požarevaca i Güvercinlik oblężony Niš wpadł 27 września 1690 w ręce Osmanów (TDV semendire). W tym samym czasie odzyskano także Widyń. W tym samym dniu atlas zapisuje powrót od Habsburgów do Osmanów innych miejscowości: Jagodina i Prokuplje (Ürküp) — ponieważ nie znaleziono dnia na poziomie miejscowości, wzięto dzień Niszu (TDV semendire; przybliżenie z deklaracją; Röder 1842 pisze, że wezyr przeszedł przez Jagodinę 8–24 września, sprzeczność nie została rozstrzygnięta).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Poddanie się wojsk austriackich w Smederevie", "90da20c4"], "d": ["Po zajęciu Niszu 27 września 1690 po czteródniowym oblężeniu poddały się wojska austriackie w Smederevie (TDV semendire). Bánlaky/Röder podaje 24 września; źródła się różnią, przyjęto TDV.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Odzyskanie Belgradu", "ab435838"], "d": ["Wielki wezyr Köprülüzâde Fâzıl Mustafa Pasza odzyskał 8 października 1690 Belgrad od Austrii; miasto utracone w 1688 wróciło w ten sposób do Osmanów (TDV suleyman-ii). W tym samym dniu atlas zapisuje powrót od Habsburgów do Osmanów innej miejscowości: Hisarcık (Grocka) — podąża za łańcuchem ośrodka-brata Belgradu (TDV suleyman-ii; przybliżenie z deklaracją).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Klęska pod Slankamenem — śmierć Fâzıla Mustafy Paszy", "10d626f1"], "d": ["W jednej z najkrwawszych bitew polnych stulecia wielki wezyr, trafiony w czoło, poległ jako męczennik; armia się rozproszyła. Nadzieja na odbudowę zgasła wraz z tą bitwą.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Utrata wyspy Chios", "07c084f8"], "d": ["Flota wenecka zajęła Chios; osmańskie panowanie na Morzu Egejskim znalazło się pod zagrożeniem. Wyspę odzyskano w następnym roku.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Decyzja Mustafy II o osobistym wyjściu na wyprawę", "61c3ba9c"], "d": ["Nowy sułtan, idąc śladem przodków, ogłosił, że wyruszy na wyprawę na czele armii; decyzja ta podniosła morale w wojsku i rozpoczęła okres osobistych wypraw trwający dwa lata.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Odzyskanie Chios", "6b496fca"], "d": ["Mezomorto Hüseyin Pasza, który w bitwach morskich pod Oinousses pokonał flotę wenecką, odzyskał Chios; było to oznaką krótkiego odrodzenia osmańskiej żeglugi.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Zwycięstwo pod Lugosem — pierwsza wyprawa austriacka Mustafy II", "d5ee9b34"], "d": ["W pierwszej wyprawie, w której sułtan wziął osobisty udział, odzyskano Lipovę, a pod Lugosem pokonano siły austriackie; w trwającym od lat łańcuchu klęsk nastąpiło pierwsze załamanie. Atlas uznaje także Caransebeș (Karánsebes) za wracające w tej wyprawie od Habsburgów do Osmanów; źródło podaje tylko wrzesień 1695 (TDV mustafa-ii), dzień atlasu wzięto z wpisu o Lugosie (przybliżenie z deklaracją).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Utrata twierdzy Azow", "2b78b5cd"], "d": ["Piotr I, który dążył do wyjścia na Morze Czarne, w drugim oblężeniu zdobył Azow; Rosja po raz pierwszy osiadła trwale w osmańskiej twierdzy i uczyniła pierwszy krok ku statusowi potęgi morskiej.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Zwycięstwo pod Ulaş (Olaşin)", "02ac9ca8"], "d": ["Zwycięstwo odniesione nad Dunajem w drugiej wyprawie sułtana pokrzyżowało austriacki plan zdobycia Timișoary; nie zmieniło jednak ogólnej równowagi wojny.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Klęska pod Zentą — losy wojny rozstrzygnięte", "475c4a7b"], "d": ["Armia została przy przekraczaniu Cisy zaskoczona nagłym napadem księcia Eugeniusza; siły rozdzielone po obu brzegach rzeki zniszczono w ciągu kilku godzin, zginęły tysiące żołnierzy i mężów stanu, w tym wielki wezyr Elmas Mehmed Pasza. Zenta, jedna z najcięższych klęsk w dziejach osmańskich, uczyniła stół pokojowy nieuniknionym.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Początek rokowań pokojowych w Karłowicach", "1f395cf3"], "d": ["W rokowaniach rozpoczętych za pośrednictwem Anglii i Holandii delegacja osmańska musiała po raz pierwszy przyjąć zasadę „uti possidetis” (pozostawienia tego, co się posiada); negocjacje trwające siedemdziesiąt dwie sesje uchodzą za narodziny nowoczesnej dyplomacji osmańskiej.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali z Kawali wylądował w Egipcie", "514c943f"], "d": ["W armii osmańskiej wysłanej w celu odzyskania Egiptu zajętego przez Francuzów znajdował się także oddział ochotników zebrany z Kawali. Mehmed Ali, trzydziestokilkuletni, był drugim dowódcą tego oddziału; stanął w Egipcie nie jako namiestnik, lecz jako oficer kompanii.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Żołnierze albańscy obalili namiestnika Egiptu", "c76a0ec2"], "d": ["Oddziały albańskie, którym nie wypłacano żołdu, zbuntowały się i zmusiły namiestnika Hüsrev Paszę do ucieczki z cytadeli. W próżni powstałej po wycofaniu się Francuzów beje mameluccy, ognisko albańskie i namiestnicy mianowani przez Bâbıâli weszli w trójstronną walkę; Mehmed Ali, ustalając równowagi w tym trójkącie, wysunął się na czoło. W tym samym dniu utracono także inne miejscowości: Ta'if.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Ulemowie Kairu ogłosili Mehmeda Alego namiestnikiem", "a16752f2"], "d": ["Rzemieślnicy i ulemowie Kairu, uciśnieni ciężarem podatków, pod wodzą nakîbüleşrafa Ömera Mekrema zbuntowali się, oświadczyli, że nie uznają namiestnika Hurşida Paszy, i osadzili na urzędzie namiestnika Mehmeda Alego. Wybór namiestnika przez lud jest w dziejach osmańskich wydarzeniem rzadko spotykanym.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Bâbıâli uznało fakt dokonany: ferman o namiestnictwie Egiptu", "b86736a3"], "d": ["Bâbıâli, nie mając w Egipcie siły, by utrzymać własnego kandydata, wysłało Mehmedowi Alemu ferman o namiestnictwie Egiptu wraz z rangą wezyra. Na mapie Egipt od tej daty przechodzi do warstwy zależnej (jasny odcień): prawnie jest ziemią osmańską, faktycznie krajem dynastii z Kawali. W tym samym dniu do warstwy zależnej przechodzą także inne miejscowości: Kair, Aleksandria, Damietta, Asjut, Asuan, Ibrim, Suez, Raszid (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Wyprawa brytyjska Frasera wylądowała w Aleksandrii", "4d6c31be"], "d": ["W odpowiedzi na zbliżenie Osmanów z Francją Anglia wysłała do Egiptu siły desantowe. Mehmed Ali zajmował się wówczas mamelukami w Górnym Egipcie; wracając szybko, zorganizował obronę.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Klęska pod Raszidem (Rosettą) — Anglicy odparci", "3636004c"], "d": ["Kolumna angielska, która weszła do miasteczka Raszid, poniosła w walkach ulicznych ciężkie straty; we wrześniu siły całkowicie opuściły Egipt. Zwycięstwo to umocniło prestiż Mehmeda Alego zarówno w Egipcie, jak i w Stambule.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Masakra w Cytadeli: likwidacja bejów mameluckich", "84030b97"], "d": ["Beje mameluccy, zaproszeni na uroczysty pochód zorganizowany z okazji wyprawy do Hidżazu, zostali uwięzieni w wąskim przejściu Cytadeli Kairu i wybici. Pięciowiekowe wpływy mameluków dobiegły w ten sposób końca, a Mehmed Ali nie miał już w Egipcie rywali.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Początek wyprawy do Hidżazu — armia ruszyła z Suezu morzem i lądem szlakiem pielgrzymim ku Yanbu", "1c05c159"], "d": ["Odzyskanie Haremejn, od 1803 pod władzą saudyjsko-wahhabicką, było dla Mahmuda II największą sprawą legitymacji; gdy Bâbıâli zabrakło sił, zadanie powierzono namiestnikowi Egiptu. Mehmed Ali wysłał na czele armii szesnastoletniego syna Tosuna.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Zajęcie Yanbu — pierwsza baza przybrzeżna wyprawy do Hidżazu", "179bc78d"], "d": ["Około dwóch tysięcy albańskich piechurów, którzy wyruszyli z Suezu nowo zbudowanymi okrętami, wylądowało w październiku 1811 pod Yanbu; miasteczko poddało się po dwóch dniach słabego oporu. Kawaleria pod dowództwem Tosuna, idąc lądem szlakiem pielgrzymim, dotarła do Yanbu przez Akabę i Wedżh dopiero po dwóch tygodniach. Yanbu stało się pierwszą bazą w Hidżazie armii egipskiej, która miała ruszyć na Medynę i Mekkę.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Pierwsza klęska w wąwozie Safra-Dżudajda", "99ef804d"], "d": ["Egipska straż przednia, wciągnięta w zasadzkę w wąskich przełęczach górskich, została rozproszona. Klęska stała się taktyczną lekcją wyprawy: zrozumiano, że bez poparcia plemion beduińskich nie można maszerować po Hidżazie.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Odzyskanie Medyny", "6f6a5d55"], "d": ["Po długim oblężeniu Medyna poddała się. Odzyskanie miasta Proroka uczczono w Stambule salwami armatnimi; Mehmedowi Alemu w nagrodę nadano także namiestnictwo Dżuddy.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Odzyskanie Mekki — otwarcie drogi pielgrzymiej", "3d6d66a0"], "d": ["Siły egipskie, które wkroczyły do Mekki, kazały ponownie odczytać w Kaabie chutbę w imieniu sułtana osmańskiego. Karawany pielgrzymów, przerwane od dziesięciu lat, mogły ponownie wyruszyć. Na mapie Hidżaz wraca pod panowanie osmańskie, lecz ponieważ zarządza nim Kair, jest pokazany w odcieniu zależnym. W tym samym dniu pod zarząd zależny przechodzi także inna miejscowość: Dżudda.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Odzyskanie Ta'if — zakończenie wyprawy do Hidżazu", "6315fb31"], "d": ["Po Medynie (grudzień 1812) i Mekce (styczeń 1813) armia egipska pod dowództwem Tosuna Paszy odzyskała od wahhabitów jako ostatnie Ta'if. Dziesięcioletnie panowanie saudyjskie dobiegło końca, a trzy święte ośrodki Hidżazu znalazły się ponownie pod kontrolą osmańsko-egipską.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali osobiście przeszedł do Hidżazu", "fda0ea2d"], "d": ["Namiestnik, widząc, że wyprawa toczy się powoli, wziął zarząd bezpośrednio w swoje ręce; targując się z wodzami plemion, próbował rozbić front saudyjski od wewnątrz. Udział Egiptu w handlu na Morzu Czerwonym także wzrósł dzięki tej wyprawie.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Bitwa pod Bisel: siły saudyjskie rozgromione", "9c9ab91f"], "d": ["Saudyjczycy, którzy ponieśli w bitwie polnej ciężką klęskę, wycofali się w głąb kraju. Zawarty rozejm nie był trwały; po dwóch latach działania miały zostać przeniesione do serca Nadżdu. Atlas uznaje po tym zwycięstwie za wyjęte spod władzy saudyjskiej Turabę i Hurmę na wschód od Ta'if (źródłem wydarzenia jest Lorimer, Gazetteer; świadectwo dla poszczególnych miejscowości i dzień 13 stycznia to przybliżenie z deklaracją).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["İbrâhim Pasza wyruszył na wyprawę do Nadżdu", "d5ed80d1"], "d": ["İbrâhim Pasza, który po śmierci brata Tosuna przejął dowództwo, rozpoczął dwuletni, ciężki marsz przez pustynię. Armia, posuwając się od studni do studni i eliminując plemiona jedno po drugim, dotarła do stolicy saudyjskiej.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Upadek Dirijji — koniec pierwszego państwa saudyjskiego", "aa96206d"], "d": ["Po sześciomiesięcznym oblężeniu Dirijja poddała się i została zburzona. Emir Abdullah ibn Saud został wysłany do Stambułu i stracony. Sztandar osmański po raz pierwszy dotarł tak głęboko w głąb Arabii; garnizon w Nadżdzie pozostał do 1824. W tym samym dniu przyłączono także inne miejscowości: Dirijja (Nadżd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Początek wyprawy do Sudanu", "b1fc6905"], "d": ["Cel Mehmeda Alego był potrójny: zebrać żołnierzy do swojej armii, dotrzeć do złota z Sennaru i zniszczyć uciekających resztki mameluków. Siły dowodzone przez jego syna İsmâila Paszę zeszły na południe wzdłuż Nilu.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Zajęcie Dongoli — rozproszenie resztek mameluków", "ba6bc24b"], "d": ["Armia, która wkroczyła do Dongoli w wielkim zakolu Nilu, zlikwidowała ostatnią grupę mameluków, która się tam schroniła. Na mapie Sudan pojawia się od tej daty w warstwie zależnej: zdobywcą jest Kair i Kair będzie nim zarządzał.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Poddanie się Sułtanatu Sennaru (Funj)", "3cac7dd2"], "d": ["Trzystuletnia dynastia Funj poddała się bez walki. W tym samym roku obóz założony w miejscu połączenia dwóch odnóg Nilu wkrótce przekształcił się w centrum administracyjne Sudanu, Chartum. W tym samym dniu przyłączono także inne miejscowości: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Zdobycie Kordofanu", "06440602"], "d": ["Druga kolumna wysłana na zachód pokonała pod Bâra siły Darfuru i zajęła Kordofan wraz z okolicami Nuhûd. Panowanie Egiptu nad Sudanem rozszerzyło się w ten sposób z doliny Nilu na zachodnie stepy.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Lądowanie sił egipskich na Krecie", "835aee90"], "d": ["Gdy powstanie greckie przeniosło się na Kretę, Bâbıâli zażądało wysłania na wyspę sił egipskich. Wpływy Mehmeda Alego na wyspie zaczęły się od tej interwencji i po ośmiu latach zakończyły przyznaniem mu namiestnictwa Krety.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Zabicie İsmâila Paszy w Shendi", "223860c9"], "d": ["Miejscowy emir Nimr, rozwścieczony ciężkimi podatkami i żądaniami żołnierzy, podpalił dom, w którym stał İsmâil Pasza, i spalił go wraz ze świtą. Wyprawa odwetowa zamieniła region w jezioro krwi; zarząd Sudanu opierał się odtąd na surowości.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II poprosił Mehmeda Alego o pomoc w Morei", "03594a42"], "d": ["W sprawie powstania w Morei, którego armią janczarską nie stłumiono w ciągu trzech lat, sułtan zwrócił się do armii egipskiej wyszkolonej na modłę europejską. W zamian obiecano namiestnictwo Morei i Kretę. Prośba ta była pierwszym jawnym przyznaniem, że imperium potrzebuje własnej prowincji.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["İbrâhim Pasza wylądował w Modon", "9c993dba"], "d": ["Siły desantowe osłaniane przez flotę egipską stanęły na południowo-zachodnim krańcu Morei. Armia wyposażona w piechotę nizamî i artylerię polową szybko uzyskała przewagę nad bandami powstańców.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Odzyskanie Tripolicy — padł ośrodek Morei", "8a478c11"], "d": ["Z upadkiem Tripolicy, ośrodka administracyjnego powstania, większa część Morei znalazła się ponownie pod kontrolą. Na mapie półwysep widnieje w odcieniu zależnym, ponieważ jest w rękach sił egipskich.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Upadek Missolonghi (Mesolongi)", "07257f87"], "d": ["Po rocznym oblężeniu miasto zdobyto. Jednak oddźwięk obrony w prasie europejskiej wzniósł sympatię dla sprawy greckiej na szczyt i przygotował grunt pod interwencję wielkich mocarstw.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Zajęcie Akropolu ateńskiego", "3b19f946"], "d": ["Wraz z upadkiem Akropolu powstanie greckie było militarnie niemal zakończone. Właśnie w tym punkcie sprawa przestała być wewnętrznym buntem i stała się przedmiotem dyplomacji europejskiej.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Traktat londyński: trzy mocarstwa narzuciły autonomię grecką", "7ce46fd8"], "d": ["Anglia, Francja i Rosja postanowiły działać wspólnie, by wymusić na Osmanach i Grekach rozejm i warunek autonomii; oznajmiono, że w razie odrzucenia interweniują ich floty. Bâbıâli odrzuciło propozycję.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Konwencja aleksandryjska: decyzja o wycofaniu Egiptu z Morei", "cc978f37"], "d": ["Mehmed Ali, który stracił flotę pod Nawarynem, porozumiał się bez konsultacji ze Stambułem bezpośrednio z admirałem angielskim i zgodził się wycofać swoje siły z Morei. Zawarcie przez namiestnika odrębnego traktatu z wielkimi mocarstwami było zwiastunem przyszłego kryzysu.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Siły egipskie opuściły Moreę", "8fb742dd"], "d": ["Ostatnie oddziały załadowano na okręty; półwysep faktycznie utracono, a protokołem londyńskim z 1830 stał się zalążkiem niepodległej Grecji. Mehmed Ali zaś nie otrzymał obiecanego namiestnictwa Morei, a w zamian stracił wielką flotę i armię. W tym samym dniu utracono także inne miejscowości: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Pozostawienie zarządu Krety Mehmedowi Alemu", "7f76396d"], "d": ["W rekompensacie za utratę Morei namiestnictwo Krety nadano Mehmedowi Alemu. Wyspa była przez dziesięć lat zarządzana z Kairu; na mapie w tym okresie widnieje w odcieniu zależnym. W tym samym dniu przyłączono także inne miejscowości: Kandia (Kreta).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["İbrâhim Pasza wkroczył do Syrii — początek pierwszego kryzysu", "1a5cc386"], "d": ["Pretekstem był namiestnik Akki, który nie wydawał fellahów uciekających z Egiptu; prawdziwą przyczyną była potrzeba Mehmeda Alego na drewno, porty i zasoby ludzkie Syrii. Armia, przekroczywszy Synaj, szybko zajęła wybrzeże palestyńskie.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Początek oblężenia Akki", "b211d96d"], "d": ["Twierdza, która zatrzymała Napoleona w 1799, opierała się przez sześć miesięcy. Oblężenie było pierwszym wielkim sprawdzianem nowoczesnej artylerii armii egipskiej.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Upadek Akki", "0f47917b"], "d": ["Gdy baterie bijące w mury zrobiły wyłom, twierdzę zdobyto. Brama Syrii została otwarta; Bâbıâli w tych samych dniach ogłosiło Mehmeda Alego buntownikiem i zniosło jego namiestnictwo.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Poddanie się Damaszku", "48da3b62"], "d": ["Miasto poddało się bez walki. İbrâhim Pasza, ogłaszając ład podatkowy i równość przyznaną niemuzułmanom, starał się zdobyć lokalne poparcie; te same polityki miały po kilku latach stać się powodem buntów przeciw niemu. W tych samych dniach przyłączono także inne miejscowości: Bejrut, Trypolis (Trablusşam), Sajda.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Bitwa pod Hims", "867810ee"], "d": ["Armia osmańska wysłana na ratunek Syrii została rozbita na otwartym terenie. Okazało się, że nowa armia utworzona sześć lat po zniesieniu janczarów nie była jeszcze gotowa.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Zajęcie Aleppo", "9c0ead76"], "d": ["Padł także ośrodek handlu i administracji Syrii Północnej. Armia egipska dotarła w ten sposób do podnóża Taurusu i zwróciła się ku przełęczom u wrót Anatolii.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Klęska w przełęczy Belen (Bajlan) — otwarcie Çukurovy", "4bae872b"], "d": ["Linię obrony w wąskiej przełęczy gór Amanos przełamano. Antiochia, Adana i Tarsus przeszły w ręce sił egipskich (okupacja Maraşu według TDV nastąpiła w 1833, osobny wpis); na mapie Çukurova wraca do odcienia zależnego. Droga w głąb Anatolii była już bezbronna.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Upadek przełęczy Gülek — wybrzeże İçil (Mersin, Silifke) pod kontrolą Egiptu", "d9049b5b"], "d": ["Przełęcz Gülek, brama Çukurovy w Taurusie, przeszła w ręce armii egipskiej. İbrâhim Pasza mianował do sandżaku İçil własnego mütesellima, a wszystkie przystanie na wybrzeżu znalazły się pod kontrolą Egiptu. Na mapie Mersin i Silifke od tego dnia (dolna granica; dnia mianowania nie ma w źródle) są pokazywane jako zależne od Egiptu; ponieważ w układzie z Kütahyi mowa tylko o muhassıllıku Adany, ta kontrola kończy się wraz z ewakuacją Anatolii.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Ereğli Konya pod okupacją egipską — taurusowe wejście drogi Konya–Adana", "fb908900"], "d": ["Ereğli leżące na drodze armii egipskiej, która przekroczyła przełęcz Gülek i szła ku Konyi, w 1832 znalazło się pod okupacją İbrâhima Paszy, a po opuszczeniu go na mocy układu z Kütahyi w 1833 zostało ponownie przyłączone do wilajetu Karaman. Na mapie jest to źródłowo poświadczony punkt pośredni linii okupacyjnej między Adaną a Konyą; dla Ulukışli i Karapınar nie znaleziono świadectwa na poziomie miasta.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Armia egipska wkroczyła do Konyi", "13952a2d"], "d": ["Armia, która przeszła Taurus, dotarła do Anatolii Środkowej. Siły osmańskiego namiestnika po raz pierwszy posuwały się po centralnych ziemiach imperium. W tym samym dniu przyłączono także inne miejscowości: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Bitwa pod Konyą: wielki wezyr w niewoli", "ec82cc9a"], "d": ["Armia osmańska, rozproszona w mglistą pogodę, poniosła ciężką klęskę, a wielki wezyr Reşid Mehmed Pasza dostał się do niewoli. Armii centralnej państwa już nie było; między Stambułem a siłami egipskimi nie pozostała żadna siła, która mogłaby je zatrzymać.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş pod okupacją egipską", "f558e383"], "d": ["Według TDV Maraş w 1833 znalazł się pod okupacją Kavalalı İbrâhima Paszy i przez blisko dziewiętnaście miesięcy pozostawał pod jego zarządem. Ponieważ Maraş leżał poza granicami ejaletów ustalonymi układem z Kütahyi, ten zarząd był nie prawny, lecz faktyczny.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) pod okupacją egipską — droga Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, leżący na drodze armii egipskiej posuwającej się po bitwie pod Konyą ku Kütahyi, przez pewien czas w 1833 pozostawał w rękach İbrâhima Paszy. Na mapie jest to źródłowo poświadczony punkt pośredni linii okupacyjnej między Konyą a Kütahyą; dla Akşehir, Ilgın i İshaklı nie znaleziono świadectwa na poziomie miasta, pozostają w kolorze osmańskim.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Armia egipska dotarła do Kütahyi", "214f8df6"], "d": ["İbrâhim Pasza zatrzymał się w Kütahyi, w odległości trzech postojów od Stambułu. To, że nie poszedł dalej, miało przyczynę nie wojskową, lecz polityczną: wzięto pod uwagę interwencję rosyjską i reakcję Europy.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Flota rosyjska pod Büyükdere", "6f836d61"], "d": ["Mahmud II, nie otrzymawszy pomocy od Anglii i Francji, zwrócił się do wczorajszego wroga, Rosji. Decyzja ta, wspominana w słowach sułtana „tonący chwyta się i węża”, zakończyła się wyjściem żołnierzy rosyjskich nad cieśniny i podniosła w Europie dzwony alarmowe.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Ugoda z Kütahyi (ustna) — Syria i Adana dla Mehmeda Alego", "25fe9985"], "d": ["Bâbıâli pozostawiło Mehmedowi Alemu, obok Egiptu, Krety i Hidżazu, namiestnictwa Damaszku, Aleppo, Trypolisu i Sajdy, a İbrâhimowi Paszy muhassıllık Adany. W zamian armia wycofała się na południe od Taurusu. Nie był to traktat, lecz fermany nadane przez sułtana namiestnikowi — sprawa nie została rozwiązana, lecz odłożona.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Wycofanie armii egipskiej z Anatolii zakończone przez Gülek", "a53ac2a3"], "d": ["Po układzie z Kütahyi siły egipskie opuściły Anatolię; około połowy czerwca cała armia przeszła przez przełęcz Gülek do Çukurovy. Wybrzeże İçil (Mersin, Silifke) wraca pod zarząd osmański; muhassıllık Adany i Syria pozostają przy Egipcie.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Traktat w Hünkâr İskelesi", "da741d5c"], "d": ["Podpisano z Rosją ośmioletni sojusz obronny. Według tajnego artykułu Osmanowie mieli zamknąć cieśniny dla okrętów wojennych, jeśli Rosja zostanie zaatakowana. Była to jedna z najbardziej spornych decyzji osmańskiej dyplomacji, która uaktywniła Anglię w sprawie egipskiej.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Powstanie w Palestynie-Nablus przeciw zarządowi egipskiemu", "4fe43e27"], "d": ["Obowiązkowa służba wojskowa, zbieranie broni i nowe podatki wywołały w Palestynie szerokie powstanie. Powstanie surowo stłumiono; poparcie dla zarządu egipskiego wśród miejscowej ludności szybko się wyczerpało.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Koniec egipskiego zarządu Maraşu (w przybliżeniu)", "bb46ca42"], "d": ["Gdy zdanie TDV o czasie „blisko dziewiętnastu miesięcy” liczy się od okupacji w 1833, zarząd egipski kończy się około lata 1834. To, że Mustafa Bej z Küçükalioğulları nie zdołał w 1834 stawić oporu armii egipskiej i wycofał się w stronę Maraşu, pokazuje też, że Maraş był wówczas schronieniem poza kontrolą egipską.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Powstanie w Dżabal ad-Druz", "12e74626"], "d": ["Opór, który wybuchł w regionie druzyjskim, trwał dwa lata. Niezadowolenie nagromadzone w Syrii miało w 1840, gdy floty sprzymierzonych wylądowały na wybrzeżu, odsłonić tyły armii egipskiej.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali ogłosił zamiar niepodległości", "48633bbd"], "d": ["Namiestnik oznajmił konsulom wielkich mocarstw, że rozważa ogłoszenie niepodległości Egiptu i Syrii. Anglia stanowczo temu się sprzeciwiła: powstanie silnego państwa na Morzu Śródziemnym, bliskiego Francji, zagrażałoby drodze do Indii.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Armia osmańska przekroczyła Eufrat", "9af1ea69"], "d": ["Mahmud II skierował armię na granicę syryjską, by odzyskać to, co stracił pod Kütahyą. Pruski oficer Moltke, który przebywał w armii jako doradca, sprzeciwił się wyborowi pozycji i wczesnemu atakowi; jego sprzeciwów nie wysłuchano.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Bitwa pod Nizip — armia osmańska rozproszona", "156b3cdf"], "d": ["Źle rozstawiona armia osmańska została rozbita w ciągu kilku godzin. Sułtan zmarł, zanim wieść o klęsce dotarła do Stambułu; państwo w ciągu kilku dni miało stracić armię, władcę, a następnie flotę.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Śmierć Mahmuda II", "07eccfff"], "d": ["Sułtan, który w ciągu trzydziestojednoletniego panowania zniósł janczarów i odbudował zarząd centralny, zmarł, nie pokonawszy swego największego przeciwnika. Choroby nie rozpoznano trafnie. Jego śmierć utrzymywano w tajemnicy do 30 czerwca, aż w mieście przedsięwzięto środki wojskowe, z obawy przed poruszeniem się mentalności janczarskiej.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Wstąpienie na tron Abdülmecida i pogrzeb Mahmuda II", "d0f3d2cc"], "d": ["Po śmierci ojca na tron wstąpił szesnastoletni Abdülmecid. W tym samym dniu zwłoki Mahmuda II przewieziono do Pałacu Topkapı; obawiane zamieszki nie wybuchły, a w kondukcie uczestniczyły szerokie rzesze muzułmanów i niemuzułmanów.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Oddanie floty Aleksandrii", "a53e6103"], "d": ["Kapudan pasza Ahmed Fevzi Pasza, podejrzewając, że wielki wezyr Koca Hüsrev Pasza odda flotę Rosji, zaprowadził flotę do Aleksandrii i oddał ją Mehmedowi Alemu. Państwo osmańskie w tym samym miesiącu pozostało bez armii, bez sułtana i bez floty.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Wspólna nota wielkich mocarstw", "2a3b8316"], "d": ["Pięć mocarstw przekazało Bâbıâli notę, żądając, by w sprawie egipskiej nie zawierało porozumienia samodzielnie. Wewnętrzna sprawa stała się w ten sposób oficjalnie „kwestią europejską”; państwo osmańskie faktycznie utraciło prawo decydowania o własnej prowincji.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Traktat londyński: cztery mocarstwa po stronie Osmanów", "a517f775"], "d": ["Traktat podpisany z pominięciem Francji dał Mehmedowi Alemu ultimatum: jeśli zgodzi się w ciągu dziesięciu dni — dziedziczne namiestnictwo Egiptu i Akka dożywotnio; jeśli w ciągu dwudziestu dni — tylko Egipt; jeśli odmówi — nic. Namiestnik odmówił.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardowanie Bejrutu i lądowanie sprzymierzonych", "0905ce92"], "d": ["Flota angielsko-austriacka ostrzelała Bejrut; ludności, która powstała w górach Libanu przeciw zarządowi egipskiemu, rozdano broń. Kontrola İbrâhima Paszy w Syrii załamała się między buntem wewnętrznym a interwencją zewnętrzną.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Utrata Bejrutu i miast przybrzeżnych", "09bdaf23"], "d": ["Po walkach w kierunku Baalbeku siły egipskie wycofały się znad wybrzeża. Na mapie wybrzeże Libanu wychodzi z odcienia zależnego i wraca pod zarząd bezpośrednio osmański.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akka padła w dwie godziny", "5aec21f0"], "d": ["Pod bombardowaniem floty sprzymierzonych wybuchł arsenał twierdzy, a Akka poddała się w ciągu kilku godzin. Twierdza, którą osiem lat wcześniej İbrâhim Pasza zdobył w sześć miesięcy, pokazała przewagę artylerii morskiej.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Konwencja aleksandryjska", "85cb47b0"], "d": ["Mehmed Ali zgodził się zrzec Syrii, Adany, Krety i Hidżazu, zwrócić flotę osmańską i uznać zwierzchnictwo sułtana; w zamian zagwarantowano dziedziczne namiestnictwo Egiptu.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Armia egipska opuściła Syrię i Çukurovę", "719a28dc"], "d": ["Dziewięcioletnia okupacja dobiegła końca; armia İbrâhima Paszy wróciła do Egiptu przez Synaj. Na mapie szeroki pas od Aleppo po Gazę i od Adany po Kretę przechodzi ponownie pod zarząd bezpośrednio osmański. W tym samym dniu utracono także inne miejscowości: Urfa, Maraş, Tarsus, Antiochia, Kandia (Kreta), Hama, Damaszek, Jerozolima, Jafa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Ferman: namiestnictwo Egiptu zostawione dziedzicznie rodzinie z Kawali", "87b89ff8"], "d": ["Ferman sułtański uznał namiestnictwo za przechodzące w obrębie dynastii z ojca na syna; w zamian liczebność armii obniżono do osiemnastu tysięcy, podatek związano ze Stambułem, a uprawnienia do bicia monety i zawierania traktatów odebrano. Egipt pozostał prowincją, lecz był już krajem odrębnej dynastii. Zarząd Hidżazu i Haremejn wrócił do Bâbıâli. W tym samym dniu z warstwy zależnej wracają do warstwy bezpośredniej inne miejscowości: Mekka, Medyna, Dżudda, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Konwencja o cieśninach w Londynie", "0e95a1ea"], "d": ["Konwencja, która zastąpiła Hünkâr İskelesi, postanowiła, że w czasie pokoju cieśniny są zamknięte dla wszystkich okrętów wojennych. Przywilej, który Rosja zyskała sama, stał się w ten sposób wspólną gwarancją Europy; kwestia cieśnin zyskała status międzynarodowy.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["İbrâhim Pasza faktycznie namiestnikiem Egiptu", "9e14f5d9"], "d": ["W miejsce starzejącego się i tracącego władze umysłowe Mehmeda Alego na namiestnictwo wprowadzono jego syna İbrâhima Paszę. Jednak po kilku miesiącach, w listopadzie 1848, zmarł przed ojcem.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Śmierć Mehmeda Alego Paszy z Kawali", "871310e0"], "d": ["Namiestnik, który urodził się w Kawali, założył dynastię w Egipcie i dwukrotnie doprowadził imperium na skraj przepaści, zmarł w wieku osiemdziesięciu lat. Założona przezeń dynastia panowała w Egipcie do 1953; państwo zaś, widząc, że ranę otwartą przezeń zdołało zamknąć interwencją europejską, poszło drogą Tanzimatu.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Süleyman b. Kutalmış pokonany i zabity pod Ajn Sulajm; Antiochia wyszła spod Seldżuków Anatolijskich", "0412dfa1"], "d": ["Süleyman b. Kutalmış, który w 1084 zajął Antiochię od Bizancjum, zginął w bitwie pod Ajn Sulajm stoczonej z władcą Seldżuków Syryjskich Tutuşem; miasto przeszło pod kontrolę sułtana Wielkich Seldżuków Melikszaha, a namiestnikiem mianowano Yağısıyana.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Melikszah zmarł; Antiochia wraz z Yağısıyanem została przyłączona do Tutuşa z Seldżuków Syryjskich", "c61da1b4"], "d": ["Po śmierci sułtana Wielkich Seldżuków Melikszaha państwo zostało podzielone między dziedziców; namiestnik Antiochii Yağısıyan związał się z panem Syrii Tutuşem.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Nikea poddała się krzyżowcom; ośrodek seldżucki cofnął się do Konyi, Bizancjum zaczęło odzyskiwać zachodnią Anatolię", "8a4e90fa"], "d": ["Po oblężeniu Nikei przez krzyżowców miasto poddało się 19 czerwca 1097 Bizancjum; sułtan seldżucki Kılıç Arslan I wycofał swój ośrodek w głąb kraju, do Konyi, a Bizancjum odzyskało miejsca na wybrzeżu zachodniej Anatolii, takie jak Efez.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kılıç Arslan II zajął od Bizancjum Dorylaion (Eskişehir) i Kütahyę", "3ddee6c2"], "d": ["Po Myriokefalonie (1176) bizantyjskie twierdze Dorylaion i Kütahya we wnętrzu Anatolii wpadły w ostatnich latach Manuela / po jego śmierci w 576/1180 w ręce Kılıça Arslana II.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Karamanoğlu Mehmed Bej mianowany subaszą Ermenek, objął İç İl", "6d62be11"], "d": ["Karamanoğlu Mehmed Bej został w 675 (1276) mianowany subaszą Ermenek i objął İç İl swoim zarządem; Ermenek stał się pierwszym ośrodkiem Karamanoğulları, którzy w następnym roku mieli pomaszerować na Konyę.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Śmierć Ertuğrula Gazi i przejęcie bejlika przez Osmana Beja — spuścizna Söğüt i Domaniç", "395fb9fa"], "d": ["Według TDV Ertuğrul Gazi zmarł w 680 (1281–82); hasło odnotowuje, że podaje się też daty 1288 i 1289. Osman Bej przejął po ojcu nie zdobyte miasto, lecz dwa nadania, które sułtan seldżucki dał Ertuğrulowi, osadzonemu na najdalszej linii pogranicza: zimowisko (yurtluk) w Söğüt i pastwisko letnie w Domaniç. Bejlik rozpoczął więc nie ze spuścizną zdobyczy, lecz z dwoma nadaniami pastwisk; na mapie te dwa miejsca są pokazane nie jako „zdobycz”, lecz „spuścizna”.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Nieszpory sycylijskie — dynastia Andegawenów utraciła wyspę Sycylię", "547db635"], "d": ["Powstanie, które w Palermo wybuchło w poniedziałek wielkanocny o godzinie nieszporów przeciw rządom Karola I Andegaweńskiego, oderwało wyspę Sycylię od dynastii Andegawenów. Królestwo Sycylii podzieliło się na dwie części: wyspa zwróciła się ku Aragonii, a dynastia Andegawenów utrzymała się w królestwie kontynentalnym z ośrodkiem w Neapolu. Zamorskie posiadłości dynastii na Adriatyku i Morzu Śródziemnym pozostały też przy tym królestwie: Korfu, które trzymali od 1267, i Durrës, które trzymali od lat 70. XIII wieku, trwały jako część Królestwa Neapolu; również twierdze Wlora, Kaninë i Himara na wybrzeżu albańskim pozostały w królestwie z ośrodkiem w Neapolu (dowódca Wlory John of Taxis opierał się Bizantyńczykom przez cały 1282; Durrës, Wlora i Kaninë najpewniej przeszły do Bizancjum na początku 1285). Malta wpadła natomiast w ręce Aragończyków dopiero w 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Napad na Kulacahisar — pierwsza akcja wojskowa Osmana Beja", "79b00b14"], "d": ["Hasło TDV Osman I: „Złupił i spalił małą twierdzę Kulaca Hisarı w pobliżu İnegöl (684/1285).” Jest to pierwsza w źródłach datowalna akcja wojskowa Osmana Beja. Nie zdobyto trwałego osiedla, twierdzę złupiono i spalono; jest to więc raczej klasyczny napad pograniczny niż zdobycie. Uważa się ją za punkt początkowy działalności wojskowej bejliku.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Zdobycie Karacahisar — pierwsze zdobycie miasta i panowanie nad Eskişehir", "178ae619"], "d": ["Hasło TDV Osman I: w 687 (1288) Osman Bej „zdobył Karacahisar i stał się panem Eskişehir”. Jest to pierwsze prawdziwe zdobycie miasta przez bejlik; według przekazu Osman Bej dzięki temu sukcesowi awansował do rangi sandżakbeja na pograniczu; opowiada się, że pierwsza piątkowa chutba została odczytana w jego imieniu w Karacahisar i że mianowano tam pierwszego kadiego. Hasło TDV o Eskişehir odnotowuje, że tradycja osmańska podaje datę 1291, lecz jej prawdziwość jest wątpliwa.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Upadek Akki w ręce mameluków — likwidacja obecności krzyżowców na wybrzeżu Syrii: Sajda i Bejrut", "3ca7a464"], "d": ["Akka, długo będąca ośrodkiem Królestwa Jerozolimskiego krzyżowców, została zdobyta przez sułtana mameluckiego al-Maliku l-Aszrafa Chalila, a panowanie krzyżowców w Palestynie dobiegło końca. Templariusze wycofani z Akki schronili się w Sajdzie; gdy zbliżyła się armia mamelucka, opuścili zamek morski i uciekli na Cypr, a miasto w to samo lato przeszło w ręce mameluków. Bejrut, od 1197 w rękach krzyżowców, został w 1291 zdobyty przez namiestnika Damaszku Sencera aş-Şücâîego. W ten sposób dwuwiekowa obecność krzyżowców została wymazana z wybrzeża Syrii i Palestyny.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Zdobycie Bileciku i Yarhisar nocnym napadem", "f461b0af"], "d": ["Hasło TDV Bilecik: „Choć inni tekfurzy regionu, wśród nich tekfur Bileciku, przygotowali zamach na Osmana Gazi, po wykryciu tego spisku siły osmańskie nagłym napadem zdobyły Yarhisar i Bilecik (1299).” Dwie twierdze zdobyto w jednej akcji, jednym nocnym napadem. Data ta jest punktem zwrotnym uznawanym za rok założenia państwa osmańskiego. W tym samym dniu przyłączono także inne miejscowości: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Bitwa pod Koyunhisar (Bafeusem) — pierwsze wielkie zwycięstwo nad armią bizantyjską", "584a9512"], "d": ["Hasło TDV Osman I: 27 lipca 1302 Osman Bej stoczył pod Bafeusem (Koyunhisar) bitwę z armią bizantyjską i ją pokonał. Zwycięstwo to jest punktem zwrotnym, który z regionalnego beja pogranicza wyniósł Osmana Beja do statusu założyciela dynastii. Po bitwie równina Bursy znalazła się pod kontrolą osmańską i rozpoczęła się blokada Nikei.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Zwycięstwo pod Dimbos i zajęcie Kite oraz Ulubatu", "e168ab64"], "d": ["Hasło TDV Osman I: w 702 (1303) sojusz utworzony przez tekfurów Bursy, Kestel, Kite i Adranos został rozbity w przełęczy Dimbos; wróg, walcząc, został cofnięty aż do wąskiego przesmyku, a tekfur Kestel poległ na polu bitwy. Zaraz po zwycięstwie zajęto twierdze Kite i Ulubat, odcinając lądowe połączenie Bursy i zacieśniając jej blokadę. Młody Orhan również uczestniczył w tej bitwie.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Wyprawa nad Sakaryę: zajęcie Leblebicihisar, Lefke, Mekece i Geyve", "a51ba4d3"], "d": ["Hasło TDV Osman I podaje kolejność wyprawy nad Sakaryę w 704 (1304): „Gdy przybył do Leblebüci Hisarı, tekfur okazał posłuszeństwo... Dotarł do Lefke... Doszedł do Mekece... Poszedł do Geyve i zajął twierdzę, którą zastał opuszczoną.” Lefke jest bramą doliny Sakaryi otwierającą się na Bilecik. Ta jedna wyprawa, oddając pod kontrolę osmańską łańcuch twierdz ciągnący się wzdłuż doliny, zamknęła wschodnie skrzydło basenu Nikei.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Chios przeszło pod kontrolę genueńskiego rodu Zaccaria", "9eebe4de"], "d": ["Wobec zagrożenia ze strony Aydınoğulları cesarz bizantyjski poprosił o pomoc Genueńczyka Benedetta Zaccaria; wyspa przeszła pod jego kontrolę (nominalna wasalność bizantyjska). Panowanie Zaccariów trwało do 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samos weszło we władanie Genueńczyków (Zaccaria) z Chios", "0e6f51e3"], "d": ["Genueński ród Zaccaria, który przejął kontrolę nad Chios, dołączył do swej własności także niemal opuszczone Samos (TDV: 1304–1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Zdobycie twierdz przełęczy Geyve: Karaçepüş, Karatigin i Absu", "76907c78"], "d": ["Hasło TDV Orhan: w wyprawie nad Sakaryę w 705 (1305) Orhan „zdobył twierdze Karaçepüş (Katoikia), Karatigin pod Nikeą i Absu (Hypsu: w przełęczy Geyve)”. Te trzy twierdze, zamykając przejście między doliną Sakaryi a basenem Nikei, całkowicie odcięły Nikeę od pomocy lądowej. W Karaçepüş i Absu w przełęczy Geyve osadzono Gazi Abdurrahmana; miasto mogło być odtąd zdobyte już tylko głodem.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Wyprawa na Adranos (Orhaneli) — ostatnia wyprawa Osmana Beja", "4811546c"], "d": ["Hasło TDV Orhan notuje wyprawę na twierdzę Adranos jesienią 1323 jako ostatnią wyprawę Osmana Beja. Tekfur Adranos był członkiem sojuszu tekfurów zawiązanego przeciw Osmanom dwadzieścia lat wcześniej pod Dimbos; wyprawa ta oznaczała zamknięcie tamtego rachunku. Dokładny dzień zdobycia twierdzy jest nieznany; działania kontynuował Orhan Bej.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Śmierć Osmana Gazi i objęcie bejliku przez Orhana Beja", "021487cd"], "d": ["Osman Gazi, od którego bejlik wziął nazwę, zmarł według świadectwa wakfów Asporça Hatun i Mekece w 724 (1324). Jego syn Orhan, który od 1305 stał na czele armii w wyprawach, objął bejlik po śmierci ojca bez żadnego sporu o tron. Bezwstrząsowe przekazanie sztandaru przez pokolenie założycieli pokazuje, że dynastia spokojnie przeszła pierwszy wielki sprawdzian na drodze od bejliku pogranicznego do państwa.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Odebranie Chios Zaccariom i związanie z Bizancjum", "f6741b26"], "d": ["Cesarz Andronik III oddalił Zaccariów z wyspy i związał wyspę z Bizancjum pod namiestnictwem Benedetta III. Wyspa miała zostać zajęta w 1346 przez Genueńczyka Simone Vignosi.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samos wróciło od Zaccariów do Bizancjum (łańcuch Chios)", "08034974"], "d": ["Wraz z upadkiem panowania Zaccariów (związanie Chios z Bizancjum w 1329) skończyła się także genueńska własność na Samos.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Bitwa pod Pelekanonem (Maltepe) i zajęcie całego Kocaeli", "389e7bd4"], "d": ["Hasło TDV Orhan: pierwszego dnia bitwy Orhan Gazi wysłał trzystuosobowy oddział, by ściągnąć na siebie armię bizantyjską; drugiego dnia, gdy oddziały pod dowództwem Pazarlu zeszły na równinę, bitwa się rozszerzyła, a gdy cesarz został ranny strzałą, w armii bizantyjskiej wybuchła panika. Wynik jest rozstrzygający: „Orhan zajął całe Kocaeli; po zwycięstwie mieszkańcy Nikei nie mieli już żadnej nadziei.” Miasteczka przybrzeżne od Hereke po Üsküdar weszły pod panowanie osmańskie, a Gebze uczyniono ośrodkiem regionu. Była to ostatnia cesarska armia bizantyjska, która przybyła na ratunek Stambułowi.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Założenie pierwszej medresy osmańskiej w Nikei", "c85fb625"], "d": ["Orhan Bej, zaraz po zajęciu Nikei, mianował tu kadiego Çandarlı Kara Halila, przekształcił bazylikę w meczet i, kazawszy obok niego zbudować imaret i medresę, rozpoczął odbudowę miasta. Według hasła TDV o Dâvûd-i Kayserî budowę medresy ukończono w 1336, a Orhan Gazi sprowadził Dâvûd-i Kayserîego na stanowisko profesora z dziennym uposażeniem 30 akçe. Medresa ta jest pierwszym instytucjonalnym krokiem osmańskiego życia naukowego; bejlik obok siły zdobywczej dodał tradycję nauki. Przekształcenie zdobytej stolicy bizantyjskiej w ośrodek nauki islamu było pierwszym konkretnym znakiem osmańskich pretensji do bycia państwem osiadłym.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Objęcie Bizancjum daniną — oblężenie İzmitu i układ", "0c1ec8d3"], "d": ["Hasło TDV Orhan: latem 733 (1333) Orhan oblegał İzmit ogromną armią i machinami miotającymi, a cesarz zgodził się na układ. W zamian za zaniechanie oblężenia Bizancjum zgodziło się płacić Orhanowi rocznie 12 000 złotych (hyperpyrów); „w ten sposób w oczach emira osmańskiego Bizancjum znalazło się w położeniu kraju płacącego daninę”. W zamian Orhan miał być przyjacielem cesarza i nie atakować miast zależnych od Bizancjum. Obłożenie podatkiem Wschodniego Rzymu przez bejlik pograniczny było oznajmieniem, jak bardzo obrócił się układ sił.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samotraka przeszła od Wenecjan do genueńskiego rodu Gattilusio", "c499ed5f"], "d": ["Genueński ród Gattilusio wypędził z wyspy Wenecjan, którzy trzymali ją od 1204.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Aneksja Bejliku Karesi: Balıkesir, Bergama, Biga, Edremit i Erdek", "c7cb0511"], "d": ["Hasło TDV Orhan (İnalcık) umieszcza aneksję w 735 (1334–35): po śmierci Demirhana Beja gazi z Karesi i Hacı İlbey zaprosili Dursuna Beja na tron i poprosili Orhana o pomoc. Orhan ruszył najpierw na Balıkesir; gdy Dursun Bej, idący na rokowania pokojowe, zginął od strzały wypuszczonej z twierdzy Bergama, bejlik został w całości przyłączony do ziem osmańskich. W tej samej akcji Kirmasti i Mihaliç okazały posłuszeństwo, zajęto Gölyazı, a Ulubat, wcześniej pozostawiony na mocy zapewnienia, został ostatecznie zdobyty. Orhan mianował do sandżaku Karesi Süleymana Paszę i uczynił Biga ośrodkiem pogranicznym — w ten sposób zdobyto morskie kadry dla przejścia do Rumelii. Uwaga: hasło TDV o Karesioğulları podaje dla tego samego wydarzenia datę 746 (1345); encyklopedia jest sama ze sobą sprzeczna. W tym samym dniu przyłączono także inne miejscowości: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samos weszło we władanie Maony Chios", "01628b2f"], "d": ["Gdy Genueńczyk Simone Vignosi zajął Chios, a zarząd pozostawiono spółce Maona, Samos również weszło we własność Genueńczyków (Maona) z Chios (TDV: 1346–1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Pierwsze kapitulacje Orhana Gazi z Genueńczykami", "e64cb196"], "d": ["Orhan Gazi, który podczas wojny wenecko-genueńskiej porozumiał się z Genueńczykami, po bitwie w cieśninie w lutym 1352 wysłał do obrony Pery 1000 łuczników i dostarczył 60 000 złotych na przewóz żołnierzy; w zamian nadał Genueńczykom pierwsze kapitulacje. Pełny tekst układu nie dotrwał do naszych czasów. Jest to pierwszy oficjalny układ Osmanów z europejską potęgą morską i miał zostać odnowiony po trzydziestu pięciu latach, w 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Zajęcie Gallipoli — trwały przyczółek w Rumelii", "ba51a160"], "d": ["Gallipoli, które Osmanowie poznali w latach 1349–1352 jako sojusznicy Kantakuzena, zajęli w 1354; okazję stworzyło wielkie trzęsienie ziemi, które zburzyło mury miasta. Wąski przyczółek w Çimpe stał się w ten sposób prawdziwą bazą na rumelijskim brzegu cieśniny, a brama otwierająca się na Trację została szeroko uchylona. Gallipoli miało zostać utracone w 1366 wskutek wyprawy krzyżowej sabaudzkiej, lecz w drugim zdobyciu w 1376 miało ostatecznie wejść pod panowanie osmańskie. W tym samym dniu przyłączono także inne miejscowości: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Śmierć zdobywcy Rumelii Süleymana Paszy", "2dc98228"], "d": ["Süleyman Pasza, najstarszy syn Orhana Beja i architekt zdobyczy w Rumelii, zmarł jesienią 1357, spadłszy z konia podczas polowania, co jest najszerzej przyjętą z dat podawanych w źródłach jako 758 (1357), 759 i 760 (1359). Śmierć księcia, który swymi przeprawami z lat 1352–1354 ustanowił trwałą obecność osmańską w Rumelii, zostawiła kolej sukcesji jego bratu Muradowi. Mauzoleum Süleymana Paszy pochowanego w Bolayırze pozostało najstarszym pomnikiem dynastii osmańskiej w Europie.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Prawo pençik — położenie podwalin pod korpus janczarów", "e5877c2d"], "d": ["Po zdobyczach w Rumelii, za radą uczonego Karamanlı Kara Rüstema, wprowadzono system pençik, przewidujący przeznaczenie dla państwa jednej piątej jeńców wojennych lub jej równowartości w pieniądzach. Dzięki temu, że wybranych spośród tych jeńców wychowywano w rodzinach tureckich i wcielano do wojska, powstał zalążek stałej piechoty podległej bezpośrednio sułtanowi — korpusu janczarów. Przemiana bejliku pogranicznego opartego na konnicy plemiennej w państwo z armią centralną rozpoczęła się od tego rozporządzenia.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Zejście do Tracji Zachodniej: zdobycie Gümülcine", "9ef69221"], "d": ["Siły pograniczne, które po zdobyciu Edirne zwróciły się na zachód od Maricy, zajęły pod dowództwem Gazi Evrenosa Beja Gümülcine, ośrodek Tracji Zachodniej. Miasto stało się wysuniętą kwaterą, z której Evrenos Bej miał przenosić swe napady na Macedonię. W ten sposób odcinek Tracji sięgający wybrzeża Morza Egejskiego znalazł się pod kontrolą osmańską i otwarto drogę do Salonik.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Warna przeszła do Księstwa Dobrudży i została stolicą", "2bfe73f9"], "d": ["W procesie rozpadu Carstwa Bułgarskiego Warna nad Morzem Czarnym została przyłączona do Księstwa Dobrudży założonego przez Dobrotica i uczyniona stolicą tego małego państwa.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Na zachód od Płowdiwu: przyłączenie Tatarpazarcığı i İhtiman", "1664d0e1"], "d": ["Po zdobyciu Płowdiwu w 1372 Tatarpazarcığı w górnym krańcu doliny Maricy i İhtiman, trzymający przełęcz otwierającą się ku Sofii, zostały przyłączone do zarządu osmańskiego. Ta linia, pozostająca w rękach lokalnych bejów, którzy stali się wasalami po bitwie pod Çirmen, została przeniesiona pod zarząd bezpośredni, a szlak Płowdiw–Sofia stał się nieprzerwany. To natarcie jest przygotowaniem drogi do zdobycia Sofii dwanaście lat później.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Bunt Savcı Beja — wspólne powstanie księcia i bizantyjskiego następcy tronu", "75198c33"], "d": ["Savcı Bej, syn Murada I, i Andronik Paleolog, syn cesarza bizantyjskiego Jana V, zbuntowali się równocześnie przeciw ojcom w Bursie i Stambule na początku maja 1373. Sojusz łączący następców tronu dwóch dynastii został szybko stłumiony; Savcı Bej został schwytany, oślepiony i stracony. Data 787 (1385) podawana przez przekaz osmański dla buntu jest błędna; wydarzenie przypada tuż po latach, w których Bizancjum weszło w wasalność osmańską, i pokazuje, jak bardzo splecione były oba pałace.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Doliny Strumy i Mesty: przyłączenie Köstendil, Petriç, Nevrokop i Drama", "8c0980c4"], "d": ["Doliny Strumy i Mesty, pozostające w rękach serbskich i bułgarskich lokalnych bejów, którzy po zwycięstwie pod Çirmen zaczęli płacić Osmanom daninę, zostały dzięki natarciu bejów pogranicznych objęte zarządem bezpośrednio osmańskim. Wraz z przyłączeniem Köstendil, Petriç, Nevrokop i Drama otwarto wschodnią połowę Macedonii, a Saloniki i Serez znalazły się w pierścieniu oblężenia. Na mapie rozszerzenie Rumelii ku południowemu zachodowi jest skutkiem tej akcji.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur zdobył Herat: koniec dynastii Kertów i przejście Chorasanu do Timurydów", "15f6019e"], "d": ["W 1380 Chorasan był rozdarty walką między Sarbadarami, Kertami i Muzaffarydami. Timur, wysławszy do regionu syna Mîrân Szaha, sam ruszył na Herat i po pewnym oblężeniu przyjął poddanie miasta od meliki Kertów Gıyâseddina Pîr Alego. Bunt, który wybuchł po jego odejściu, został krwawo stłumiony przez Mîrân Szaha, a dynastia Kertów, panująca w Heracie od 1255, dobiegła końca. Cały Chorasan od Meszhedu po Niszapur wszedł w tym czasie pod zarząd timurydzki.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Koniec Bejliku Eretna i założenie Państwa Kadı Burhâneddina", "60dcaf57"], "d": ["Eretnaoğulları, którzy powstali w 1335 z namiestnictwa ilchanidzkiego i przez czterdzieści sześć lat rządzili Anatolią Środkową z ośrodkami w Sivas i Kayseri, rozpadli się wskutek sporów wewnątrz pałacu. Kadı Burhâneddin, który w maju 1378 został wezyrem, po usunięciu rywali Kılıcarslana i Hacı Şadgeldiego ogłosił jesienią 1381 swój sułtanat, położył kres bejlikowi i założył państwo noszące jego imię. Wschodni sąsiad Osmanów zmienił w ten sposób właściciela; linia Sivas–Kayseri miała odtąd przez siedemnaście lat pozostawać w rękach Kadı Burhâneddina.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Natarcie w głąb Macedonii: zdobycie Monastyru i Ochrydy", "63bb7838"], "d": ["Monastyr na Via Egnatia i Ochryda nad jeziorem weszły pod zarząd osmański w czasie napadów w kierunku Albanii. Oba były kluczowymi punktami drogi sięgającej Adriatyku; Ochryda była ponadto najstarszym prawosławnym ośrodkiem arcybiskupim Bałkanów. TDV odnotowuje, że co do daty zdobycia Ochrydy nie ma pewnych informacji, że podaje się daty 787 (1385) i 797 (1395), po śmierci Marka Kraljevicia; tu przyjęto 1385. Monastyr miał w następnych stuleciach stać się jednym z najważniejszych ośrodków wojskowych Rumelii.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Bitwa nad Saurą — otwarcie bram Albanii", "dda6671b"], "d": ["Na wezwanie o pomoc albańskiego beja Karla Thopii, przyciśniętego przez dynastię Balszów, siły osmańskie rozbiły na równinie Saura armię Balszy II; Balsza poległ na polu bitwy. Bitwa, do której wkroczono na zaproszenie miejscowego beja, dała Osmanom pierwsze trwałe wpływy na ziemiach albańskich sięgających wybrzeży Adriatyku. Polityka wykorzystywania kłótni między bejami regionu miała w następnym stuleciu stać się niezmienną metodą zdobyczy bałkańskich.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["„Trzyletnia wyprawa” Timura: zajęcie Azerbejdżanu i Północnego Iranu", "2a98ec51"], "d": ["Timur, który podczas wypraw chorasańskich z bliska poznał rozdrobnienie Iranu, wyruszył na zachód w 788 (1386). W wyprawie 1386–1388, zwanej „trzyletnią”, przeszedł przez Mazandaran, Luristan i Gruzję do Azerbejdżanu i dotarł do Karabachu; Tabriz, Ardabil, Urmia i Nachiczewan weszły pod zarząd timurydzki. Opanowanie Północnego Iranu i Azerbejdżanu stało się też, jak niegdyś między ulusem Dżocziego a Ilchanami, początkiem długiego sporu ze Złotą Ordą.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Bitwa pod Frenkyazısı i oblężenie Konyi — pierwsza wyprawa na Karaman", "af4e5d77"], "d": ["Murad I osobiście wyruszył na wyprawę przeciw Karamanoğlu Alâeddinowi Alemu Bejowi, który mimo że był jego zięciem, niepokoił się osmańską ekspansją w Anatolii Zachodniej; w bitwie stoczonej na miejscu zwanym Frenk Yazısı wyszkolona i doświadczona armia osmańska pokonała siły karamańskie. Następnie oblężono twierdzę Konya, lecz wskutek ułaskawienia Alâeddina Beja bejlik nie został całkowicie zlikwidowany. Wyprawa ta jest otwierającym aktem długiego rozrachunku między Osmanami a Karamanem, który miał trwać stulecie i zakończyć się ostateczną aneksją dopiero w 1468.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Muş przeszło od zarządu Karakoyunlu pod zarząd Timura (789/1387)", "ed2e7a11"], "d": ["Muş, które po epoce mongolskiej przeszło pod zarząd Karakoyunlu, weszło w 789 (1387) pod zarząd Timura, który posiadał ziemie Karakoyunlu. W atlasie Muş jest zapisane w tym roku jako przechodzące od Karakoyunlu do Timurydów.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Założenie stoczni w Gallipoli — narodziny floty osmańskiej", "47546241"], "d": ["Pierwszą zorganizowaną stocznię państwa osmańskiego założył w 1390 Bayezid Błyskawica w Gallipoli, w miejscu stoczni pozostałej po Bizancjum. Osmanowie, przejmując morskie dziedzictwo bejlików Anatolii Zachodniej, stali się w ten sposób po raz pierwszy potęgą morską budującą własne okręty. Stocznia, położona w kluczowym punkcie Dardaneli, pełniła przez półtora stulecia rolę głównej bazy floty osmańskiej, od oblężenia Stambułu po wyprawy egejskie.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Prowincja Hamîd przyłączona do Osmanów: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Bayezid Błyskawica, który po napaści Karamanoğlu Alâeddina Beja na prowincję Hamîd i skargach ludności wyruszył na wyprawę, zajął całość pozostałych ziem Hamîdoğulları i oddał ich zarząd synowi İsie Çelebiemu.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Koniec dynastii Muzaffarydów: klęska Szacha Mansûra pod Szirazem", "5fd14eb8"], "d": ["Szach Mansûr, ostatni silny władca Muzaffarydów, którzy od 1318 panowali w Jazd, Fars, Isfahanie i Kirmanie, połączył siły z krewnymi i wystąpił przeciw Timurowi. W bitwie pod Szirazem, gdy jeden z jego emirów przeszedł na stronę przeciwną, stracił większość sił, został pokonany i zabity. Gdy Timur kazał następnie zabić wszystkich członków dynastii, panowanie Muzaffarydów dobiegło końca, a Fars i Kirman przyłączono do zarządu timurydzkiego.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Przyłączenie Amasyi do ziem osmańskich", "fe2860cf"], "d": ["Emir Amasyi, oblężonej w czasie kampanii Bayezida Błyskawicy w Anatolii Środkowej, oddał miasto Osmanom i Bayezid wkroczył doń w 1393. Sułtan zostawił zarząd nad miastem synowi Mehmedowi Çelebiemu; Amasya jako sandżak książęcy stała się odtąd jednym z najważniejszych ośrodków wychowania dynastii osmańskiej. Ten wybór miał okazać się rozstrzygający w późniejszym Interregnum, a Çelebi Mehmed miał prowadzić walkę o ponowne zjednoczenie państwa właśnie z bazy w Amasyi.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur zdobył Bagdad — Dżalajirydzi uciekli do Anatolii", "4d5602b3"], "d": ["Timur po długim oblężeniu zajął Bagdad; władca miasta, dżalajirydzki sułtan Ahmed, uciekł na zachód i schronił się najpierw u mameluków, potem na dworze osmańskim. Ekspansja Timura na zachód po raz pierwszy zetknęła się w ten sposób bezpośrednio ze strefą wpływów osmańskich. Stąd zaczyna się pierwsze ogniwo wrogości między dwoma władcami.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Zajęcie Warny nad Morzem Czarnym", "a84b2abf"], "d": ["W czasie ściskania ziem Carstwa Bułgarskiego między Dunajem a Morzem Czarnym Warna, największy port na wybrzeżu, przeszła pod zarząd osmański. Zajęcie portu otworzyło drogę natarciu w kierunku Dobrudży i dało Osmanom pierwszą wielką przystań na zachodnim wybrzeżu Morza Czarnego. Warna miała też być sceną zwycięstwa z 1444, w którym pięćdziesiąt jeden lat później zniszczono armię krzyżowców.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Okolice Nevşehir i Ürgüp przeszły od Karamanoğulları w ręce osmańskie", "06ff59e8"], "d": ["W wyprawach Bayezida Błyskawicy przeciw Karamanoğulları okolice Nevşehir (Muşkara) i Ürgüp przeszły w 800/1398 pod zarząd osmański; w 1402, po bitwie pod Ankarą, Timur zwrócił region Karamanoğulları.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Upadek Państwa Kadı Burhâneddina", "b13391e3"], "d": ["Kadı Burhâneddin, który dostał się do niewoli władcy Akkoyunlu Karayülüka Osmana Beja, zaproponował wypuszczenie w zamian za poddanie Sivas, lecz mieszkańcy miasta stawili opór, a sułtana stracono przed murami. Choć notable Sivas wprowadzili na tron jego syna Alâeddina Alego Çelebiego, wobec nacisku Akkoyunlu poprosili o pomoc Bayezida Błyskawicę; siły osmańskie pod dowództwem Süleymana Çelebiego pokonały Karayülüka i opanowały miasto. W ten sposób Państwo Kadı Burhâneddina przeszło do historii, a Sivas, Tokat, Niksar i Kayseri przyłączono do ziem osmańskich. W tym samym dniu przyłączono także inne miejscowości: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Przeciąganie liny przez Timura: odrzucenie wydania zbiegów", "33790bc8"], "d": ["Pod naciskiem Timura dżalajirydzki sułtan Ahmed i przywódca Karakoyunlu Kara Yûsuf schronili się na ziemiach osmańskich; Timur zażądał wydania tych dwóch zbiegów, a Bayezid Błyskawica odmówił. Wtedy między dwoma władcami zaczęto wymieniać listy pełne wzajemnych ciężkich obelg. Ideologiczny grunt wojny został założony tą korespondencją, zanim jeszcze ruszył jakikolwiek żołnierz.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Dârüşşifâ Błyskawicy w Bursie — pierwszy szpital osmański", "5f0dc59a"], "d": ["Bayezid Błyskawica, w latach, gdy kazał zbudować w Bursie wspaniały Wielki Meczet, podarował miastu także dârüşşifâ; było to ogniwo przeznaczone dla medycyny w obszernym programie dzieł dobroczynnych, obejmującym imaret, medresę, han i most. Ta budowla, pierwszy szpital założony przez państwo, pełniąc też funkcję szkoły medycznej kształcącej lekarzy, wyznaczyła model osmańskich instytucji zdrowotnych. Dzieło ukończone zaledwie dwa lata przed katastrofą pod Ankarą należy do ostatnich ogniw wizji Błyskawicy przekształcenia Bursy w stolicę imperium.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur zrównał Sivas z ziemią", "f4d79de6"], "d": ["Timur, który pod przewodnictwem Karayülüka Osmana Beja z Akkoyunlu i emira Erzincan Mutahhartena pomaszerował na Sivas, oblegał miasto osiemnaście dni i po przyjęciu poddania z obietnicą, że niczyja krew nie zostanie przelana, dokonał wielkiej rzezi; obrońców kazał wrzucić do rowów i zasypać żywcem. Zniszczono ważne dzieła miasta, na czele z murami, a Sivas załamało się demograficznie. Jest to pierwszy wielki cios, który Timur zadał ziemiom osmańskim na dwa lata przed bitwą pod Ankarą.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bayezid Błyskawica odzyskał Erzincan i Kemah", "7047ca08"], "d": ["Bayezid Błyskawica, wykorzystując wyjście Timura na wyprawę syryjską, odebrał Erzincan i Kemah emirowi Erzincan Mutahharteneowi, zależnemu od Timura. Choć nie interweniował przy zniszczeniu Sivas, ten ruch oznaczał bezpośrednie rzucenie wyzwania sferze wpływów Timura we Wschodniej Anatolii. Stosunki między dwoma władcami były odtąd nie do naprawienia.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatum Timura z Tabrizu — cztery warunki", "3e1ac50e"], "d": ["Timur przez posła wysłanego z Tabrizu ogłosił cztery warunki: zwrot Kemah Mutahharteneowi, zwrócenie właścicielom ziem odebranych bejom anatolijskim, wysłanie jako zakładnika osmańskiego księcia oraz przyjęcie czapki i pasa jako znaku poddaństwa, wydanie Kara Yûsufa. Bayezid nie przyjął żadnego z nich; mimo nalegań mężów stanu i pośrednictwa Mutahhartena rokowania się załamały. Timur był zdecydowany przed wyprawą do Chin ostatecznie zamknąć sprawę Anatolii.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Odtworzenie Saruhanoğulları — Manisa wychodzi z rąk osmańskich", "ac747b05"], "d": ["Trzy tygodnie po klęsce pod Ankarą Orhan Bej z poparciem Timura stanął na czele bejliku i prowincja Saruhan odzyskała niepodległość. Region z ośrodkiem w Manisie zniknął z mapy dwanaście lat po osmańskiej aneksji z 1390. Jest to jedno z pierwszych o dokładnie znanej dacie zastosowań polityki Timura odtwarzania bejlików.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Süleyman uciekł do Rumelii ze skarbem państwa", "0a2b7363"], "d": ["Emir Süleyman, zabrawszy ze sobą skarb państwa w Bursie, archiwa, rodzinę i braci, przeprawił się okrętem z Gemlik do Güzelcehisar (Anadoluhisarı), stamtąd dotarł do Gallipoli i ogłosił w Edirne swoje panowanie. Przeniesienie archiwum państwowego i skarbu do Rumelii jest początkiem przesunięcia osmańskiego środka ciężkości na Bałkany na jedno pokolenie. Na mapie Rumelia od tej daty jest rysowana kolorem samego emira Süleymana.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur odtworzył bejliki anatolijskie — rozpad jedności tureckiej", "15187774"], "d": ["Timur po zwycięstwie pod Ankarą zwrócił będącym przy nim bejom ich dawne ziemie. Karamanoğlu Mehmedowi i Alemu Bejom przyznano prowincję Karaman oraz Kayseri, Kırşehir, Sivrihisar i Beyşehir; Germiyanoğlu Yâkubowi Bejowi II — Kütahyę i prowincję Germiyan; Candaroğlu İsfendiyarowi Bejowi, oprócz linii Kastamonu–Synopa, Çankırı i Kalecik. Prowincje Aydın, Menteşe i Teke wróciły także do dawnych dynastii. Jedność turecka Anatolii, zbudowana przez Bayezida Błyskawicę w dziesięć lat, rozpadła się w jedno lato; na mapie te bejliki pojawiają się ponownie w swoich kolorach.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur zdobył Izmir od joannitów", "66dd1dd4"], "d": ["Timur, który przez Kütahyę, Denizli, Aydın, Ayasuluk i Tire zszedł na zachód, oblegał i zdobył nadmorski Izmir, od 1344 pozostający w rękach chrześcijan. Twierdzę, której Bayezid Błyskawica przez lata nie mógł zdobyć, Timur zajął w krótkim czasie, a zająwszy także okoliczne twierdze, zostawił prowincję Aydın dawnym właścicielom i zawrócił na wschód. Miasto weszło odtąd pod zarząd Aydınoğlu Cüneyda Beja.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Îsâ Çelebi zajął Bursę — narodził się dział anatolijski", "955128c1"], "d": ["Îsâ Çelebi, który po klęsce pod Ankarą wycofał się w okolice Karesi, zajął Bursę, gdy Timur był w Izmirze. W dawnej stolicy, złupionej i spalonej przez żołnierzy Timura, ogłosił swoje panowanie i kazał bić monetę w swoim imieniu; w styczniu 1403 był w Anatolii uznawany jako „władca Turków”. Na mapie ten dział wzdłuż azjatyckiego wybrzeża Marmary jest pokazany kolorem samego Îsâ Çelebiego.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Wycofanie się Timura z Anatolii", "93a98839"], "d": ["Timur, otrzymawszy wiadomość o śmierci Bayezida Błyskawicy w Akşehir, uznał swą sprawę w Anatolii za skończoną i zwrócił się na wschód. Zostawił za sobą bejliki deklarujące mu wierność oraz zwaśnionych książąt osmańskich; niektóre miasta, takie jak Sivas, zostały pozostawione w rękach emirów zależnych od Timura, podobnych do Mezida Beja. Timur do Anatolii już nie wrócił, lecz ten rozdrobniony ład, który ustanowił, trwał dziesięć lat.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Süleyman przeszedł do Anatolii: Bursa wpadła w jego ręce", "9b27aa5f"], "d": ["Emir Süleyman, który usłyszał o klęsce Îsâ Çelebiego, przeszedł z silną armią do Anatolii wraz z Çandarlı Alim Paszą i zajął Bursę; zapisy z marca 1404 wskazują, że także Karadeniz Ereğli było pod jego zarządem. Çelebi Mehmed nie zdołał się oprzeć Süleymanowi, który w krótkim czasie zapanował nad Rumelią i większą częścią Anatolii. Na mapie od tej daty aż do ponownego zajęcia Bursy przez Çelebiego Mehmeda (1410) oba brzegi pokazane są jednym kolorem, w dziale emira Süleymana.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Bitwa na równinie Yenişehir — Çelebi Mehmed wycofał się do Amasyi", "f1568288"], "d": ["Çelebi Mehmed, który stracił Bursę i Ankarę, został pokonany na równinie Yenişehir przez emira Süleymana, utracił wszystkie zdobycze w Anatolii Zachodniej i wycofał się do bazy Tokat–Amasya. Po tej klęsce unikając bezpośredniego starcia, zwrócił się ku umacnianiu władzy w głębi Anatolii. Tak rozpoczęła się najdłuższa cicha faza Interregnum.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Süleyman zajął Ankarę Çelebiemu Mehmedowi", "d6a2acd6"], "d": ["Ankarę, która po wycofaniu się Timura z Anatolii pozostała w rękach Çelebiego Mehmeda, oblegał w 1406 emir Süleyman. Komendant twierdzy Yâkub Bej przez jakiś czas się opierał, lecz podstępem wielkiego wezyra Çandarlı Alego Paszy oddał twierdzę Süleymanowi. Wówczas Çelebi Mehmed, porozumiawszy się z Karamanoğlu Mehmedem Bejem, wystąpił przeciw Süleymanowi.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed odzyskał Sivas od timurydzkiego Mezida Beja", "90079b0c"], "d": ["Po najeździe Timura zarząd Sivas pozostawiono Mezidowi Bejowi, zależnemu od Timura. Çelebi Mehmed z Amasyi wysłał swego dowódcę Bayezida Paszę, by zajął miasto, i po zaciętym oporze Sivas po raz drugi wpadło w ręce dynastii osmańskiej. W ten sposób dział Mehmeda osiągnął sześć lat po bitwie pod Ankarą swą dawną granicę na wschodzie.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Koniec dynastii Artukidów: poddanie Mardinu Karakoyunlu", "15b06f33"], "d": ["Artukidzi, panujący w Mardinie od 1106 i będący najdłużej trwającą gałęzią dynastii, nie utrzymali się wobec nacisku Akkoyunlu. Melik Ahmed, zrozumiawszy, że nie obroni miasta, porozumiał się z władcą Karakoyunlu Kara Yûsufem i oddał mu Mardin. Panowanie Artukidów, trwające ponad trzy wieki, dobiegło w ten sposób końca; Mardin i okolice były sceną walki Karakoyunlu z Akkoyunlu, aż po stuleciu przeszły do Osmanów.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Bitwa pod Yambol — Mûsâ Çelebi wkroczył do Edirne", "8f978408"], "d": ["Mûsâ Çelebi, który przeszedł do Rumelii przez Wołoszczyznę, rozbił pod Yambol siły emira Süleymana z poparciem wołoskim i serbskim i wkroczył do Edirne. W czasie Interregnum Rumelia po raz pierwszy wyszła z rąk emira Süleymana. Jego panowanie nie było jednak trwałe; po czterech miesiącach, pokonany pod Kosmidion, miał wycofać się w głąb Bałkanów.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Bitwa pod İnceğiz — pierwsza porażka Çelebiego Mehmeda w Rumelii", "3c35cd43"], "d": ["Çelebi Mehmed, który przeprawił się do Rumelii okrętami bizantyjskimi, stoczył pod İnceğiz bitwę z Mûsâ Çelebim; Mûsâ pokonał Mehmeda siedmioma tysiącami janczarów i Mehmed musiał wrócić do Anatolii. Ta klęska skierowała Mehmeda ku strategii przeciągnięcia na swoją stronę bejów pogranicznych Rumelii i serbskiego despotatu zamiast bezpośredniej walki. Grunt pod zwycięstwo pod Çamurlu po dziewięciu miesiącach przygotowano tą dyplomacją.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Oblężenie Konyi i układ z Karamanoğulları — odzyskano Hamîd-ili, Said-ili, Beyşehir, Seydişehir i Akşehir", "0996257e"], "d": ["Çelebi Mehmed zorganizował wielką wyprawę przeciw Karamanoğulları, którzy w czasie Interregnum napadli na ziemie osmańskie oraz oblegali i spalili Bursę, i oblegał Konyę w muharremie 818. Karamanoğlu Mehmed Bej II musiał prosić o pokój; w wyniku układu Hamîd-ili (okolice Isparty) i Said-ili zostały ponownie przyłączone do ziem osmańskich, zwrócono też Beyşehir, Seydişehir i Akşehir; Sivrihisar, który Timur dał Karamanoğulları w 1402, wrócił do Osmanów. Wyprawa ta, w której zaczęła się łatać jedność Anatolii rozbita bitwą pod Ankarą, jest jednym z konkretnych powodów uznawania Çelebiego Mehmeda za „drugiego założyciela”.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Zajęcie Izmiru od Aydınoğlu Cüneyda Beja", "2377ca51"], "d": ["Izmir, ośrodek Aydınoğlu Cüneyda Beja, który w czasie Interregnum stale zmieniał strony między książętami, został po dziesięciodniowym oblężeniu zdobyty przez Çelebiego Mehmeda; Cüneyd został ułaskawiony i wysłany do sandżakbejlika Nikopolis. Miasto zwrócone przez Timura w 1402 Aydınoğullarom wróciło w ten sposób po trzynastu latach do Osmanów. Cüneyd miał ponownie zająć miasto w 1422, a sprawę zamknął dopiero w latach 1424–1426 Murad II.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Stracenie Torlaka Kemala — Saruhan ostatecznie osmański", "8a09dbf1"], "d": ["Torlak Kemal, który prowadził zachodnioanatolijską gałąź ruchu szejcha Bedreddina, został pokonany w okolicach Manisy i stracony. Od tej daty region Saruhan ostatecznie wszedł pod kontrolę osmańską, a odtworzony przez Timura w 1402 bejlik przeszedł do historii. Ostatnie polityczne resztki Interregnum w Anatolii Zachodniej zostały w ten sposób oczyszczone.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Zdobycie Wlory, Beratu i Kaninë", "1e1949b8"], "d": ["Osmanowie w 1417 objęli swoim panowaniem Wlorę nad Adriatykiem wraz z położonym w głębi kraju miastem Berat i twierdzą Kaninë. Po roku próba odzyskania miasta przez Wenecję się nie powiodła, utworzono tu organizację sandżaku i władza osmańska się utrwaliła. Zajęcie Wlory dało Osmanom po raz pierwszy bezpośredni port na Adriatyku, a tym samym zamorski trampolinę wobec Włoch.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Odzyskanie Anatolii Środkowej: Kayseri i Kırşehir", "204eacb3"], "d": ["Miasta Anatolii Środkowej, które w czasie Interregnum wpadły w ręce Karamanoğulları, wróciły pod zarząd osmański podczas wypraw Çelebiego Mehmeda mających na celu odbudowę państwa. Wraz z przyłączeniem Kayseri i Kırşehir w dużej mierze odzyskano dorzecze Kızılırmaku utracone w bitwie pod Ankarą. To natarcie jest ciągiem polityki zwrotu ku wschodowi, zapoczątkowanej oblężeniem Konyi cztery lata wcześniej.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Mamelucy oddali Kayseri Dulkadırlı Nâsırüddinowi Muhammedowi", "aad4b00c"], "d": ["Armia mameluków, wyruszywszy na wyprawę przeciw Karamanoğlu Mehmedowi Bejowi, zajęła Kayseri; dowódca mamelucki zostawił miasto i okolice Dulkadırlı Nâsırüddinowi Muhammedowi i wrócił do swego kraju.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Śmierć Mehmeda I i wstąpienie na tron Murada II", "98acac77"], "d": ["Mehmed I, który zakończył Interregnum i ponownie zjednoczył ziemie osmańskie w jednym ręku, zmarł 25 czerwca 1421 w Edirne, a jego syn Murad wstąpił na tron w Bursie. Według układu zawartego z Bizancjum przed jego śmiercią młodsi synowie mieli zostać wysłani jako zakładnicy do cesarza, a cesarz nie miał wypuścić pretendenta do tronu Mustafy Çelebiego, którego trzymał; Murad II odmówił wysłania braci do cesarza.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Ostateczna likwidacja Tekeoğulları: zajęcie Antalyi", "e65565b2"], "d": ["Bejlik Tekeoğulları, odtworzony po bitwie pod Ankarą przez Timura, dobiegł końca, gdy siły osmańskie pod dowództwem Hamzy Beja oblegały Antalyę; usunięto ostatniego ważnego męża beyliku, Osmana Çelebiego. W ten sposób prowincja Teke nad Morzem Śródziemnym została po dwudziestojednoletnim oddzieleniu ostatecznie przyłączona do Osmanów. Bejlik jako gałąź oddzielona od Hamîdoğulları panował w Antalyi od 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Wyprawa Turahana Beja do Morei i zburzenie muru Hexamilion", "c6c2706d"], "d": ["Gdy Bizancjum poparło konkurencyjnego pretendenta do tronu Mustafę Çelebiego, Murad II wysłał Turahana Beja na Moreę. Turahan Bej, zburzywszy mur Hexamilion zamykający od końca do końca przesmyk Koryntu, wkroczył na półwysep i dokonał wielkich zniszczeń. Pokój zawarto pod warunkiem, że mur nie zostanie ponownie zbudowany i że będzie płacony roczny podatek; despotat Morei został w ten sposób pozbawiony obrony wojskowej, a grunt pod ostateczne zdobycie z 1460 przygotowano na trzydzieści siedem lat wcześniej.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Objęcie klasztorów Athos protekcją osmańską", "562de5ea"], "d": ["W latach oblężenia Salonik republika klasztorna Athos na wschodnim palcu Chalkidiki zwróciła się do Murada II o protekcję i uznała panowanie osmańskie. Zagwarantowano mnichom prawa własności i kultu; klasztory pozostawiono w zamian za podatek swobodne w sprawach wewnętrznych. Ten ład stał się najtrwalszym przykładem stosunku protekcji, jaki Osmanowie nawiązali z instytucjami prawosławnymi, i trwał pięć stuleci.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Aneksja Bejliku Tâceddinoğulları: Niksar", "370ffd47"], "d": ["Pod naciskiem beylerbeja Amasyi Yörgüça Paszy Tâceddinoğlu Hüsâmeddin Hasan Bej oddał w 830 (1427) klucze swego kraju z ośrodkiem w Niksarze; otrzymał sandżak w Rumelii. Bejlik założony w drugiej połowie XIV wieku, którego granice sięgały czasem Kelkit, Amasyi, Samsun, Ordu i Giresun, w ten sposób dobiegł końca. W tym samym roku ziemie należące do Hacıemiroğulları zostały także objęte tahrirem i przyłączone do sandżaku Canik; epoka bejlików na środkowym wybrzeżu Morza Czarnego się zamknęła.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Oddanie Belgradu Węgrom — traktat w Tata", "62481183"], "d": ["Po śmierci serbskiego despoty Stefana Lazarevicia, zgodnie z traktatem w Tata między królem węgierskim Zygmuntem a następcą Đurađem Brankoviciem, twierdza Belgrad została przekazana Węgrom. Twierdza, stojąca u zbiegu Dunaju i Sawy, była do tej pory w rękach despotatu serbskiego i dla Osmanów stanowiła zamek zamykający bramę otwierającą się na Europę Środkową. To przekazanie uczyniło z Belgradu na sto lat najsurowszą przeszkodę dla osmańskiego natarcia: oblężenia z 1440 i 1456 miały się nie udać, a twierdza miała upaść dopiero w 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin przeszedł od załogi Karakoyunlu do Karayülüka Osmana Beja z Akkoyunlu", "d82bc97f"], "d": ["Mardin, zajęty przez Kara Yûsufa w 1409, był zarządzany przez namiestników Karakoyunlu; Emîr Nâsır, pozostawiony jako komendant, oddał miasto w 835 (1432) Karayülükowi Osmanowi Bejowi z Akkoyunlu. Zarząd Akkoyunlu trwał do początku XVI wieku.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Karamanoğulları zabrali Kayseri Dulkadırlım", "2b09e8e8"], "d": ["Bej Karamanu, dzięki zwycięstwu nad Dulkadırlı, przyłączył do swego kraju Kayseri, Ürgüp, Develi Karahisârı i Uçhisar.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Wydarzenie na Buçuktepe — pierwszy bunt janczarów i powrót Murada II na tron", "6388dda1"], "d": ["Wydarzenie na Buçuktepe, pierwszy znany historii bunt janczarów, który wybuchł w Edirne, zaczęło się od żądania podwyższenia ich żołdu o pół akçe i zakończyło się detronizacją młodego Mehmeda II. Murad II w 8 safarze 850 pospiesznie wyruszył z Manisy i rozpoczął swoje drugie panowanie. Wydarzenie było pierwszym znakiem, że korpus kapıkulu stał się siłą mającą głos w sprawie tronu, i ukształtowało trwającą przez całe życie ostrożność Zdobywcy wobec janczarów.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Przyłączenie wybrzeża Epiru: Arta i Preweza", "796f7ecf"], "d": ["Dziewiętnaście lat po poddaniu się Janiny w 1430 Arta i Preweza w przybrzeżnej części despotatu Epiru weszły pod zarząd osmański. W ten sposób objęto kontrolą otwartą na Morze Jońskie zatokę Ambrakijską i dopełniono morskie połączenie Janiny. Preweza jest kluczowym punktem zatoki, która miała dziewięćdziesiąt lat później dać swoją nazwę słynnemu zwycięstwu Barbarossy.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Śmierć Murada II i drugie wstąpienie na tron Mehmeda II", "8f8256ad"], "d": ["Murad II, który zachorował po weselu syna, zmarł w Edirne 1 muharrema 855 (3 lutego 1451). Dziewiętnastoletni Mehmed II wstąpił na tron osmański po raz drugi 16 muharrema 855 (18 lutego 1451) — tym razem na stałe. Powrót młodego władcy, zdetronizowanego pięć lat wcześniej na Buçuktepe, jest początkiem panowania, które miało zostać ukoronowane dwa lata później zdobyciem Stambułu i przekształcić Bejlik Osmański w światowe imperium.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Pierwsze oblężenie Kafy przez połączone siły osmańsko-krymskie", "e346d163"], "d": ["Chan krymski Hacı Giray, który w czerwcu 1454 porozumiał się z sułtanem Mehmedem Zdobywcą, oblegał Kafę od strony lądu z 7000 jeźdźców; osmańska flota z pięćdziesięciu–sześćdziesięciu galer stanęła także na redzie. Genueńska Kafa zniosła oblężenie, płacąc daninę, a ostateczne zdobycie odłożono o dwadzieścia jeden lat, do 1475. Ta pierwsza wspólna akcja była pierwszym przykładem współpracy wojskowej osmańsko-krymskiej, który miał się powtórzyć przy ostatecznym zdobyciu Kafy.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Zajęcie wysp północnego Morza Egejskiego: Bozcaada, İmroz i Thasos", "76575895"], "d": ["Bezpośrednio po zdobyciu Stambułu sułtan Mehmed Zdobywca, by zabezpieczyć drogę morską nowej stolicy, zwrócił się ku wyspom u egejskiego wejścia do Dardaneli; Bozcaada i İmroz zostały zabrane Bizancjum, Thasos zaś rodowi Gattilusio genueńskiego pochodzenia. Wyspy zamykające oba brzegi cieśniny stały się odtąd pierwszym ogniwem linii zaopatrzenia i obrony Stambułu. Wskutek interwencji flot papieskiej i weneckiej panowanie przez pewien czas się chwiało i ostatecznie ustaliło się dopiero w 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Zdobycie Kosowa: zajęcie Prisztiny i Novi Pazaru", "d7ed2345"], "d": ["Armia osmańska, ruszająca na Despotat Serbski, zajęła Prisztinę na Kosowym Polu i Novi Pazar, ośrodek regionu Raszka; w tej samej akcji zdobyto także Novo Brdo, słynne ze srebrnych kopalń. W ten sposób południowa połowa Serbii została objęta bezpośrednim zarządem osmańskim, a despotat w Smederevie został odcięty od swoich ziem centralnych. To zdobycie było rozstrzygającym krokiem na drodze do całkowitej aneksji Serbii cztery lata później.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Peć (İpek) pod zarządem osmańskim — jeden z ośrodków sandżaku Dukakin", "19511588"], "d": ["W 1455, bezpośrednio po wyprawie serbskiej sułtana Mehmeda Zdobywcy, Peć, ośrodek patriarchatu serbskiego, przeszła pod zarząd osmański; w źródłach osmańskich nie ma zapisu o tym przejściu. Miasteczko z czasem stało się małym miasteczkiem muzułmańskim i jednym z miejsc rezydencji sandżakbeja w sandżaku Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Zdobycie Enez i Samotraki — dopełnienie wybrzeża Tracji Zachodniej", "106e723b"], "d": ["Enez u ujścia Maricy do morza zostało zajęte od rodu Gattilusio genueńskiego pochodzenia, który trzymał je od osiemdziesięciu lat; w tej samej akcji zdobyto też podległą mu wyspę Samotrakę. Wraz z upadkiem Enez pas przybrzeżny Tracji Zachodniej od Salonik po Gallipoli stał się nieprzerwaną ziemią osmańską. W rękach rodu Gattilusio pozostała jedynie Lesbos; i ona miała zostać zdobyta po sześciu latach.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Niepowodzenie oblężenia Belgradu", "3d53a604"], "d": ["Mehmed Zdobywca po zdobyciu Stambułu oblegał Belgrad, uchodzący za klucz do Europy Środkowej; jednak posiłki sprowadzone przez Jana Hunyadiego Dunajem i ochotnicy zebrani przez kaznodzieję krzyżowego Kapistrano uchroniły twierdzę przed upadkiem. Sułtan, mimo osobistego bohaterstwa okazanego przed oblężeniem, został ranny i musiał się wycofać. Ta porażka na sześćdziesiąt pięć lat zamknęła granicę z Węgrami przed osmańskim natarciem; Belgrad miał zostać zdobyty dopiero w 1521 przez Sulejmana.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Zdobycie północnej Morei: Patras (Balyabadra)", "c08a8509"], "d": ["Siły sułtana Mehmeda Zdobywcy, który w tych samych latach co aneksja Serbii zwrócił się ku despotatowi Morei, zajęły Patras (Balyabadra) w północno-zachodniej części półwyspu. Port ten, trzymający wejście do Zatoki Korynckiej, jest kluczem do lądowego wejścia do Morei; jego zajęcie przygotowało grunt pod ostateczne zdobycie dwa lata później. Miasto było ostatnim wielkim przystankiem, przez który despoci bizantyjscy utrzymywali łączność ze światem łacińskim.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Zajęcie zachodniego wybrzeża Morza Czarnego: Amasra", "f43608fc"], "d": ["Amasra, umocniona kolonia Genui na zachodnim wybrzeżu Morza Czarnego, poddała się bez oporu pod wspólnym naciskiem floty i sił lądowych Mehmeda Zdobywcy. Port ten na wybrzeżu Bartın–Zonguldak stał jako łacińska kieszeń między ziemiami Candaroğulları a ziemiami osmańskimi; jego zajęcie scaliło wybrzeże. Upadek Amasry jest pierwszym krokiem wielkiej wyprawy czarnomorskiej, która dwa lata później (1461) miała ruszyć na Synopę i Trapezunt.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Zdobycie wyspy Lesbos", "fe17aeba"], "d": ["Armia osmańska pod dowództwem sułtana Mehmeda Zdobywcy w zilhiddże 866 po krótkim, lecz gwałtownym oblężeniu zabrała Lesbos z rąk rodu Gattilusio genueńskiego pochodzenia i anektowała ją. Upadek największej wyspy północnego Morza Egejskiego zlikwidował też ostatnią ważną bazę Genueńczyków w regionie. Wyspa, dzięki bliskości wybrzeża Anatolii, miała odtąd pełnić dla floty osmańskiej funkcję wysuniętego posterunku, a zarazem wejść do historii żeglugi jako miejsce wychowania braci Barbarossa.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Początek szesnastoletniej wojny osmańsko-weneckiej", "563ddb68"], "d": ["Wenecjanie, by powstrzymać osmańskie natarcie w Morei i na Morzu Egejskim, zawarli sojusz z władcami Karamanu i Akkoyunlu i rozpoczęli wojnę w 1463. Strategia okrążenia ustanowiona z Uzunem Hasanem na wschodzie, Wenecją na zachodzie i Karamanem pośrodku zmusiła Zdobywcę do walki na wielu frontach naraz. Trwająca szesnaście lat walka obejmowała wszystkie wielkie akcje epoki, od Otlukbeli po wyprawy albańskie, i miała zakończyć się dopiero traktatem stambulskim z 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Zdobycie większej części Hercegowiny: Trebinje i Mostar", "f54c0100"], "d": ["Ziemie księcia Hercegowiny Stjepana Vukčicia-Kosača, który ustanowił zarząd odrębny od Bośni, w trzy lata po upadku Królestwa Bośni w znacznej mierze przeszły pod zarząd osmański: na południu Trebinje zostało zdobyte w 1466 „wraz z niemal całym regionem Hercegowiny”. Mostar, powstały wokół dwóch małych twierdz przy moście na Neretwie, musiał zostać zajęty nieco przed zdobyciem Blagaju, ośrodka Hercegowiny, w latach 1466–1468; w bośniackim rejestrze icmal z lat 1468–1469 figuruje pod nazwą „Köprülü Hisar”. Zdobycie Hercegowiny wraz z pozostałymi twierdzami księstwa zakończono w 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["II wyprawa albańska — osobisty marsz Zdobywcy na Skanderbega", "9cdd2bfa"], "d": ["Aby złamać trwający ponad ćwierć wieku opór Skanderbega, sułtan Mehmed Zdobywca zorganizował w latach 1466–1467 wielkie wyprawy, którymi dowodził osobiście. Armia osmańska oblegała Krujë i zbudowała twierdzę Elbasan, by opanować region. Wyprawa, choć złamała grzbiet albańskiego oporu, nie zdołała zdobyć twierdzy; pełne poddanie regionu miało nastąpić dopiero w dziesięć lat po śmierci Skanderbega.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Straż przednia Akkoyunlu zajęła od Karakoyunlu twierdzę Bingöl", "51b94cbc"], "d": ["W ostatnich tygodniach wyprawy Cihana Szacha przeciw Uzunowi Hasanowi straż przednia Akkoyunlu zdobyła twierdzę Bingöl; wraz z zabiciem Cihana Szacha 10 listopada 1467 panowanie Karakoyunlu w regionie się skończyło.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Upadek państwa Karakoyunlu: zabicie Cihan Szacha", "30bc6358"], "d": ["Cihan Szach, władca Karakoyunlu, który na wyprawie przeciw Uzunowi Hasanowi, wracając z powodu nadejścia zimy, został zaskoczony napadem, zginął podczas ucieczki między Bingöl a Kiğı. Po tym ciosie państwo się nie podniosło; ostatni władca Hasan Ali został w 1469 pojmany i zabity przez Uğurlu Mehmeda, syna Uzuna Hasana. Panowanie Karakoyunlu we Wschodniej Anatolii, Azerbejdżanie i Iraku, trwające blisko stulecie, przeszło w ten sposób na Akkoyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Śmierć Skanderbega — wygaśnięcie oporu albańskiego", "9158c35f"], "d": ["Skanderbeg, który wychowany na dworze osmańskim zbuntował się w 1444 po klęsce pod Zlaticą i przez ponad ćwierć wieku stawiał opór w Albanii, zmarł w Lezhë, gdzie się schronił. Opór, który wielokrotnie absorbował armie osmańskie za Murada II i Zdobywcy, utracił wraz z jego śmiercią przywództwo centralne. Po załamaniu się frontu albańskiego, podsycanego przez papiestwo i Wenecję, Osmanowie w ciągu dziesięciu lat zajęli Krujë i Szkodrę i ostatecznie przyłączyli region do swych ziem.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Ustanowienie zarządu osmańskiego w Kayseri: Gedik Ahmed Pasza zakończył istnienie Karamanoğulları", "33cf35fc"], "d": ["Wraz z zakończeniem przez Gediga Ahmeda Paszę istnienia Karamanoğulları w 1474 Kayseri weszło pod zarząd osmański; w XV wieku miasto zmieniało właściciela między Dulkadıroğulları, Ramazanoğulları i Karamanoğulları. Pod zarządem osmańskim Kayseri stało się ośrodkiem sandżaku beylerbeyliku Karamanu.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samos opuszczone: koniec genueńskiej (Maona) własności", "5bdc380c"], "d": ["Według TDV wyspa została po 1475 opuszczona; w 1479 sułtan Mehmed Zdobywca zdobył wyspę i kazał zbudować twierdzę.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Klęska pod Račową (Vaslui) w Mołdawii", "a1a74bf7"], "d": ["Wojewoda mołdawski Stefan Wielki, wciągnąwszy siły osmańskie pod dowództwem beylerbeja Rumelii Hadıma Süleymana Paszy na grunt błotnisty, zadał im ciężką klęskę. Ta klęska, jedna z najcięższych porażek lądowych za czasów Zdobywcy, wywołała w Europie wielki oddźwięk i przyniosła Stefanowi sławę w świecie krzyżowców. Sułtan miał w następnym roku osobiście wyruszyć na wyprawę odwetową.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Zwycięstwo pod Valea Albă (Akdere) — wyprawa na Mołdawię", "45a66791"], "d": ["Sułtan Mehmed Zdobywca, który osobiście wyruszył na wyprawę, by pomścić klęskę pod Račową sprzed roku, zadał armią osmańską i oddziałom mołdawskim wielką klęskę na miejscu Valea Albă i wkroczył do Suczawy, ośrodka bejliku. Nie zdołano jednak zająć twierdz; wskutek braku żywności, dżumy, która wybuchła wśród janczarów, i węgierskich przygotowań armia musiała się wycofać. Ostateczne związanie Mołdawii miało zostać osiągnięte dopiero w następnych latach, wraz ze zdobyciem Kilii i Akkermanu w 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Zdobycie Krujë i dopełnienie zdobycia Albanii", "559a79b4"], "d": ["W dziesięć lat po śmierci Skanderbega, w 1478, wraz ze zdobyciem Krujë, Drivastu, Lezhë i Jablanicy zdobycie Albanii zostało w znacznej mierze dopełnione. Upadek twierdzy Krujë, która przez lata opierała się armiom osmańskim i była symbolem oporu Skanderbega, oznaczał koniec sojuszu wenecko-albańskiego w regionie. Pozostała Szkodra miała zostać pozostawiona Osmanom na mocy traktatu stambulskiego podpisanego w następnym roku.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Przyłączenie półwyspu Taman", "4ef917b8"], "d": ["Po zajęciu Kafy i Kerczu w 1475 flota wysłana przez Mehmeda Zdobywcę na wybrzeża kaukaskie zajęła, wraz z Anapą i Kopą, genueńską Matregę (Tamatarhan) na półwyspie Taman. W ten sposób oba brzegi cieśniny znalazły się pod kontrolą, a wejście do Morza Azowskiego stało się w pełni kontrolowane. Taman został przyłączony do sandżaku Kafy jako brama otwierająca się na Północny Kaukaz.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Wejście Samos pod zarząd osmański (Zdobywca)", "c877bc14"], "d": ["Sułtan Mehmed Zdobywca zdobył Samos, kazał zbudować twierdzę i na nowo uporządkował spis; twierdzę kazał zburzyć w 1483 z powodów politycznych Bayezid II.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Niepowodzenie oblężenia Rodos", "35a85c28"], "d": ["Flota 160 jednostek pod dowództwem Mesiha Paszy, wysłana z rozkazu sułtana Mehmeda Zdobywcy, obległa Rodos wiosną 885 (1480) i wyspa pozostawała w blokadzie przez trzy miesiące. Joannici pod wodzą wielkiego mistrza Pierre'a d'Aubusson, mimo ciężkich strat, bronili się zaciekle; gdy odparto także ostatni wielki szturm z 20 cemâziyelevvel 885, flota wycofała się 3 sierpnia. Po tej porażce mury miasta odbudowano od podstaw i uczyniono je najpotężniejszym umocnieniem Europy, a wyspę zdołał zdobyć dopiero w 1522 Sulejman.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Ikaria (Nikarya) weszła pod zarząd joannitów z Rodos", "5cbc2669"], "d": ["Ikaria między Samos a Chios znajdowała się od 1481 do 1521 pod zarządem joannitów z Rodos.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Bitwa pod Yenişehir — klęska księcia Cema", "c35abee2"], "d": ["Dwaj bracia, którzy po śmierci Zdobywcy wystąpili o tron, stanęli naprzeciw siebie na równinie Yenişehir, a książę Cem poniósł ostateczną klęskę. Książę, który przez osiemnaście dni rządził w Bursie i kazał czytać w swoim imieniu chutbę, musiał po klęsce schronić się najpierw w Konyi, a stamtąd na ziemiach mameluckich. Yenişehir rozpoczęło najdłużej trwający kryzys dynastyczny w dziejach osmańskich: sprawa Cema miała przez czternaście lat paraliżować osmańską politykę zagraniczną wobec Europy.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Aneksja Hercegowiny", "bf247891"], "d": ["Ziemie Księstwa Hercegowiny, które przetrwało po zdobyciu Bośni w 1463, stopniowo przechodziły pod zarząd osmański: Trebinje i Mostar zajęto w 1466, sandżak Hercegowiny utworzono w 1470, a ostatnie ziemie księstwa na wybrzeżu Adriatyku wraz z Herceg Novi zdobyto na początku 1482 i przyłączono do sandżaku. W ten sposób region górzysty za Adriatykiem stał się całkowicie osmański, a Bośnia i Hercegowina utworzyły jedną geografię administracyjną. Syn ostatniego księcia, który wszedł na dwór osmański, to Hersekzâde Ahmed Pasza, który miał wspiąć się aż do godności wielkiego wezyra.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Pozostawienie Zakynthos (Zaklise) Wenecji za coroczną daninę", "268a691a"], "d": ["Zakynthos, jedną z Wysp Jońskich zabranych rodowi Tocco pod koniec epoki Zdobywcy, pozostawiono Wenecji wobec dążenia nowego sułtana, zajętego sprawą Cema, do spokoju na Zachodzie. Wyspę przekazano zarządowi weneckiemu, który uznawał zwierzchnictwo osmańskie i płacił roczną daninę pięciuset dukatów. W ten sposób na Morzu Jońskim bezpośredni zarząd osmański pozostał tylko w Aya Mavra.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Schronienie księcia Cema na Rodos", "2228d6da"], "d": ["Książę Cem, którego próba oblężenia Konyi także nie przyniosła skutku, uciekł z Anatolii z około trzydziestoma ludźmi i dotarł na Rodos, gdzie rycerze św. Jana powitali go uroczyście. Gościna jednak szybko zamieniła się w niewolę; książę został przekazany najpierw Francji, a następnie papiestwu i stał się kartą w rękach polityki europejskiej. Bayezid II musiał płacić roczną opłatę w zamian za przetrzymywanie brata, a osmańskie ruchy wojskowe wymierzone w Zachód zostały zawieszone aż do śmierci Cema.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Początek wojny osmańsko-mameluckiej (front Çukurovy)", "3fe3f0c7"], "d": ["Walka o wpływy nad Dulkadıroğulları i wrogość pozostawiona przez schronienie księcia Cema na ziemiach mameluckich rozpoczęły w 1485 wojnę dwóch wielkich mocarstw sunnickich, która miała trwać sześć lat. W starciach na Çukurovie w okolicach Adany i Tarsusu strony nie zdołały uzyskać przewagi; armie osmańskie otrzymały kilka ciężkich ciosów. Wojna ta jest pierwszą fazą załamania stosunków osmańsko-mameluckich i otwarciem procesu, który miał zakończyć się trzydzieści lat później wyprawami Selima pod Mardż Dabik i Ridaniją.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Pokój osmańsko-mamelucki — pośrednictwo Tunisu", "60dd6719"], "d": ["W wojnie osmańsko-mameluckiej rozpoczętej w 1485 strony nie odniosły decydującego zwycięstwa; za pośrednictwem władcy Tunisu Osmana Hafsydy w 1491 doszło do porozumienia. Traktat w znacznej mierze przywrócił granice sprzed wojny, a rozrachunek między dwoma państwami islamu został odłożony o pokolenie. Sześcioletnia wyczerpująca walka jest jedną z głównych przyczyn ostrożnej polityki zagranicznej Bayezida II i jego skupienia się na urządzeniach wewnętrznych zamiast zwrotu ku wschodowi.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Przyjęcie sefardyjskich Żydów wypędzonych z Hiszpanii do państwa osmańskiego", "5c2b5c24"], "d": ["Po upadku Granady część Żydów uciekających przed prześladowaniami inkwizycji w Hiszpanii schroniła się na ziemiach osmańskich i została osiedlona w różnych miastach. Pod zarządem osmańskim te wspólnoty sefardyjskie zyskały swobody, jakich do tej pory nie widziały: osiedlania się, gdzie chciały, życia według swej wiary, otwierania instytucji edukacyjnych i budowy nowych synagog. Ta migracja, która dzięki przywiezionej wiedzy drukarskiej, medycznej i finansowej przekształciła życie gospodarcze Salonik i Stambułu, stała się w Europie najczęściej omawianym przykładem osmańskiego ładu tolerancji.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Śmierć księcia Cema — koniec czternastoletniego zakładnika", "f6588b70"], "d": ["Książę Cem, przekazany przez papiestwo królowi Francji Karolowi VIII, zmarł w miejscu zwanym Castel Capuana po wyruszeniu z Rzymu 27 stycznia 1495; źródła odnotowują, że mógł zostać otruty przez kręgi papieskie. Śmierć księcia, trzymanego przez czternaście lat w rękach państw europejskich jako karta zagrożenia przeciw Osmanom, ostatecznie rozwiązała ręce Bayezidowi II. Istotnie, sułtan miał odtąd wypowiedzieć wojnę Wenecji i poprowadzić flotę do pierwszego wielkiego zwycięstwa.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Zwycięstwo morskie pod Sapienzą (Zonchio) — pierwszy wielki sukces floty na Morzu Śródziemnym", "9754aaef"], "d": ["Bayezid II, któremu wraz z zakończeniem sprawy Cema rozwiązały się ręce, wypowiedział w 1499 wojnę Wenecji; flota osmańska pokonała pod Sapienzą (Zonchio) flotę wenecką i odniosła pierwsze wielkie zwycięstwo morskie na Morzu Śródziemnym. Dzięki temu zwycięstwu flota ogłosiła, że potrafi już stawić czoło Wenecji na morzu.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Utrata Kefalonii i Itaki", "60f0f687"], "d": ["Wenecja, wstrząśnięta zajęciem Modon i Koron, połączyła się z Hiszpanią i przeszła do kontrataku, oblegając Kefalonię, pozostającą w rękach osmańskich od 1479. Po czterdziestosiedmiodniowym oporze twierdza padła, a wyspa wraz z Itaką przeszła do Wenecji i przez trzysta lat nie wróciła pod zarząd osmański. Ta strata stworzyła równowagę, w której to, co zdobyto w Morei, zostało oddane na Morzu Jońskim.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Upadek Chanatu Złotej Ordy i wzrost znaczenia Krymu", "0d1dc515"], "d": ["Ostatni władca, Szejch Ahmed Chan (1481–1502), nie zdołał wydobyć kraju z kryzysu, w który popadł, a Chanat Złotej Ordy przeszedł do historii w 1502 wskutek ciosu chana krymskiego Mengliego Gireja. W wyniku sporów o tron i rozpadu na ziemiach dawnej Złotej Ordy powstały chanaty Krymu, Kazania, Nogajów, Astrachania i Sybiru. To zwycięstwo Krymu pod protekcją osmańską uczyniło wpływy osmańskie na północy Morza Czarnego niekwestionowanymi, a próżnię powstałą w regionie miała w następnym stuleciu wypełnić Moskwa.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Zakończenie wojny osmańsko-weneckiej i pokój", "125b1526"], "d": ["Wojna rozpoczęta w 1499, która wstrząsnęła Wenecją pod Sapienzą, Lepanto oraz utratą Modon i Koron, zakończyła się pokojem w 1502. Wenecja, utraciwszy najważniejsze bazy w Morei, musiała uznać przewagę osmańską w zamian za zachowanie przywilejów handlowych we wschodniej części Morza Śródziemnego. Panowanie Bayezida II, uchodzące za ostrożne, wyniosło tą wojną Osmanów po raz pierwszy do pozycji poważnej potęgi morskiej na Morzu Śródziemnym.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Powstanie Şahkuluego — powstanie Kızılbaszy od okolic Teke po Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, który pod wpływem propagandy safawidzkiej w Anatolii ujawnił swój bunt w 1510, w marcu 1511 napadł na rynek Antalyi, a w kwietniu pokonał siły osmańskie w okolicach Kütahyi. W ostatniej bitwie z wielkim wezyrem Hadımem Alim Paszą pod Sivas obie strony poniosły ciężkie straty; zginęli zarówno wielki wezyr, jak i przywódca powstania. Powstanie, które nadwątliło władzę państwa w Anatolii, obnażyło próżnię władzy w ostatnich latach Bayezida II i stało się najsilniejszym uzasadnieniem marszu księcia Selima na tron.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Abdykacja Bayezida II i wstąpienie na tron Selima Strasznego", "c4cfab69"], "d": ["Pod naciskiem księcia Selima, który w walce o tron z braćmi miał za sobą poparcie janczarów, Bayezid II abdykował 24 kwietnia 1512, a Selim I wstąpił tego samego dnia na tron jako dziewiąty władca osmański. Stary sułtan, jadąc do rodzinnej Dimetoki, zmarł w drodze we wsi Abalar koło Çorlu 25 rebîülevvel 918 (10 czerwca 1512). Trzydziestojednoletnie ostrożne i zwrócone do wewnątrz panowanie zastąpiła epoka Straszliwego, który w osiem lat miał podwoić granice imperium.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Zdobycie twierdzy Sinj", "83271ea5"], "d": ["Osmańskie siły akindżich na granicy bośniackiej zabrały Królestwu Węgier twierdzę Sinj, sięgającą w głąb Dalmacji. Było to wczesne ogniwo linii granicznej Dalmacji, która miała rozszerzyć się po dziewięciu latach wraz ze zdobyciem Kninu i okolic przez Gazi Hüsrev Beja; twierdza miała zostać utracona na rzecz Wenecji w 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Bitwa pod Yenişehir i usunięcie księcia Ahmeda", "e2ed15dd"], "d": ["Sułtan Selim Straszny pokonał na równinie Yenişehir pod Bursą swego starszego brata, księcia Ahmeda, najsilniejszego rywala do tronu, i usunął go, biorąc do niewoli. Trwająca od 1511 walka braci została w ten sposób zamknięta, a wewnętrzny podział Anatolii się skończył. Selim, zabezpieczywszy tyły, zyskał swobodę, by zwrócić się ku sprawie safawidzkiej.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Wkroczenie sułtana Selima Strasznego do Tabrizu", "dad2e227"], "d": ["Po zwycięstwie pod Çaldıranem armia osmańska wkroczyła do stolicy safawidzkiej Tabrizu, a w mieście odczytano chutbę w imieniu sułtana. Selim zabawił tu tydzień i kazał przenieść do Stambułu część artystów i ulemów z Tabrizu; to przeniesienie miało głęboko wpłynąć na sztukę pałacową Osmanów. Choć miasto opuszczono wobec zbliżającej się zimy i niezadowolenia janczarów, przewaga Safawidów na Wschodzie została złamana. Na mapie miejsca przechodzące do Osmanów tego dnia nie sąsiadują ze sobą i tak ma być: Tabriz to dziewięciodniowa okupacja wojskowa; równina Erzincan poddała się podczas wyprawy bez walki, a leżąca pośrodku twierdza Kemah broniła się u Safawidów do 19 maja 1515; Siirt odebrał Safawidom, wyrzekłszy posłuszeństwo Osmanom, melik Hasankeyf Halil Bej, uwolniony z więzienia szacha İsmaila w Tabrizie — otaczający Diyarbakır pozostał safawidzki do 1515, a Hasankeyf do 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş i Bingöl (Çapakçur) przeszły od Safawidów pod zarząd osmański", "b0a53b5a"], "d": ["Gdy po Çaldıranie Wschodnia Anatolia została odebrana Safawidom, Muş weszło w 921/1515 pod zarząd osmański; sąsiedni Çapakçur (Bingöl) został przyłączony do Osmanów w tym samym procesie.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Zdobycie twierdzy Kemah od Safawidów", "73fd8671"], "d": ["Sułtan Selim Straszny, który w drodze powrotnej spod Çaldıranu spędził zimę w Amasyi, powierzył zdobycie umocnionej twierdzy Kemah, trzymającej punkt przeprawy przez Eufrat, Bıyıklı Mehmedowi Paszy. Po oblężeniu, w którym wziął udział osobiście sułtan, twierdzę odebrano Safawidom i otwarto bramę Anatolii Wschodniej. To zdobycie jest pierwszym konkretnym krokiem przekształcającym zwycięstwo pod Çaldıranem w trwałą zdobycz terytorialną.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Zwycięstwo pod Turnadağ — Bejlik Dulkadir stał się zależny od Osmanów", "fd879145"], "d": ["Siły osmańskie pokonały beja Dulkadir Alâüddevle Bozkurta, który w czasie wyprawy pod Çaldıran zajął postawę dwuznaczną, na miejscu Ördekli między Göksun a Andırın; Alâüddevle zginął w tej bitwie. Bejlik nie został w tym czasie anektowany: po Alâüddevle na czele Bejliku Dulkadıroğulları sułtan Selim Straszny postawił Şehsuvaroğlu Alego Beja, a kraj z ośrodkiem Maraş–Elbistan trwał jako bejlik zależny od Osmanów. Bufor na granicy mameluckiej znalazł się w ten sposób pod kontrolą osmańską i otwarto drogę wyprawie egipskiej sprzed dwóch lat; aneksja miała nastąpić dopiero po zabiciu Alego Beja.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Zdobycie Âmid (Diyarbekir) i utworzenie beylerbeyliku Diyarbekir", "a6867d5b"], "d": ["Gdy İdrîs-i Bitlisî pozyskał dla Osmanów sunnickich bejów kurdyjskich w regionie, siły safawidzkie nie wytrzymały długiego oblężenia, a klucze Âmid wręczono Bıyıklı Mehmedowi Paszy. Miasto uczyniono ośrodkiem nowo utworzonego beylerbeyliku Diyarbekir. W ten sposób administracyjne jądro Górnej Mezopotamii przeszło w ręce osmańskie.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Zdobycie Harput — otwarcie drogi do Diyarbekir", "564eb269"], "d": ["Beylerbej Karamanu Hüsrev Pasza, który wyruszył, by uwolnić od oblężenia safawidzkiego Diyarbekir zajęty po Çaldıranie, zdobył po trzydniowym oblężeniu twierdzę Harput, której okolice wcześniej zajął Çerkez Hüseyin Bej. W ten sposób zabezpieczono drogę na wschód od Eufratu ku Diyarbekirowi.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Bitwa pod Koçhisar (Kızıltepe) — klęska Kara Chana", "9ea9e843"], "d": ["Armia osmańska pod dowództwem Bıyıklı Mehmeda Paszy pokonała w całodziennej bitwie polnej na miejscu Koruk na stepie Dede Garkın pod Koçhisar namiestnika safawidzkiego Kara Chana; ścięta głowa Kara Chana została wysłana do obozu sułtana. Następnie siły osmańskie wkroczyły do miasta Mardin, lecz po kilku dniach je opuściły; twierdza Mardin trzymana przez załogę safawidzką mogła zostać zajęta dopiero rok później. To zwycięstwo, zapewniając południową granicę Selima, umożliwiło mu zwrócenie się ku wyprawie egipskiej. W tym samym dniu przyłączono także inne miejscowości: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Wyjście sułtana Selima Strasznego ze Stambułu na wyprawę egipską", "ac258b4b"], "d": ["Sułtan Selim Straszny wyruszył ze Stambułu pozornie w ramach przygotowań do nowej wyprawy wschodniej przeciw Safawidom i skierował się na południe przez Akşehir. Nawiązanie przez sułtana mameluckiego Kansu Gavriego kontaktu z szachem İsmâilem i zagrożenie osmańskiego skrzydła wschodniego miało wkrótce doprowadzić do zmiany celu. Wyprawa jest początkiem wielkiej akcji, która miała trwać dwa lata i przekształcić Osmanów w imperium bliskowschodnie.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Zajęcie Zabîd: pierwsze wejście osmańskich żeglarzy na Morze Czerwone", "38740e0c"], "d": ["Wobec nacisku Portugalii na Oceanie Indyjskim Hüseyin Bej i Selman Reis, żeglarze pochodzenia osmańskiego wysłani na Morze Czerwone na żądanie sułtana mameluckiego Kansu Gavriego, zajęli swoimi flotami Zabîd. Akcja prowadzona jeszcze w służbie mameluckiej jest pierwszą faktyczną obecnością osmańskiej marynarki na linii Morze Czerwone–Indie. Gdy rok później Egipt przejdzie do Osmanów, ta sama flota zostanie podporządkowana bezpośrednio Stambułowi.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Oficjalne ogłoszenie celu wyprawy: mamelucy i Aleppo", "689e310d"], "d": ["Sułtan Selim Straszny, gdy Kansu Gavri porozumiał się z Safawidami i skierował swą armię na Aleppo, ogłosił jawnie celem wyprawy sułtana mameluckiego i Aleppo. W ten sposób trwająca od lat ukryta rywalizacja między dwoma państwami sunnickimi przekształciła się w otwartą wojnę. To ogłoszenie rozpoczęło czterotygodniowe odliczanie prowadzące do Mardż Dabik.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Niepowodzenie oblężenia Adenu: pierwsza próba na Morzu Czerwonym przeciw Portugalii", "8ffd46f2"], "d": ["Selman Reis i Hüseyin Bej, by zająć Aden, bramę Morza Czerwonego otwierającą się na Ocean Indyjski, prowadzili ośmiodniowe oblężenie, lecz wobec silnych umocnień miasta musieli się wycofać. To, że Adenu nie zdobyto, miało na wiele lat zakłócić południową strategię prowadzoną przeciw Portugalii. Ta próba jest pierwszym sprawdzianem osmańskiej polityki oceanicznej.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Związanie Bejliku Ramazanoğulları z Osmanami", "cfaa3754"], "d": ["Przy nadaniach dokonanych po zwycięstwie pod Mardż Dabik bejlik Ramazanoğulları z ośrodkiem w Adanie został nadany Mahmudowi Bejowi i objęty panowaniem osmańskim. Bejlik, który wyszedł z zależności mameluckiej, zamiast być zlikwidowany, został pozostawiony rodzinie ze statusem „ocaklık”; Ramazanoğulları nadal zarządzali Çukurovą jako sandżakbejowie osmańscy. Ten uprzywilejowany ład trwał do 1608, gdy Pîr Mansûr zrezygnował z bejliku. W tym samym dniu przyłączono także inne miejscowości: Malatya, Tarsus, Mosul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Wejście Aleppo, Rakki i Dajr az-Zaur pod panowanie osmańskie", "2088eb6a"], "d": ["Cztery dni po Mardż Dabik sułtan Selim Straszny wkroczył do Aleppo bez napotkania oporu, a w meczetach miasta czytano chutbę w jego imieniu. Tak szybki upadek Aleppo, uchodzącego za handlową i administracyjną stolicę Syrii, pokazuje, że władza mamelucka w regionie się załamała. Zajęcie miasta otworzyło naraz drogę do Damaszku, a stamtąd do Egiptu. W tym samym dniu przyłączono także inne miejscowości: Antiochia, Rakka, Dajr az-Zaur.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Spotkanie w Aleppo na Gökmeydan z kalifem abbasydzkim Mutawakkilem III", "22979f42"], "d": ["Kalif abbasydzki z Kairu Mutawakkil III, który dostał się do niewoli wraz z armią mameluck pod Mardż Dabik, został stawiony przed sułtanem w Aleppo na Gökmeydan, a sułtan Selim Straszny okazał mu wielki szacunek. Kalifat kairski, od 1261 symboliczny urząd w cieniu sułtanów mameluckich, przeszedł dzięki temu spotkaniu faktycznie pod protekcję osmańską. Kalif miał być później zabrany do Stambułu razem z sułtanem.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Wejście Trypolisu i Hamy pod zarząd osmański", "a1e19a79"], "d": ["Po Aleppo i Hamie również Trypolis na wybrzeżu syryjskim przeszedł bez oporu pod zarząd osmański. Miasto, jeden z najruchliwszych portów wschodniej części Morza Śródziemnego, było otwartą na morze bramą Damaszku i ośrodkiem handlu jedwabiem i cukrem. Wraz z jego zajęciem pas przybrzeżny Bilâdüşşam całkowicie zmienił właściciela.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Wejście Damaszku pod panowanie osmańskie", "2b844d91"], "d": ["Sułtan Selim Straszny, któremu po poddaniu się Hamy i Hims otworzyła się droga, dotarł 27 września pod Damaszek; nie wszedł od razu do miasta, lecz rozbił namiot na zewnątrz w miejscu Mastaba i wkroczył do środka z wielką ceremonią w dwunasty dzień po przybyciu. Zostawszy w Damaszku długo, ustanowił administracyjny ład Syrii i kazał zbudować grobowiec Muhyiddina Ibn Arabiego. W ten sposób cały Bilâdüşşam wyszedł spod zarządu mameluckiego. W tym samym dniu przyłączono także inne miejscowości: Bejrut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Ogłoszenie Tomanbaya sułtanem mameluckim w Kairze", "6020d90d"], "d": ["Po śmierci Kansu Gavriego pod Mardż Dabik emirowie mameluccy wprowadzili na tron Tomanbaya, który miał zostać ostatnim sułtanem państwa. Nowy sułtan pochodzenia czerkieskiego przejął państwo, które straciło Syrię, miało wyczerpany skarb i było pozbawione broni palnej. Mimo to miał zorganizować ostatni opór przeciw osmańskiemu natarciu, budując linię obrony przed Kairem.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Bitwa pod Gazą (Han Yûnus): klęska Canbirdiego Gazâlîego", "9f1eb8cb"], "d": ["Sułtan Selim Straszny wysłał wielkiego wezyra Hadıma Sinana Paszę z czterotysięczną strażą przednią do Gazy. Canbirdi Gazâlî, mianowany przez Tomanbaya namiestnikiem Damaszku, próbował zatrzymać osmańską straż przednią na linii Gaza–Han Yûnus, lecz poniósł ciężką klęskę i uciekł do Egiptu. Wraz z rozproszeniem ostatniej mameluckiej siły buforowej w Palestynie droga na pustynię Synaj została całkowicie otwarta.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Na wschód od Jordanu: wejście Ammanu pod zarząd osmański", "9db62667"], "d": ["Po bitwie pod Gazą, gdy siły osmańskie przygotowujące się do wyprawy egipskiej schodziły na południe, Amman na wschód od Jordanu również wszedł pod zarząd osmański. Miasta przybrzeżne i wewnętrzne Palestyny (Jafa, Nablus, Sajda, Akka, Jerozolima) zmieniły właściciela już jesienią 1516, po Mardż Dabik. Miasta te przez cztery stulecia były zarządzane jako sandżaki ejaletu Damaszku.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Przybycie sułtana Selima Strasznego do Jerozolimy", "66d7bfad"], "d": ["Do Jerozolimy, która po Mardż Dabik przeszła pod zarząd osmański bez oporu, sułtan Selim Straszny przybył po bitwie pod Gazą wraz z notablami państwa i wojskiem. Sułtan odwiedził Kopułę na Skale i meczet Al-Aksa i potwierdził święty status miasta. Jerozolima miała pozostawać pod zarządem osmańskim od tej daty aż do grudnia 1917, pełne cztery stulecia.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Wkroczenie sułtana Selima Strasznego do Gazy i zwrot ku pustyni Synaj", "2106bfc7"], "d": ["Po klęsce Canbirdiego Gazâlîego pod Hanyûnus (21 grudnia 1516) Gaza była w rękach straży przedniej. Sułtan wkroczył do Gazy 2 stycznia 1517, spotkał się tu ze stojącym na czele straży przedniej Sinanem Paszą, a armia dokonała ostatnich przygotowań do przejścia do Egiptu. Na bezwodnej pustyni Katya (Synaj) od Gazy po Salihiję miano maszerować osiem postojów, przewożąc wodę na wielbłądach. Przejście to jest najbardziej ryzykowną i logistycznie najtrudniejszą fazą wyprawy.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Zajęcie Suezu — brama otwierająca się na Morze Czerwone", "05f3324e"], "d": ["Po zwycięstwie pod Ridaniją, wraz z wkroczeniem wojsk osmańskich do Kairu, Suez na północnym krańcu Morza Czerwonego przeszedł pod zarząd osmański. Ten port stoczniowy, z którego mamelucy wysyłali flotę na Ocean Indyjski, stał się bazą południowej polityki prowadzonej przeciw Portugalii. Suez jest północnym wlotem linii, na której trzy stulecia później otwarto kanał.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Pierwsze wkroczenie wojsk osmańskich do Kairu", "0a3f4f4d"], "d": ["Dzień po zwycięstwie pod Ridaniją pozwolono armiom osmańskim wejść do Kairu, a 24 stycznia oddziały rozlokowały się w mieście. Wkroczenie to nie oznaczało jednak pełnej kontroli nad miastem; Tomanbay wycofał się do Górnego Egiptu, a opór mamelucki nie został jeszcze złamany. Zdobycie Kairu miało zostać dopełnione nie w jeden dzień, lecz w krwawym procesie rozciągniętym na tygodnie.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Napad Tomanbaya na Kair i trzydniowe walki uliczne", "b83b6ce6"], "d": ["Tomanbay, który wycofał się do Górnego Egiptu, wkroczył z około siedmioma tysiącami ludzi nagle do Kairu w nocy z 27 na 28 stycznia i rozpoczął opór w mieście, stawiając oddziały osmańskie w niezwykle trudnym położeniu. W trwających trzy dni zaciętych walkach ulicznych mamelucy tymczasowo utrzymali większą część miasta. Opór mógł zostać złamany dopiero po wejściu do akcji artylerii osmańskiej i sił wzmocnienia.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Wejście Canbirdiego Gazâlîego w służbę osmańską", "a94ea459"], "d": ["Dawny emir mamelucki Canbirdi Gazâlî, który po Ridaniji wycofał się do Salihiji, zwrócił się do sułtana, prosząc o aman. Sułtan Selim Straszny, uznając, że będzie pożyteczny w ustanowieniu porządku w Egipcie i Syrii, przyjął go do swej służby. Ten wybór jest pierwszym wielkim przykładem osmańskiej polityki włączania kadr mameluckich do systemu zamiast ich likwidacji.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Uroczyste wkroczenie sułtana Selima Strasznego do Kairu i odczytanie chutby", "6d98080c"], "d": ["Po stłumieniu walk ulicznych sułtan wkroczył 15 lutego 1517 do Kairu w bardzo świetnej ceremonii, a w meczetach odczytano chutbę w jego imieniu. Odczytanie chutby w Kairze w imieniu sułtana osmańskiego jest ogłoszeniem prawnego końca panowania mameluckiego trwającego od 1250. Data ta uchodzi za symboliczny moment dopełnienia faktycznego zdobycia Egiptu.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Schwytanie ostatniego sułtana mameluckiego Tomanbaya w Terrûce", "7058e6ad"], "d": ["Tomanbay, który po opuszczeniu Kairu ukrywał się w delcie Nilu, został zadenuncjowany przez beduinów, którzy dali mu schronienie, i pojmany w okolicach Terrûce. Jego schwytanie zlikwidowało zorganizowany ośrodek oporu mameluckiego. Ostatni sułtan miał być odtąd przez czternaście dni trzymany w rękach osmańskich.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Stracenie Tomanbaya przy Bâbüzüveyle i koniec państwa mameluckiego", "ad9820be"], "d": ["Czternaście dni po schwytaniu Tomanbay został powieszony przy słynnej bramie Kairu Bâbüzüveyle; jego ciało pochowano później w medresie zbudowanej przez jego wuja. W ten sposób Państwo Mameluckie, rządzące Egiptem i Syrią od 1250, formalnie przeszło do historii. Wraz ze złamaniem oporu także miasta Górnego Egiptu (Saidu), takie jak Asjut i Asuan, zostały przyłączone do zarządu osmańskiego.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Atak floty portugalskiej na Dżuddę i obrona Selmana Reisa", "52322cf5"], "d": ["Flota portugalska licząca około trzydziestu galer i galeonów zaatakowała Dżuddę; Selman Reis, kierując obroną miasta, uniemożliwił wrogowi wylądowanie i zatopił kilka okrętów portugalskich. Obrona ta zapobiegła przejściu portu Mekki, a tym samym szlaku pielgrzymiego, w ręce państwa chrześcijańskiego. Dżudda miała po kilku miesiącach zostać oficjalnie włączona do zarządu osmańskiego dzięki bî'at Hidżazu.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Przejęcie Aleksandrii przez flotę — dopełnienie zdobycia Egiptu", "386878fe"], "d": ["Dokładnie cztery miesiące po Ridaniji i trzydzieści sześć dni po straceniu Tomanbaya, wraz z przybyciem do portu floty osmańskiej pod zarządem Câfera Beja, Aleksandria przeszła pod zarząd osmański; porty delty, takie jak Raszid i Damietta, zostały przyłączone w tym samym procesie. To, że wielki port Egiptu otwarty na Morze Śródziemne został przejęty miesiące po upadku Kairu i nie z lądu, lecz z morza, jasno pokazuje, że zdobycie zostało dokonane nie jedną bitwą, lecz region po regionie. Aleksandria miała odtąd stać się życiowym portem łączącym Stambuł z Kairem. W tym samym dniu przyłączono także inne miejscowości: Raszid (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Bezwojenne przyłączenie Hidżazu: bî'at Abû Numayya, syna szarifa Mekki", "c13b98c7"], "d": ["Sułtan Selim Straszny początkowo rozważał wysłanie wojska dla zajęcia Mekki i okolic, lecz zrezygnował z tego, gdy emir Mekki szarif Berekât zadeklarował posłuszeństwo. Dwunastoletni syn Berekâta, Abû Numayy, przybył do Kairu z darami ojca i kluczami Mekki i został przyjęty przez sułtana. Hidżaz nie przyłączył się więc do Osmanów jako automatyczny skutek Ridaniji, lecz po pięciu i pół miesiącach i bez jednego wystrzału, drogą układu i bî'at. W tym samym dniu przyłączono także inne miejscowości: Ta'if.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Przyjęcie tytułu Hâdimü'l-Haremeyn i chutba w Medynie", "63b32b59"], "d": ["Po drugim przyjęciu delegacji mekkańskiej sułtan Selim Straszny oficjalnie objął protektorat nad Haremejn i zaczął używać tytułu „hâdimü'l-Haremeyni'ş-şerîfeyn” (sługa dwóch świętych sanktuariów). Szarif Berekât, włożywszy przysłaną mu szatę honorową, kazał odczytać chutbę w imieniu sułtana; gdy delegacja medyńska udała się do Stambułu, emirat Berekâta został potwierdzony beratem. Sułtan wysłał mieszkańcom Haremejn dwieście tysięcy sztuk złota i obfite zapasy żywności, rozpoczynając tradycję surre powtarzaną co roku. W tym samym dniu przyłączono także inne miejscowości: Yanbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Wejście Selmana Reisa w służbę osmańską i przekazanie polityki Morza Czerwonego", "771da99a"], "d": ["Selman Reis, który bronił Dżuddy przed Portugalczykami, przybył do Kairu i stanął przed sułtanem Selimem Strasznym; choć przez pewien czas był zatrzymany, w 1519 został wezwany do Stambułu i zobowiązał się przygotować trzydzieści galer i kilka galeonów przeciw zagrożeniu portugalskiemu. Spotkanie to jest początkiem przejęcia polityki Morza Czerwonego i Oceanu Indyjskiego ze spuścizny mameluckiej i związania jej bezpośrednio ze Stambułem. Osmanowie byli odtąd nie tylko państwem śródziemnomorskim, lecz także potęgą prowadzącą politykę oceaniczną.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Wyjazd sułtana Selima Strasznego z Kairu i beylerbejstwo Hayıra Beja", "8cd4fb23"], "d": ["Sułtan Selim Straszny, który spędził w Egipcie około ośmiu miesięcy, ustanawiając ład administracyjny, finansowy i wojskowy, opuścił Kair; Hayır Bej, dawny namiestnik Aleppo, który pod Mardż Dabik wycofał lewe skrzydło i przyspieszył klęskę mameluków, rozpoczął zarząd z Cytadeli jako pierwszy beylerbej osmański Egiptu. Wybór namiestnika pochodzenia mameluckiego był świadomą polityką przejściową, dzięki której nowy zarząd nie wydawał się obcy miejscowej ludności. W drodze powrotnej sułtan zabrał do Stambułu ostatniego kalifa abbasydzkiego Mutawakkila III oraz wybitnych artystów i uczonych Egiptu.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Koniec kairskiego kalifatu abbasydzkiego — przekaz o „ceremonii przekazania”", "1d357640"], "d": ["Sułtan Selim Straszny po zdobyciu Egiptu zabrał do Stambułu ostatniego kalifa Mutawakkila III al-Allaha, który dostał się do niewoli pod Mardż Dabik; kairski kalifat abbasydzki, od 1261 trwający bez władzy w cieniu sułtanów mameluckich, w ten sposób się skończył. Natomiast słynny przekaz, że kalifat został przekazany Selimowi w oficjalnej ceremonii w Hagia Sophia, po raz pierwszy występuje pod koniec XVIII wieku w dziele d'Ohssona i nie ma go w żadnym ze źródeł z epoki Selima. TDV İslâm Ansiklopedisi uznaje przekaz za zmyślenie, ponieważ nie ma oryginalnego źródła dokumentującego ceremonię; odnotowuje jednak, że dla przejścia kalifatu nie była też według szariatu potrzebna taka ceremonia przekazania.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum przyłączony do zarządu osmańskiego — złamanie wpływów safawidzkich we Wschodniej Anatolii", "78d1be02"], "d": ["Choć po zwycięstwie pod Çaldıranem (1514) wpływy osmańskie w regionie wzrosły, pełne zajęcie Erzurumu opóźniło się aż do złamania wpływów irańskich; miasto zostało przyłączone do zarządu osmańskiego dopiero po wyprawie egipskiej, w latach 1518–19. Erzurum znalazł się pod panowaniem safawidzkim w 1502, gdy szach İsmâil położył kres Bejlikowi Akkoyunlu; szesnastoletni okres się w ten sposób zamknął. W 1534, w czasie wyprawy Irakejn, miał zostać utworzony beylerbeylik Erzurumu. W latach 1518–1519 wraz z regionem Erzurum przyłączono do zarządu osmańskiego także Aşkale (dzień niepotwierdzony).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Początek powstań celâlich: powstanie Şeycha Celâla z Bozok", "99bd8a99"], "d": ["W okolicach Bozok pewien człowiek o imieniu Şeyh Celâl, ogłosiwszy się mahdim, zbuntował się w okolicach Tokat; choć powstanie stłumiono, jego imię przez stulecie stało się nazwą dla wszystkich ruchów zbójeckich i powstańczych w Anatolii. Celâlizm, połączony pod koniec XVI wieku z rozpadem ładu timarowego i naciskiem demograficznym, przekształcił się w najdłużej trwający problem bezpieczeństwa wewnętrznego imperium. Powstania spowodowały w Anatolii masowe migracje zwane „wielką ucieczką”.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Przyłączenie Algieru do Państwa Osmańskiego", "b8eba4c1"], "d": ["Hayreddin Reis, który opierał się w Afryce Północnej naciskowi hiszpańskiemu, zwrócił się do Stambułu, by się utrzymać, i oddał Algier sułtanowi, a chutbę odczytano w imieniu sułtana Selima Strasznego. W ten sposób Algier został oficjalnie przyłączony do ziem osmańskich, a Hayreddinowi wysłano z tytułem beylerbeja żołnierzy i działa. To przyłączenie położyło podwaliny osmańskiego panowania morskiego na zachodzie Morza Śródziemnego, które miało trwać stulecia. W tym samym dniu przyłączono także inne miejscowości: Konstantyna, Szerszel (Cherchell), Médéa (Titteri), Sétif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Śmierć sułtana Selima Strasznego w Çorlu", "9fe83744"], "d": ["Selim I, który w osiem lat ponad dwukrotnie powiększył ziemie państwa, wyruszył ze Stambułu 18 lipca 1520 na nową wyprawę; z powodu wielkiego guza, który wyrósł mu na plecach, nie mógł pójść dalej niż Çorlu. Mimo interwencji lekarzy choroba się pogłębiła i po dwumiesięcznym beznadziejnym leczeniu zmarł tu 8–9 şewwala 926 (21–22 września 1520). Dzięki Çaldıranowi, Mardż Dabik i Ridaniji zatrzymał Iran i zlikwidował Państwo Mameluckie, przynosząc Osmanom kalifat i protektorat nad Haremejn. Zostawił jednego syna: Sulejmana.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Wejście wyspy Ikaria (Nikarya) pod zarząd osmański", "6afa972b"], "d": ["Ikaria między Samos a Chios znajdowała się od 1481 do 1521 pod zarządem joannitów z Rodos; pierwszy okres osmański na wyspie rozpoczął się w 1522 i trwał do 1822. W tym okresie za zbieranie i płacenie podatków odpowiadał kaymakam; podobnie jak na innych wyspach Morza Egejskiego trwała też lokalna rada starszych (demogerontia), która od czasu do czasu wchodziła w konflikt z zarządem osmańskim.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Aneksja ziemi Dulkadir — ejalet Dulkadir z ośrodkiem w Maraşu", "595c3c30"], "d": ["Ziemia Dulkadir, trwająca od klęski pod Turnadağ w 1515 jako bejlik zależny od Osmanów, została po wymordowaniu Şehsuvaroğlu Alego Beja wraz z dziećmi w Artukova bezpośrednio przyłączona do ziem osmańskich i przekształcona w ejalet z ośrodkiem w Maraşu. Region Bozok bejliku został związany z zarządem osmańskim jako odrębny sandżak. W ten sposób zamknął się około dwustuletni okres Dulkadırlı w Maraşu, Elbistanie, Göksun, Gürün, Zamantı i Darende; bufor bejlik na granicy mameluckiej całkowicie zniknął.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Zdobycie Kninu", "a46d3117"], "d": ["W wyniku napadów sandżakbeja Bośni Gazi Hüsrev Beja w latach 927–928 (1521–1522) szereg twierdz weneckich, na czele z Kninem, Skradinem i Ostrovicą, przeszedł pod zarząd osmański; granicę odepchnięto za drugi łańcuch gór. Ten łańcuch zdobyczy położył podwaliny pod sandżak Dalmacji, który miał zostać dopełniony po piętnastu latach zajęciem Klisu.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Wycofanie się rycerzy: przekazanie Bodrum, Kos i Dodekanezu", "ea01666e"], "d": ["Zgodnie z warunkami poddania Rodos joannici opuścili nie tylko ośrodek wyspy, ale wszystkie pozycje, które trzymali od dwustu lat. Twierdza Bodrum (Saint Pierre) na wybrzeżu Anatolii oraz wyspy Kos, Kalymnos i Leros przeszły w ten sposób bez walki pod zarząd osmański. Wraz z tym przekazaniem, dopełnionym dwa tygodnie po upadku Rodos, obecność łacińska w południowo-wschodnim narożniku Morza Egejskiego całkowicie się skończyła.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Powstanie Hain Ahmeda Paszy w Egipcie", "b18bb805"], "d": ["Ahmed Pasza, który oczekując wielkiego wezyratu został wysłany na namiestnictwo Egiptu, ogłosił w Kairze niepodległość, mianując się „al-Malik al-Mansûr Sułtan Ahmed”. Powstanie szybko stłumiono, a paszę zabito, lecz wydarzenie pokazało kruchość kontroli centralnej w najbogatszym ejalecie imperium. Wobec tego İbrahim Pasza udał się do Egiptu i kazał przygotować słynne Kanunname Egiptu, na nowo porządkujące zarząd ejaletu.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Aneksja Północnej Bośni: Jajce i Banja Luka", "8ec86cfa"], "d": ["Gdy po Mohaczu węgierska linia obrony się załamała, sandżakbej Bośni Gazi Hüsrev Bej, maszerując w dolinę Vrbasu, zajął ostatnie twierdze bośniackie pozostające w rękach królestwa węgierskiego. Wraz z upadkiem Jajce i Banja Luki ejalet Bośni sięgnął na północy rzeki Sawy i narodził się front chorwacki. Banja Luka wkrótce stała się drugim ośrodkiem ejaletu.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Zajęcie Budy i oddanie jej Zápolyi", "fba4f89b"], "d": ["W drodze na wyprawę wiedeńską armia osmańska oblegała i odzyskała Budę, która wpadła w ręce Ferdynanda, i oddała miasto królowi Węgier pod protekcją osmańską, Jánosowi Szapolyaiemu. W ten sposób na Węgrzech ustanowiono w rywalizacji habsbursko-osmańskiej model buforowego królestwa wasalnego. Ten ład miał trwać do 1541, a po śmierci Zápolyi Buda miała zostać przekształcona w bezpośredni ejalet osmański.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Sulejman wyruszył na wyprawę niemiecką — wyzwanie rzucone Karolowi V", "7c3d7055"], "d": ["Po bezskutecznym oblężeniu Wiednia i ponownym oblężeniu Budy przez Ferdynanda sułtan wyruszył ze Stambułu, by tym razem bezpośrednio wciągnąć cesarza Karola V w bitwę polną. Armia miała w sierpniu zatrzymać się przy oporze małej twierdzy Güns, a ponieważ cesarz nie wyszedł do bitwy, wyprawa miała ograniczyć się do napadów. Wyprawa przygotowała grunt pod pierwszy pokój z Habsburgami w następnym roku.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Wyprawa niemiecka i oblężenie Güns (Kőszeg)", "8aec937a"], "d": ["Sulejman, chcąc zmusić Karola V do bitwy polnej, poprowadził armię na Austrię; mała twierdza Güns, broniąc się dwadzieścia pięć dni, opóźniła natarcie armii. Ponieważ cesarz nie wyszedł do bitwy, akindżi uderzyli na okolice Wiednia, a wobec postępu pory roku zawrócono. Wyprawa nie przyniosła zdobyczy terytorialnych, lecz posadziwszy Habsburgów przy stole przygotowała grunt pod pokój w następnym roku.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Traktat stambulski — pierwszy pokój z Habsburgami", "b085767a"], "d": ["Sułtan, który przyjął posła Ferdynanda Corneliusa, zgodził się na rozejm i powstał pierwszy oficjalny tekst pokojowy między Osmanami a Austrią. Na mocy traktatu Ferdynand zgodził się płacić roczny podatek za ziemie węgierskie, które trzymał, a arcyksiąże austriacki w protokole został uznany za równego wielkiemu wezyrowi. Ten nierówny status był jawnym wyrazem osmańskich pretensji do wyższości w XVI wieku.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Zajęcie Karsu i otwarcie granicy północno-wschodniej", "742e3101"], "d": ["Gdy kolumna czołowa wyprawy Irakejn zwróciła się z Erzurumu na wschód, twierdza Kars, znajdująca się w rękach atabegatu gruzińskiego i leżąca w ruinie od czasów Timura, została przejęta bez oporu. Miasto, trzymając przejście między łukiem Arasu a Çıldır, uchodziło za klucz północnej bramy otwierającej się na Iran. Ta zdobycz stała się pierwszym ogniwem beylerbeyliku Karsu, który miał powstać po trzydziestu latach, i linii kaukaskiej.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Pierwsze wkroczenie do Tabrizu — otwarcie wyprawy Irakejn", "cf7ed4e3"], "d": ["İbrahim Pasza, który ruszył naprzód jako serdar-ı ekrem, wkroczył bez oporu do stolicy safawidzkiej Tabrizu, gdy szach Tahmasp, unikając bitwy polnej, wycofał się w głąb kraju. Sulejman dotarł do miasta we wrześniu; jednak wskutek nadejścia zimy i zbytniego wydłużenia linii zaopatrzenia armia zwróciła się w kierunku Bagdadu, a Tabriz nie mógł być utrzymany przez dłuższy czas. Miasto zajęte po raz drugi po Çaldıranie stało się miejscem, w którym Osmanowie nauczyli się, że na wschodzie zdobyć jest łatwo, a utrzymać trudno.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Zdobycie Tunisu przez Barbarossę", "d8754216"], "d": ["Kapudan pasza Barbarossa Hayreddin Pasza, po uderzeniu flotą na wybrzeża Włoch, zwrócił się ku Tunisowi i wkroczył do miasta, zmusiwszy do ucieczki władcę Hafsydów Mulaja Hasana. Zajęcie Tunisu dzięki jego położeniu kontrolującemu Cieśninę Sycylijską nagle obróciło równowagę sił w zachodniej części Morza Śródziemnego na korzyść Osmanów. Panowanie to nie miało jednak trwać długo, a Karol V miał w następnym roku odpowiedzieć wielką flotą.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Utrata Tunisu na rzecz Karola V", "a691f0f8"], "d": ["Karol V, po zdobyciu Halk al-Wadi wielką wyprawą wspartą flotami genueńską i papieską, zajął Tunis i przywrócił na tron Mulaja Hasana pod protekcją hiszpańską. W mieście osadzono garnizon hiszpański i osmańskie natarcie w środkowej części Morza Śródziemnego zostało tymczasowo zatrzymane. Ostateczne zdobycie Tunisu miało stać się możliwe dopiero po czterdziestu latach, w 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Akcja Gazi Hüsrev Beja wzdłuż Sawy: Bosanski Brod i Jasenovac", "3740ec83"], "d": ["Po zajęciu Jajce i Banja Luki w 1528 twierdze wzdłuż rzeki Sawy pozostawały jeszcze przez pewien czas na granicy chorwacko-slawońskiej podległej koronie habsburskiej. Gazi Hüsrev Bej, który w 1536 po raz trzeci został sandżakbejem Bośni, w tym samym roku, zajmując Požegę i okolice, przyłączył do zarządu osmańskiego także twierdze Brod i Jasenovac nad Sawą. Północna granica Bośni sięgnęła w ten sposób Sawy; region został dopełniony po dwóch latach zajęciem Dubicy.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Stracenie Makbula İbrahima Paszy", "348aa7b8"], "d": ["İbrahim Pasza, który przez trzynaście lat był wielkim wezyrem, najbliższym przyjacielem Sulejmana i faktycznie drugim człowiekiem państwa, został uduszony i stracony w pałacu, do którego wezwano go na iftar, bez podania żadnego powodu. Za czynniki jego śmierci uważa się jego postawę w wyprawie Irakejn, używanie tytułu „serasker sułtan” oraz układy wewnątrz pałacu. Stracenie jest punktem zwrotnym pokazującym, że w osmańskim zarządzie centralnym wielcy wezyrowie nie mają absolutnego bezpieczeństwa.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Zdobycie twierdzy Klis i utworzenie sandżaku Dalmacji", "6ffd4ebf"], "d": ["Murad Bej, neofita chorwackiego pochodzenia i kethüda Gazi Hüsrev Beja, zajął od Wenecji strategiczną twierdzę Klis tuż na północ od Splitu. Bezpośrednio po zdobyciu Klis uczyniono ośrodkiem nowego sandżaku i kazy obejmującego okolice; granice tego sandżaku w znacznej mierze wyznaczyły ramy osmańskiej Chorwacji. To zdobycie, następujące piętnaście lat po Kninie, dopełniło administracyjny szkielet wnętrza Dalmacji.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Oblężenie Korfu i wojna z Wenecją", "11af95bd"], "d": ["Po wyprawie do Apulii armia osmańska wysadziła wojsko na Korfu i oblegała potężną twierdzę wenecką na wyspie. Wskutek stromego położenia twierdzy, ciężkich strat i warunków pory roku blokadę zniesiono i wycofano się 6 września. Choć oblężenie nie przyniosło skutku, wojna otwarta z Wenecją zakończyła się przyłączeniem do Osmanów wielu wysp na Morzu Egejskim i Adriatyku oraz zwycięstwem pod Prewezą w następnym roku.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Wyprawa Barbarossy na Morze Egejskie: zajęcie wysp zarządzanych bezpośrednio przez Wenecję", "1b32ed96"], "d": ["Flota, wracając spod oblężenia Korfu, wykorzystując wypowiedzenie wojny Wenecji, przejmowała jedną po drugiej wyspy Morza Egejskiego podlegające nie księstwu, lecz bezpośrednio Wenecji. Eginę zdobyto po zaciętym oporze, Astypalaja w rękach rodu Querini oraz Karpathos i Kasos się poddały, a Patmos pod zarządem klasztoru przyjęło protekcję osmańską. Księstwo Naksos pozostawiono natomiast na miejscu, związane daniną; jego aneksja miała czekać do 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Wyprawa Barbarossy na północne Morze Egejskie: zajęcie Skyros i Północnych Sporad", "20ab688e"], "d": ["W drodze do Prewezy flota przejęła jedną po drugiej wyspy północnego Morza Egejskiego, które po zdobyciu Stambułu schroniły się u Wenecji. Skyros na północ od Negroponte oraz Skiathos, Skopelos i Alonissos trzymające wejście do Zatoki Salonickiej weszły w ten sposób pod zarząd osmański. Te wyspy zamknęły ostatnią północnoegejską próżnię, która, choć Negroponte zdobyto w 1470, pozostawała jeszcze przez sześćdziesiąt osiem lat w rękach Wenecji.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Zajęcie Adenu i aneksja wybrzeża Jemenu", "e7d46d8f"], "d": ["Flota wypływająca z Suezu na wyprawę indyjską, ponieważ nie można było wyjść na ocean bez zabezpieczenia Morza Czerwonego, zwróciła się najpierw ku wybrzeżu Jemenu. Hadım Süleyman Pasza wszedł 3 sierpnia 1538 do portu Aden; władca Tâhirîdów Âmir b. Dâvud, skłonny do Portugalczyków, został sprowadzony do bramy kapitana i stracony, a w mieście zostawiono 500-osobową załogę. Podczas tej samej wyprawy przyjęto także poddanie Mokha oraz wysp Kamaran i Farasan panujących nad cieśniną, i położono podwaliny pod beylerbeylik Jemenu. W ten sposób państwo osmańskie po raz pierwszy zdobyło całe północne wybrzeże Bab al-Mandab; Sana i regiony wewnętrzne miały czekać jeszcze dziewięć lat.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Wyprawa na Mołdawię i aneksja regionu Budżak (Bender)", "90a88a56"], "d": ["W wyprawie przeciw wojewodzie mołdawskiemu Petru Rareșowi, który nie wypełniał zobowiązań wobec Osmanów, zdobyto Suczawę, a miasto Jassy zostało złupione przez chana krymskiego Sâhiba Gireja. Sułtan wprowadził na wojewodztwo Stefana Çekirge i przyłączył Bender wraz z regionem Budżak (południowa Besarabia) bezpośrednio do ziem osmańskich. Ta aneksja stała się jednym z ogniw przekształcających północno-zachodnie wybrzeża Morza Czarnego w osmańskie morze wewnętrzne. Mołdawia była już województwem zależnym od Osmanów; wyprawa ta nie zabrała ziemi obcemu państwu, lecz jedynie odebrała wojewodzie zarząd wewnętrzny Benderu i Budżaku i związała go bezpośrednio z sułtanem; reszta wojewodztwa zachowała status zależny. Ta sama struktura miała się powtórzyć w 1484 w Kilii i Akkermanie, a w 1713 w Chocimiu: twierdze graniczne bezpośrednio, ziemie wewnętrzne zależne.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Przejęcie Nauplionu (Anabolu) na mocy traktatu", "104d0937"], "d": ["Trwająca po Prewezie trzy lata wojna z Wenecją zakończyła się zgodą republiki na zostawienie dwóch ostatnich twierdz w Morei. Nauplion (Anabolu) i Monemwazja (Benefşe), których nie zdobyto w oblężeniu, zostały przekazane Osmanom przy stole, oprócz trzystu tysięcy dukatów odszkodowania wojennego. Półwysep Morea w ten sposób zjednoczył się tak, że nie pozostał na nim ani jeden ślad Wenecji.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Wejście Segedynu pod zarząd osmański i utworzenie liwy Segedynu", "019aa000"], "d": ["Po pełnym ustanowieniu zarządu osmańskiego w Budzie w 1541 notable Segedynu przyjęli panowanie Ferdynanda I i przygotowali się do obrony zbrojnej. Beylerbej Budy Küçük Bâlî Pasza na początku 1543 kazał wezwać zarządców miasta i stracić ich pod zarzutem zdrady, a następnie wysłał oddział, by zająć miasto. W tym czasie utworzono liwę Segedynu i na pierwszego sandżakbeja mianowano Derviş Beja, syna Bâlîego Paszy; liwa początkowo rozciągała się między Dunajem a Cisą.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Zdobycie Valpo, Siklósu i Pécsu", "2ca030a3"], "d": ["Pierwszym celem wyprawy węgierskiej, podjętej dwa lata po aneksji Budy, było zabezpieczenie południowego skrzydła nowego ejaletu między Drawą a Dunajem. Po zdobyciu twierdz Valpo i Siklós poddał się Pécs, ośrodek Baranyi. Miasto miało stać się najludniejszym i najbardziej rozbudowanym ośrodkiem osmańskich Węgier, a historyk İbrahim Peçuylu miał od niego wziąć swe przezwisko.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Zdobycie Ostrzyhomia i Székesfehérvár", "efca9e05"], "d": ["W wyprawie węgierskiej, którą Sulejman prowadził osobiście, po dwuipółtygodniowym oblężeniu Ostrzyhom, ośrodek religijny Królestwa Węgier i miasto arcybiskupie, wszedł pod zarząd osmański. Następnie zajęto także Székesfehérvár, miasto koronacji królów węgierskich, i pas obronny ejaletu Budy został dopełniony. Ostrzyhom miał pozostać w rękach osmańskich do 1595 jako kluczowa twierdza linii Dunaju.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Północno-zachodni pas obrony Budy: Vác, Hatvan i Simontornya", "733ee5ce"], "d": ["Po zdobyciu Ostrzyhomia i Székesfehérvár beylerbej Budy ruszył bez wyprawy sułtana, by dopełnić pierścień twierdz otaczających stolicę. Vác w zakolu Dunaju, Hatvan, brama Alföldu, i Simontornya na linii Sió zostały przejęte jedna po drugiej. Zdobycze tego cichego roku przekształciły Budę z miasta pogranicznego w ośrodek ejaletu, który miał przetrwać sto czterdzieści lat.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Aneksja Basry i wyjście do Zatoki Perskiej", "02f87c11"], "d": ["Władca Basry Râşid b. Megāmis w czasie zdobycia Bagdadu (1534) zadeklarował Sulejmanowi posłuszeństwo, a w 1538 przysłał klucze miasta. Gdy zastępujący go szejch Yahyâ zwrócił się przeciw Osmanom, beylerbej Bagdadu Ayas Pasza ruszył lądem, a sandżakbej Mosulu z 120 okrętami Eufratem; Ayas Pasza wkroczył do Basry 26 grudnia 1545, a miasto stało się ośrodkiem beylerbeyliku. Port u ujścia Szatt al-Arab był bramą, przez którą Osmanowie otworzyli się na zatokę kontrolowaną przez Portugalię z Ormuzu; traktatem z Amasyi z 1555 Iran także uznał ten stan.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Zdobycie Sany i wnętrza Jemenu", "d31ded85"], "d": ["Po Ta'izz zajęto także Sanę, a cały kraj został związany z beylerbeylikiem. Jednak wskutek stromej geografii i różnicy wyznaniowej to panowanie nigdy nie było spokojne; Jemen stał się dla Osmanów frontem nieustannie pochłaniającym żołnierzy.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Zdobycie Ta'izz", "d4509df9"], "d": ["W Jemenie, gdzie dziewięć lat wcześniej poprzestano na pasie wybrzeża, wobec rosnącej siły imamów zajdyckich w górzystym wnętrzu siły Özdemira Paszy weszły na wyżynę i zajęły Ta'izz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Traktat stambulski — pięcioletni pokój z Habsburgami", "41f81773"], "d": ["Między Osmanami a Habsburgami podpisano pięcioletni pokój; Ferdynand zgodził się płacić rocznie 30 000 dukatów za ziemie węgierskie, które trzymał. Traktat prawnie utrwalił faktyczny stan Węgier podzielonych na trzy części. Zabezpieczenie w ten sposób frontu zachodniego dało Sulejmanowi możliwość zorganizowania nowych wypraw na Iran.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Druga wyprawa irańska i ponowne zajęcie Tabrizu", "e82365df"], "d": ["W wyprawie podjętej z zachęty brata szacha Tahmaspa, Elkasa Mirzy, który zbuntował się przeciw niemu i schronił w Stambule, armia po raz drugi weszła do Tabrizu. Ponieważ Safawidzi znów nie weszli do bitwy polnej i wycofali się, paląc ziemię, w mieście można było zostać tylko kilka tygodni. Wyprawa przesądziła, że Tabrizu nie da się utrzymać, i skierowała osmańską strategię ku utworzeniu trwałej linii granicznej, czyli ku umocnieniu Wanu.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Zdobycie Wanu i ustalenie granicy wschodniej", "fc8f930b"], "d": ["Twierdza Wan, oblężona w drodze powrotnej z Tabrizu, dzięki położeniu na skale wznoszącej się nad wschodnim brzegiem jeziora była niekwestionowanym kluczem regionu i po krótkim oblężeniu się poddała. Miasto natychmiast uczyniono ośrodkiem beylerbeyliku; sandżaki Erciş, Adilcevaz i Hakkâri podporządkowano mu. W odróżnieniu od Tabrizu Wan został utrzymany i przez czterysta lat pozostał najdalej wysuniętą trwałą pozycją Osmanów na wschodzie.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Aneksja Al-Hasa i Al-Katif — arabskie wybrzeże Zatoki", "f6701e60"], "d": ["Po zajęciu Basry zdobyto Al-Katif, który na zachodnim wybrzeżu Zatoki stał się wysuniętym posterunkiem Portugalii, i wraz z oazami Al-Hasa we wnętrzu utworzono nowy beylerbeylik. To stąd wychodziły akcje skierowane na Bahrajn i Ormuz. Państwo osmańskie zyskało w ten sposób głos jednocześnie na wybrzeżach półwyspu Arabskiego nad Morzem Czerwonym i Zatoką Perską.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Utrata Şehrizoru — bej Erdelanu Sührâb skłonił się ku Safawidom", "5600efc9"], "d": ["Region Şehrizoru, który w czasie wyprawy Irakejn (1535) uznał zwierzchnictwo osmańskie, znajdował się pod zarządem emira Erdelanu Bige Beja rezydującego w twierdzy Zalm. Po śmierci Bige Beja w 1550 jego brat Sührâb, który zajął twierdzę Zalm i opanował bejlik, zwrócił się ku Safawidom i wypowiedział posłuszeństwo Osmanom; region Şehrizoru wyszedł w ten sposób spod wpływów osmańskich. Region został odzyskany dopiero w 1554, podczas wyprawy nachiczewańskiej, po oblężeniu i zajęciu twierdzy Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Zajęcie Ardahanu i dorzecza Çıldır", "14c9eb76"], "d": ["Beylerbej Erzurumu, w czasie trwającej wojny z Safawidami zwróciwszy się ku ziemiom atabegów gruzińskich na łuku Kury, przyłączył do zarządu osmańskiego Ardahan i okolice Çıldır. Linia Kars–Ardahan została w ten sposób zjednoczona, a wyżyny otwierające się na Gruzję na północnym wschodzie objęto kontrolą. Ostateczny ład administracyjny regionu miał zostać dopełniony po dwudziestu siedmiu latach utworzeniem ejaletu Çıldır.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokollu Mehmed Pasza przekroczył Dunaj — początek wojny o Siedmiogród", "38fde931"], "d": ["Wobec zamętu wywołanego przez mnicha Martinuzziego, opiekuna króla Siedmiogrodu, małego Jánosa Zsigmonda, i oddania przez Siedmiogród twierdz Banatu Ferdynandowi uznano za konieczną nową wyprawę; dowództwo powierzono beylerbejowi Rumelii Sokollu Mehmedowi Paszy. Armia, mimo zwodzących zabiegów Martinuzziego, przekroczyła Dunaj i zajęła Becse, Becskerek, Csanád i Lippę; jednak oblężenie Timișoary zniesiono 16 listopada z powodu mrozów. W ten sposób na Węgrzech rozpoczęła się nowa wojna osmańsko-habsburska.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Miasto Lipova (Lippa) wpadło w ręce armii austriackiej Castaldo — twierdza poddała się 5 grudnia", "a0e1ff0d"], "d": ["Lipovę, zajętą przez Sokollu Mehmeda Paszę w październiku 1551, armia generała Castaldo oblegała od 4 listopada; po dwóch dniach miasto wpadło w ręce Austriaków. Ulama Pasza z 5000-osobową załogą bronił twierdzy jeszcze dziewięć dni i 5 grudnia 1551 wyszedł na mocy układu. Do upadku Timișoary w 1552 Lipova pozostawała w rękach Habsburgów.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Utrzymanie przez siły wysłane z Timișoary palanek Banatu Południowego — Versec, Haram, Keve", "edca0921"], "d": ["Po poddaniu się Timișoary armii osmańskiej oddziały odłączone od armii oblężniczej zwróciły się ku małym palankom Banatu; według relacji Bánlakyego palanki Versec, Facset, Mehádia, Csákóvár, Haramvár i Keve były trzymane przez te siły. W ten sposób także Haram nad Dunajem wpadł w ręce osmańskie.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Zdobycie Szolnoku i niepowodzenie oblężenia Egeru", "a7156e8f"], "d": ["Po zdobyciu Timișoary dwie połączone armie osmańskie zajęły niemal bez walki Szolnok nad Cisą, gdy najemnicy opuścili twierdzę. Oblężona następnie twierdza Eger nie została zdobyta wobec trzydziestoośmiodniowego oporu dwutysięcznego garnizonu pod dowództwem Istvána Dobó, a armia, gdy nadeszła zima, się wycofała. To, że w tej samej wyprawie jedna twierdza padła łatwo, a druga się oparła, było pierwszym jawnym znakiem, że granica na Węgrzech nie przesuwa się już sama na korzyść Osmanów.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Sojusz osmańsko-francuski — oddanie floty francuskiej pod rozkazy osmańskie", "a8e01b22"], "d": ["Traktatem z 1 lutego 1553 flotę francuską oddano pod rozkazy floty osmańskiej; przewidziano wspólne działania w zachodniej części Morza Śródziemnego przeciw Hiszpanii. Po traktacie Turgut Reis wyruszył 15 czerwca 1553 z czterdziestoma pięcioma galerami wesprzeć Francję. Był to pierwszy oficjalny traktat sojuszniczy przenoszący handlowy grunt kapitulacji z 1536 na współpracę wojskową.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Stracenie księcia Mustafy w Konya Ereğli", "dec36858"], "d": ["Książę Mustafa, który wszedł do namiotu ojca, by dołączyć do armii zebranej na wyprawę nachiczewańską, w chwili gdy miał stanąć przed obliczem sułtana spotkał katów i został uduszony. Zabicie następcy, wielce kochanego w armii, wywołało głęboki gniew wśród janczarów, a Rüstem Pasza został odwołany z wezyratu. Wydarzenie weszło do literatury i pamięci ludowej jako jedno z najbardziej spornych załamań osmańskiej polityki książęcej.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Przesunięcie granicy Nubii na południe wraz z Ibrim", "c57d5d77"], "d": ["Południowa granica beylerbeyliku Egiptu została przesunięta poza drugą kataraktę, gdy twierdza Ibrim, wznosząca się na skalistym przylądku nad Nilem, została umocniona przez Özdemira Beja, a Dolna Nubia całkowicie przyłączona do osmańskiego Egiptu. (W Ibrim osmańska organizacja administracyjna została ustanowiona po zdobyciu Egiptu; na mapie Ibrim jest pokazywany jako osmański od 1517. Rok ten jest przybliżony, źródło nie podaje roku.) Twierdza była zaporą przeciw napadom z Nubii, a zarazem punktem kontroli szlaku złota i niewolników prowadzącego do Sennaru. Osadzona tu bośniacka załoga okazała się tak trwała, że jej potomkowie byli w twierdzy jeszcze trzysta lat później. Źródła podają dwie różne relacje o czasie wejścia Ibrim pod zarząd osmański: hasło TDV o Sudanie wiąże przyłączenie Dolnej Nubii do osmańskiego Egiptu z akcją Özdemira Paszy w połowie XVI wieku, natomiast hasło o Nubii pisze, że region aż po dolinę Halfa i organizacja administracyjna w Ibrim zostały ustanowione bezpośrednio po zdobyciu z 1517. Sandżak Ibrim został 26 lipca 1573 przyłączony do ejaletu Habesz.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Zdobycie Bidżaji (Bougie) od Hiszpanów", "49691cda"], "d": ["Bidżaja, w rękach Hiszpanii od czterdziestu trzech lat i dzieląca wybrzeże między Algierem a Konstantyną na dwie części, poddała się po oblężeniu z lądu i morza. Wraz z upadkiem twierdzy wybrzeże odżaku algierskiego stało się nieprzerwane aż po Oran. W Hiszpanii ta strata wywołała tak wielkie oburzenie, że dowódca Alonso de Peralta, który oddał twierdzę, został w kraju stracony.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Przyłączenie Zeili do Ejaletu Habesz", "7bbf369a"], "d": ["Port Zeila na afrykańskim wybrzeżu Zatoki Adeńskiej, na południowym krańcu ejaletu Habesz, został związany z zarządem osmańskim. Miasto, brama Sułtanatu Adal otwierająca się na morze, było ostatnim punktem zaopatrzenia dla okrętów wychodzących poza Bab al-Mandab. Wraz z przyłączeniem Zeili granica państwa osmańskiego w Afryce osiągnęła swój najdalszy południowy punkt.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Bitwa książąt pod Konyą", "1c8de387"], "d": ["Książę Bayezid, który wszedł do walki o tron, przybył pod Konyę z około 30 000 ludzi i w trwającej dwa dni walce przegrał z bratem księciem Selimem. Rozbity Bayezid schronił się przez Amasyę w Iranie u szacha Tahmaspa. Bitwa w ostatnich latach Sulejmana zamieniła kryzys sukcesji tronu w problem polityki zagranicznej.", "d466cfc5"]}
});
